bot.answer_callback_query = _safe_answer_cb


# ================================================================================
# 🔐 HAR BIR AMAL OLDIDAN TEKSHIRUV (til → jins → kanalga majburiy obuna)
# Barcha message/callback handlerlari ro'yxatdan o'tayotganda shu yerda o'raladi — shuning uchun
# hech bir buyruq yoki tugma tekshiruvsiz ishlamaydi. Tekshiruv mantig'i pastda (_gate_* funksiyalari).
# Tekshiruvning o'zida xato chiqsa — foydalanuvchi bloklanmaydi (fail-open), xato logga yoziladi.
# ================================================================================
def _gate_wrap_message(fn):
    @functools.wraps(fn)
    def w(message, *a, **k):
        try:
            if _gate_blocks_message(message):
                return None
        except Exception:
            _logger.warning("gate (message) xatosi — foydalanuvchi o'tkazildi", exc_info=True)
        return fn(message, *a, **k)
    return w


def _gate_wrap_callback(fn):
    @functools.wraps(fn)
    def w(call, *a, **k):
        try:
            if _gate_blocks_callback(call):
                return None
        except Exception:
            _logger.warning("gate (callback) xatosi — foydalanuvchi o'tkazildi", exc_info=True)
        try:
            return fn(call, *a, **k)
        except (ValueError, IndexError):
            # Eskirgan yoki buzilgan tugma ma'lumoti (masalan eski xabardagi tugma): foydalanuvchiga
            # tushunarli javob beriladi, xato logga yoziladi, egaga bezovta xabar ketmaydi.
            _logger.warning("Eskirgan/noto'g'ri tugma ma'lumoti (%s): %r", getattr(fn, "__name__", "?"),
                            getattr(call, "data", None), exc_info=True)
            try:
                bot.answer_callback_query(call.id, "❌ Bu tugma eskirgan. Bosh menyudan qayta urinib ko'ring.")
            except Exception:
                pass
            return None
    return w


def _patch_handler_decorator(name, wrapper):
    _orig_deco = getattr(bot, name)

    def _factory(*da, **dk):
        _d = _orig_deco(*da, **dk)

        def _outer(fn):
            return _d(wrapper(fn))
        return _outer
    setattr(bot, name, _factory)


_patch_handler_decorator("message_handler", _gate_wrap_message)
_patch_handler_decorator("callback_query_handler", _gate_wrap_callback)

# ================================================================================
# ⚡ TEZKOR TUGMA JAVOBI: tungi/kunduzgi tugma bosilganda ilgari handler AVVAL guruhga xabar
# yuborib, xabarni tahrirlab, sheriklarga DM jo'natib, KEYIN tugmaga javob berardi — har bir
# Telegram so'rovi 0.2–1 soniya, shuning uchun tugma "osilib" turardi. Endi shu handlerlarda
# tarmoq so'rovlari (send/edit/delete) orqasiga yashirin fon oqimida, TARTIB bilan bajariladi,
# tugma javobi (answer_callback_query) esa darhol ketadi.
# ================================================================================
_DEFER_TL = threading.local()
_BG_IO = __import__("concurrent.futures").futures.ThreadPoolExecutor(max_workers=16, thread_name_prefix="bgio")

def _install_deferred_io():
    for _name in ("send_message", "edit_message_text", "delete_message", "edit_message_reply_markup"):
        _orig = getattr(bot, _name, None)
        if _orig is None or getattr(_orig, "_hm_deferrable", False):
            continue
        def _mk(orig):
            @functools.wraps(orig)
            def w(*a, **k):
                q = getattr(_DEFER_TL, "queue", None)
                if q is not None:
                    q.append((orig, a, k))
                    return None
                return orig(*a, **k)
            w._hm_deferrable = True
            return w
        setattr(bot, _name, _mk(_orig))

def _run_deferred(items):
    for fn, a, k in items:
        try:
            fn(*a, **k)
        except Exception:
            _logger.debug("deferred IO xatosi", exc_info=True)

def fast_callback(fn):
    @functools.wraps(fn)
    def wrapper(call, *a, **k):
        _DEFER_TL.queue = []
        try:
            return fn(call, *a, **k)
        finally:
            items, _DEFER_TL.queue = _DEFER_TL.queue, None
            if items:
                _BG_IO.submit(_run_deferred, items)
    return wrapper

# --- har o'yin uchun ALOHIDA qulf: bitta guruhning tun/kun yakunlanishi (o'nlab DM) boshqa
# guruhlarni va umumiy GAME_LOCK'ni to'xtatib qo'ymasin.
_CHAT_LOCKS = {}
_CHAT_LOCKS_GUARD = threading.Lock()
def _glock(chat_id):
    with _CHAT_LOCKS_GUARD:
        l = _CHAT_LOCKS.get(chat_id)
        if l is None:
            l = _CHAT_LOCKS[chat_id] = threading.RLock()
        return l


# ================================================================================
#  🎨 v8 — HUNTER RANGLI TUGMALAR (Telegram Bot API: InlineKeyboardButton.style)
# ================================================================================
# Telegram inline tugmalarga faqat 3 xil rang beradi: 🟢 success (yashil — Hunter
# "zumrad"), 🔵 primary (ko'k) va 🔴 danger (qizil). Botdagi HAMMA inline tugma
# (yuzlab joyda) matniga qarab AVTOMATIK bo'yaladi — shuning uchun mavjud kodning
# birorta tugmasi qo'lda o'zgartirilmaydi:
#   🔴 danger  — Orqaga / Bekor qilish / Yopish / Rad etish / ❌ / 🔙 / o'chirish
#   🟢 success — ✅ / Qo'shilish / Sotib olish / Xarid / Tasdiqlash / Qabul / Boshlash / Mukofot
#   🔵 primary — Do'kon / Profil / Geroy / Reyting / Para / Klan / Kabinet / Yordam / Sozlamalar
# Boshqa tugmalar (masalan o'yinchi ismlari) standart rangda qoladi.
#
# Xavfsizlik: (1) HUNTER_BUTTON_STYLES=0 muhit o'zgaruvchisi hammasini o'chiradi;
# (2) agar Telegram biror xabarni "style" tufayli rad etsa, xabar rangsiz qayta
# yuboriladi va ranglar avtomatik o'chiriladi (bot hech qachon yiqilmaydi);
# (3) eski Telegram ilovalari tugmani oddiy rangda ko'rsatadi (xatosiz).
# ⚪ Standart: tugmalar SHAFFOF (oddiy Telegram ko'rinishi). Ranglarni qaytarish uchun: HUNTER_BUTTON_STYLES=1
BUTTON_STYLES_ENABLED = os.environ.get("HUNTER_BUTTON_STYLES", "0").strip().lower() in ("1", "true", "on", "yes")

# 🎨 YAGONA RANG QOIDASI (butun bot bo'yicha, istisnosiz):
#   🟢 YASHIL  — tasdiqlash / qabul qilish / "Ha"        (✅ ☑️ 👍, "Tasdiqlash", "Qabul", "Ha")
#   🔴 QIZIL   — rad etish / bekor qilish / orqaga / yopish (❌ 🔙 ✖️ 👎, "Rad", "Bekor", "Orqaga", "Ortga", "Yopish", "Yo'q")
#   🔵 KO'K    — qolgan BARCHA tugmalar (do'kon, profil, o'yinchi ismlari, keyingi, sozlamalar ...)
_BTN_DANGER_RE = re.compile(
    r"(orqaga|ortga|bekor|yopish|\brad\b|rad\s*et|bosh\s*menyu|❌|🔙|✖️|👎|\byo['‘’`]q\b)", re.IGNORECASE)
_BTN_SUCCESS_RE = re.compile(
    r"(✅|☑️|✔️|tasdiq|qabul\s*qil|qabul\b|👍|\bha\b)", re.IGNORECASE)


def auto_button_style(text, callback_data=None):
    """Tugma matniga qarab rang: 'danger' (qizil) / 'success' (yashil) / boshqa hammasi 'primary' (ko'k)."""
    t = (text or "").strip()
    if not t:
        return "primary"
    if _BTN_DANGER_RE.search(t):
        return "danger"
    if _BTN_SUCCESS_RE.search(t):
        return "success"
    return "primary"


_ikb_orig_to_dict = types.InlineKeyboardButton.to_dict
_STYLE_DISABLED_UNTIL = 0.0   # 🎨 ranglar vaqtincha o'chirilgan bo'lsa — qaysi vaqtgacha


def _styles_on():
    return bool(BUTTON_STYLES_ENABLED) and time.time() > _STYLE_DISABLED_UNTIL


def _ikb_styled_to_dict(self):
    d = _ikb_orig_to_dict(self)
    try:
        if _styles_on() and "style" not in d and not d.get("pay"):
            st = auto_button_style(d.get("text", ""), d.get("callback_data"))
            if st:
                d["style"] = st
    except Exception:
        pass
    return d


types.InlineKeyboardButton.to_dict = _ikb_styled_to_dict


def _strip_button_styles(reply_markup_json):
    """reply_markup (JSON matn) ichidagi barcha 'style' maydonlarini olib tashlaydi."""
    try:
        data = json.loads(reply_markup_json)
    except Exception:
        return reply_markup_json
    changed = False
    for row in (data.get("inline_keyboard") or []):
        for btn in row:
            if isinstance(btn, dict) and "style" in btn:
                btn.pop("style", None)
                changed = True
    return json.dumps(data) if changed else reply_markup_json


def _make_style_safe_request(orig):
    """apihelper._make_request'ni o'rab oladi: 'style' tufayli rad etilgan so'rovni
    rangsiz qayta yuboradi (faqat qayta yuborish MUVAFFAQIYATLI bo'lsa ranglar o'chiriladi)."""
    def wrapper(*args, **kwargs):
        global _STYLE_DISABLED_UNTIL
        try:
            return orig(*args, **kwargs)
        except telebot.apihelper.ApiTelegramException as first_err:
            params = kwargs.get("params")
            in_args = False
            if params is None and len(args) >= 4:
                params = args[3]
                in_args = True
            try:   # 🔧 v8: bot guruhdan chiqarilgan bo'lsa — o'yin/holatni tozalaymiz
                if isinstance(params, dict) and any(m in str(first_err).lower() for m in _CHAT_DEAD_MARKERS):
                    _forget_dead_chat(params.get("chat_id"))
            except Exception:
                pass
            rm = params.get("reply_markup") if isinstance(params, dict) else None
            if not (BUTTON_STYLES_ENABLED and isinstance(rm, str) and '"style"' in rm):
                raise
            _el = str(first_err).lower()
            if "message is not modified" in _el:   # oddiy, zararsiz javob — tugma rangiga aloqasi yo'q
                raise
            if not any(k in _el for k in ("style", "button", "reply markup", "reply_markup", "bad request")):
                raise
            new_params = dict(params)
            new_params["reply_markup"] = _strip_button_styles(rm)
            if in_args:
                new_args = list(args)
                new_args[3] = new_params
                retry = lambda: orig(*new_args, **kwargs)
            else:
                new_kwargs = dict(kwargs)
                new_kwargs["params"] = new_params
                retry = lambda: orig(*args, **new_kwargs)
            try:
                result = retry()
            except telebot.apihelper.ApiTelegramException:
                raise first_err  # muammo ranglarda emas edi — asl xato qaytariladi
            if any(k in _el for k in ("style", "button", "reply markup", "reply_markup")):
                _STYLE_DISABLED_UNTIL = time.time() + 600   # faqat 10 daqiqaga, keyin yana yoqiladi
                _logger.warning("🎨 Tugma ranglari rad etildi — 10 daqiqaga o'chirildi: %s", first_err)
            return result
    return wrapper


if getattr(telebot.apihelper, "_make_request", None) is not None:
    telebot.apihelper._make_request = _make_style_safe_request(telebot.apihelper._make_request)


# ================================================================================
# 🛡 TELEGRAM XATOLARIGA CHIDAMLILIK (o'yin o'rtasida qotib qolishning ASOSIY sababi)
# Oldin: 429 (Too Many Requests) yoki 502/503/504 (Telegram vaqtinchalik nosoz) chiqsa,
# xato to'g'ridan-to'g'ri taymer oqimiga (threading.Timer) yetib borar, oqim o'lar va
# o'yin bosqichi (tun/kun/ovoz/osish) hech qachon davom etmasdi.
# Endi: har bir Telegram so'rovi 429 da Telegram aytgan muddat (retry_after) kutib,
# 502/503/504 va tarmoq uzilishlarida esa qisqa kutib, cheklangan marta qayta uriniladi.
# ================================================================================
_TG_RETRY_MAX = 4          # eng ko'pi bilan nechta urinish
_TG_RETRY_AFTER_CAP = 8    # shu soniyadan uzoq kutish kerak bo'lsa — oqim uxlamaydi, xabar navbatga olinadi
_TG_TRANSIENT_CODES = (502, 503, 504)


def _tg_retry_after_seconds(err):
    """429 xatosidan Telegram so'ragan kutish vaqtini (soniya) oladi."""
    try:
        params = (getattr(err, "result_json", None) or {}).get("parameters") or {}
        if params.get("retry_after") is not None:
            return int(params["retry_after"])
    except Exception:
        pass
    try:
        import re as _re
        m = _re.search(r"retry after (\d+)", str(err), _re.I)
        if m:
            return int(m.group(1))
    except Exception:
        pass
    return 5


def _make_retrying_request(orig):
    """apihelper._make_request'ni 429 / 502 / 503 / 504 / tarmoq uzilishlariga qarshi
    qayta urinish bilan o'raydi. Boshqa (haqiqiy) xatolar o'zgarishsiz yuqoriga uzatiladi."""
    import requests as _rq

    def wrapper(*args, **kwargs):
        attempt = 0
        while True:
            attempt += 1
            try:
                return orig(*args, **kwargs)
            except telebot.apihelper.ApiTelegramException as e:
                code = getattr(e, "error_code", None)
                if attempt >= _TG_RETRY_MAX:
                    raise
                if code == 429:
                    if getattr(globals().get("_PHASE_TL"), "depth", 0) > 0:
                        raise   # o'yin bosqichi qulf ostida — uxlab turmaymiz, xabar navbatga olinadi (_phase_aware_send)
                    if _tg_retry_after_seconds(e) > _TG_RETRY_AFTER_CAP:
                        raise   # uzoq kutish — oqimni band qilmaymiz (xabar yuborish navbatga olinadi)
                    wait_s = _tg_retry_after_seconds(e) + 1
                elif code in _TG_TRANSIENT_CODES:
                    wait_s = min(2 ** (attempt - 1), 8)
                else:
                    raise
                _logger.warning("⏳ Telegram %s xatosi (%s-urinish) — %s soniyadan keyin qayta uriniladi.",
                                code, attempt, wait_s)
                time.sleep(wait_s)
            except (_rq.exceptions.ConnectionError, _rq.exceptions.Timeout) as e:
                if attempt >= _TG_RETRY_MAX:
                    raise
                wait_s = min(2 ** (attempt - 1), 8)
                _logger.warning("⏳ Tarmoq xatosi (%s-urinish) — %s soniyadan keyin qayta uriniladi: %s",
                                attempt, wait_s, e)
                time.sleep(wait_s)
    return wrapper


if getattr(telebot.apihelper, "_make_request", None) is not None:
    telebot.apihelper._make_request = _make_retrying_request(telebot.apihelper._make_request)


# ================================================================================
# 🛡 XAVFSIZ TAYMER: o'yin bosqichlarini (tun/kun/ovoz/osish/oxirgi so'z...) boshqaradigan
# har bir threading.Timer endi istisno bilan "jimgina o'lmaydi" — xato logga yoziladi va
# egaga xabar beriladi. Bu bilan bitta kutilmagan xato butun bosqichni muzlatib qo'ymaydi.
# ================================================================================
class _SafeTimer(threading.Timer):
    def __init__(self, interval, function, args=None, kwargs=None):
        def _guarded(*a, **k):
            try:
                return function(*a, **k)
            except Exception as exc:
                try:
                    notify_owner_of_error(
                        f"taymer ({getattr(function, '__name__', 'callback')})", exc)
                except Exception:
                    _logger.exception("taymer xatosi")
        super().__init__(interval, _guarded, args=args, kwargs=kwargs)


threading.Timer = _SafeTimer


def _thread_excepthook(args):
    """Har qanday boshqa fon oqimi kutilmagan xato bilan o'lsa — jimgina emas, logga yoziladi."""
    if args.exc_type is SystemExit:
        return
    try:
        _logger.error("🧵 Oqim xato bilan to'xtadi (%s)", getattr(args.thread, "name", "?"),
                      exc_info=(args.exc_type, args.exc_value, args.exc_traceback))
    except Exception:
        pass


threading.excepthook = _thread_excepthook


