def theron_available():
    """Theron ishga tayyor-tayyormasligini tekshiradi. 🔧 O'ZGARTIRILDI: Theron
    endi tashqi AI (Gemini/Grok) API kaliti kerak bo'lmagan, TO'LIQ LOKAL
    (kod bilan yozilgan) yordamchi — shuning uchun har doim TAYYOR, hech qanday
    API kalitiga bog'liq emas."""
    return True


def _theron_today():
    return time.strftime("%Y-%m-%d")


def theron_check_and_consume_quota(uid, is_elite_user):
    """Foydalanuvchining kunlik AI-savol limiti tugamaganini tekshiradi va
    ishlatilgan deb hisoblaydi. Owner uchun limit umuman qo'llanmaydi.
    Qaytaradi: (ruxsat_bormi: bool, qolgan_soni: int)"""
    if is_owner(uid):
        return True, 999
    limit = THERON_ELITE_DAILY_LIMIT if is_elite_user else THERON_FREE_DAILY_LIMIT
    today = _theron_today()
    with _THERON_USAGE_LOCK:
        rec = _THERON_USAGE.get(uid)
        if not rec or rec["date"] != today:
            rec = {"date": today, "count": 0}
        if rec["count"] >= limit:
            _THERON_USAGE[uid] = rec
            return False, 0
        rec["count"] += 1
        _THERON_USAGE[uid] = rec
        return True, max(0, limit - rec["count"])


def _theron_call_one_model(model, payload):
    """Bitta model bilan bitta urinish. Muvaffaqiyatli bo'lsa matnni qaytaradi,
    model TOPILMASA (404 — o'chirilgan/eskirgan) maxsus belgi qaytaradi, boshqa
    xatolikda — aniq sabab (status kod + Google'ning javob matni) bilan
    Exception ko'taradi, shu orqali diagnostika aniq bo'ladi (masalan: API
    kalit noto'g'ri = 400/403, kunlik limit tugagan = 429)."""
    resp = requests.post(_gemini_url_for(model), params={"key": GEMINI_API_KEY}, json=payload, timeout=25)
    if resp.status_code == 404:
        return "__MODEL_NOT_FOUND__"
    if resp.status_code >= 400:
        detail = resp.text[:300] if resp.text else "(javob matni yo'q)"
        raise RuntimeError(f"Gemini API xatoligi (model={model}, status={resp.status_code}): {detail}")
    data = resp.json()
    cands = data.get("candidates") or []
    if not cands:
        return None
    parts = cands[0].get("content", {}).get("parts") or []
    text = "".join(p.get("text", "") for p in parts).strip()
    return text or None


def _theron_raw_call(system_instruction, user_prompt, history=None, max_tokens=500, temperature=0.9):
    """Gemini API'ga so'rov — avval ESLAB QOLINGAN (oldin ishlagan) model bilan
    sinaydi, agar u endi mavjud bo'lmasa (Google o'chirib tashlagan bo'lsa),
    ro'yxatdagi keyingi modellarga avtomatik o'tadi. Har qanday yakuniy
    xatolikda None qaytaradi — chaqiruvchi tomon buni albatta "AI hozircha
    javob berolmadi" kabi yumshoq xabarga aylantiradi, hech qachon
    foydalanuvchiga xom Python xatoligini ko'rsatmaydi. YAKUNIY muvaffaqiyatsizlikda
    esa bot egasiga ANIQ sabab (notify_owner_of_error orqali) yuboriladi —
    "AI ishlamayapti" degan noaniqlik endi qolmaydi.

    🔧 O'ZGARTIRILDI: bot egasining talabiga ko'ra Theron endi tashqi AI
    xizmatlariga (Gemini, Grok va h.k.) UMUMAN murojaat qilmaydi — bu funksiya
    ataylab har doim None qaytaradi, shunda barcha chaqiruvchi joylar o'zining
    tayyor LOKAL (kod bilan yozilgan) javobiga o'tadi. Kod GEMINI_API_KEY
    o'chirilmagan holatda ham ishlaydi — xavfsizlik uchun ikki qavat qilib
    qo'yilgan (bu qator + pastdagi eski tekshiruv)."""
    return None  # 🚫 tashqi AI butunlay o'chirilgan — Theron endi 100% lokal ishlaydi
    if not GEMINI_API_KEY:
        return None

    contents = []
    for turn in (history or []):
        contents.append({"role": turn["role"], "parts": [{"text": turn["text"]}]})
    contents.append({"role": "user", "parts": [{"text": user_prompt}]})
    payload = {
        "system_instruction": {"parts": [{"text": system_instruction}]},
        "contents": contents,
        "generationConfig": {
            "maxOutputTokens": max_tokens,
            "temperature": temperature,
        },
        "safetySettings": [
            {"category": c, "threshold": "BLOCK_ONLY_HIGH"}
            for c in (
                "HARM_CATEGORY_HARASSMENT", "HARM_CATEGORY_HATE_SPEECH",
                "HARM_CATEGORY_SEXUALLY_EXPLICIT", "HARM_CATEGORY_DANGEROUS_CONTENT",
            )
        ],
    }

    global _GEMINI_WORKING_MODEL
    # 1) Avval oldin ishlagani ma'lum bo'lgan modelni sinaymiz (tezroq — har
    #    safar butun ro'yxatni qaytadan aylanib chiqmaslik uchun)
    order = ([_GEMINI_WORKING_MODEL] if _GEMINI_WORKING_MODEL else []) + [
        m for m in GEMINI_MODEL_CANDIDATES if m != _GEMINI_WORKING_MODEL
    ]

    last_error = None
    for model in order:
        try:
            result = _theron_call_one_model(model, payload)
        except Exception as e:
            last_error = e
            continue
        if result == "__MODEL_NOT_FOUND__":
            # Bu model endi mavjud emas (Google o'chirgan) — jimgina keyingisiga o'tamiz
            _logger.warning("🧠 Theron: model '%s' topilmadi (404, ehtimol eskirgan) — keyingisiga o'tilmoqda", model)
            continue
        if result:
            with _GEMINI_MODEL_LOCK:
                _GEMINI_WORKING_MODEL = model  # ✅ ishladi — keyingi safar shundan boshlaymiz
            return result
        # bo'sh javob qaytdi — baribir shu model "topildi" hisoblanadi, boshqasiga o'tmaymiz
        return None

    # 🚨 Ro'yxatdagi BARCHA modellar muvaffaqiyatsiz bo'ldi — bu endi "kutilmagan"
    # holat, shuning uchun ANIQ sababni bot egasiga yuboramiz (throttling bilan,
    # notify_owner_of_error ichida allaqachon bor — 2 daqiqada bir marta).
    if last_error:
        notify_owner_of_error("Theron AI — barcha Gemini modellari sinab ko'rildi", last_error)
    else:
        notify_owner_of_error(
            "Theron AI — barcha modellar 404 qaytardi",
            RuntimeError(f"GEMINI_MODEL_CANDIDATES ro'yxatidagi hech biri topilmadi: {GEMINI_MODEL_CANDIDATES}"),
        )
    return None


