def theron_owner_report_text():
    """Owner uchun — botning real statistikasi asosida Theron'ning qisqa
    hisobot + tavsiyasini generatsiya qiladi. Statistikani biz o'zimiz DB'dan
    olib, AI'ga FAKT sifatida beramiz — AI hech qachon raqamni o'zidan
    o'ylab topmaydi, faqat sharhlaydi va maslahat beradi."""
    try:
        with db_lock:
            cur.execute("SELECT COUNT(*) FROM users")
            total_users = cur.fetchone()[0]
            cur.execute("SELECT charges FROM users WHERE charges IS NOT NULL")
            now = time.time()
            elite_users = 0
            for (charges_json,) in cur.fetchall():
                try:
                    if json.loads(charges_json or "{}").get("vip_until", 0) > now:
                        elite_users += 1
                except Exception:
                    pass
            cur.execute("SELECT COUNT(*) FROM users WHERE last_bonus_date = ?", (time.strftime("%Y-%m-%d"),))
            active_today = cur.fetchone()[0]
        active_games = len(GAMES)
    except Exception as e:
        _logger.warning("Theron hisobot uchun statistika olishda xatolik: %s", e)
        total_users = elite_users = active_today = active_games = 0

    facts = (
        f"Jami ro'yxatdan o'tgan foydalanuvchilar: {total_users} ta.\n"
        f"Hozirgi faol ELITE a'zolar: {elite_users} ta.\n"
        f"Bugun faol bo'lgan (bonus olgan) foydalanuvchilar: {active_today} ta.\n"
        f"Hozir davom etayotgan o'yinlar soni: {active_games} ta."
    )
    advice = random.choice([
        "Tavsiya: faol foydalanuvchilar uchun yangi promo-kod chiqarsangiz, qaytish darajasi oshishi mumkin.",
        "Tavsiya: yangi turnir e'lon qilish faollikni yaxshi ko'taradi — qulay payt bo'lishi mumkin.",
        "Tavsiya: ELITE a'zolar sonini oshirish uchun cheklangan muddatli chegirma e'lon qilishni ko'rib chiqing.",
    ])
    return (
        f"🧠 <b>{THERON_NAME}dan hisobot:</b>\n\n"
        f"Assalomu alaykum, xo'jayin! Bugungi holat:\n{facts}\n\n💡 {advice}"
    )


