def theron_build_user_context(uid):
    """Foydalanuvchi haqida DB'dan REAL ma'lumot yig'ib, AI'ga tushunarli
    matn shaklida beradi — shaxsiylashtirilgan tavsiyalar aynan shu orqali
    ishlaydi (AI hech narsani o'ylab topmaydi, faqat bergan faktlarimizni
    sharhlaydi)."""
    try:
        u = user_dict(uid)
        elite = is_elite(uid)
        elite_left = elite_days_left(uid) if elite else 0
        clan_owner_id = find_member_clan(uid) if "find_member_clan" in globals() else None
        clan = get_clan(clan_owner_id) if clan_owner_id else None
        clan_line = f"ha — {clan['name']}" if clan else "yo'q"
        return (
            f"Foydalanuvchi ismi: {u.get('name')}.\n"
            f"O'ynagan o'yinlar: {u.get('games', 0)}, g'alabalar: {u.get('wins', 0)}.\n"
            f"Balans: {u.get('dollar', 0)}$ / {u.get('diamond', 0)}💎 / {u.get('coin', 0)}🪙.\n"
            f"Duel statistikasi: {u.get('duel_wins', 0)} g'alaba / {u.get('duel_losses', 0)} mag'lubiyat.\n"
            f"ELITE holati: {'faol, ' + str(elite_left) + ' kun qoldi' if elite else 'faol emas'}.\n"
            f"Klan a'zosimi: {clan_line}."
        )
    except Exception as e:
        _logger.warning("Theron uchun foydalanuvchi konteksti yig'ishda xatolik: %s", e)
        return "Foydalanuvchi haqida qo'shimcha ma'lumot yig'ib bo'lmadi."


