def faq_lookup(question):
    """Savolni FAQ bazasidan qidiradi. Aniq so'z mos kelsa yuqori ball,
    "yaqin" (1-2 harf farqli/adashgan) so'z topilsa ham past ball beriladi —
    shu orqali kichik xato-yozuvlarda ham to'g'ri mavzu topiladi. Ishonchli
    darajada mos kelgan javob topilmasa — None qaytaradi (bu holda cmd_theron
    haqiqiy AI'ga murojaat qiladi)."""
    norm = _faq_normalize(question)
    if not norm:
        return None
    words = norm.split()
    best_answer, best_score = None, 0
    for entry in FAQ_KB:
        score = 0
        for kw in entry["keywords"]:
            kw_norm = _faq_normalize(kw)
            if kw_norm in norm:
                score += 3  # to'liq ibora topildi — juda ishonchli
                continue
            kw_words = kw_norm.split()
            matched_words = 0
            for kww in kw_words:
                if kww in words:
                    matched_words += 1
                elif difflib.get_close_matches(kww, words, n=1, cutoff=0.72):
                    matched_words += 1  # 🔧 1-2 harf adashgan bo'lsa ham tanish
            if kw_words and matched_words == len(kw_words):
                score += 2
        if score > best_score:
            best_score, best_answer = score, entry["answer"]
    return best_answer if best_score >= 2 else None



def theron_answer_user(uid, question, is_elite_user):
    """Elite/oddiy foydalanuvchining savoliga javob — TO'LIQ LOKAL mexanizm:
    1) Avval FAQ bazasi (faq_lookup — cmd_theron/free-chat ichida bundan oldin
       ham tekshiriladi, lekin bu yerda ham qayta tekshiriladi — funksiya
       mustaqil chaqirilishi mumkin bo'lgani uchun xavfsizroq).
    2) 20 ta "aqlli funksiya" (THERON_SMART_FUNCS) — foydalanuvchining REAL
       ma'lumotlari (balans, statistika, klan va h.k.) asosida DINAMIK javob.
    3) 10 ta o'yin-strategiya maslahati (THERON_GAME_TIPS).
    4) Hech biri mos kelmasa — xushmuomala, xilma-xil (tasodifiy) umumiy
       javob (THERON_FALLBACK_REPLIES)."""
    norm = _faq_normalize(question)
    words = norm.split()

    faq_answer = faq_lookup(question)
    if faq_answer:
        return faq_answer

    if is_owner(uid):
        for intent in THERON_OWNER_FUNCS:
            if _theron_keywords_match(intent["keywords"], norm, words):
                try:
                    return intent["fn"](uid, is_elite_user)
                except Exception as e:
                    _logger.warning("Theron owner funksiyasida xatolik (%s): %s", intent.get("name"), e)

    for intent in THERON_SMART_FUNCS:
        if _theron_keywords_match(intent["keywords"], norm, words):
            try:
                return intent["fn"](uid, is_elite_user)
            except Exception as e:
                _logger.warning("Theron aqlli funksiyasida xatolik (%s): %s", intent.get("name"), e)

    for tip in THERON_GAME_TIPS:
        if _theron_keywords_match(tip["keywords"], norm, words):
            return tip["answer"]

    result = random.choice(THERON_FALLBACK_REPLIES)
    if not is_elite_user and random.random() < 0.35:
        result += "\n\n💎 <i>ELITE a'zolikda Theron yanada ko'proq va chuqurroq maslahat beradi — /elite</i>"
    return result


def _theron_keywords_match(keyword_groups, norm, words):
    """Bitta intentning kalit-so'z guruhlaridan KAMIDA bittasi savolda
    uchrasa (to'liq ibora sifatida yoki har bir so'zi alohida-alohida
    topilsa) — True qaytaradi. difflib orqali kichik xato-yozuvlarga ham
    chidamli."""
    for kw in keyword_groups:
        kw_norm = _faq_normalize(kw)
        if kw_norm and kw_norm in norm:
            return True
        kw_words = kw_norm.split()
        if kw_words and all(
            (kww in words) or difflib.get_close_matches(kww, words, n=1, cutoff=0.72)
            for kww in kw_words
        ):
            return True
    return False


