def _migration_ignore(exc, what):
    """Migratsiya (ALTER/INDEX) xatosi: "ustun allaqachon bor" — KUTILGAN holat (jimgina o'tkaziladi);
    boshqa har qanday xato (qulf, buzilgan baza, noto'g'ri SQL) — KUTILMAGAN, ko'rinadigan logga yoziladi."""
    msg = str(exc).lower()
    if "duplicate column name" in msg or "already exists" in msg:
        return
    _logger.warning("Migratsiya bajarilmadi (%s): %s", what, exc)


def _column_exists(table, column):
    try:
        cur.execute(f"PRAGMA table_info({_sql_ident(table)})")
        return any(row[1] == column for row in cur.fetchall())
    except Exception:
        return False


@bot.message_handler(commands=["theron"])
def cmd_theron(message):
    """🧠 Theron bilan suhbat. Ish tartibi:
    1) Savol bo'lmasa — tanishtiruv.
    2) Savol FAQ bazasida (eng ko'p so'raladigan mavzular) topilsa — DARHOL
       javob beriladi, AI so'rov QILINMAYDI, kunlik limitdan HECH NARSA
       sarflanmaydi (bu tezkor va bepul yo'l).
    3) FAQ'da topilmasa — haqiqiy AI (Gemini) chaqiriladi, bu safar kunlik
       limitdan 1 ta sarflanadi (owner uchun limit yo'q — u har doim
       ustuvor va cheklovsiz)."""
    try:
        maybe_capture_owner(message.from_user)
        uid = message.from_user.id
        parts = message.text.split(maxsplit=1)
        question = parts[1].strip() if len(parts) > 1 else ""

        if not question:
            bot.reply_to(
                message,
                f"🧠 <b>{THERON_NAME}</b> {THERON_MEANING}\n\n"
                "Savolingizni yozing — javob beraman!\n\n"
                "✍️ <code>/theron savolingiz</code>\n"
                f"👑 ELITE: kuniga {THERON_ELITE_DAILY_LIMIT} ta | 👤 Oddiy: kuniga {THERON_FREE_DAILY_LIMIT} ta\n"
                "📚 Mashhur mavzular (ELITE, klan, duel, nikoh) — limitsiz javob beraman!",
            )
            return

        # 1) 📚 Avval "tezkor bilim bazasi" (FAQ) — limitsiz, AI shart emas
        faq_answer = faq_lookup(question)
        if faq_answer:
            bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {faq_answer}")
            return

        # 2) FAQ'da topilmadi — haqiqiy AI kerak
        if not theron_available():
            bot.reply_to(
                message,
                f"🧠 <b>{THERON_NAME}</b> {THERON_MEANING}\n\n"
                "Bu savolga tayyor javobim yo'q, AI xizmati hozircha o'chirilgan. "
                "Boshqa buyruqlar /yordam orqali ishlayveradi."
            )
            return

        elite_user = is_elite(uid)
        allowed, remaining = theron_check_and_consume_quota(uid, elite_user)
        if not allowed:
            bot.reply_to(
                message,
                f"⏳ Bugungi {THERON_NAME} bilan chuqur AI-suhbat limitingiz tugadi.\n"
                + ("Ertaga qayta urinib ko'ring." if elite_user else
                   f"👑 ELITE a'zolikda kunlik limit {THERON_ELITE_DAILY_LIMIT} tagacha — /elite orqali oling."),
            )
            return

        try:
            bot.send_chat_action(message.chat.id, "typing")
        except Exception:
            pass

        answer = theron_answer_user(uid, question, elite_user)
        if not answer:
            bot.reply_to(message, f"⚠️ {THERON_NAME} hozir javob berolmadi (AI xizmati vaqtincha ishlamayapti). Birozdan keyin qayta urinib ko'ring.")
            return

        suffix = f"\n\n<i>💬 Bugun yana {remaining} ta chuqur AI-savol qoldi.</i>" if not is_owner(uid) else ""
        bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {answer}{suffix}")
    except Exception as e:
        notify_owner_of_error("cmd_theron (/theron buyrug'i)", e)
        try:
            bot.reply_to(message, f"⚠️ {THERON_NAME} bilan bog'lanishda xatolik yuz berdi. Qaytadan urinib ko'ring.")
        except Exception:
            pass


