USER_COLS = ["user_id", "name", "dollar", "diamond", "coin", "games", "wins",
             "shield", "inventory", "married_to", "last_bonus_date", "charges",
             "duel_wins", "duel_losses", "banned", "married_at", "bio", "fav_role"]


def get_user_row(uid, name=None):
    with db_lock:
        cur.execute("SELECT * FROM users WHERE user_id=?", (uid,))
        row = cur.fetchone()
        if row is None:
            cur.execute("INSERT INTO users (user_id, name) VALUES (?,?)", (uid, name or str(uid)))
            try:
                cur.execute("UPDATE users SET first_seen=? WHERE user_id=?", (time.time(), uid))
            except Exception:
                pass
            conn.commit()
            cur.execute("SELECT * FROM users WHERE user_id=?", (uid,))
            row = cur.fetchone()
        elif name and row[1] != name:
            cur.execute("UPDATE users SET name=? WHERE user_id=?", (name, uid))
            conn.commit()
            row = list(row)
            row[1] = name
            row = tuple(row)
        return row


def user_dict(uid, name=None):
    row = get_user_row(uid, name)
    d = dict(zip(USER_COLS, row))
    if d.get("charges") is None:
        d["charges"] = "{}"
    if d.get("duel_wins") is None:
        d["duel_wins"] = 0
    if d.get("duel_losses") is None:
        d["duel_losses"] = 0
    if d.get("banned") is None:
        d["banned"] = 0
    if d.get("married_at") is None:
        d["married_at"] = ""
    if d.get("bio") is None:
        d["bio"] = ""
    if d.get("fav_role") is None:
        d["fav_role"] = ""
    return d


def update_user(uid, **fields):
    with db_lock:
        keys = ", ".join(f"{_sql_ident(k, _UPDATABLE_USER_COLUMNS)}=?" for k in fields)
        vals = list(fields.values()) + [uid]
        cur.execute(f"UPDATE users SET {keys} WHERE user_id=?", vals)
        conn.commit()


_LEDGER_SINCE_READY = False


def _ledger_record(uid, dollar=0, diamond=0, coin=0):
    """📒 Joriy tranzaksiya ichida (db_lock ostida) valyuta o'zgarishini jurnalga yozadi.
    Xatolik hech qachon asosiy pul amaliyotini to'xtatmaydi."""
    global _LEDGER_SINCE_READY
    try:
        now = time.time()
        for cname, delta in (("dollar", dollar), ("diamond", diamond), ("coin", coin)):
            if delta:
                cur.execute("INSERT INTO top_ledger (user_id, currency, delta, ts) VALUES (?,?,?,?)",
                            (uid, cname, int(delta), now))
        if not _LEDGER_SINCE_READY:
            cur.execute("INSERT OR IGNORE INTO bot_settings (key, value) VALUES ('top_ledger_since', ?)", (str(int(now)),))
            _LEDGER_SINCE_READY = True
    except Exception:
        _logger.warning("top_ledger yozilmadi (uid=%s)", uid, exc_info=True)


# 💎🪙 IQTISOD QOIDASI: 💎 Olmos faqat ⭐ Stars orqali (yoki egasi tarqatganda), 🪙 Coin faqat kurs
# bo'yicha sotib olinadi. Shu sabab add_balance orqali musbat 💎/🪙 faqat ruxsat etilgan manbadan
# (src) kiritiladi; boshqa har qanday "bepul" 💎/🪙 avtomatik 💵 ga aylantiriladi (fail-safe).
FREE_DIAMOND_DOLLAR_VALUE = 40    # bepul mukofotda 1 💎 o'rniga beriladigan 💵 (o'yin-ichi qiymat)
FREE_COIN_DOLLAR_VALUE = 3000     # (faqat himoya; hech bir joydan bepul coin chiqmaydi)
PREMIUM_CREDIT_SRC = frozenset({"refund", "transfer", "market", "owner"})
CHANNEL_SUB_BONUS = 5   # 📣 kanalga obuna bo'lgan o'yinchiga har o'yindan keyin qo'shimcha $


def add_balance_as(src, uid, **kw):
    """Ruxsat etilgan manbadan (qaytarish/o'tkazma/bozor/egasi) balans qo'shish."""
    return add_balance(uid, src=src, **kw)


def add_balance(uid, dollar=0, diamond=0, coin=0, ledger=True, src=None):
    """Atomik: bitta SQL UPDATE ichida o'qish+yozish — parallel chaqiruvlarda
    pul yo'qolib/qo'shilib ketishining oldini oladi. MAX(0, ...) manfiyga
    tushib ketmasligini kafolatlaydi.
    🔒 src ruxsatsiz bo'lsa musbat 💎/🪙 dollarga aylantiriladi (bepul premium valyuta yo'q)."""
    if (diamond > 0 or coin > 0) and src not in PREMIUM_CREDIT_SRC:
        _logger.warning("Ruxsatsiz premium kredit dollarga aylantirildi (uid=%s d=%s c=%s)", uid, diamond, coin)
        dollar += max(diamond, 0) * FREE_DIAMOND_DOLLAR_VALUE + max(coin, 0) * FREE_COIN_DOLLAR_VALUE
        diamond, coin = min(diamond, 0), min(coin, 0)
    with db_lock:
        cur.execute(
            "UPDATE users SET dollar=MAX(0, dollar+?), diamond=MAX(0, diamond+?), "
            "coin=MAX(0, coin+?) WHERE user_id=?",
            (dollar, diamond, coin, uid),
        )
        if ledger and cur.rowcount > 0:   # ledger=False: sovg'a/egasi tuzatishi — "topilgan daromad"ga kirmaydi
            _ledger_record(uid, dollar=dollar, diamond=diamond, coin=coin)
        conn.commit()


def try_charge(uid, currency, amount):
    """Atomik pul yechish: balans yetarli bo'lsagina bitta UPDATE bilan
    kamaytiradi va True qaytaradi; aks holda hech narsa o'zgarmaydi va
    False qaytaradi. currency: 'dollar' | 'diamond' | 'coin'."""
    if currency not in ("dollar", "diamond", "coin"):
        raise ValueError("noto'g'ri valyuta: %r" % currency)
    if amount <= 0:
        return True
    with db_lock:
        cur.execute(
            f"UPDATE users SET {currency}={currency}-? WHERE user_id=? AND {currency}>=?",
            (amount, uid, amount),
        )
        ok = cur.rowcount > 0
        if ok:
            _ledger_record(uid, **{currency: -amount})
        conn.commit()
        return ok


def _atomic_json_field_update(uid, field, mutate_fn):
    """Generik atomik o'qi-o'zgartir-yoz: JSON ustun (inventory/charges va h.k.)
    uchun butun o'qish+mutatsiya+yozish bitta db_lock ichida bajariladi, shu
    bilan parallel chaqiruvlar orasidagi race-condition oldini oladi.
    mutate_fn(value) -> (new_value, result) qaytarishi kerak."""
    _sql_ident(field, _JSON_USER_FIELDS)
    with db_lock:
        cur.execute(f"SELECT {field} FROM users WHERE user_id=?", (uid,))
        row = cur.fetchone()
        raw = row[0] if row else None
        try:
            value = json.loads(raw) if raw else ({} if field == "charges" else [])
        except Exception:
            value = {} if field == "charges" else []
        new_value, result = mutate_fn(value)
        cur.execute(f"UPDATE users SET {field}=? WHERE user_id=?", (json.dumps(new_value), uid))
        conn.commit()
        return result


def add_inventory_item(uid, item_name):
    def _mut(inv):
        inv = list(inv)
        inv.append(item_name)
        return inv, True
    return _atomic_json_field_update(uid, "inventory", _mut)


def remove_inventory_item_by_index(uid, index):
    """Qora bozorga sotuvga qo'yish uchun — inventardagi index bo'yicha buyumni
    olib tashlaydi va nomini qaytaradi. Atomik: o'qish+pop+yozish bitta lock ichida."""
    def _mut(inv):
        inv = list(inv)
        if index < 0 or index >= len(inv):
            return inv, None
        item = inv.pop(index)
        return inv, item
    return _atomic_json_field_update(uid, "inventory", _mut)


def _shield_expired_purge(uid):
    """Do'kondan olingan himoyaning 7 kunlik muddati tugagan bo'lsa — qalqonlarni nolga tushiradi."""
    try:
        with db_lock:
            cur.execute("SELECT charges, shield FROM users WHERE user_id=?", (uid,))
            row = cur.fetchone()
            if not row or not row[1]:
                return
            ch = json.loads(row[0] or "{}")
            t = ch.get("_shield_exp")
            if t and time.time() >= float(t):
                ch.pop("_shield_exp", None)
                cur.execute("UPDATE users SET shield=0, charges=? WHERE user_id=?", (json.dumps(ch), uid))
                conn.commit()
    except Exception:
        _logger.warning("shield purge xatosi", exc_info=True)


def add_shield(uid, n=1, ttl=None):
    """ttl (soniya) berilsa — qalqon muddati belgilanadi (do'kon xaridi). Sovg'a/mukofot qalqoni muddatsiz."""
    _shield_expired_purge(uid)
    with db_lock:
        cur.execute("UPDATE users SET shield=MAX(0, shield+?) WHERE user_id=?", (n, uid))
        if ttl and n > 0:
            cur.execute("SELECT charges FROM users WHERE user_id=?", (uid,))
            row = cur.fetchone()
            try:
                ch = json.loads((row[0] if row else None) or "{}")
            except Exception:
                ch = {}
            ch["_shield_exp"] = time.time() + min(ttl, ITEM_TTL_SECONDS)
            cur.execute("UPDATE users SET charges=? WHERE user_id=?", (json.dumps(ch), uid))
        conn.commit()


def sweep_expired_items():
    """Davriy tozalash: muddati o'tgan zaryad/qalqonlarni bazadan olib tashlaydi (profil to'g'ri ko'rinishi uchun)."""
    now = time.time()
    with db_lock:
        cur.execute("SELECT user_id FROM users WHERE charges LIKE '%\"_exp\"%' OR charges LIKE '%_shield_exp%'")
        uids = [r[0] for r in cur.fetchall()]
    for uid in uids:
        _shield_expired_purge(uid)
        try:
            with db_lock:
                cur.execute("SELECT charges FROM users WHERE user_id=?", (uid,))
                row = cur.fetchone()
                raw = json.loads((row[0] if row else None) or "{}")
                pr = _prune_charges(raw)
                if pr != raw:
                    cur.execute("UPDATE users SET charges=? WHERE user_id=?", (json.dumps(pr), uid))
                    conn.commit()
        except Exception:
            _logger.warning("sweep xatosi (uid=%s)", uid, exc_info=True)


def consume_shield(uid):
    """Atomik: shield>0 bo'lsagina 1 ta kamaytiradi va True qaytaradi."""
    _shield_expired_purge(uid)
    with db_lock:
        cur.execute("UPDATE users SET shield=shield-1 WHERE user_id=? AND shield>0", (uid,))
        conn.commit()
        return cur.rowcount > 0


# ---- "charges" (jangovar effektlar) tizimi — har bir do'kon buyumi shu orqali ishlaydi ----

ITEM_TTL_SECONDS = 7 * 86400   # 🕒 do'kon buyumlari ENG KO'PI 7 kun amal qiladi (so'ngra yonib ketadi)


def _prune_charges(ch):
    """Muddati o'tgan buyum zaryadlarini (ch['_exp'][kalit] < hozir) olib tashlaydi. Yangi dict qaytaradi."""
    ch = dict(ch)
    exp = ch.get("_exp")
    if not isinstance(exp, dict) or not exp:
        return ch
    now = time.time()
    keep = {}
    for k, t in exp.items():
        try:
            if now >= float(t):
                ch.pop(k, None)
                continue
        except Exception:
            pass
        keep[k] = t
    ch["_exp"] = keep
    return ch


def get_charges(uid):
    u = user_dict(uid)
    try:
        return _prune_charges(json.loads(u.get("charges") or "{}"))
    except Exception:
        return {}


def set_charges(uid, ch):
    update_user(uid, charges=json.dumps(ch))


def add_charge(uid, key, n=1, ttl=None, perm=False):
    """Zaryad qo'shadi. ttl (soniya) berilsa — buyum shu muddatdan keyin yonib ketadi (har xaridda yangilanadi)."""
    def _mut(ch):
        ch = _prune_charges(ch)
        ch[key] = ch.get(key, 0) + n
        if ttl:
            exp = dict(ch.get("_exp") or {})
            exp[key] = time.time() + min(ttl, ITEM_TTL_SECONDS)
            ch["_exp"] = exp
        elif perm:
            exp = dict(ch.get("_exp") or {})
            if key in exp:
                exp.pop(key, None)   # muddatsiz buyum: eski muddat yozuvi olib tashlanadi
                ch["_exp"] = exp
        return ch, True
    return _atomic_json_field_update(uid, "charges", _mut)


def use_charge(uid, key, n=1):
    """Atomik: zaryad yetarli bo'lsagina kamaytiradi va True qaytaradi."""
    def _mut(ch):
        ch = _prune_charges(ch)
        if ch.get(key, 0) >= n:
            ch[key] -= n
            return ch, True
        return ch, False
    return _atomic_json_field_update(uid, "charges", _mut)


def set_charge_value(uid, key, value):
    def _mut(ch):
        ch = dict(ch)
        ch[key] = value
        return ch, True
    return _atomic_json_field_update(uid, "charges", _mut)


