_GROUP_MEMBER_CACHE = {}  # (chat_id, user_id) -> oxirgi yozilgan vaqt (ortiqcha DB yozuvlarini kamaytirish uchun)
_GROUP_MEMBER_CACHE_TTL = 3600  # soniya — shu vaqt ichida qayta yozilmaydi


_LAST_MSG_AT = {}   # (chat_id, user_id) -> oxirgi xabar vaqti (xotirada; "onlayn" aniqlash uchun)


def track_group_member(chat_id, user_id):
    key = (chat_id, user_id)
    now = time.time()
    _LAST_MSG_AT[key] = now
    if _GROUP_MEMBER_CACHE.get(key, 0) > now - _GROUP_MEMBER_CACHE_TTL:
        return
    _GROUP_MEMBER_CACHE[key] = now
    try:
        with db_lock:
            cur.execute(
                "INSERT OR REPLACE INTO group_members (chat_id, user_id, last_seen) VALUES (?,?,?)",
                (chat_id, user_id, int(now)),
            )
            conn.commit()
    except Exception as e:
        _logger.warning("track_group_member xatolik: %s", e)


def get_group_member_ids(chat_id):
    with db_lock:
        cur.execute("SELECT user_id FROM group_members WHERE chat_id=?", (chat_id,))
        return {r[0] for r in cur.fetchall()}


def list_known_groups():
    with db_lock:
        cur.execute("SELECT chat_id, title FROM known_groups")
        return cur.fetchall()


