def error_notify_enabled():
    """🔔 Bot egasiga xatolik xabarnomalari yuborilishi kerakmi — bazadagi
    sozlamadan o'qiydi. Sozlama umuman kiritilmagan bo'lsa (masalan bot
    birinchi marta ishga tushirilganda), DEFAULT holatda YOQILGAN deb
    hisoblanadi — shuning uchun xato haqida darhol xabar berib turadi."""
    val = get_setting("error_notify_enabled")
    return val != "0"


@bot.message_handler(commands=["xatolik_bildirish"])
def cmd_xatolik_bildirish(message):
    """🔔/🔕 Bot egasiga (OWNER) botda yuz beradigan xatoliklar haqidagi
    avtomatik Telegram xabarnomalarini YOQIB yoki O'CHIRIB turadigan buyruq.
    Faqat bot egasi uchun ishlaydi. Argumentsiz chaqirilsa — hozirgi holatni
    teskarisiga o'zgartiradi (toggle); "/xatolik_bildirish yoq" yoki
    "/xatolik_bildirish ochiq" — majburan yoqadi; "/xatolik_bildirish off"
    yoki "/xatolik_bildirish yopiq" — majburan o'chiradi."""
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    parts = message.text.split(maxsplit=1)
    arg = parts[1].strip().lower() if len(parts) > 1 else None

    current = error_notify_enabled()
    if arg in ("on", "yoq", "yoqish", "yoqilgan", "ochiq", "ochish", "yes", "1"):
        new_state = True
    elif arg in ("off", "ochiriq", "o'chir", "ochir", "o'chirish", "yopiq", "no", "0"):
        new_state = False
    else:
        new_state = not current  # 🔁 argument berilmasa — teskarisiga o'giradi

    set_setting("error_notify_enabled", "1" if new_state else "0")

    if new_state:
        bot.send_message(
            message.chat.id,
            "🔔 <b>Xatolik bildirishnomalari YOQILDI.</b>\n\n"
            "Botda kutilmagan xatolik yuz bersa, endi shu yerga (Telegram orqali) "
            "avtomatik xabar keladi.",
        )
    else:
        bot.send_message(
            message.chat.id,
            "🔕 <b>Xatolik bildirishnomalari O'CHIRILDI.</b>\n\n"
            "Botda xatolik yuz berganda endi bu yerga xabar KELMAYDI — xatolar "
            "faqat server log fayliga yozilib boradi. Qayta yoqish uchun: "
            "/xatolik_bildirish",
        )


def get_top_players(limit=10, member_ids=None):
    """👑 Qirol unvoni egalari tepada chiqadi, bot
    egasi reytingdan doim yashiriladi. member_ids berilsa (masalan bitta
    guruhning a'zolari), faqat o'sha ID'lardagi foydalanuvchilar hisobga olinadi."""
    with db_lock:
        # member_ids berilsa (guruh TOP'i) — LIMIT QO'YILMAYDI: aks holda global reytingda 500-o'rindan pastdagi
        # guruh a'zolari ro'yxatdan tushib qolardi.
        cur.execute("SELECT user_id, name, wins, dollar, charges FROM users ORDER BY wins DESC, dollar DESC"
                    + ("" if member_ids is not None else " LIMIT 500"))
        rows = cur.fetchall()
    normal, qirol = [], []
    for user_id, name, wins, dollar, charges_json in rows:
        if is_owner(user_id):
            continue
        if member_ids is not None and user_id not in member_ids:
            continue
        try:
            ch = json.loads(charges_json or "{}")
        except Exception:
            ch = {}
        entry = (user_id, name, wins, dollar, ch.get("qirol_until", 0) > time.time())
        (qirol if entry[4] else normal).append(entry)
    return (qirol + normal)[:limit]


TOP_PAGE_SIZE = 10  # 🔧 YANGI (#9): har sahifada nechta o'yinchi ko'rsatilishi


def build_top_text(page=0, chat_id=None):
    member_ids = get_group_member_ids(chat_id) if chat_id is not None else None
    rows = get_top_players(limit=_top_limit("wins"), member_ids=member_ids)  # ro'yxat uzunligi Owner Center'dan sozlanadi
    if not rows:
        return "🏆 Hozircha reyting bo'sh.", 1
    total_pages = max(1, (len(rows) + TOP_PAGE_SIZE - 1) // TOP_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * TOP_PAGE_SIZE: page * TOP_PAGE_SIZE + TOP_PAGE_SIZE]
    title = "🏆 <b>TOP O'YINCHILAR (g'alabalar bo'yicha)</b>" + (" — shu guruh" if chat_id is not None else "")
    lines = [title + "\n"]
    for i, (user_id, name, wins, dollar, is_qirol) in enumerate(chunk, page * TOP_PAGE_SIZE + 1):
        crown = "🐉 " if is_qirol else ""
        lines.append(f"{i}. {crown}{mention(user_id, name)} — {wins} g'alaba, ${dollar}")
    lines.append(f"\n📄 {page + 1}/{total_pages}-sahifa")
    return "\n".join(lines), total_pages


def get_top_by_field(field, limit=50, member_ids=None):
    """field: 'diamond', 'dollar', 'coin', 'games' yoki 'wins' — bot egasi reytingdan doim yashiriladi.
    member_ids berilsa, faqat o'sha ID'lar (masalan bitta guruh a'zolari) hisobga olinadi."""
    _sql_ident(field, _TOP_USER_FIELDS)
    with db_lock:
        cur.execute(f"SELECT user_id, name, {field}, charges FROM users ORDER BY {field} DESC"
                    + ("" if member_ids is not None else " LIMIT 500"))
        rows = cur.fetchall()
    result = []
    for user_id, name, value, charges_json in rows:
        if is_owner(user_id):
            continue
        if member_ids is not None and user_id not in member_ids:
            continue
        try:
            ch = json.loads(charges_json or "{}")
        except Exception:
            ch = {}
        result.append((user_id, name, value))
    return result[:limit]


