def _top_page_markup(kind, page, total_pages, scope="a"):
    if total_pages <= 1:
        return None
    kb = types.InlineKeyboardMarkup()
    row = []
    if page > 0:
        row.append(types.InlineKeyboardButton("◀️", callback_data=f"topPage|{kind}|{page - 1}|{scope}"))
    row.append(types.InlineKeyboardButton(f"{page + 1}/{total_pages}", callback_data=f"topPage|noop|0|{scope}"))
    if page < total_pages - 1:
        row.append(types.InlineKeyboardButton("▶️", callback_data=f"topPage|{kind}|{page + 1}|{scope}"))
    kb.row(*row)
    return kb


# ================================================================================
#  🏆 KENGAYTIRILGAN TOP TIZIMI
#   • Ruxsat: umumiy (global) TOP FAQAT haqiqiy bot egasiga (shaxsiy chat / egasining kanali).
#     Guruhda — har kim (admin ham) faqat O'Z guruhining TOP'ini ko'radi. Ruxsat HAR SAFAR
#     serverda bosgan odam va xabar joylashgan chat bo'yicha hisoblanadi — callback_data'dagi
#     scope belgisiga ishonilmaydi.
#   • Turlar: g'alaba, o'yinlar soni, joriy balans (💎/💵/🪙) va davr bo'yicha TOPILGAN
#     daromad (top_ledger jurnalidan), faollik ballari (kalendar davrlar).
#   • Ro'yxat uzunligi har tur uchun Owner Center'dan sozlanadi (3–90), sahifalanadi.
# ================================================================================

TOP_LIMIT_WINS = 50
TOP_LIMIT_GAMES = 50
TOP_LIMIT_DIAMOND = 50
TOP_LIMIT_DOLLAR = 50
TOP_LIMIT_COIN = 50
TOP_LIMIT_EARNED = 20
TOP_LIMIT_ACTIVE = 20
_TOP_LIMIT_VARS = {
    "wins": "TOP_LIMIT_WINS", "games": "TOP_LIMIT_GAMES", "diamond": "TOP_LIMIT_DIAMOND",
    "dollar": "TOP_LIMIT_DOLLAR", "coin": "TOP_LIMIT_COIN", "earn": "TOP_LIMIT_EARNED", "act": "TOP_LIMIT_ACTIVE",
}
TOP_DENIED_TEXT = ("🔒 Umumiy reyting faqat bot egasiga ko'rinadi.\n"
                   "O'z guruhingiz reytingini ko'rish uchun <code>/top</code> buyrug'ini guruhda yozing.")
_CUR_META = {"dollar": ("💵", "dollar"), "diamond": ("💎", "olmos"), "coin": ("🪙", "Hunter Coin")}


def _top_limit(group):
    try:
        v = int(globals().get(_TOP_LIMIT_VARS.get(group, ""), 50))
    except Exception:
        v = 50
    return max(1, min(90, v))


def _top_access(chat, user_id):
    """(chat_filter, scope, allowed). Reytinglar FAQAT bot egasi (yoki egasining kanali) uchun."""
    try:
        if is_owner_channel(chat) or (user_id and is_owner(user_id)):
            return None, "a", True
    except Exception:
        pass
    return None, "x", False


def _top_scope_for(chat, user_id):
    """Eski nom (moslik uchun). scope == 'x' — ruxsat yo'q."""
    cf, scope, _ok = _top_access(chat, user_id)
    return cf, scope


def _scope_members(message):
    """Guruhda — shu guruh a'zolari; global ruxsat bo'lsa — None (hammasi); ruxsat yo'q bo'lsa — bo'sh to'plam."""
    try:
        cf, scope, ok = _top_access(message.chat, message.from_user.id if message.from_user else None)
        if not ok:
            return set()
        if cf is not None:
            return get_group_member_ids(cf)
    except Exception:
        return set()
    return None


def _top_hidden(user_id, charges_json=None):
    """Bot egasi reytingda ko'rinmaydi."""
    return bool(is_owner(user_id))


def get_earned_top(currency, period, limit=20, member_ids=None):
    """Davr ichida TOPILGAN (ijobiy o'zgarishlar yig'indisi) valyuta bo'yicha reyting — top_ledger'dan.
    Joriy balans emas, davrda ishlab topilgani."""
    if currency not in _CUR_META:
        raise ValueError("noto'g'ri valyuta")
    since = _period_start(period)
    with db_lock:
        if member_ids is None:
            cur.execute("SELECT user_id, SUM(delta) AS s FROM top_ledger WHERE currency=? AND delta>0 AND ts>=? "
                        "GROUP BY user_id ORDER BY s DESC LIMIT ?", (currency, since, limit + 200))
        else:
            cur.execute("SELECT user_id, SUM(delta) AS s FROM top_ledger WHERE currency=? AND delta>0 AND ts>=? "
                        "GROUP BY user_id ORDER BY s DESC", (currency, since))
        rows = cur.fetchall()
    out = []
    for uid, total in rows:
        if member_ids is not None and uid not in member_ids:
            continue
        if _top_hidden(uid):
            continue
        out.append((uid, user_dict(uid).get("name") or "O'yinchi", int(total)))
        if len(out) >= limit:
            break
    return out


def _ledger_since_text():
    try:
        v = get_setting("top_ledger_since")
        if not v:
            with db_lock:
                cur.execute("SELECT MIN(ts) FROM top_ledger")
                r = cur.fetchone()
            v = int(r[0]) if r and r[0] else None
        if v:
            return time.strftime("%d.%m.%Y", time.gmtime(int(float(v)) + TOP_TZ_OFFSET_HOURS * 3600))
    except Exception:
        pass
    return None


def _build_ranked(title, rows, fmt, page, empty_text, note=""):
    if not rows:
        return empty_text, 1
    ps = max(1, int(TOP_PAGE_SIZE))
    total_pages = max(1, (len(rows) + ps - 1) // ps)
    page = max(0, min(page, total_pages - 1))
    lines = [title + "\n"]
    for i, (uid, name, val) in enumerate(rows[page * ps: page * ps + ps], page * ps + 1):
        lines.append(f"{i}. {mention(uid, name)} — {fmt(val)}")
    if note:
        lines.append("\n" + note)
    lines.append(f"\n📄 {page + 1}/{total_pages}-sahifa")
    return "\n".join(lines), total_pages


def build_top_any(kind, page=0, chat_id=None):
    """Barcha TOP turlari uchun yagona kirish nuqtasi. kind: wins | games | diamond | dollar | coin |
    earn:<valyuta>:<davr> | act:<davr>"""
    suffix = " — shu guruh" if chat_id is not None else ""
    members = get_group_member_ids(chat_id) if chat_id is not None else None
    if kind == "wins":
        return build_top_text(page, chat_id)
    if kind == "diamond":
        return build_top_diamond_text(page, chat_id)
    if kind == "dollar":
        return build_top_dollar_text(page, chat_id)
    if kind == "coin":
        rows = get_top_by_field("coin", limit=_top_limit("coin"), member_ids=members)
        return _build_ranked("🪙 <b>TOP ENG KO'P HUNTER COIN'I BOR O'YINCHILAR</b>" + suffix, rows,
                             lambda v: f"🪙 {v}", page, "🪙 Hozircha reyting bo'sh.")
    if kind == "games":
        rows = get_top_by_field("games", limit=_top_limit("games"), member_ids=members)
        return _build_ranked("🎮 <b>TOP ENG KO'P O'YNAGAN O'YINCHILAR</b>" + suffix, rows,
                             lambda v: f"{v} o'yin", page, "🎮 Hozircha reyting bo'sh.")
    if kind.startswith("earn:"):
        try:
            _, cname, period = kind.split(":")
            emoji, label = _CUR_META[cname]
        except Exception:
            return "⚠️ Noma'lum reyting turi.", 1
        rows = get_earned_top(cname, period, limit=_top_limit("earn"), member_ids=members)
        since = _ledger_since_text()
        note = f"<i>📒 Hisob {since} dan yuritiladi — undan oldingi daromad hisobga olinmaydi.</i>" if since else \
               "<i>📒 Daromad hisobi yangi yoqilgan — ma'lumot to'planib boradi.</i>"
        title = f"{emoji} <b>{PERIOD_LABELS.get(period, period)} TOPILGAN {label.upper()}</b>" + suffix
        return _build_ranked(title, rows, lambda v: f"{emoji} +{v}", page,
                             f"{emoji} {PERIOD_LABELS.get(period, period)} daromad reytingi hozircha bo'sh.\n{note}", note)
    if kind.startswith("act:"):
        period = kind.split(":", 1)[1]
        return build_points_top_text(period, chat_id=chat_id), 1
    return "⚠️ Noma'lum reyting turi.", 1


