def add_points(uid, points, reason=""):
    with db_lock:
        cur.execute(
            "INSERT INTO points_log (user_id, points, reason, ts) VALUES (?, ?, ?, ?)",
            (uid, points, reason, time.time()),
        )
        conn.commit()


TOP_TZ_OFFSET_HOURS = 5   # 🕔 Toshkent (UTC+5), DST yo'q


def _period_start(period, now=None):
    """📅 Kalendar davr boshi (Toshkent vaqti): kun = bugun 00:00, hafta = dushanba 00:00, oy = 1-sana 00:00."""
    now = time.time() if now is None else now
    off = TOP_TZ_OFFSET_HOURS * 3600
    shifted = now + off
    t = time.gmtime(shifted)
    day0 = shifted - (t.tm_hour * 3600 + t.tm_min * 60 + t.tm_sec)
    if period == "kun":
        start = day0
    elif period == "hafta":
        start = day0 - t.tm_wday * 86400
    elif period == "oy":
        start = day0 - (t.tm_mday - 1) * 86400
    elif period == "30k":
        return now - 30 * 86400
    else:
        return 0
    return start - off


def get_points_leaderboard(period, limit=10, member_ids=None, calendar=False):
    """period: 'kun', 'hafta', 'oy', 'mutlaq'. member_ids berilsa (masalan bitta
    guruhning a'zolari), faqat o'sha ID'lar hisobga olinadi.
    calendar=True — kalendar davr (bugun/shu hafta/shu oy); False — eski sirpanuvchi oyna (24s/7k/30k)."""
    now = time.time()
    if calendar:
        since = _period_start(period, now)
    else:
        since = {
            "kun": now - 86400,
            "hafta": now - 7 * 86400,
            "oy": now - 30 * 86400,
            "mutlaq": 0,
        }.get(period, 0)
    with db_lock:
        if member_ids is None:
            cur.execute(
                "SELECT user_id, SUM(points) FROM points_log WHERE ts >= ? GROUP BY user_id ORDER BY SUM(points) DESC LIMIT ?",
                (since, limit),
            )
        else:  # guruh scope'i: kesmasdan hammasini olib, so'ng filtrlaymiz
            cur.execute(
                "SELECT user_id, SUM(points) FROM points_log WHERE ts >= ? GROUP BY user_id ORDER BY SUM(points) DESC",
                (since,),
            )
        rows = cur.fetchall()
    result = []
    for uid, total in rows:
        if total is None:
            continue
        if member_ids is not None and uid not in member_ids:
            continue
        u = user_dict(uid)
        result.append((uid, u.get("name") or "O'yinchi", total))
        if len(result) >= limit:
            break
    return result


PERIOD_LABELS = {"kun": "📅 Bugungi", "hafta": "🗓 Shu haftalik", "oy": "📆 Shu oylik", "mutlaq": "♾ Mutlaq (bot boshidan)"}


def record_group_game(chat_id, points):
    """🏘 Guruh statistikasi: o'yin tugaganda o'yinlar soni va to'plangan ballni oshiradi."""
    with db_lock:
        try:
            cur.execute("INSERT OR IGNORE INTO group_stats (chat_id, games, points) VALUES (?, 0, 0)", (chat_id,))
            cur.execute("UPDATE group_stats SET games=games+1, points=points+? WHERE chat_id=?", (int(points), chat_id))
            try:   # 📆 davriy (kun/hafta/oy) guruh reytingi uchun jurnal
                cur.execute("INSERT INTO group_points_log (chat_id, points, ts) VALUES (?,?,?)", (chat_id, int(points), time.time()))
            except Exception:
                _logger.warning("group_points_log yozilmadi (chat=%s)", chat_id, exc_info=True)
            conn.commit()
        except Exception:
            # Statistika xatosi o'yin yakunini to'xtatmasin, lekin yo'qolgani ko'rinib tursin.
            conn.rollback()
            _logger.warning("record_group_game: guruh statistikasi yozilmadi (chat=%s)", chat_id, exc_info=True)


