# ================================================================================
#  🔁 O'YINCHINI USHLAB QOLISH (retention) — hammasi 💵 dollar, bepul 💎/🪙 yo'q
#   • Yangi o'yinchi: dastlabki NEWBIE_GAMES ta o'yinda mukofot ×NEWBIE_REWARD_MULT (1.3)
#   • Qaytish bonusi: COMEBACK_DAYS kun yo'q bo'lib qaytsa — bir martalik bonus
#   • Yutqazish seriyasi: LOSS_STREAK_N ketma-ket mag'lubiyatdan keyin "omad qaytadi" bonusi
#   • G'alaba seriyasi: 3/5/10 ketma-ket g'alabaga bonus
#   • Daraja ko'tarilishi: har yangi daraja uchun bonus
# ================================================================================
NEWBIE_GAMES = 10
NEWBIE_REWARD_MULT = 1.3
COMEBACK_DAYS = 3
COMEBACK_BONUS = 150
LOSS_STREAK_N = 3
LOSS_STREAK_BONUS = 40
WIN_STREAK_BONUS = {3: 30, 5: 70, 10: 150}
LEVELUP_BONUS_PER_LEVEL = 20
LEVELUP_BONUS_CAP = 200


def _newbie_mult(uid):
    try:
        if int(user_dict(uid).get("games") or 0) < NEWBIE_GAMES and NEWBIE_REWARD_MULT > 1:
            return float(NEWBIE_REWARD_MULT)
    except Exception:
        pass
    return 1.0


def _retention_after_game(uid, u_before, won, left, draw=False):
    """O'yin tugagach (statistika yangilangandan keyin) qo'shimcha bonuslarni hisoblab beradi.
    u_before — o'yindan OLDINGI user dict. [(matn, summa), ...] qaytaradi."""
    notes = []
    if left:
        return notes
    now = time.time()
    box = {}

    def _mut(ch):
        ch = dict(ch)
        r = dict(ch.get("ret") or {})
        last = float(r.get("last_game", 0) or 0)
        box["gap_days"] = (now - last) / 86400.0 if last else 0
        if not draw:
            if won:
                r["win_streak"] = int(r.get("win_streak", 0)) + 1
                r["loss_streak"] = 0
            else:
                r["loss_streak"] = int(r.get("loss_streak", 0)) + 1
                r["win_streak"] = 0
        box["win"] = int(r.get("win_streak", 0))
        box["loss"] = int(r.get("loss_streak", 0))
        if not draw and not won and box["loss"] >= LOSS_STREAK_N:
            r["loss_streak"] = 0          # bonus bir marta, seriya yangidan boshlanadi
            box["loss_bonus"] = True
        if won and box["win"] in WIN_STREAK_BONUS:
            box["win_bonus"] = WIN_STREAK_BONUS[box["win"]]
        if won and box["win"] >= max(WIN_STREAK_BONUS):
            r["win_streak"] = 0
        r["last_game"] = now
        ch["ret"] = r
        return ch, True
    _atomic_json_field_update(uid, "charges", _mut)
    if box.get("gap_days", 0) >= COMEBACK_DAYS and COMEBACK_BONUS > 0:
        notes.append((f"👋 Qaytganingiz bilan! ({int(box['gap_days'])} kundan keyin)", COMEBACK_BONUS))
    if box.get("loss_bonus") and LOSS_STREAK_BONUS > 0:
        notes.append((f"🍀 {LOSS_STREAK_N} ta ketma-ket mag'lubiyat — omad qaytadi!", LOSS_STREAK_BONUS))
    if box.get("win_bonus"):
        notes.append((f"🔥 {box['win']} ta ketma-ket g'alaba!", int(box["win_bonus"])))
    try:
        g0, w0 = int(u_before.get("games") or 0), int(u_before.get("wins") or 0)
        lvl0 = level_progress(xp_of_user({"games": g0, "wins": w0}))[0]
        lvl1 = level_progress(xp_of_user({"games": g0 + 1, "wins": w0 + (1 if won else 0)}))[0]
        if lvl1 > lvl0 and LEVELUP_BONUS_PER_LEVEL > 0:
            notes.append((f"🆙 {lvl1}-daraja!", min(LEVELUP_BONUS_CAP, LEVELUP_BONUS_PER_LEVEL * lvl1)))
    except Exception:
        pass
    total = sum(a for _t, a in notes)
    if total > 0:
        add_balance(uid, dollar=total)
        safe_send(uid, "🎁 <b>Qo'shimcha bonuslar:</b>\n" + "\n".join(f"{t} <b>+{a}$</b>" for t, a in notes))
    return notes


_SUB_CACHE = {}   # uid -> (obuna_bo'lganmi, tekshirilgan_vaqt)
_SUB_POSITIVE_TTL = 60   # obuna bo'lgan foydalanuvchi natijasi shuncha soniya eslab qolinadi
_SUB_NEGATIVE_TTL = 3    # obuna bo'lMAGAN: faqat ketma-ket tez bosishlarni bir tekshiruvga birlashtirish uchun
_SUB_WARN_LAST = [0.0]


def check_channel_subscription(uid):
    """📣 Foydalanuvchi egasi kanalida (OWNER_CHANNEL_ID) a'zomi?
    True — a'zo; False — a'zo EMAS (aniq); None — aniqlab bo'lmadi (kanal o'rnatilmagan yoki
    Telegram/tarmoq xatosi yoki bot kanalda admin emas). None bo'lsa foydalanuvchi BLOKLANMAYDI."""
    ch_id = OWNER_CHANNEL_ID
    if not ch_id:
        return None
    now = time.time()
    hit = _SUB_CACHE.get(uid)
    if hit and now - hit[1] < (_SUB_POSITIVE_TTL if hit[0] else _SUB_NEGATIVE_TTL):
        return hit[0]
    try:
        m = bot.get_chat_member(ch_id, uid)
        status = getattr(m, "status", "")
        ok = status in ("member", "administrator", "creator") or (
            status == "restricted" and bool(getattr(m, "is_member", False)))
    except telebot.apihelper.ApiTelegramException as e:
        if getattr(e, "error_code", None) == 400 and "user not found" in str(e).lower():
            ok = False
        else:
            if now - _SUB_WARN_LAST[0] > 600:
                _SUB_WARN_LAST[0] = now
                _logger.warning("⚠️ Kanal obunasini tekshirib bo'lmadi (bot kanalda admin bo'lishi kerak): %s", e)
            return None
    except Exception as e:
        _logger.warning("Kanal obunasini tekshirishda xato: %s", e)
        return None
    _SUB_CACHE[uid] = (ok, now)
    if len(_SUB_CACHE) > 20000:
        _SUB_CACHE.clear()
    return ok


def is_channel_subscriber(uid):
    """Bonus uchun: faqat ANIQ a'zo bo'lsa True."""
    return check_channel_subscription(uid) is True


# --- kanal havolasi (tugma uchun) ---
_CHANNEL_LINK_CACHE = {"ts": 0.0, "url": None, "ch": None}


def _channel_join_url():
    ch_id = OWNER_CHANNEL_ID
    if not ch_id:
        return None
    now = time.time()
    c = _CHANNEL_LINK_CACHE
    if c["ch"] == ch_id and now - c["ts"] < (3600 if c["url"] else 60):
        return c["url"]
    url = None
    try:
        chat = bot.get_chat(ch_id)
        if getattr(chat, "username", None):
            url = f"https://t.me/{chat.username}"
        elif getattr(chat, "invite_link", None):
            url = chat.invite_link
        else:
            url = bot.export_chat_invite_link(ch_id)
    except Exception as e:
        _logger.warning("Kanal havolasini olib bo'lmadi: %s", e)
    c.update(ts=now, url=url, ch=ch_id)
    return url


