def _gt(uid, key):
    tbl = _GATE_TEXT[key]
    lang = get_lang(uid)
    return tbl.get(lang) or tbl.get("en") or tbl["uz"]


# --- bosqichlar: til → jins → kanal ---
_GATE_PENDING_START = {}   # uid -> /start xabari (deep-link yo'qolib ketmasligi uchun)
_GATE_PROMPT_LAST = {}     # uid -> oxirgi so'rov yuborilgan vaqt (spamga qarshi)


def _gate_stage(uid, include_channel=True):
    """Foydalanuvchi hali qaysi bosqichdan o'tmagan: 'lang' / 'gender' / 'channel' / None."""
    ch = get_charges(uid)
    if not ch.get("lang_chosen"):
        return "lang"
    if ch.get("gender") not in ("female", "male"):
        return "gender"
    if include_channel and OWNER_CHANNEL_ID and check_channel_subscription(uid) is False:
        return "channel"
    return None


def _gate_show_prompt(chat_id, uid, stage):
    now = time.time()
    if now - _GATE_PROMPT_LAST.get(uid, 0) < 1.5:
        return   # bir zumda ketma-ket bosishda xabar spami bo'lmasin
    _GATE_PROMPT_LAST[uid] = now
    if len(_GATE_PROMPT_LAST) > 20000:
        _GATE_PROMPT_LAST.clear()
    if stage == "lang":
        show_first_time_lang_menu(chat_id, uid)
    elif stage == "gender":
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.row(
            types.InlineKeyboardButton(_gt(uid, "female"), callback_data="gate_gender|female"),
            types.InlineKeyboardButton(_gt(uid, "male"), callback_data="gate_gender|male"),
        )
        bot.send_message(chat_id, _gt(uid, "gender_title"), reply_markup=kb)
    elif stage == "channel":
        kb = types.InlineKeyboardMarkup(row_width=1)
        url = _channel_join_url()
        if url:
            kb.add(types.InlineKeyboardButton(_gt(uid, "sub_btn"), url=url))
        kb.add(types.InlineKeyboardButton(_gt(uid, "check_btn"), callback_data="gate_sub_check"))
        bot.send_message(chat_id, _gt(uid, "sub_title"), reply_markup=kb)


def _gate_finish(chat_id, user):
    """Barcha bosqichlardan o'tgach — kutib turgan /start (deep-link) yoki bosh menyu."""
    uid = user.id
    pending = _GATE_PENDING_START.pop(uid, None)
    if pending is not None:
        parts = (getattr(pending, "text", "") or "").split(maxsplit=1)
        if len(parts) > 1:
            try:
                cmd_start(pending)
                return
            except Exception:
                _logger.warning("gate: kutilgan /start qayta ishlanmadi", exc_info=True)
    send_menu_media(chat_id, caption=menu_welcome(uid), reply_markup=get_main_menu(None, uid))


def _gate_continue(chat_id, user):
    stage = _gate_stage(user.id)
    if stage:
        _GATE_PROMPT_LAST.pop(user.id, None)
        _gate_show_prompt(chat_id, user.id, stage)
    else:
        _gate_finish(chat_id, user)


def _gate_exempt_user(user):
    return user is None or getattr(user, "is_bot", False) or is_owner(user.id)


def _gate_blocks_message(message):
    """True — xabar to'xtatiladi (foydalanuvchiga tegishli bosqich ko'rsatiladi)."""
    if message.chat.type != "private":
        return False   # guruh xabarlari tekshirilmaydi (spam/yuk bo'lmasligi uchun)
    user = message.from_user
    if _gate_exempt_user(user):
        return False
    if getattr(message, "content_type", "") == "successful_payment":
        return False   # to'lov qayd etilishi hech qachon to'xtatilmaydi
    stage = _gate_stage(user.id)
    if not stage:
        return False
    text = getattr(message, "text", "") or ""
    if text.startswith("/start"):
        _GATE_PENDING_START[user.id] = message
        if len(_GATE_PENDING_START) > 5000:
            _GATE_PENDING_START.clear()
    _gate_show_prompt(message.chat.id, user.id, stage)
    return True


def _gate_blocks_callback(call):
    data = call.data or ""
    if data.startswith("gate_") or data.startswith("onboardlang|"):
        return False
    user = call.from_user
    if _gate_exempt_user(user):
        return False
    chat = call.message.chat if getattr(call, "message", None) is not None else None
    in_private = chat is None or chat.type == "private"
    stage = _gate_stage(user.id, include_channel=True)
    if not stage:
        return False
    if not in_private:
        if stage != "channel":
            return False   # guruhda til/jins so'ralmaydi
        try:
            bot.answer_callback_query(call.id, _gt(user.id, "group_alert"), show_alert=True)
        except Exception:
            pass
        return True
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    _gate_show_prompt(chat.id if chat else user.id, user.id, stage)
    return True


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("gate_gender|"))
def cb_gate_gender(call):
    uid = call.from_user.id
    value = call.data.split("|", 1)[1]
    if value not in ("female", "male"):
        bot.answer_callback_query(call.id)
        return
    _first_gender = get_gender(uid) is None
    if not _first_gender:   # jins keyin o'zgartirilmaydi
        bot.answer_callback_query(call.id)
        return _gate_continue(call.message.chat.id, call.from_user)
    set_charge_value(uid, "gender", value)
    if _first_gender and not get_charges(uid).get("gender_reward"):
        set_charge_value(uid, "gender_reward", True)
        try:
            add_balance_as("owner", uid, diamond=1)
        except Exception:
            _logger.warning("gender +1 💎 berilmadi", exc_info=True)
    bot.answer_callback_query(call.id, "+1 💎" if _first_gender else None)
    try:
        bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    _gate_continue(call.message.chat.id, call.from_user)


@bot.callback_query_handler(func=lambda c: c.data == "gate_sub_check")
def cb_gate_sub_check(call):
    uid = call.from_user.id
    _SUB_CACHE.pop(uid, None)   # tugma bosilganda doim YANGI tekshiruv
    state = check_channel_subscription(uid)
    if state is False:
        bot.answer_callback_query(call.id, _gt(uid, "not_yet"), show_alert=True)
        return
    bot.answer_callback_query(call.id)
    try:
        bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    if state is True:
        text = _gt(uid, "congrats")
        bonus = int(CHANNEL_SUB_BONUS or 0)
        text += _gt(uid, "congrats_bonus").format(b=bonus) if bonus > 0 else "."
        bot.send_message(call.message.chat.id, text)
    _gate_continue(call.message.chat.id, call.from_user)


def is_owner_channel(chat):
    """Kanal postlari uchun: message.from_user doim None bo'ladi (Telegram buni
    hech kimga ko'rsatmaydi), shuning uchun faqat oldindan tasdiqlangan kanal
    chat_id'siga ishonamiz — chunki faqat o'sha kanalning administratorlari
    unga post qila oladi."""
    return chat.type == "channel" and OWNER_CHANNEL_ID is not None and chat.id == OWNER_CHANNEL_ID


@bot.message_handler(commands=["shu_kanal"])
def cmd_set_owner_channel(message):
    """Bot egasi shu buyruqni SHAXSIY chatda yozadi (kanalning o'zida emas — chunki u
    yerda foydalanuvchi shaxsi Telegram tomonidan yashiriladi). Masalan:
    /shu_kanal @Mirkamilovic   yoki   /shu_kanal -1001234567890
    Bot avval o'sha kanalga administrator sifatida qo'shilgan bo'lishi shart."""
    global OWNER_CHANNEL_ID
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    parts = message.text.split(maxsplit=1)
    if len(parts) != 2:
        bot.send_message(message.chat.id, "Foydalanish: <code>/shu_kanal @kanal_username</code> yoki <code>/shu_kanal -100...</code>")
        return
    identifier = parts[1].strip()
    try:
        chat = bot.get_chat(identifier)
    except Exception as e:
        bot.send_message(
            message.chat.id,
            f"❌ Kanalni topib bo'lmadi: {e}\n"
            "Bot o'sha kanalga administrator sifatida qo'shilganiga ishonch hosil qiling.",
        )
        return
    if chat.type != "channel":
        bot.send_message(message.chat.id, "❌ Bu kanal emas.")
        return
    OWNER_CHANNEL_ID = chat.id
    set_setting("owner_channel_id", OWNER_CHANNEL_ID)
    bot.send_message(message.chat.id, f"✅ Endi <b>{chat.title}</b> kanalidan buyruq berishingiz mumkin (masalan: /top, /topalmaz, /topdollar, /topguruh, /givevey).")


def is_owner(user_id):
    # 1) Muhit o'zgaruvchisida aniq berilgan ID — eng ishonchli, doim ustuvor.
    if OWNER_ID_FROM_ENV is not None and user_id == OWNER_ID_FROM_ENV:
        return True
    # 2) Avtomatik aniqlangan/bazada saqlangan owner_id.
    return OWNER_ID is not None and user_id == OWNER_ID


def maybe_capture_owner(tg_user):
    """OWNER_ID_FROM_ENV berilgan bo'lsa, bu funksiya hech narsa qilmaydi —
    chunki ishonchli manba muhit o'zgaruvchisi hisoblanadi. Aks holda,
    eski (zaif) username-asosidagi avtomatik aniqlash ishlashda davom etadi,
    lekin bu endi faqat OWNER_ID_FROM_ENV sozlanmagan hollar uchun zaxira usul."""
    global OWNER_ID
    _remember_username(tg_user)   # 🧩 v8: @username → id (o'tkazma/sovg'a uchun)
    if OWNER_ID_FROM_ENV is not None:
        return
    if OWNER_ID is not None or tg_user is None:
        return
    if tg_user.username and tg_user.username.lower() == OWNER_USERNAME.lower():
        OWNER_ID = tg_user.id
        set_setting("owner_id", OWNER_ID)


def is_banned(uid):
    return bool(user_dict(uid).get("banned"))


def ban_user(uid):
    update_user(uid, banned=1)


def unban_user(uid):
    update_user(uid, banned=0)


def record_duel_result(winner_id, loser_id):
    """qoshimchakod4.py g'oyasi asosida — endi haqiqiy SQLite bazasida saqlanadi.
    Atomik: ikki alohida o'qish+yozish o'rniga to'g'ridan-to'g'ri +1 UPDATE."""
    user_dict(winner_id)  # qatorni mavjud qilish (agar yo'q bo'lsa)
    user_dict(loser_id)
    with db_lock:
        cur.execute("UPDATE users SET duel_wins=COALESCE(duel_wins,0)+1 WHERE user_id=?", (winner_id,))
        cur.execute("UPDATE users SET duel_losses=COALESCE(duel_losses,0)+1 WHERE user_id=?", (loser_id,))
        conn.commit()


def get_partner_id(uid):
    u = user_dict(uid)
    return u.get("married_to") or 0


def get_partner_name(uid):
    """qoshimchakod3.py / qoshimchakod6.py g'oyasi — married_to ustuni asosida haqiqiy holat."""
    partner_id = get_partner_id(uid)
    if not partner_id:
        return None
    return user_dict(partner_id)["name"]


def get_partner_mention(uid):
    """Juftim (turmush o'rtoq) ismini bosilganda Telegram profiliga o'tadigan link ko'rinishida qaytaradi."""
    partner_id = get_partner_id(uid)
    if not partner_id:
        return None
    return mention(partner_id, user_dict(partner_id)["name"])


def is_group_admin(chat_id, user_id):
    try:
        member = bot.get_chat_member(chat_id, user_id)
        return member.status in ("administrator", "creator")
    except Exception:
        return False


def is_authorized(message):
    """O'yin boshqaruv buyruqlari uchun: guruh admini, bot yaratuvchisi,
    yoki ⚡️ Admin privilegiyasi (1 kun) buyumi faol bo'lgan foydalanuvchi."""
    uid = message.from_user.id
    if is_owner(uid):
        return True
    ch = get_charges(uid)
    until = ch.get("temp_admin_until", 0)
    if until and time.time() < until:
        return True
    if message.chat.type in ("group", "supergroup"):
        return is_group_admin(message.chat.id, uid)
    return False


