def team_of(role):
    if role in MAFIA_ROLES:
        return "mafia"
    if role in INDEPENDENT_ROLES:
        return "independent"
    return "town"


def role_goal_line(role):
    """🎯 Rol tushganda BIR QATORLIK aniq "maqsad" xulosasi."""
    team = team_of(role)
    if role == R_SUI:
        return "🎯 Maqsadingiz: kunduzgi ovoz berishda osilish."
    if role == R_JOK:
        return "🎯 Maqsadingiz: nishoningiz o'lim kartasini tanlashi."
    if role == R_GAZ:
        return "🎯 Maqsadingiz: o'lganingizda yoningizda 3 ta belgilangan odamni olib ketish."
    if role == R_FIT:
        return "🎯 Maqsadingiz: fitna sabab kimdir osilsin va siz oxirigacha tirik qoling."
    if role == R_CUP:
        return "🎯 Maqsadingiz: o'yin oxirigacha ikki sevishgan ham tirik qolsin."
    if role in KILLER_SOLO_ROLES or role in SURVIVOR_ROLES:
        return "🎯 Maqsadingiz: oxirigacha tirik qolish."
    if team == "mafia":
        return "🎯 Maqsadingiz: mafiachilar soni qolgan hamma o'yinchilar soniga teng bo'lguncha tirik qolish."
    return "🎯 Maqsadingiz: mafia va yakka qotillarni topib, kunduzi osish."


