def role_intro_text(role):
    """📨 Rol berilganda yuboriladigan xabar: "{emoji} Siz — {Rol}!" + rasmdagi tavsif."""
    port = role_portrait(role)
    emoji = port.split("</tg-emoji>")[0] + "</tg-emoji>" if "</tg-emoji>" in port else role.rsplit(" ", 1)[-1]
    name = role.rsplit(" ", 1)[0] if " " in role else role
    short = ROLES_INFO.get(role, "")
    if role in _CARD_ROLES:
        team = {"town": "🔵 Shahar", "mafia": "🔴 Mafia", "independent": "🟣 Neytral"}[team_of(role)]
        return (f"🎭 <b>Sizning rolingiz:</b> {emoji} {name}\n<b>Jamoa:</b> {team}\n\n{short}\n\n"
                f"🏆 <b>G'alaba:</b> {_CARD_WIN[role]}")
    return f"{emoji} Siz — <b>{name}</b>!\n{short}"


def mafia_count_for(n):
    if n <= 7:
        return 1
    elif n <= 12:
        return 2
    elif n <= 16:
        return 3
    else:
        return max(3, n // 5)


