def hero_image_path(hero_key):
    """Geroyning o'ziga xos rasmi — skript bilan bir papkada joylashgan bo'lishi kerak
    (masalan hero_draven.jpg). Fayl topilmasa None qaytaradi (chaqiruvchi shunda
    rasmsiz, faqat matn bilan davom etadi)."""
    rel = HEROES.get(hero_key, {}).get("image")
    if not rel:
        return None
    path = os.path.join(ASSETS_DIR, rel)
    return path if os.path.exists(path) else None


HERO_MAX_LEVEL = 30
HERO_ZARYAD_MAX = 10             # to'liq zaryad: shuncha hujum/himoya
HERO_ATTACK_COOLDOWN_DAYS = 1    # hujum HAR KUNI (kuniga 1 marta)
HERO_LVL_STEP = 0.25             # har keyingi daraja narxi: asosiy narx × (1 + 0.25 × (daraja−2))
# Narxlar bot_settings'da (Owner Center → 👑 Qahramonlar). Sotib olish narxi — Olmos do'konidagi
# "🥷 Geroy" buyumining narxi (bitta manba).
HERO_PRICE_DEFAULTS = {
    "oddiy": {"buy_diamond": 120, "buy_stars": 840, "lv2_diamond": 60, "lv2_stars": 420,
              "charge_dollar": 195, "rename_dollar": 780},
}
HERO_PRICE_ITEMS = ("buy_diamond", "lv2_diamond", "charge_dollar", "rename_dollar")
HERO_LEVEL_UP_COSTS = [HERO_PRICE_DEFAULTS["oddiy"]["lv2_diamond"]]  # eski nom (moslik uchun)
HERO_SWAP_ENABLED = False


def hero_price(hero_key, item):
    """Geroy narxlari. buy_diamond — do'kon buyumi narxi; lvN_diamond — 2-daraja asosiy narxidan
    chiziqli oshib boradi; *_stars — 💎 narxi × (1 💎 = ⭐); charge_dollar / rename_dollar — 💵."""
    d = HERO_PRICE_DEFAULTS["oddiy"]
    if item == "buy_stars":
        return hero_price(hero_key, "buy_diamond") * DIAMOND_STARS_RATE
    if item == "buy_diamond":
        try:
            return int(SHOP_DIAMOND["geroy"]["price"])
        except Exception:
            return d["buy_diamond"]
    if item.startswith("lv"):
        try:
            lvl = int(item[2:].split("_")[0])
        except Exception:
            lvl = 2
        raw = get_setting("hero_price_oddiy_lv2_diamond")
        try:
            base = max(1, int(raw)) if raw not in (None, "") else d["lv2_diamond"]
        except Exception:
            base = d["lv2_diamond"]
        diamonds = max(1, round(base * (1 + HERO_LVL_STEP * max(0, lvl - 2))))
        return diamonds * DIAMOND_STARS_RATE if item.endswith("_stars") else diamonds
    if item in ("charge_dollar", "rename_dollar"):
        try:
            raw = get_setting(f"hero_price_oddiy_{item}")
            return max(1, int(raw)) if raw not in (None, "") else d[item]
        except Exception:
            return d[item]
    return d.get(item, 1)


def hero_auto_enabled(uid):
    """🤖 Geroy mahoratlarining AVTOMATIK ishlashi (standart — yoqilgan). Panel tugmasi bilan o'chiriladi."""
    try:
        return get_charges(uid).get("hero_auto", 1) != 0
    except Exception:
        return True


def _grant_hero(uid, hero_key):
    """Geroyni 1-daraja bilan beradi (foydalanuvchida allaqachon geroy bo'lmasa). True/False qaytaradi."""
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)",
                    (uid, hero_key, time.time()))
        ok = cur.rowcount > 0
        conn.commit()
    return ok


def _migrate_hero_levels_v8():
    """Eski 1-15 darajalarni yangi 1-3 darajaga BIR MARTA o'tkazadi (1-5→1, 6-10→2, 11-15→3):
    hech kim yo'qotmaydi."""
    try:
        if get_setting("hero_levels_migrated_v8") == "1":
            return
        with db_lock:
            cur.execute("UPDATE heroes SET level = CASE WHEN level <= 5 THEN 1 WHEN level <= 10 THEN 2 ELSE 3 END")
            conn.commit()
        set_setting("hero_levels_migrated_v8", "1")
    except Exception:
        _logger.exception("Geroy darajalarini yangi tizimga o'tkazishda xatolik")


_migrate_hero_levels_v8()


