def get_hero(uid):
    with db_lock:
        cur.execute("SELECT hero_key, level, acquired_at, temp_until FROM heroes WHERE user_id=?", (uid,))
        row = cur.fetchone()
    if not row:
        return None
    key, level, acquired_at, temp_until = row
    # ⏳ Vaqtincha berilgan geroyning muddati tugagan bo'lsa — avtomatik olib
    # qo'yiladi (keyingi safar tekshirilganda ko'rinmaydi, xuddi hech
    # bo'lmagandek). Muddat tugagani haqida foydalanuvchiga DM yuboriladi.
    if temp_until and temp_until > 0 and time.time() > temp_until:
        with db_lock:
            cur.execute("DELETE FROM heroes WHERE user_id=?", (uid,))
            conn.commit()
        hero_name = HEROES.get(key, {}).get("name", key)
        safe_send(uid, f"⏳ <b>{hero_name}</b> geroyingizning vaqtinchalik muddati tugadi — endi sizda emas.")
        return None
    data = HEROES.get(key, {})
    days_active = int((time.time() - (acquired_at or time.time())) // 86400)
    return {"key": key, "level": level, "acquired_at": acquired_at, "days_active": days_active,
            "temp_until": temp_until, "name": data.get("name"), "image": data.get("image"),
            "abilities": data.get("abilities", [])}


def hero_level_up_cost(current_level, hero_key=None):
    """Keyingi darajaga o'tish narxi (💎). hero_key berilmasa — oddiy geroy narxi."""
    if current_level < 1 or current_level >= HERO_MAX_LEVEL:
        return None
    return hero_price(hero_key or "soya", f"lv{current_level + 1}_diamond")


def _ability_power(level, unlock, base, cap):
    """`unlock` darajada `base`dan boshlanib, oxirgi (3) darajada `cap`gacha chiziqli o'sadigan,
    chegaralangan (chit bo'lib qolmaydigan) kuch qiymati. `unlock`dan past level uchun 0."""
    if level < unlock:
        return 0.0
    if unlock >= HERO_MAX_LEVEL:
        return base
    t = (level - unlock) / (HERO_MAX_LEVEL - unlock)
    return base + (cap - base) * t


def _hero_swap_for(uid):
    """🔁 Agar foydalanuvchi hozir ishtirok etayotgan FAOL o'yin uchun 'Qobiliyatni
    almashtirish' huquqidan foydalangan bo'lsa — shu o'yindagi almashtirish yozuvini
    qaytaradi ({"from": key, "to": key, ...} yoki None)."""
    for _cid, _g in GAMES.items():
        p = _g.get("players", {}).get(uid)
        if p and _g.get("phase") in ("night", "day"):
            return _g.get("hero_ability_swap", {}).get(uid)
    return None


def hero_unlocked_abilities(uid):
    """Foydalanuvchining geroyi va uning HOZIRGI darajasida ochilgan qobiliyatlari
    ro'yxatini (hisoblangan qiymati bilan) qaytaradi. Har biri: {key,name,desc,value,unlocked}.
    🔁 Agar o'yinchi joriy o'yin uchun bir martalik 'Qobiliyatni almashtirish' huquqini
    ishlatgan bo'lsa, shu yerda avtomatik hisobga olinadi — natijada BUTUN botdagi
    geroy funksiyalari (hero_has_ability, hero_ability_value va h.k.) qo'shimcha
    o'zgartirishsiz to'g'ri natija beradi."""
    hero = get_hero(uid)
    if not hero:
        return []
    swap = _hero_swap_for(uid)
    result = []
    for ab in hero["abilities"]:
        unlocked = hero["level"] >= ab["unlock"]
        if swap and ab["key"] == swap.get("from"):
            unlocked = False  # bu o'yin uchun ongli ravishda voz kechilgan
        if swap and ab["key"] == swap.get("to"):
            unlocked = True  # bu o'yin uchun vaqtincha ochilgan
        value = None
        if unlocked and "base" in ab:
            value = _ability_power(hero["level"], ab["unlock"], ab["base"], ab["cap"])
        result.append({**ab, "unlocked": unlocked, "value": value})
    return result


def hero_ability_value(uid, ability_key):
    """Berilgan turdagi (masalan 'survive', 'duel_bonus') qobiliyat qiymatini qaytaradi
    (0 — agar geroy yo'q, ochilmagan yoki bu turdagi qobiliyat yo'q bo'lsa)."""
    for ab in hero_unlocked_abilities(uid):
        if ab["key"] == ability_key and ab["unlocked"]:
            return ab["value"] or 0.0
    return 0.0


def hero_has_ability(uid, ability_key):
    """Binary (bor/yo'q) qobiliyatlar uchun — masalan 'compass_free', 'revive_once'."""
    for ab in hero_unlocked_abilities(uid):
        if ab["key"] == ability_key and ab["unlocked"]:
            return True
    return False


def hero_survive_chance(uid):
    return hero_ability_value(uid, "survive")


