def alive_players(game):
    return {uid: p for uid, p in game["players"].items() if p["alive"]}


def _special_member_tag(game, uid):
    """🔴🔵/💍 Lobby va yakuniy natijalarda jamoa/juftlik belgisini
    nickname oldida aniq ko'rsatadi. Bu faqat squad/couple rejimlariga tegishli."""
    if game.get("squad_mode"):
        side = game.get("squads", {}).get(uid)
        return "🔴" if side == "wolf" else ("🔵" if side == "eagle" else "⚪")
    if game.get("couple_mode"):
        return "💍"
    return ""

def player_line_list(game):
    if not game["players"]:
        return "Hozircha hech kim yo'q."
    rows=[]
    for uid, p in game["players"].items():
        tag=_special_member_tag(game, uid)
        prefix=f"{tag} " if tag else ""
        rows.append(f"• {prefix}{mention(uid, p['name'])}")
    return "\n".join(rows)


# ================================================================================
#  🔴🔵 JAMOAVIY (SQUAD) REJIMI — jamoa a'zolari soni, jamodoshlar ro'yxati va
#  tugmalardagi jamoa belgisi uchun yordamchi funksiyalar. (YANGI QO'SHILDI —
#  mavjud hech bir funksiya o'chirilmadi yoki o'zgartirilmadi.)
# ================================================================================

def squad_counts_line(game):
    """🔴🔵 Ro'yxatga olish xabarida ko'rsatish uchun — har bir jamoaga necha kishi
    yozilganini alohida-alohida sanab qaytaradi (masalan: '🔵 Ko'k — 2 ta,
    🔴 Qizil — 3 ta'). Kim aniq qaysi jamoada ekani baribir MAXFIY qolaveradi —
    faqat SONLAR ko'rsatiladi, ismlar emas."""
    if not game.get("squad_mode"):
        return None
    squads = game.get("squads", {})
    wolf_n = sum(1 for uid in game["players"] if squads.get(uid) == "wolf")
    eagle_n = sum(1 for uid in game["players"] if squads.get(uid) == "eagle")
    return f"🔵 Ko'k — {eagle_n} ta, 🔴 Qizil — {wolf_n} ta"


def ally_roster(game, viewer_uid):
    """🐺🦅💍🕶 O'yinchining "jamodoshlari" ro'yxatini aniqlaydi — o'yin rejimiga
    qarab avtomatik tanlanadi:
      • 🔴🔵 Qizil va Ko'k rejimi  → o'zi bilan bir xil jamoadagilar (Qizil/Ko'k)
      • 💍 Para rejim        → turmush o'rtog'i (agar u ham shu o'yinda va tirik bo'lsa)
      • Oddiy (asosiy) o'yin → 🕶 Mafiya jamoasi a'zolari (Don + Mafia), FAQAT
        o'zi ham mafiya bo'lsa (tinch aholi/komissar/doktor va h.k.ga hech kim
        "jamodosh" sifatida ko'rsatilmaydi, chunki ularning maxfiy sherigi yo'q)
    Qaytaradi: (label, emblem, [(uid, name), ...]) — hech narsa topilmasa
    (None, None, [])."""
    p = game["players"].get(viewer_uid)
    if not p:
        return None, None, []
    if game.get("squad_mode"):
        squads = game.get("squads", {})
        my_squad = squads.get(viewer_uid)
        if not my_squad:
            return None, None, []
        emblem = "🔴" if my_squad == "wolf" else "🔵"
        label = "Qizil" if my_squad == "wolf" else "Ko'k"
        mates = [(uid, pp["name"]) for uid, pp in game["players"].items()
                 if uid != viewer_uid and squads.get(uid) == my_squad and pp.get("alive")]
        return label, emblem, mates
    if game.get("couple_mode"):
        spouse_uid = game.get("couple_of", {}).get(viewer_uid)
        sp = game["players"].get(spouse_uid) if spouse_uid else None
        if not sp or not sp.get("alive"):
            return None, None, []
        return "Turmush o'rtog'i", "💍", [(spouse_uid, sp["name"])]
    kind, emblem = _team_kind(p.get("role"))
    if kind:
        mates = [(uid, pp["name"]) for uid, pp in game["players"].items()
                 if uid != viewer_uid and pp.get("alive") and _team_kind(pp.get("role"))[0] == kind]
        if mates:
            return ("Mafiya" if kind == "mafia" else "Qonun"), emblem, mates
    return None, None, []


def _team_kind(role):
    """🤵👮 Yashirin jamoa turi: Don/Mafia/Advokat → ("mafia", "🤵"),
    Komissar/Serjant → ("law", "👮"); boshqa rollar → (None, None)."""
    if role in MAFIA_KNOWN_ROLES:
        return "mafia", "🤵"
    if role in (R_KOM, R_SER):
        return "law", "👮"
    return None, None


_TEAM_ROLE_SHORT = {R_DON: "don", R_MAF: "mafia", R_ADV: "advokat", R_DXO: "xotini", R_KOM: "komissar", R_SER: "serjant"}


def send_team_rosters(game):
    """🤵👮 Mafiya jamoasi (Don/Mafia/Advokat) va Qonun jamoasi (Komissar/Serjant)
    a'zolariga sheriklari ro'yxatini ("Ism rol" ko'rinishida) yuboradi.
    HAR TUN EMAS: faqat o'yin boshida bir marta, so'ng esa sheriklardan biri
    halok bo'lganda yoki rollar o'zgarganda (ro'yxat tarkibi o'zgargan bo'lsa)."""
    if game.get("squad_mode") or game.get("couple_mode"):
        return
    sent = game.setdefault("team_roster_sig", {})
    for viewer_uid, vp in alive_players(game).items():
        kind, emblem = _team_kind(vp.get("role"))
        if not kind:
            continue
        mates = [(pp["name"], pp.get("role")) for uid, pp in game["players"].items()
                 if uid != viewer_uid and pp.get("alive") and _team_kind(pp.get("role"))[0] == kind]
        sig = "|".join(f"{n}:{r}" for n, r in mates)   # JSON-da saqlanadigan oddiy satr
        if sent.get(viewer_uid) == sig:
            continue
        sent[viewer_uid] = sig
        if not mates:
            continue
        lines = [f"{emblem} <b>Sheriklaringiz:</b>"]
        lines += [f"{esc(n)} {_TEAM_ROLE_SHORT.get(r, '')}".rstrip() for n, r in mates]
        safe_send(viewer_uid, "\n".join(lines))


def squad_tag(game, viewer_uid, target_uid):
    """🔴🔵💍🕶 Agar 'target_uid' 'viewer_uid'ning jamodoshi (bir jamoadagi
    sherigi, turmush o'rtog'i yoki mafiya safdoshi) bo'lsa, tugma matni
    oldiga qo'shiladigan belgini (emoji) qaytaradi — shunda o'yinchi
    tugmalar orasida o'z jamodoshini darhol tanib oladi. Aks holda bo'sh
    satr qaytadi — bu holatda tugma AVVALGIDEK, hech qanday o'zgarishsiz
    ko'rinadi."""
    if target_uid == viewer_uid:
        return ""
    _, emblem, mates = ally_roster(game, viewer_uid)
    if not emblem:
        return ""
    if any(uid == target_uid for uid, _name in mates):
        return f"{emblem} "
    return ""


def format_squad_roster_text(game, viewer_uid):
    """🐺🦅💍🕶 O'yinchining o'z jamodoshlari ro'yxatini tayyorlaydi — RAQAMLANGAN
    (1, 2, 3...) va HAR BIRI ALOHIDA QATORDA (yonma-yon emas, pastga qarab),
    shunda o'yinchi jamodoshlarini o'qishda chalkashib ketmaydi. 💍 Para
    rejimida turmush o'rtog'ining ismi <b>qalin</b> qilib ajratib ko'rsatiladi.
    Jamodosh topilmasa — None qaytadi (hech narsa yuborilmaydi)."""
    label, emblem, mates = ally_roster(game, viewer_uid)
    if not emblem or not mates:
        return None
    if game.get("couple_mode"):
        _mate_uid, mate_name = mates[0]
        return f"{emblem} <b>Sizning turmush o'rtog'ingiz:</b> <b>{mate_name}</b>"
    header_label = f"\"{label}\" jamoangiz" if game.get("squad_mode") else "mafiya sheriklaringiz"
    lines = [f"{emblem} <b>Sizning {header_label} a'zolari:</b>"]
    for i, (_mate_uid, mate_name) in enumerate(mates, start=1):
        lines.append(f"{i}. {emblem} {mate_name}")
    return "\n".join(lines)


def send_squad_reminders(game):
    """🔴🔵💍🕶 Har bir tirik o'yinchiga (jamoaviy yoki para o'yinda) o'z
    jamodoshlari ro'yxatini shaxsiy chatga BIR MARTA (o'yin davomida faqat
    birinchi safar — tun 1) eslatma qilib yuboradi. Ilgari bu HAR tun va HAR
    kun ovoz berishidan oldin qayta-qayta yuborilardi — endi faqat bir marta,
    shunda o'yinchining shaxsiy xabarlari keraksiz ravishda ko'payib ketmaydi."""
    if game.get("squad_roster_shown"):
        return
    if not (game.get("squad_mode") or game.get("couple_mode")):
        # 🤵👮 Oddiy rejimda sheriklar ro'yxati send_team_rosters() orqali boshqariladi
        send_team_rosters(game)
        return
    sent_any = False
    for viewer_uid in alive_players(game):
        text = format_squad_roster_text(game, viewer_uid)
        if text:
            safe_send(viewer_uid, text)
            sent_any = True
    if sent_any:
        game["squad_roster_shown"] = True


def get_group_link(chat_id):
    game = GAMES.get(chat_id)
    if game and game.get("group_link"):
        return game["group_link"]
    try:
        link = bot.export_chat_invite_link(chat_id)
        if game:
            game["group_link"] = link
        return link
    except Exception:
        return None


def safe_delete(message):
    try:
        bot.delete_message(message.chat.id, message.message_id)
    except Exception:
        pass


def _group_jump_kb(uid):
    """↗️ Foydalanuvchi faol o'yinda bo'lsa — DM xabari tagiga "Guruhga o'tish" tugmasi
    (o'yin guruhiga havola). O'yinda bo'lmasa yoki guruh havolasi yo'q bo'lsa — None."""
    try:
        for g in list(GAMES.values()):
            if g.get("phase") in ("waiting", "night", "day") and uid in g.get("players", {}):
                link = g.get("group_link")
                if link:
                    kb = types.InlineKeyboardMarkup()
                    kb.add(types.InlineKeyboardButton("↗️ Guruhga o'tish", url=link))
                    return kb
                return None
    except Exception:
        pass
    return None


def safe_send(uid, text, reply_markup=None):
    try:
        if reply_markup is None:
            reply_markup = _group_jump_kb(uid)   # tugmasiz o'yin xabarlari tagiga "Guruhga o'tish"
        bot.send_message(uid, localize_text(uid, text), reply_markup=reply_markup)
        return True
    except Exception:
        return False


def queue_dawn(game, uid, text):
    """🌅 Tungi ma'lumotni (kim kelgani, tekshiruv natijasi) darhol emas, TONGDA yetkazish uchun navbatga qo'yadi."""
    game.setdefault("dawn_queue", []).append([uid, text])


def flush_dawn_queue(game):
    """🌅 Tong otganda navbatdagi barcha tungi xabarlarni DM orqali yuboradi."""
    q = game.get("dawn_queue") or []
    game["dawn_queue"] = []
    for uid, text in q:
        try:
            safe_send(uid, text)
        except Exception:
            pass


