#  Ism uslubi bilan BIRGA ishlaydi (masalan 𝐁𝐨𝐥𝐝 + 🔴 = qizil qalin ism).
# ================================================================================
NAME_COLOR_CATALOG = {
    "red":    ("🔴", "Qizil", 130, 30),
    "orange": ("🟠", "To'q sariq", 130, 30),
    "yellow": ("🟡", "Sariq", 130, 30),
    "green":  ("🟢", "Yashil", 130, 30),
    "blue":   ("🔵", "Ko'k", 130, 30),
    "purple": ("🟣", "Binafsha", 150, 30),
    "black":  ("⚫️", "Qora", 150, 30),
    "white":  ("⚪️", "Oq", 150, 30),
    "brown":  ("🟤", "Jigarrang", 130, 30),
}


def name_color_active(uid):
    ch = get_charges(uid)
    key = ch.get("name_color") or ""
    until = ch.get("name_color_until", 0)
    return key if (key and until and until > time.time()) else None


def name_color_grant(uid, color_key, days):
    if color_key not in NAME_COLOR_CATALOG:
        return
    ch = get_charges(uid)
    now = time.time()
    cur_until = ch.get("name_color_until", 0)
    base = cur_until if (ch.get("name_color") == color_key and cur_until > now) else now
    ch["name_color"] = color_key
    ch["name_color_until"] = base + days * 86400
    set_charges(uid, ch)


def name_color_shop_text_and_kb(uid):
    active = name_color_active(uid)
    lines = [
        "🌈✨ <b>ISM RANGI DO'KONI</b> ✨🌈",
        "━━━━━━━━━━━━━━━━━━",
        "",
        "Telegram harflarni bo'yashga imkon bermaydi — shuning uchun ismingiz "
        "yonida tanlagan rangdagi belgi doim yonib turadi, o'zingizga xos ko'rinish:",
        "",
    ]
    kb = types.InlineKeyboardMarkup(row_width=3)
    row = []
    for key, (emoji, label, price, days) in NAME_COLOR_CATALOG.items():
        mark = "  ✅" if key == active else ""
        lines.append(f"{emoji} <b>{label}</b>{mark} · {price} ⭐️")
        row.append(types.InlineKeyboardButton(f"{emoji} {price}⭐️", callback_data=f"namecolor|{key}"))
        if len(row) == 3:
            kb.add(*row); row = []
    if row:
        kb.add(*row)
    if active:
        ch = get_charges(uid)
        left_days = max(0, int((ch.get('name_color_until', 0) - time.time()) / 86400))
        lines += ["", "━━━━━━━━━━━━━━━━━━",
                   f"⏳ Faol rang: <b>{NAME_COLOR_CATALOG[active][1]}</b> — {left_days} kun qoldi"]
    return "\n".join(lines), with_back_button(kb)


