def mention(uid, name):
    """Guruh xabarlarida o'yinchi ismini bosilganda uning profiliga o'tadigan qilib ko'rsatish uchun.
    🦁 Agar o'yinchi HUNTER ELITE bo'lsa, ismi ikki tomonidan haqiqiy PREMIUM
    SHER emojisi bilan bezaladi (CLAN_PORTRAIT_EMOJI["logo"]) — ELITE belgisi.
    🖼 Agar o'yinchida faol Mifik ramka bo'lsa, uning ismi HAMMA ko'radigan joyda
    (o'yin e'lonlari, reytinglar, o'lim xabarlari va h.k.) maxsus ramka bilan ko'rinadi.
    ❗️ MUHIM: <tg-emoji> tegi <a href="tg://user?id=..."> havolasi ICHIGA
    JOYLASHTIRILMAYDI — Telegram bunday "ichma-ich" (nested) formatni to'g'ri
    ko'rsata olmay, faqat zaxira (fallback) belgini chiqarib qo'yadi. Shuning
    uchun premium belgi havola TASHQARISIGA (oldiga/orqasiga) qo'shiladi —
    shunda u guruhda ham, shaxsiy chatda ham haqiqiy premium ko'rinishda chiqadi.
    🔒 Ism (name) va laqab (nickname) HAR DOIM esc() orqali xavfsizlashtiriladi —
    aks holda foydalanuvchi o'z Telegram ismiga "<", ">" yoki "&" kabi belgilar
    qo'yib qo'ysa, bot HTML xabarni yubora olmay qolishi yoki soxta teglar
    "in'ektsiya" qilinishi mumkin edi."""
    _anon = anon_label_of(uid)
    if _anon:   # 🦊 anonim o'yin: ism/ELITE/ramka/havola — hech biri ko'rinmaydi
        return f"<b>{esc(_anon)}</b>"
    display = name or "O'yinchi"
    prefix = ""
    suffix = ""
    badge = ""
    try:
        ch = get_charges(uid)
        # 🦁 HUNTER ELITE a'zosi bo'lsa va shaxsiy laqab (taxallus) o'rnatgan bo'lsa —
        # hamma joyda (o'yin e'lonlari, reytinglar, o'lim xabarlari) o'sha laqab bilan ko'rinadi.
        badge = toifa_badge(uid, ch)   # maxsus toifa belgisi — ism OXIRIGA qo'yiladi (🎖 / 🏛 / 🐺)
        elite_until = ch.get("vip_until", 0)
        _ovl = toifa_get(uid, ch) == "overlord"
        if (elite_until and elite_until > time.time()) or _ovl:
            nick = (ch.get("nickname") or "").strip()
            if nick:
                display = nick
            # 💎 Endi faqat "𝐄𝐋𝐈𝐓𝐄 💎" (qalin shrift + olmos) ko'rsatiladi — oldingi
            # 🦁 sher belgisi (prefiksda) olib tashlandi, orqadagi olmos saqlanib qoldi.
            if not _ovl:   # OVERLORD'da alohida ELITE yozuvi chiqmaydi — uning o'z nishoni bor
                prefix += "<b>𝐄𝐋𝐈𝐓𝐄</b> 💎 "
        ramka_until = ch.get("ramka_until", 0)
        if ramka_until and ramka_until > time.time():
            prefix += premium_emoji("frame", "🖼") + "✨ "
            suffix = " ✨" + premium_emoji("frame", "🖼") + suffix
        # 🎨 v13: sotib olingan "Ism uslubi" (Unicode shrift skin) — faol bo'lsa,
        # ism harflari maxsus uslubli belgilarga almashtiriladi (masalan 𝕭𝖔𝖑𝖉).
        # ESLATMA: bu esc() dan OLDIN qilinadi — aks holda "&amp;" kabi HTML
        # entity ichidagi harflar ham (noto'g'ri) o'zgartirilib qolar edi.
        style_key = ch.get("name_style") or ""
        style_until = ch.get("name_style_until", 0)
        if style_key and style_until and style_until > time.time():
            display = apply_name_style(display, style_key)
        # 🎨 v14: "Ism rangi" — Telegram bot xabarlarida harf rangini o'zgartirib
        # bo'lmaydi (Bot API buni qo'llab-quvvatlamaydi), shuning uchun buning
        # o'RNIga ismning ikki tomoniga tanlangan RANGDAGI belgi qo'yiladi —
        # natijada ism "rangli" ko'rinadi va HAMMA joyda bir xil chiqadi.
        color_key = ch.get("name_color") or ""
        color_until = ch.get("name_color_until", 0)
        if color_key and color_until and color_until > time.time():
            cemoji = NAME_COLOR_CATALOG.get(color_key, ("",))[0]
            if cemoji:
                prefix += cemoji + " "
                suffix = " " + cemoji + suffix
        # 👑 v14: oyning eng ko'p xarajat qilgan foydalanuvchisi (Oyning homiysi)
        sponsor_until = ch.get("sponsor_badge_until", 0)
        if sponsor_until and sponsor_until > time.time():
            prefix += "👑 <b>OYNING HOMIYSI</b> "
    except Exception:
        pass
    safe_name = esc(display)
    return f'{prefix}<a href="tg://user?id={uid}">{safe_name}</a>{badge}{suffix}'


