def wrap_known_emojis(text):
    """Matndagi 121-lik to'plamda mavjud BARCHA "eski" (oddiy) emojilarni
    haqiqiy premium <tg-emoji> tegiga o'raydi. Allaqachon <tg-emoji> tegi
    ichida turgan belgilarga tegmaydi — shuning uchun HTML formatlangan
    xabarlarga xavfsiz qo'llash mumkin."""
    if not text:
        return text
    placeholders = []

    def _stash(m):
        placeholders.append(m.group(0))
        return f"\x00{len(placeholders) - 1}\x00"

    safe_text = re.sub(r"<tg-emoji[^>]*>.*?</tg-emoji>", _stash, text, flags=re.S)
    for emoji, emoji_id in EMOJI_TO_ID.items():
        if emoji_id and emoji in safe_text:
            safe_text = safe_text.replace(
                emoji, f'<tg-emoji emoji-id="{emoji_id}">{emoji}</tg-emoji>'
            )

    def _unstash(m):
        return placeholders[int(m.group(1))]

    return re.sub(r"\x00(\d+)\x00", _unstash, safe_text)


def send_message_premium(chat_id, text, reply_markup=None, **kwargs):
    """bot.send_message() ning premium-emoji bilan avtomatik boyitilgan
    varianti — istalgan joyda oddiy bot.send_message(...) o'rniga shuni
    chaqirsangiz, matningizdagi barcha eski emojilar avtomatik haqiqiy
    premium ko'rinishda chiqadi."""
    kwargs.setdefault("parse_mode", "HTML")
    return bot.send_message(chat_id, wrap_known_emojis(text), reply_markup=reply_markup, **kwargs)


# 🦁 GLOBAL AVTOMATIK ULASH — bot allaqachon parse_mode="HTML" bilan ishga
# tushirilgan (yuqorida, `bot = telebot.TeleBot(...)` qatorida), shuning
# uchun bu xavfsiz: FAQAT xabar MATNIGA (bot.send_message / edit_message_text)
# ta'sir qiladi — tugma yozuvlari (InlineKeyboardButton) va callback-alert
# (answer_callback_query) matnlari Telegram tomonidan umuman HTML qabul
# qilmagani uchun ULARGA TEGINILMAYDI, o'zgarishsiz qoladi.
_orig_send_message = bot.send_message
_orig_edit_message_text = bot.edit_message_text
_TG_MAX_LEN = 4096
_TG_CHUNK = 3600


def _u16(t):
    """Telegram uzunlikni UTF-16 birliklarida sanaydi (emoji = 2) — Python len() kam ko'rsatadi."""
    try:
        return len(t.encode('utf-16-le')) // 2
    except Exception:
        return len(t)



def _safe_wrap_text(text):
    """Emoji-wrap qiladi, lekin 4096 limitdan oshsa — oddiy matnni qaytaradi."""
    if not isinstance(text, str):
        return text
    try:
        wrapped = wrap_known_emojis(text)
    except Exception:
        return text
    return wrapped if _u16(wrapped) <= _TG_MAX_LEN else text


def _split_text(text, limit=_TG_CHUNK):
    """Matnni qatorlar bo'yicha limit ichidagi bo'laklarga ajratadi."""
    chunks, cur = [], ""
    for line in text.split("\n"):
        while _u16(line) > limit:
            if cur:
                chunks.append(cur)
                cur = ""
            cut = max(1, limit // 2)
            while cut < len(line) and _u16(line[:cut + 1]) <= limit:
                cut += 1
            chunks.append(line[:cut])
            line = line[cut:]
        if _u16(cur) + _u16(line) + 1 > limit and cur:
            chunks.append(cur)
            cur = line
        else:
            cur = line if not cur else cur + "\n" + line
    if cur:
        chunks.append(cur)
    return chunks or [""]


_VALID_TAG_RE = r"(?:b|i|u|s|a|code|pre|tg-emoji|tg-spoiler|blockquote|em|strong|ins|del|strike)"


def _fix_html(text):
    """Yopilmagan/begona '<' belgilarini &lt; ga aylantiradi (Telegram "can't parse entities" bermasligi uchun)."""
    return re.sub(r"<(?!/?" + _VALID_TAG_RE + r"[\s>/])", "&lt;", text)


def _plain_text(text):
    return html.unescape(re.sub(r"<[^>]*>", "", text)) if isinstance(text, str) else text


def _is_parse_error(e):
    return "can't parse entities" in str(e)


def _send_in_chunks(chat_id, raw, a, kw, limit):
    """MESSAGE_TOO_LONG'dan keyin: asl matnni (emoji-wrapsiz) kichikroq bo'laklarga bo'lib yuboradi."""
    chunks = _split_text(raw, limit)
    markup = kw.pop("reply_markup", None)
    res = None
    for i, ch in enumerate(chunks):
        k = dict(kw)
        if i == len(chunks) - 1 and markup is not None:
            k["reply_markup"] = markup
        res = _orig_send_message(chat_id, ch, *a, **k)
    return res


def _safe_send_message(chat_id, text, *a, **kw):
    raw = text
    text = _safe_wrap_text(text)
    if not isinstance(text, str) or _u16(text) <= _TG_MAX_LEN:
        try:
            return _orig_send_message(chat_id, text, *a, **dict(kw))
        except Exception as e:
            if "MESSAGE_TOO_LONG" in str(e) and isinstance(raw, str):
                return _send_in_chunks(chat_id, raw, a, dict(kw), 3000)
            if _is_parse_error(e) and isinstance(raw, str):
                _logger.warning("HTML parse xatosi (send): %s | matn boshi: %r", e, raw[:120])
                try:
                    return _orig_send_message(chat_id, _fix_html(raw), *a, **dict(kw))
                except Exception as e2:
                    if not _is_parse_error(e2):
                        raise
                    k2 = dict(kw); k2["parse_mode"] = None
                    return _orig_send_message(chat_id, _plain_text(raw), *a, **k2)
            raise
    chunks = _split_text(text)
    markup = kw.pop("reply_markup", None)
    res = None
    for i, ch in enumerate(chunks):
        k = dict(kw)
        if i == len(chunks) - 1 and markup is not None:
            k["reply_markup"] = markup
        res = _orig_send_message(chat_id, _safe_wrap_text(ch), *a, **k)
    return res


def _safe_edit_message_text(text, *a, **kw):
    raw = text
    text = _safe_wrap_text(text)
    if not isinstance(text, str) or _u16(text) <= _TG_MAX_LEN:
        try:
            return _orig_edit_message_text(text, *a, **kw)
        except Exception as e:
            if _is_parse_error(e) and isinstance(raw, str):
                _logger.warning("HTML parse xatosi (edit): %s | matn boshi: %r", e, raw[:120])
                try:
                    return _orig_edit_message_text(_fix_html(raw), *a, **kw)
                except Exception as e2:
                    if not _is_parse_error(e2):
                        raise
                    k2 = dict(kw); k2["parse_mode"] = None
                    return _orig_edit_message_text(_plain_text(raw), *a, **k2)
            if "MESSAGE_TOO_LONG" in str(e) and isinstance(raw, str):
                cid = kw.get("chat_id") if kw.get("chat_id") is not None else (a[0] if a else None)
                kw2 = {k: v for k, v in kw.items() if k != "reply_markup"}
                chunks = _split_text(raw, 3000)
                res = _orig_edit_message_text(chunks[0], *a, **kw2)
                for i, ch in enumerate(chunks[1:], 1):
                    k = {}
                    if kw.get("parse_mode"):
                        k["parse_mode"] = kw["parse_mode"]
                    if i == len(chunks) - 1 and kw.get("reply_markup") is not None:
                        k["reply_markup"] = kw["reply_markup"]
                    try:
                        _orig_send_message(cid, ch, **k)
                    except Exception:
                        pass
                return res
            raise
    chunks = _split_text(text)
    chat_id = kw.get("chat_id")
    if chat_id is None and a:
        chat_id = a[0]
    res = _orig_edit_message_text(_safe_wrap_text(chunks[0]), *a, **{k: v for k, v in kw.items() if k != "reply_markup"})
    if chat_id is not None:
        for i, ch in enumerate(chunks[1:], 1):
            k = {}
            if kw.get("parse_mode"):
                k["parse_mode"] = kw["parse_mode"]
            if i == len(chunks) - 1 and kw.get("reply_markup") is not None:
                k["reply_markup"] = kw["reply_markup"]
            try:
                _orig_send_message(chat_id, _safe_wrap_text(ch), **k)
            except Exception:
                pass
    return res


bot.send_message = _safe_send_message
bot.edit_message_text = _safe_edit_message_text


def role_portrait(role_name):
    """Rol nomidagi ODDIY (standart) emojini Hanter to'plamining HAQIQIY
    PORTRETIGA ALMASHTIRIB qaytaradi (ID topilsa) — ENDI ikkalasi ham birga
    ko'rinib, "3 ta emoji" xatosiga sabab bo'lmasligi uchun standart emoji
    OLIB TASHLANADI, faqat custom portret qoladi. ID topilmasa, rol nomini
    o'zgarishsiz qaytaradi — xato bermaydi."""
    portrait_id = ROLE_PORTRAIT_EMOJI.get(role_name)
    if not portrait_id:
        return role_name
    parts = role_name.rsplit(" ", 1)
    name_only = parts[0] if len(parts) == 2 else role_name
    return f'<tg-emoji emoji-id="{portrait_id}">🎭</tg-emoji> {name_only}'


def premium_emoji(key, fallback="⭐️"):
    """PREMIUM_EMOJI lug'atidan shu kalit uchun tayyor HTML <tg-emoji> tegini qaytaradi.
    ID hali kiritilmagan bo'lsa, shunchaki oddiy fallback emojini qaytaradi (xato bermaydi)."""
    emoji_id = PREMIUM_EMOJI.get(key)
    if not emoji_id:
        return fallback
    return f'<tg-emoji emoji-id="{emoji_id}">{fallback}</tg-emoji>'


def render_premium_text(template, **emoji_keys):
    """Shablon matn ichidagi {key} joylarini mos PREMIUM_EMOJI bilan almashtiradi.
    Masalan: render_premium_text("G'alaba {fire}!", fire=("fire", "🔥"))
    bu yerda qiymat (kalit, fallback) juftligi."""
    values = {name: premium_emoji(key, fallback) for name, (key, fallback) in emoji_keys.items()}
    return template.format(**values)


def send_premium_message(chat_id, text_with_tags, reply_markup=None):
    """<tg-emoji> teglari bo'lgan HTML matnni yuboradi. Agar biror sababdan xato
    chiqsa (masalan juda eski bot kutubxonasi versiyasi), oddiy xabar sifatida
    (teglarsiz, faqat fallback emojilar bilan) qayta yuborishga urinadi."""
    try:
        return bot.send_message(chat_id, text_with_tags, reply_markup=reply_markup)
    except Exception as e:
        _logger.warning("Premium emoji xabari yuborilmadi, oddiy matn bilan urinilmoqda: %s", e)
        import re as _re
        plain = _re.sub(r'<tg-emoji[^>]*>(.*?)</tg-emoji>', r'\1', text_with_tags)
        return bot.send_message(chat_id, plain, reply_markup=reply_markup)


def _extract_custom_emoji_entities(message):
    """Xabardagi barcha custom_emoji turidagi entity'larni (ID + fallback emoji matni
    bilan birga) ro'yxat qilib qaytaradi."""
    result = []
    entities = (message.entities or []) + (message.caption_entities or [])
    text = message.text or message.caption or ""
    # Telegram offset/length UTF-16 birliklarida hisoblanadi — Python uchun to'g'ri kesish
    utf16 = text.encode("utf-16-le")
    for ent in entities:
        if ent.type == "custom_emoji":
            try:
                piece = utf16[ent.offset * 2: (ent.offset + ent.length) * 2].decode("utf-16-le")
            except Exception:
                piece = ""
            result.append((ent.custom_emoji_id, piece))
    return result


@bot.message_handler(
    func=lambda m: m.chat.type == "private" and _extract_custom_emoji_entities(m),
    content_types=["text"],
)
def collect_custom_emoji_ids(message):
    """🆔 YORDAMCHI: bot egasi shaxsiy chatda o'zi yaratgan maxsus emojilarni yuborsa,
    bot ularning HAR BIRINING custom_emoji_id raqamini konsolga (log) VA chatga
    darhol qaytarib beradi. Bu orqali PREMIUM_EMOJI lug'atini to'ldirish oson bo'ladi."""
    if not is_owner(message.from_user.id):
        return
    found = _extract_custom_emoji_entities(message)
    if not found:
        return
    if _toifa_try_consume(message, found):
        return
    if _pe_try_consume(message, found):
        return
    lines = ["🆔 <b>Topilgan maxsus emoji ID'lari:</b>\n"]
    for emoji_id, fallback in found:
        line = f"{fallback}  →  <code>{emoji_id}</code>"
        lines.append(line)
        _logger.info("Custom emoji topildi: fallback=%s id=%s", fallback, emoji_id)
        print(f"[PREMIUM EMOJI] fallback={fallback!r}  custom_emoji_id={emoji_id}")
    lines.append("\n📋 Shu ID'larni <code>PREMIUM_EMOJI</code> lug'atiga qo'shing, masalan:\n"
                  f'<code>"nomi": "{found[0][0]}"</code>')
    bot.send_message(message.chat.id, "\n".join(lines))


@bot.message_handler(commands=["hanter_ids"])
def cmd_hanter_ids(message):
    """🆔 VAQTINCHALIK BUYRUQ: 'HanterMafiaBot' maxsus emoji to'plamini
    Telegram serveridan TO'G'RIDAN-TO'G'RI so'rab, uning HAQIQIY (yuklangan)
    tartibida, 1 dan boshlab raqamlab chiqaradi. Qo'lda emoji terib
    nusxalashda tartib buzilishi mumkin — bu buyruq esa hech qachon
    adashmaydi, chunki ma'lumotni bevosita Telegramning o'zidan oladi.
    Faqat bot egasi uchun ishlaydi. Ishni tugatgach shu buyruqni (va shu
    funksiyani) kodda qoldirish yoki o'chirish ixtiyoriy — xavfsiz, hech
    kimga zarar keltirmaydi, faqat egaga ma'lumot chiqaradi."""
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    try:
        sset = bot.get_sticker_set("HanterMafiaBot")
        lines = [f"{i}. {s.emoji}  →  {s.custom_emoji_id}" for i, s in enumerate(sset.stickers, start=1)]
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ To'plamni olishda xato: {e}")
        return
    bot.send_message(message.chat.id, f"🆔 Jami: {len(lines)} ta emoji topildi. Tartib — to'plamdagi HAQIQIY (yuklangan) tartib.")
    chunk, length = [], 0
    for line in lines:
        chunk.append(line)
        length += len(line) + 1
        if length > 3000:
            bot.send_message(message.chat.id, "\n".join(chunk))
            chunk, length = [], 0
    if chunk:
        bot.send_message(message.chat.id, "\n".join(chunk))


