# ================================================================================
#  🎨 PREMIUM EMOJILARNI BOT ICHIDAN ALMASHTIRISH  —  /emoji  (faqat owner)
#  ================================================================================
#  Owner /emoji bosadi → toifani tanlaydi → almashtirmoqchi bo'lgan emojini tanlaydi →
#  botga YANGI premium emojini yuboradi → bot uning ID'sini bazaga saqlaydi.
#  Almashtirish ID bo'yicha BARCHA joyda (EMOJI_TO_ID, PREMIUM_EMOJI, ROLE_PORTRAIT_EMOJI,
#  CLAN_PORTRAIT_EMOJI) birdaniga qo'llanadi va botni qayta ishga tushirmasdan ishlaydi.
#  Qayta ishga tushirilganda ham saqlanib qoladi (bot_settings: "premium_ovr").
# ================================================================================
_PE_CATS = {
    "e": ("🔤 Oddiy emoji → premium", EMOJI_TO_ID),
    "k": ("🗂 Nomli emojilar", PREMIUM_EMOJI),
    "r": ("🎭 Rol portretlari", ROLE_PORTRAIT_EMOJI),
    "c": ("🏰 Klan belgilari", CLAN_PORTRAIT_EMOJI),
}
_PE_DEFAULTS = {c: dict(d) for c, (_t, d) in _PE_CATS.items()}   # asl (kod ichidagi) qiymatlar
_PE_WAIT = {}        # owner_id -> {"id": eski(asl) ID, "chat": chat_id}
_PE_PER_PAGE = 10


def _pe_load():
    try:
        raw = get_setting("premium_ovr")
        data = json.loads(raw) if raw else {}
        return {str(k): str(v) for k, v in data.items()} if isinstance(data, dict) else {}
    except Exception:
        return {}


def _pe_apply(ovr=None):
    """Saqlangan almashtirishlarni jonli lug'atlarga qo'llaydi (asl ID → yangi ID)."""
    if ovr is None:
        ovr = _pe_load()
    # 🍎 Standart holat: HAMMA emoji oddiy (iPhone/Unicode). Faqat owner /emoji orqali
    # alohida belgilab bergan o'rinlar maxsus (custom) emoji bilan chiqadi.
    for c, (_t, d) in _PE_CATS.items():
        for k, orig in _PE_DEFAULTS[c].items():
            d[k] = ovr.get(orig, "")


def _pe_save(ovr):
    set_setting("premium_ovr", json.dumps(ovr))
    _pe_apply(ovr)


def _pe_items(cat):
    """Toifadagi noyob ASL ID'lar ro'yxati: [(asl_id, yorliq)]"""
    seen, out = {}, []
    for k, orig in _PE_DEFAULTS[cat].items():
        if orig not in seen:
            seen[orig] = len(out)
            out.append([orig, [k]])
        else:
            out[seen[orig]][1].append(k)
    return [(o, "/".join(ks[:2]) + (f" +{len(ks) - 2}" if len(ks) > 2 else "")) for o, ks in out]


def _pe_valid_id(s):
    return bool(re.fullmatch(r"\d{10,25}", str(s or "")))


def _pe_kb_main():
    ovr = _pe_load()
    kb = types.InlineKeyboardMarkup(row_width=1)
    for c, (title, _d) in _PE_CATS.items():
        kb.add(types.InlineKeyboardButton(f"{title} ({len(_pe_items(c))})", callback_data=f"pe|l|{c}|0"))
    kb.add(types.InlineKeyboardButton("👑 Toifa emojilari", callback_data="tem|menu"))
    kb.add(types.InlineKeyboardButton("🧪 Hammasini ko'rish (sinov)", callback_data="pe|test"))
    if ovr:
        kb.add(types.InlineKeyboardButton(f"♻️ Hammasini asliga qaytarish ({len(ovr)})", callback_data="pe|rall"))
    return kb


def _pe_kb_list(cat, page):
    items = _pe_items(cat)
    ovr = _pe_load()
    pages = max(1, (len(items) + _PE_PER_PAGE - 1) // _PE_PER_PAGE)
    page = max(0, min(page, pages - 1))
    kb = types.InlineKeyboardMarkup(row_width=2)
    row = []
    for i in range(page * _PE_PER_PAGE, min(len(items), (page + 1) * _PE_PER_PAGE)):
        orig, label = items[i]
        mark = "✏️ " if orig in ovr else ""
        row.append(types.InlineKeyboardButton(f"{mark}{label}"[:30], callback_data=f"pe|s|{cat}|{i}"))
        if len(row) == 2:
            kb.row(*row)
            row = []
    if row:
        kb.row(*row)
    nav = []
    if page > 0:
        nav.append(types.InlineKeyboardButton("◀️ Oldingi", callback_data=f"pe|l|{cat}|{page - 1}"))
    if page < pages - 1:
        nav.append(types.InlineKeyboardButton("Keyingi ▶️", callback_data=f"pe|l|{cat}|{page + 1}"))
    if nav:
        kb.row(*nav)
    kb.add(types.InlineKeyboardButton("⬅️ Orqaga", callback_data="pe|m"))
    return kb, page, pages


def _pe_show(call, text, kb):
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        try:
            bot.send_message(call.message.chat.id, text, reply_markup=kb)
        except Exception:
            _logger.exception("pe_show")


_PE_HELP = ("🎨 <b>Premium emoji boshqaruvi</b>\n\n"
            "Bot hozir HAMMA joyda oddiy (iPhone) emojilarni ishlatadi. Istagan emojingizni shu yerdan "
            "maxsus (premium) emojiga almashtirasiz — kodga tegmasdan, botni qayta ishga tushirmasdan.\n\n"
            "1️⃣ Toifani tanlang\n2️⃣ Almashtiriladigan emojini tanlang\n"
            "3️⃣ Botga yangi premium emojini yuboring (shaxsiy chatda)\n\n"
            "ℹ️ Almashtirish shu emoji ishlatilgan <b>barcha joyda</b> birdaniga qo'llanadi.\n"
            "✏️ belgisi — premiumga almashtirilgan emojilar. ♻️ — oddiy emojiga qaytaradi.")


@bot.message_handler(commands=["emoji"])
def cmd_emoji_manage(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    if message.chat.type != "private":
        bot.send_message(message.chat.id, "ℹ️ Premium emojini almashtirish uchun menga shaxsiy chatda /emoji yozing.")
        return
    _PE_WAIT.pop(message.from_user.id, None)
    bot.send_message(message.chat.id, _PE_HELP, reply_markup=_pe_kb_main())


def _pe_try_consume(message, found):
    """Owner almashtirish kutayotgan bo'lsa, yuborilgan birinchi premium emoji ID'sini saqlaydi."""
    w = _PE_WAIT.get(message.from_user.id)
    if not w:
        return False
    new_id = str(found[0][0])
    if not _pe_valid_id(new_id):
        bot.send_message(message.chat.id, "❌ Emoji ID noto'g'ri. Qaytadan yuboring.")
        return True
    _PE_WAIT.pop(message.from_user.id, None)
    ovr = _pe_load()
    orig = w["id"]
    if new_id == orig:
        ovr.pop(orig, None)
    else:
        ovr[orig] = new_id
    _pe_save(ovr)
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✅ Tayyor — ro'yxatga qaytish", callback_data=f"pe|l|{w['cat']}|{w['page']}"))
    kb.add(types.InlineKeyboardButton("♻️ Asliga qaytarish", callback_data=f"pe|r|{w['cat']}|{w['idx']}"))
    txt = (f"✅ <b>Almashtirildi!</b>\n\n"
           f"Eski: <tg-emoji emoji-id=\"{orig}\">⭐️</tg-emoji>\n"
           f"Yangi: <tg-emoji emoji-id=\"{new_id}\">⭐️</tg-emoji>\n\n"
           "Endi bot shu emojini ishlatadi.")
    try:
        bot.send_message(message.chat.id, txt, reply_markup=kb)
    except Exception:
        bot.send_message(message.chat.id, re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", txt), reply_markup=kb)
    return True


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("pe|"))
def cb_premium_emoji(call):
    uid = call.from_user.id
    if not is_owner(uid):
        try:
            bot.answer_callback_query(call.id, "🔒 Faqat bot egasi uchun.", show_alert=True)
        except Exception:
            pass
        return
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    parts = call.data.split("|")
    act = parts[1] if len(parts) > 1 else "m"
    try:
        if act == "m":
            _PE_WAIT.pop(uid, None)
            _pe_show(call, _PE_HELP, _pe_kb_main())
        elif act == "l":
            _PE_WAIT.pop(uid, None)
            cat, page = parts[2], int(parts[3])
            if cat not in _PE_CATS:
                return
            kb, page, pages = _pe_kb_list(cat, page)
            _pe_show(call, f"{_PE_CATS[cat][0]}\n\nSahifa {page + 1}/{pages}. Almashtirmoqchi bo'lganingizni bosing:", kb)
        elif act == "s":
            cat, idx = parts[2], int(parts[3])
            items = _pe_items(cat)
            orig, label = items[idx]
            _PE_WAIT[uid] = {"id": orig, "cat": cat, "idx": idx, "page": idx // _PE_PER_PAGE, "chat": call.message.chat.id}
            cur_id = _pe_load().get(orig, "")
            _cur_html = f'<tg-emoji emoji-id="{cur_id}">⭐️</tg-emoji>' if cur_id else "standart emoji"
            kb = types.InlineKeyboardMarkup(row_width=1)
            kb.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data=f"pe|l|{cat}|{idx // _PE_PER_PAGE}"))
            txt = (f"✏️ <b>{esc(label)}</b>\n\nHozirgi: {_cur_html}\n\n"
                   "👉 Endi menga <b>yangi premium emojini</b> yuboring (klaviaturadan tanlab, oddiy xabar sifatida).")
            try:
                _pe_show(call, txt, kb)
            except Exception:
                _pe_show(call, re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", txt), kb)
        elif act == "r":
            cat, idx = parts[2], int(parts[3])
            orig = _pe_items(cat)[idx][0]
            ovr = _pe_load()
            ovr.pop(orig, None)
            _pe_save(ovr)
            kb, page, pages = _pe_kb_list(cat, idx // _PE_PER_PAGE)
            _pe_show(call, f"♻️ Asliga qaytarildi.\n\n{_PE_CATS[cat][0]}\n\nSahifa {page + 1}/{pages}:", kb)
        elif act == "rall":
            _pe_save({})
            _pe_show(call, "♻️ Hammasi asliga qaytarildi.\n\n" + _PE_HELP, _pe_kb_main())
        elif act == "test":
            seen, lines = set(), []
            for c in _PE_CATS:
                for orig, label in _pe_items(c):
                    nid = _pe_load().get(orig, orig)
                    if (c, orig) in seen:
                        continue
                    seen.add((c, orig))
                    lines.append(f'<tg-emoji emoji-id="{nid}">⭐️</tg-emoji> {esc(label)}')
            chunk = []
            for ln in lines:
                chunk.append(ln)
                if sum(len(x) + 1 for x in chunk) > 3000:
                    send_premium_message(call.message.chat.id, "\n".join(chunk))
                    chunk = []
            if chunk:
                send_premium_message(call.message.chat.id, "\n".join(chunk))
    except Exception:
        _logger.exception("cb_premium_emoji")


try:
    _pe_apply()
except Exception:
    _logger.exception("premium emoji almashtirishlarini yuklashda xato")



