def _tour_kb(n):
    kb = types.InlineKeyboardMarkup()
    act = _TOUR[n][2]
    if act:
        kb.add(types.InlineKeyboardButton(act[1], callback_data=act[0]))
    nav = []
    if n > 0:
        nav.append(types.InlineKeyboardButton("🔙 Orqaga", callback_data=f"tour|{n - 1}"))
    if n < len(_TOUR) - 1:
        nav.append(types.InlineKeyboardButton("Keyingi ➡️", callback_data=f"tour|{n + 1}"))
    if nav:
        kb.row(*nav)
    kb.add(types.InlineKeyboardButton("🏠 Bosh menyu" if n == len(_TOUR) - 1 else "🏠 Menyuga o'tish", callback_data="menu|main_back"))
    return kb


@bot.callback_query_handler(func=lambda c: c.data.startswith("tour|") or c.data == "menu|guide")
def cb_menu_guide(call):
    try:
        maybe_capture_owner(call.from_user)
        try:
            n = int(call.data.split("|")[1]) if call.data.startswith("tour|") else 0
        except (ValueError, IndexError):
            n = 0
        n = max(0, min(n, len(_TOUR) - 1))
        bot.answer_callback_query(call.id)
        title, body, _a = _TOUR[n]
        dots = "".join("●" if i == n else "○" for i in range(len(_TOUR)))
        txt = f"🧭 <b>Qo'llanma · {n + 1}/{len(_TOUR)}</b>\n{dots}\n\n<b>{title}</b>\n\n{body}"
        try:   # bosh menyu rasmli xabar — rasmli xabarda matn o'rniga caption tahrirlanadi
            if _msg_has_media(call.message):
                bot.edit_message_caption(txt, call.message.chat.id, call.message.message_id, reply_markup=_tour_kb(n))
                return
        except Exception:
            pass
        smart_render(call, txt, _tour_kb(n))
    except Exception as e:
        _logger.warning("cb_menu_guide xatolik: %s", e)


