# ================================================================================
#  🔔 "Bildirish" — guruhda yangi o'yin ochilganda obunachilarga DM
# ================================================================================
def _bld_get(chat_id):
    try:
        return set(json.loads(get_setting(f"bildir_{chat_id}") or "[]"))
    except Exception:
        return set()


def _bld_put(chat_id, subs):
    set_setting(f"bildir_{chat_id}", json.dumps(sorted(subs)[:5000]))


def offer_bildirish(uid, chat_id, title):
    """O'lgach / o'yin tugagach: yangi o'yin haqida ogohlantirishni so'raydi (obuna bo'lmaganlarga)."""
    try:
        if uid in _bld_get(chat_id):
            return
        kb = types.InlineKeyboardMarkup()
        kb.row(types.InlineKeyboardButton("🔔 Ogohlantirish", callback_data=f"bld|1|{chat_id}"),
               types.InlineKeyboardButton("🔕 Bekor qilish", callback_data=f"bld|0|{chat_id}"))
        safe_send(uid, f"<b>{esc(title or 'Guruh')}</b> guruhida yangi o'yin boshlangani haqida ogohlantirilsinmi?", kb)
    except Exception:
        _logger.warning("bildirish taklifi yuborilmadi", exc_info=True)


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("bld|"))
def cb_bildirish(call):
    _, on, cid = call.data.split("|")
    chat_id = int(cid)
    subs = _bld_get(chat_id)
    if on == "1":
        subs.add(call.from_user.id)
        msg, txt = "🔔 Yangi o'yin boshlanganda xabar beramiz.", "🔔"
    else:
        subs.discard(call.from_user.id)
        msg, txt = "🔕 Bekor qilindi.", "🔕"
    _bld_put(chat_id, subs)
    bot.answer_callback_query(call.id, txt)
    try:
        bot.edit_message_text(msg, call.message.chat.id, call.message.message_id)
    except Exception:
        pass


def notify_game_subscribers(chat_id, title):
    def _run():
        subs = _bld_get(chat_id)
        if not subs:
            return
        kb = None
        link = (GAMES.get(chat_id) or {}).get("group_link")
        if link:
            kb = types.InlineKeyboardMarkup()
            kb.add(types.InlineKeyboardButton("🚀 Guruhga o'tish", url=link))
        done = set()
        for u in list(subs):
            safe_send(u, f"🎮 <b>{esc(title or 'Guruh')}</b> guruhida yangi o'yin boshlandi!", kb)
            done.add(u)
            time.sleep(0.05)
        # 🔔 Bir martalik: xabar yuborilgach obuna o'chadi — keyingi so'rov o'yin oxirida yuboriladi
        _bld_put(chat_id, _bld_get(chat_id) - done)
    threading.Thread(target=_run, daemon=True).start()


@bot.message_handler(commands=["NewGame", "newgame"])
def cmd_newgame(message, anon=False):
    global BOT_USERNAME
    maybe_capture_owner(message.from_user)
    if BOT_USERNAME is None:
        BOT_USERNAME = bot.get_me().username

    safe_delete(message)

    if message.chat.type not in ("group", "supergroup"):
        return
    if not is_authorized(message):
        bot.send_message(message.chat.id, "⛔ Bu buyruqni faqat guruh admini yoki bot egasi ishlatishi mumkin.")
        return

    chat_id = message.chat.id
    add_known_group(chat_id, message.chat.title or "Nomsiz guruh")

    with _glock(chat_id):
        old = GAMES.get(chat_id)
        if old and old.get("join_msg_id"):
            _close_join_message(chat_id, old["join_msg_id"])

        GAMES[chat_id] = new_game(chat_id, message.chat.title)
        # 🐺🦅💍 Owner /teamgame yoki /parateam orqali shu guruh uchun oldindan
        # yoqib qo'ygan bo'lsa — yangi o'yin AVTOMATIK shu rejimda boshlanadi.
        GAMES[chat_id]["squad_mode"] = get_setting(f"squad_mode_{chat_id}") == "1"
        GAMES[chat_id]["couple_mode"] = get_setting(f"couple_mode_{chat_id}") == "1"
        GAMES[chat_id]["anon"] = bool(anon)
        try:
            GAMES[chat_id]["group_link"] = bot.export_chat_invite_link(chat_id)
        except Exception:
            pass

        kb = build_join_markup(chat_id, GAMES[chat_id])
        mode_lines = []
        if GAMES[chat_id]["squad_mode"]:
            mode_lines.append("🔴🔵 <b>Qizil va Ko'k</b> — jamoangizni tanlang!")
        if GAMES[chat_id]["couple_mode"]:
            mode_lines.append("💍 <b>Para</b> — ikkalangiz bitta tugma bilan qo'shiling!")
        if GAMES[chat_id]["anon"]:
            mode_lines.append(f"{anon_icon()} <b>Anonim</b> — o'yin boshlangach ismlar yashirinadi.")
        mode_block = ("\n" + "\n".join(mode_lines) + "\n") if mode_lines else ""
        sent = bot.send_message(
            chat_id,
            "🎮 <b>Ro'yxat ochiq!</b> Pastdagi tugmani bosing.\n"
            f"{mode_block}\n"
            "👥 <b>O'yinchilar (0):</b> hali yo'q",
            reply_markup=kb,
        )
        GAMES[chat_id]["join_msg_id"] = sent.message_id
        try:
            bot.pin_chat_message(chat_id, sent.message_id, disable_notification=True)
        except Exception:
            pass
        notify_game_subscribers(chat_id, message.chat.title)


# ================================================================================
#  /game — SODDALASHTIRILGAN kirish nuqtasi: agar lobbi hali OCHIQ bo'lsa (hali
#  /startgame berilmagan bo'lsa), yangisini yaratib yubormaydi — o'sha ochiq
#  lobbini qayta (pastga) yuboradi, xuddi "/game" allaqachon ishga tushirilgan
#  o'yinni qayta ko'rsatadigandek. Aks holda /NewGame bilan bir xil ishlaydi.
# ================================================================================

@bot.message_handler(commands=["game", "Game"])
def cmd_game(message):
    maybe_capture_owner(message.from_user)
    if message.chat.type not in ("group", "supergroup"):
        safe_delete(message)
        return
    if not is_authorized(message):
        safe_delete(message)
        bot.send_message(message.chat.id, "⛔ Bu buyruqni faqat guruh admini yoki bot egasi ishlatishi mumkin.")
        return

    chat_id = message.chat.id
    with _glock(chat_id):
        existing = GAMES.get(chat_id)
        if existing and existing.get("phase") == "waiting":
            safe_delete(message)
            if existing.get("join_msg_id"):
                _close_join_message(chat_id, existing["join_msg_id"])
            kb = build_join_markup(chat_id, existing)
            names = [p["name"] for p in existing["players"].values()]
            players_block = "\n".join(f"• {n}" for n in names) if names else "Hozircha hech kim yo'q."
            sent = bot.send_message(
                chat_id,
                "🎮 <b>Ro'yxat ochiq!</b> Pastdagi tugmani bosing.\n\n"
                f"👥 <b>O'yinchilar ({len(names)}):</b>\n{players_block}",
                reply_markup=kb,
            )
            existing["join_msg_id"] = sent.message_id
            try:
                bot.pin_chat_message(chat_id, sent.message_id, disable_notification=True)
            except Exception:
                pass
            return
    # 🎮 Ochiq lobbi yo'q — xuddi /NewGame kabi yangisini ochamiz
    cmd_newgame(message)


def _close_join_message(chat_id, msg_id):
    """🔧 TUZATISH: eski "🎮 O'yinga qo'shilish" e'lon xabarini yopadi.
    Avval faqat unpin+delete qilinardi — agar botda guruhda xabar o'chirish
    huquqi bo'lmasa (masalan admin huquqi olib qo'yilgan bo'lsa), ikkalasi
    ham JIM ravishda muvaffaqiyatsiz bo'lib, ESKI TUGMA ABADIY GURUHDA
    QOLIB KETARDI — odamlar keyin ham bosaverib "o'yin allaqachon tugagan"
    xatosini olaverishardi. Endi delete ishlamasa ham, KAMIDA tugmani
    (reply_markup=None) olib tashlashga urinamiz, shunda tugma bosilmay qoladi."""
    if not msg_id:
        return
    try:
        bot.unpin_chat_message(chat_id, msg_id)
    except Exception:
        pass
    try:
        bot.delete_message(chat_id, msg_id)
        return  # o'chirildi — tugma ham u bilan birga yo'qoldi, boshqa hech narsa kerak emas
    except Exception:
        pass
    # 🔧 zaxira reja: o'chirib bo'lmasa ham, hech bo'lmasa TUGMANI olib tashlaymiz
    try:
        bot.edit_message_reply_markup(chat_id, msg_id, reply_markup=None)
    except Exception:
        pass
    try:
        bot.edit_message_text("🔒 Bu o'yin lobbysi endi yopiq — yangi o'yin uchun /NewGame kuting.", chat_id, msg_id)
    except Exception:
        pass


def build_join_text(game):
    lines = [
        "🎮 <b>Ro'yxat ochiq!</b>\n",
        f"👥 <b>O'yinchilar ({len(game['players'])}):</b>\n{player_line_list(game)}\n",
    ]
    if game.get("squad_mode"):
        wolf_n = sum(1 for uid in game["players"] if game["squads"].get(uid) == "wolf")
        eagle_n = sum(1 for uid in game["players"] if game["squads"].get(uid) == "eagle")
        # 🤫 Kim qaysi jamoada ekani MAXFIY qoladi — o'yin oxirigacha guruhda
        # faqat SONI ko'rsatiladi, ismlar emas (asosiy Hunter Mafia'dagi kabi
        # rollar ham maxfiy bo'lgani kabi). YANGI: endi har bir jamoa uchun
        # ALOHIDA-ALOHIDA son ham ko'rsatiladi (masalan "Eagles — 2 ta").
        lines.append(
            f"🔴🔵 {squad_counts_line(game)}\n"
        )
    if game.get("couple_mode"):
        lines.append("💍 <i>Para: ikkalangiz oxirigacha tirik qolsangiz — g'olibsiz.</i>\n")
    if game.get("anon"):
        lines.append(f"{anon_icon()} <i>Anonim: o'yin boshlangach ismlar yashirinadi.</i>\n")
    return "\n".join(lines)


def build_join_markup(chat_id, game=None):
    kb = types.InlineKeyboardMarkup()
    # 🔧 Jamoaviy (squad) yoki Para (couple) rejimda oddiy "yakka" qo'shilish
    # tugmasi endi umuman ko'RSATILMAYDI — bu rejimlarda HAR BIR ishtirokchi
    # albatta jamoasini yoki juftligini tanlab qo'shilishi SHART (aks holda
    # "oxirgi juftlik/jamoa g'olib" qoidasi ishonchli ishlamay qolardi).
    show_plain_join = not (game and (game.get("squad_mode") or game.get("couple_mode")))
    if show_plain_join:
        if BOT_USERNAME:
            # 🤖 endi guruhdagi tugma bosilganda foydalanuvchi avtomatik botning shaxsiy
            # chatiga o'tkaziladi va o'sha yerda o'yinga qo'shiladi (do'stona, tushunarli UX)
            kb.add(types.InlineKeyboardButton("🎮 O'yinga qo'shilish", url=f"https://t.me/{BOT_USERNAME}?start=join_{chat_id}"))
        else:
            kb.add(types.InlineKeyboardButton("🎮 O'yinga qo'shilish", callback_data=f"join|{chat_id}"))
    if game and game.get("squad_mode"):
        if BOT_USERNAME:
            # 🤖 Oddiy qo'shilish kabi — avval botning shaxsiy chatiga o'tkaziladi,
            # shunda DM ochilgani kafolatlanadi (aks holda tun kelganda rol/harakat
            # xabari yetib bormay, o'yinchi sababsiz AFK bo'lib qolardi).
            kb.add(
                types.InlineKeyboardButton("🔴 Qizil jamoa", url=f"https://t.me/{BOT_USERNAME}?start=squadjoin_{chat_id}_wolf"),
                types.InlineKeyboardButton("🔵 Ko'k jamoa", url=f"https://t.me/{BOT_USERNAME}?start=squadjoin_{chat_id}_eagle"),
            )
        else:
            kb.add(
                types.InlineKeyboardButton("🔴 Qizil jamoa", callback_data=f"squadjoin|{chat_id}|wolf"),
                types.InlineKeyboardButton("🔵 Ko'k jamoa", callback_data=f"squadjoin|{chat_id}|eagle"),
            )
    if game and game.get("couple_mode"):
        if BOT_USERNAME:
            kb.add(types.InlineKeyboardButton("💍 Men va turmush o'rtog'imni qo'shish", url=f"https://t.me/{BOT_USERNAME}?start=couplejoin_{chat_id}"))
        else:
            kb.add(types.InlineKeyboardButton("💍 Men va turmush o'rtog'imni qo'shish", callback_data=f"couplejoin|{chat_id}"))
    return kb


