# ================================================================================
#  /start (guruhda) — asosiy o'yinni boshlash. Eski /StartGame nomi endi yo'q,
#  cmd_start() shu funksiyani to'g'ridan-to'g'ri chaqiradi.
# ================================================================================

def cmd_startgame(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)

    if message.chat.type not in ("group", "supergroup"):
        return
    if not is_authorized(message):
        # ⚙️ v8: guruh sozlamasi "Har bir ishtirokchi boshlaydi" bo'lsa, o'yinga
        # qo'shilgan har qanday ishtirokchi ham boshlay oladi.
        _lobby = GAMES.get(message.chat.id)
        if not (_lobby and gsv(_lobby, "who_starts") == "all" and message.from_user.id in _lobby["players"]):
            bot.send_message(message.chat.id, "⛔ Bu buyruqni faqat guruh admini yoki bot egasi ishlatishi mumkin.")
            return

    chat_id = message.chat.id
    game = GAMES.get(chat_id)
    if not game or game["phase"] != "waiting":
        bot.send_message(chat_id, "❌ Avval /NewGame bilan o'yin oching.")
        return
    _min_players = game_min_players(game)
    if len(game["players"]) < _min_players:
        bot.send_message(chat_id, f"❌ Kamida {_min_players} ta ishtirokchi kerak.")
        return

    # 🔴🔵 XATOLIK TUZATILDI: Qizil va Ko'k o'yinida ilgari HECH QANDAY tekshiruv
    # yo'q edi — agar hamma faqat bitta jamoaga (masalan faqat 🔴 Qizil) yozilib,
    # 🔵 Ko'kda birortа ham odam bo'lmasa, o'yin boshlangan zahoti (birinchi
    # tundan oldinoq) "Burgut butunlay qirildi" deb NOTO'G'RI g'olib e'lon
    # qilinardi — o'yin HAQIQIY boshlanmasdanoq buzilib qolardi. Endi ikkala
    # jamoada ham kamida 2 tadan o'yinchi bo'lishi SHART, aks holda o'yin
    # boshlanmaydi va admin/o'yinchilarga aniq sabab ko'rsatiladi.
    if game.get("squad_mode"):
        wolf_n = sum(1 for u in list(game["players"]) if game.get("squads", {}).get(u) == "wolf")
        eagle_n = sum(1 for u in list(game["players"]) if game.get("squads", {}).get(u) == "eagle")
        unassigned_n = len(game["players"]) - wolf_n - eagle_n
        if wolf_n < 2 or eagle_n < 2:
            bot.send_message(
                chat_id,
                f"❌ Qizil va Ko'k o'yinini boshlab bo'lmaydi — jamoalar muvozanatsiz!\n\n"
                f"🔴 Qizil: {wolf_n} kishi\n🔵 Ko'k: {eagle_n} kishi\n"
                + (f"❓ Jamoa tanlamaganlar: {unassigned_n} kishi\n" if unassigned_n else "")
                + f"\nHar ikkala jamoada ham kamida 2 tadan o'yinchi bo'lishi kerak. "
                  f"Yetishmayotgan jamoaga qo'shilishni so'rang yoki /vsgame bilan qayta e'lon qiling."
            )
            return

    if game.get("join_msg_id"):
        _close_join_message(chat_id, game["join_msg_id"])
        game["join_msg_id"] = None

    # 🐺🦅 Muvozanatlashtirish uchun: rol beriladigan chiptali (forced_role)
    # o'yinchilarni ROL ASSIGN QILISHDAN OLDIN eslab qolamiz — ular pullab
    # olgan rolini keyin muvozanat almashinuvida yo'qotib qo'ymasin.
    _forced_uids = set(game.get("forced_roles", {}).keys())
    for _uid in list(game["players"]):
        if _uid not in _forced_uids and role_ticket_get(_uid):
            _forced_uids.add(_uid)

    assign_roles(game)
    if game.get("squad_mode"):
        _balance_squad_mafia(game, exclude_uids=_forced_uids)
    game["day_number"] = 1

    # 💍 Para (couple) rejimi: o'yindagi turmush qurgan a'zolarni bir-biriga
    # MAXFIY sherik sifatida bog'laymiz (guruhga hech qachon ochiq aytilmaydi —
    # faqat ular DM'da o'zlari biladi, biri halok bo'lguncha).
    if game.get("couple_mode"):
        game["couple_of"] = {}
        game["revealed_couples"] = set()
        linked = set()
        for uid in list(game["players"].keys()):
            if uid in linked:
                continue
            partner_id = get_partner_id(uid)
            if partner_id and partner_id in game["players"] and partner_id not in linked:
                game["couple_of"][uid] = partner_id
                game["couple_of"][partner_id] = uid
                linked.add(uid)
                linked.add(partner_id)

    group_link = game.get("group_link")
    for uid, p in list(game["players"].items()):
        role = p["role"]
        desc = ROLES_INFO.get(role, "")
        kb = None
        if group_link:
            kb = types.InlineKeyboardMarkup()
            kb.add(types.InlineKeyboardButton("↗️ Guruhga o'tish", url=group_link))
        # 🎯 "Sizning maqsadingiz" — uzun tavsifni qayta o'qib, xulosa
        # chiqarmasdan, darhol BIR QATORDA aniq maqsad ko'rsatiladi.
        role_text = role_intro_text(role)
        safe_send(uid, role_text, kb)

        # 📨 TUZATILDI: avval bu yerda o'yinchiga ketma-ket 4-5 ta ALOHIDA
        # xabar ketardi (sheriklar/jamoa/juftlik/missiya) — endi BITTA yig'ma
        # xabarga birlashtirildi, DM chati ortiqcha to'lib ketmasin.
        info_lines = []

        # 🔴🔵 Jamoaviy (squad) rejimi: kim qaysi jamoada ekani guruhga hech
        # qachon oshkor qilinmaydi (o'yin oxirigacha maxfiy) — shu sababli har
        # bir o'yinchiga O'Z JAMOASINING to'liq ro'yxati shaxsiy xabarda (DM)
        # yuboriladi, aks holda ular o'z sheriklarini bilmay qolar edi.
        if game.get("squad_mode") and game.get("squads"):
            my_squad = game["squads"].get(uid)
            if my_squad:
                squad_mates = [(u2, pp["name"]) for u2, pp in list(game["players"].items())
                               if u2 != uid and game["squads"].get(u2) == my_squad]
                squad_label = "🔴 Qizil" if my_squad == "wolf" else "🔵 Ko'k"
                if squad_mates:
                    info_lines.append(f"{squad_label} jamoangiz: " + ", ".join(mention(u2, n2) for u2, n2 in squad_mates)
                                       + "\n⚠️ Guruhda hech qachon oshkor qilinmaydi!")
                else:
                    info_lines.append(f"{squad_label} jamoasida yolg'izsiz.")

        # 💍 Para rejimida — sherigingiz kimligini FAQAT o'zingiz, shaxsiy xabarda
        # bilasiz. Guruhda bu hech qachon ochiq aytilmaydi (biri halok bo'lmaguncha).
        partner_id = game.get("couple_of", {}).get(uid)
        if partner_id:
            partner_name = game["players"].get(partner_id, {}).get("name", "Sherigingiz")
            info_lines.append(
                f"💍 Maxfiy juftlik! Sherigingiz: <b>{partner_name}</b>. "
                f"⚠️ Guruhda aytmang — biringiz halok bo'lsa, ikkalangiz ham chiqasiz."
            )

        if info_lines:
            safe_send(uid, "\n\n".join(info_lines))

    game["started_ts"] = time.time()   # ⏱ o'yin davomiyligini yakuniy xabarda ko'rsatish uchun
    _role_kb = types.InlineKeyboardMarkup()
    _role_kb.add(types.InlineKeyboardButton("🎭 Sizning rolingiz", callback_data=f"myrole|{chat_id}"))
    bot.send_message(chat_id, f"🌙 <b>O'yin boshlandi!</b> {len(game['players'])} kishiga rol berildi. Roldan DM'da qarang.",
                     reply_markup=_role_kb)
    start_night(chat_id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("myrole|"))
def cb_my_role_popup(call):
    """🎭 "Sizning rolingiz" — guruhda tugmani bosgan o'yinchiga roli POPUP oynada ko'rsatiladi
    (boshqalar ko'rmaydi)."""
    try:
        chat_id = int(call.data.split("|")[1])
    except Exception:
        bot.answer_callback_query(call.id)
        return
    game = GAMES.get(chat_id)
    p = game["players"].get(call.from_user.id) if game else None
    if not p or not p.get("role"):
        bot.answer_callback_query(call.id, "Siz bu o'yinda ishtirok etmayapsiz.", show_alert=True)
        return
    role = p["role"]
    goal = re.sub(r"<[^>]+>", "", role_goal_line(role) or ROLES_INFO.get(role, ""))
    text = f"Siz — {role}!\n{goal}"
    bot.answer_callback_query(call.id, text[:200], show_alert=True)   # Telegram chegarasi: 200 belgi


def _assign_no_repeat(uids, pool):
    """`uids` ro'yxatidagi har bir o'yinchiga `pool` dagi rollarni, iloji boricha
    o'sha o'yinchining OXIRGI o'ynagan roli bilan bir xil bo'lmaydigan qilib
    taqsimlaydi (bir xil rol ketma-ket 2 marta bir kishiga tushmasin degan talab).
    Agar imkoni bo'lmasa (masalan, kichik o'yin, muqobil yo'q) — eng kam
    to'qnashuvli variant qaytariladi."""
    best = None
    for _ in range(40):
        shuffled = pool[:]
        random.shuffle(shuffled)
        conflicts = sum(
            1 for uid, role in zip(uids, shuffled)
            if get_charges(uid).get("last_role") == role
        )
        if conflicts == 0:
            return list(zip(uids, shuffled))
        if best is None or conflicts < best[0]:
            best = (conflicts, list(zip(uids, shuffled)))
    return best[1] if best else list(zip(uids, pool))


def _balance_squad_mafia(game, exclude_uids=None):
    """🔴🔵 XATOLIK/MUVOZANAT TUZATILDI: Qizil va Ko'k o'yinida rollar ilgari
    JAMOADAN MUSTAQIL, butunlay tasodifiy taqsimlanardi — bu degani, sof
    tasodif tufayli BARCHA mafiya (o'ldiruvchi kuch) bitta jamoaga (masalan
    faqat 🔴 Qizilga) tushib qolishi mumkin edi, natijada bu jamoa boshqasini
    tunlarda tez orada butunlay qirib, adolatsiz g'alaba qozonardi. Endi rol
    taqsimotidan KEYIN, lekin DM yuborishdan OLDIN — ikkala jamoadagi mafiya
    (o'ldiruvchi) sonini son jihatdan TENGLASHTIRAMIZ: ortiqcha mafiyaga ega
    jamoadagi bitta mafiya o'yinchisi bilan kam jamoadagi bitta mafiya-bo'lmagan
    o'yinchining ROLI (FAQAT roli — jamoasi EMAS) almashtiriladi. Pullab rol
    chiptasi sotib olgan o'yinchilar (exclude_uids) bu almashinuvga aralashtirilmaydi."""
    exclude_uids = exclude_uids or set()
    wolf = [u for u in list(game["players"]) if game.get("squads", {}).get(u) == "wolf"]
    eagle = [u for u in list(game["players"]) if game.get("squads", {}).get(u) == "eagle"]
    if not wolf or not eagle:
        return

    def is_mafia(u):
        return team_of(game["players"][u]["role"]) == "mafia"

    for _ in range(20):  # 20 marta yetarli — real o'yin hajmida undan ko'p almashinuv kerak bo'lmaydi
        wolf_mafia = [u for u in wolf if is_mafia(u)]
        eagle_mafia = [u for u in eagle if is_mafia(u)]
        diff = len(wolf_mafia) - len(eagle_mafia)
        if abs(diff) < 2:
            break
        heavy, heavy_mafia, light = (wolf, wolf_mafia, eagle) if diff > 0 else (eagle, eagle_mafia, wolf)
        heavy_swappable = [u for u in heavy_mafia if u not in exclude_uids]
        light_swappable = [u for u in light if not is_mafia(u) and u not in exclude_uids]
        if not heavy_swappable or not light_swappable:
            break  # muvozanatlashning iloji yo'q (hammasi chiptali) — shunday qoladi
        a, b = heavy_swappable[0], light_swappable[0]
        pa, pb = game["players"][a], game["players"][b]
        pa["role"], pb["role"] = pb["role"], pa["role"]
        pa["team"], pb["team"] = pb["team"], pa["team"]


def _build_role_pool(n):
    """🎲 n ta o'yinchi uchun 25 rolli to'plamdan rollar ro'yxatini tuzadi.
    Don har doim; Komissar n>=2, Doktor n>=3; mafia soni mafia_count_for(n);
    yakka rollar o'yinchi soniga qarab (SOLO_MIN_PLAYERS); qolgani — Shahar tomoni."""
    pool = []
    if n >= 1:
        pool.append(R_DON)
    if n >= 2:
        pool.append(R_KOM)
    if n >= 3:
        pool.append(R_DOK)

    # 🤵 Mafia tomoni: Don + (Mafia, Advokat, Убийца) — Don o'lsa o'rnini Mafia egallashi uchun
    # birinchi qo'shimcha o'rin doim Mafia.
    mafia_extra = max(0, mafia_count_for(n) - 1) if n >= 4 else 0
    extras = [R_MAF]
    tail = [R_ADV, R_UBI, R_MAF]
    if n >= NEW_ROLE_MIN_PLAYERS[R_DXO]:
        tail.append(R_DXO)
    random.shuffle(tail)
    extras += tail
    for i in range(mafia_extra):
        pool.append(extras[i] if i < len(extras) else R_MAF)

    # 🎭 Yakka rollar soni
    if n < 5:
        solo_n = 0
    elif n < 8:
        solo_n = 1
    elif n < 12:
        solo_n = 2
    elif n < 16:
        solo_n = 3
    else:
        solo_n = max(4, n // 5)
    solo_pool = [r for r in INDEPENDENT_ROLES if SOLO_MIN_PLAYERS.get(r, 99) <= n]
    random.shuffle(solo_pool)
    pool += solo_pool[:min(solo_n, max(0, n - len(pool)))]

    # 🕊 Shahar tomoni: maxsus rollar (Serjant n>=5) + qolgan o'rinlar "Tinch axoli"
    town_special = [R_JAN, R_DAY, R_AFS, R_KOL, R_JUR]
    town_special += [r for r in (R_OML, R_MSH, R_MUX, R_FOT, R_ADM, R_ROB, R_RIK) if n >= NEW_ROLE_MIN_PLAYERS[r]]
    if n >= 5:
        town_special.append(R_SER)
    random.shuffle(town_special)
    free = n - len(pool)
    # maxsus Shahar rollari bo'sh o'rinlarning ~yarmini egallaydi, qolgani Tinch axoli
    take = min(len(town_special), (free + 1) // 2) if free > 0 else 0
    pool += town_special[:take]
    while len(pool) < n:
        pool.append(R_TIN)
    return pool[:n]


def assign_roles(game):
    apply_anonymity(game)   # 🦊 anonim rejim: ismlar "🦊 N" ga almashadi
    player_ids = list(game["players"].keys())
    n = len(player_ids)
    if n == 0:
        return

    forced = dict(game.get("forced_roles", {}))
    # 🎭 Lobbyga qo'shilgandan KEYIN sotib olingan rol chiptasi ham hisobga olinadi
    for _uid in player_ids:
        if _uid not in forced:
            _t = role_ticket_get(_uid)
            if _t:
                forced[_uid] = _t
                _ch = get_charges(_uid)
                _ch.pop("role_ticket", None)
                set_charges(_uid, _ch)
                safe_send(_uid, f"🎭 Chiptangiz ishlatildi: bu o'yinda <b>{_t}</b> siz bo'lasiz!")
    # faqat yangi 25 rolning biri bo'lgan majburiy rollar o'tadi
    forced = {u: r for u, r in forced.items() if r in ROLES_INFO}

    pool = _build_role_pool(n)
    random.shuffle(pool)

    # avval 🎭 huquqi bilan tanlangan rollarni beramiz
    remaining_players = []
    for uid in player_ids:
        if uid in forced and forced[uid]:
            role = forced[uid]
            p = game["players"][uid]
            p["role"], p["team"], p["alive"] = role, team_of(role), True
            if role in pool:
                pool.remove(role)
            elif pool:
                pool.pop()
        else:
            remaining_players.append(uid)

    random.shuffle(remaining_players)
    while len(pool) < len(remaining_players):
        pool.append(R_TIN)

    # 🎲 rol — o'yinchining oldingi o'yindagi roliga imkon qadar mos kelmaydigan qilib taqsimlanadi
    for uid, role in _assign_no_repeat(remaining_players, pool):
        p = game["players"][uid]
        p["role"], p["team"], p["alive"] = role, team_of(role), True

    # keyingi o'yinda solishtirish uchun har bir o'yinchining ENDIGI rolini "last_role" sifatida saqlaymiz
    for uid in player_ids:
        ch = get_charges(uid)
        ch["last_role"] = game["players"][uid]["role"]
        set_charges(uid, ch)

    # 🏆 Geroy (Elandriel/Zephyrion "Boylik siri") — har o'yin boshlanganda avtomatik +1 💎
    game.setdefault("hero_income_claimed", set())
    for uid in player_ids:
        if hero_has_ability(uid, "diamond_trickle"):
            add_balance(uid, dollar=FREE_DIAMOND_DOLLAR_VALUE)
            game["hero_income_claimed"].add(uid)
            safe_send(uid, f"💰 Geroyingiz sizga bu o'yin uchun +{FREE_DIAMOND_DOLLAR_VALUE}$ in'om qildi!")

    game["forced_roles"] = {}


