def alive_role_holders(game, predicate):
    return [uid for uid, p in list(game["players"].items()) if p["alive"] and predicate(p["role"])]


def _bot_dm_button(label="🤖 Botga o'tish"):
    """Guruhdagi xabarlarda botning shaxsiy chatiga o'tish tugmasi."""
    global BOT_USERNAME
    if BOT_USERNAME is None:
        try:
            BOT_USERNAME = bot.get_me().username
        except Exception:
            return None
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(label, url=f"https://t.me/{BOT_USERNAME}"))
    return kb


def _send_night_time_reminder(chat_id, night_no):
    """⏰ Tun tugashiga NIGHT_REMINDER_LEAD_SECONDS soniya qolganda — harakat qilmaganlarga eslatma."""
    game = GAMES.get(chat_id)
    if not game or game.get("phase") != "night" or game.get("night_count") != night_no:
        return
    prompted = game.get("prompted_tonight", set())
    responded = game.get("responded_tonight", set())
    for uid in prompted - responded:
        p = game["players"].get(uid)
        if p and p.get("alive"):
            safe_send(uid, f"⏰ Vaqtingiz tugayapti! Tanlov qilish uchun ~{NIGHT_REMINDER_LEAD_SECONDS} soniya qoldi.")


