AFSUNGAR_WAIT_SECONDS = 30
_SEH_WAIT = {}   # chat_id -> Sehrgar qarori kutilayotgan holat (runtime, JSON'ga yozilmaydi)
_AFS_WAIT = {}   # chat_id -> Afsungar tanlovi kutilayotgan holat


def _name_of(game, uid):
    return game["players"].get(uid, {}).get("name", "?")


def _na_kb(game, chat_id, uid, kind, exclude=(), prefix=""):
    kb = types.InlineKeyboardMarkup()
    for tid, tp in alive_players(game).items():
        if tid in exclude:
            continue
        tag = squad_tag(game, uid, tid)
        kb.add(types.InlineKeyboardButton(f"{tag}{tp['name']}", callback_data=f"na|{chat_id}|{kind}|{prefix}{tid}"))
    kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|{kind}|{prefix}skip"))
    return kb


def _night_exclude(game, uid, kind):
    """Rol o'zi tanlay olmaydigan o'yinchilar."""
    ex = {uid}
    if kind in ("don", "maf"):
        ex |= {u for u, p in alive_players(game).items() if p["role"] in MAFIA_KNOWN_ROLES}
    elif kind == "adv":
        ex = set()   # Advokat o'zini ham himoya qila oladi
    elif kind == "dok":
        ex = set()
        last = game.get("doc_last", {}).get(uid)
        if last is not None:
            ex.add(last)
        if uid in game.get("doc_self_used", set()):
            ex.add(uid)
    elif kind == "dxo":
        ex |= {u for u, p in alive_players(game).items() if p["role"] in MAFIA_KNOWN_ROLES}
    elif kind == "fit":
        ex |= set(game.get("fit_cands", []))
    elif kind == "gaz":
        ex |= set(game.get("gaz_marks", {}).get(uid, []))
    return ex


def start_night(chat_id):
    game = GAMES.get(chat_id)
    if not game:
        return
    # 🧹 Rol berilmagan (start bilan bir vaqtda qo'shilib qolgan) o'yinchilar o'yindan olib tashlanadi
    for _u in [u for u, pp in game["players"].items() if not pp.get("role")]:
        game["players"].pop(_u, None)

    game["night_count"] = game.get("night_count", 0) + 1
    game["hero_armed_defense"] = set()   # 🏆 Geroy himoyasi har tun yangidan faollashtiriladi

    # ============================================================================
    #  🚨 AFK NAZORATI — 2 tun ketma-ket harakat qilmaganlar avtomatik chiqariladi
    # ============================================================================
    prev_prompted = game.get("prompted_tonight", set())
    prev_responded = game.get("responded_tonight", set())
    afk_streak = game.setdefault("afk_streak", {})
    kicked_afk = []
    for uid in prev_prompted:
        p = game["players"].get(uid)
        if not p or not p["alive"]:
            continue
        if uid in prev_responded or uid in game.get("day_voted", set()):
            afk_streak[uid] = 0
        else:
            afk_streak[uid] = afk_streak.get(uid, 0) + 1
            if afk_streak[uid] >= game_afk_limit(game):
                p["alive"] = False
                kicked_afk.append(uid)
                afk_streak[uid] = 0
    game["day_voted"] = set()
    for uid in kicked_afk:
        p = game["players"][uid]
        p["left_game"] = True
        joke = random.choice(AFK_KICK_JOKES).format(who=mention(uid, p["name"]), role=f"<b>{p['role']}</b>")
        bot.send_message(chat_id, joke)
        safe_send(uid, f"😴 Siz {game_afk_limit(game)} tun ketma-ket harakatsiz qolganingiz uchun o'yindan avtomatik chiqarildingiz.")
        add_points(uid, -10, "afk_kick")
        handle_death_side_effects(game, chat_id, uid)
    # 🏁 Har bir tun boshlanishidan OLDIN g'alaba shartini ALBATTA tekshiramiz (faqat AFK
    # chiqarilganda emas) — aks holda biror o'lim yo'li tekshiruvni o'tkazib yuborsa,
    # masalan 2 mafiya + 1 tinch qolganda ham o'yin tunga o'tib ketardi.
    if check_and_end_game(chat_id):
        return

    game["phase"] = "night"
    game["mafia_votes"] = {}
    game["doctor_target"] = None
    game["komissar_action"] = None
    game["komissar_target"] = None
    game["night_announced"] = set()
    game["touched_tonight"] = set()
    game["night_flavor_sent"] = set()
    game["prompted_tonight"] = set()
    game["responded_tonight"] = set()
    game["na2"] = {}                 # uid -> {"role","kind","t","m"}
    game["koldun_protect"] = set()   # ertangi osishdan himoyalanganlar
    game["fit_active"] = None        # Fitnachi: bugungi ovoz berishdagi 2 nomzod
    game["day_silenced"] = set()
    game["advocate_protect"] = None
    game["advocate_actor"] = None

    send_scene_photo(
        chat_id, NIGHT_PHOTO_LOCAL, NIGHT_PHOTO,
        caption=f"🌙 <b>{game['day_number']}-tun.</b> Guruhda yozish taqiqlangan.\n"
                "Harakatingizni botda (shaxsiy chat) tanlang. 🤖",
        reply_markup=_bot_dm_button(),
    )
    send_squad_reminders(game)
    send_night_roster(chat_id, game)

    alive = alive_players(game)
    joker_busy = bool(game.get("joker_pending"))
    for uid, p in alive.items():
        role = p["role"]
        kind = ROLE_TO_NIGHT_KIND.get(role)
        try:
            if role == R_KOM:
                kb = types.InlineKeyboardMarkup()
                kb.add(types.InlineKeyboardButton("🔍 Tekshirish", callback_data=f"na|{chat_id}|kom|check"),
                       types.InlineKeyboardButton("🔫 O'q uzish", callback_data=f"na|{chat_id}|kom|shoot"))
                kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|kom|skip"))
                safe_send(uid, "🕵️ Komissar, bu kecha nima qilasiz?", kb)
                game["prompted_tonight"].add(uid)
            elif role == R_KIM:
                ku = game.setdefault("kim_used", {}).setdefault(uid, {})
                kb = types.InlineKeyboardMarkup()
                row = []
                if not ku.get("heal"):
                    row.append(types.InlineKeyboardButton("💉 Davolash", callback_data=f"na|{chat_id}|kim|heal"))
                if not ku.get("poison"):
                    row.append(types.InlineKeyboardButton("☠️ Zahar", callback_data=f"na|{chat_id}|kim|poison"))
                if not row:
                    continue
                kb.add(*row)
                kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|kim|skip"))
                safe_send(uid, "🧑‍🔬 Kimyogar, bu kecha nima qilasiz?", kb)
                game["prompted_tonight"].add(uid)
            elif role == R_CUP:
                if not game.get("lovers"):
                    kb = _na_kb(game, chat_id, uid, "cup", exclude=set())
                    safe_send(uid, "💘 Cupid, birinchi sevishganni tanlang:\n<i>Ikkalasi ham tanlangach, biri o'lsa — ikkinchisi ham halok bo'ladi.</i>", kb)
                    game["prompted_tonight"].add(uid)
            elif kind == "tin":
                # 🏠 Faqat juft tunlarda; ixtiyoriy — "prompted" ga QO'SHILMAYDI, shuning uchun
                # tanlamagan Tinch aholi AFK hisoblanmaydi va hech narsa kutilmaydi.
                if game["night_count"] % 2 == 0:
                    _, prompt = NIGHT_PROMPTS[kind]
                    kb = _na_kb(game, chat_id, uid, kind, exclude=_night_exclude(game, uid, kind))
                    safe_send(uid, prompt + "\n<i>Ixtiyoriy: o'sha odam uyda bo'lgan yoki tashqarida yurganini bilasiz.</i>", kb)
            elif kind:
                if kind == "jok" and uid in game.get("joker_won", set()):
                    continue   # maqsadiga erishgan Joker endi karta yubormaydi
                if kind == "jok" and joker_busy:
                    safe_send(uid, "🤡 Oldingi kartalaringiz hali tanlanmagan. Natijani kuting.")
                    continue
                if kind == "ani" and False:
                    pass
                _, prompt = NIGHT_PROMPTS[kind]
                kb = _na_kb(game, chat_id, uid, kind, exclude=_night_exclude(game, uid, kind))
                if kind == "gaz":
                    prompt += f"\nBelgilanganlar: {len(game.get('gaz_marks', {}).get(uid, []))}/3"
                if kind == "fit":
                    prompt += f"\nNomzodlar: {len(game.get('fit_cands', []))}/2"
                safe_send(uid, prompt, kb)
                game["prompted_tonight"].add(uid)
        except Exception:
            _logger.warning("tungi so'rov yuborilmadi (uid=%s, role=%s)", uid, role, exc_info=True)

    # 🔫 Do'kon "Miltiq" — zaxirasi bor o'yinchiga tunda nishon tanlash (1 o'q, ixtiyoriy)
    game["rifle_actions"] = {}
    for uid, p in alive.items():
        try:
            if int(get_charges(uid).get("rifle", 0) or 0) <= 0:
                continue
            kb = types.InlineKeyboardMarkup()
            for target_id, tp in alive.items():
                if target_id == uid:
                    continue
                kb.add(types.InlineKeyboardButton(tp["name"], callback_data=f"na|{chat_id}|rifle|{target_id}"))
            kb.add(types.InlineKeyboardButton("🚫 Otmayman", callback_data=f"na|{chat_id}|rifle|skip"))
            safe_send(uid, "🔫 <b>Miltiq</b> sizda. Bu tun 1 kishiga o'q uzasizmi? (O'q faqat otsangiz sarflanadi.)", kb)
        except Exception:
            _logger.debug("rifle prompt", exc_info=True)

    # 🏆 Geroy — himoyaga ega o'yinchilarga har tun eslatma + tugma
    for uid, p in alive.items():
        if hero_has_ability(uid, "survive") or hero_has_ability(uid, "revive_once"):
            if hero_auto_enabled(uid):
                game.setdefault("hero_armed_defense", set()).add(uid)
                continue
            kb = types.InlineKeyboardMarkup()
            kb.add(types.InlineKeyboardButton("🛡 Geroy himoyasini faollashtirish", callback_data=f"heroarm|defense|{chat_id}"))
            safe_send(uid, "🏆 Geroyingiz bu tun himoya taklif qilmoqda. Faollashtirmasangiz, u sizni himoya QILMAYDI:", kb)

    _night_s = game_times(game)["night"]
    t = threading.Timer(_night_s, lambda: resolve_night(chat_id))
    t.daemon = True
    t.start()
    game["timers"].append(t)

    if _night_s > NIGHT_REMINDER_LEAD_SECONDS:
        night_no = game["night_count"]
        rt = threading.Timer(_night_s - NIGHT_REMINDER_LEAD_SECONDS,
                              lambda: _send_night_time_reminder(chat_id, night_no))
        rt.daemon = True
        rt.start()
        game["timers"].append(rt)

    game["day_sub_phase"] = None
    game["phase_deadline"] = time.time() + _night_s
    save_games_state()


def _na_edit(call, text):
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id)
    except Exception:
        pass


# 🌙 Tun atmosferasi — guruhga "kim harakat qilgani" (rol nomi ko'rinadi, nishon EMAS) sezdiriladi.
