def _night_flavor(game, chat_id, kind, mode=None):
    """Guruhga tun atmosferasi xabarini yuboradi (sozlamadan o'chirish mumkin)."""
    try:
        if gsv(game, "night_flavor") == "0":
            return
        text = NIGHT_FLAVOR_TEXT.get((kind, mode))
        if not text:
            return
        key = f"{game.get('night_count', 0)}:{kind}:{'kom' if kind == 'kom' else ''}"
        sent = game.setdefault("night_flavor_sent", set())
        if key in sent:
            return
        sent.add(key)
        bot.send_message(chat_id, text)
    except Exception:
        _logger.debug("tun atmosferasi xabari yuborilmadi", exc_info=True)


@bot.callback_query_handler(func=lambda c: c.data.startswith("na|"))
@fast_callback
def cb_night_action(call):
    maybe_capture_owner(call.from_user)
    parts = call.data.split("|")
    chat_id = int(parts[1])
    kind, value = parts[2], parts[3]
    game = GAMES.get(chat_id)
    uid = call.from_user.id

    if not game or game["phase"] != "night" or uid not in game["players"] or not game["players"][uid]["alive"]:
        bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
        return
    role = game["players"][uid]["role"]

    # 🚨 AFK nazorati + faollik balli
    game.setdefault("responded_tonight", set()).add(uid)
    game.setdefault("activity_score", {})
    game["activity_score"][uid] = game["activity_score"].get(uid, 0) + 1
    acts = game.setdefault("na2", {})

    # ---- 🔫 Do'kon miltig'i ----
    if kind == "rifle":
        game.setdefault("rifle_actions", {})[uid] = value if value == "skip" else int(value)
        _na_edit(call, f"Siz - <b>{_name_of(game, int(value))}</b> ni nishonga oldingiz." if value != "skip" else "🚫 Bu tun otmaysiz.")
        bot.answer_callback_query(call.id, "Qabul qilindi!")
        return

    # ---- 🕵️ Komissar: avval harakat turi, keyin nishon ----
    if kind == "kom":
        if role != R_KOM:
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return
        if value == "skip":
            acts.pop(uid, None)
            _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
            bot.answer_callback_query(call.id)
            return
        kb = _na_kb(game, chat_id, uid, "komt", exclude={uid}, prefix=f"{value}:")
        try:
            bot.edit_message_text("🔍 Kimni tekshirasiz?" if value == "check" else "🔫 Kimni otasiz?",
                                  call.message.chat.id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if kind == "komt":
        if role != R_KOM:
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return
        mode, _, tv = value.partition(":")
        if tv == "skip" or mode not in ("check", "shoot"):
            acts.pop(uid, None)
            _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
        else:
            tid = int(tv)
            if tid not in game["players"] or not game["players"][tid]["alive"] or tid == uid:
                bot.answer_callback_query(call.id, "Nishon yaroqsiz.")
                return
            acts[uid] = {"role": role, "kind": "kom", "t": tid, "m": mode}
            _na_edit(call, f"Siz - <b>{_name_of(game, tid)}</b> ni tanladingiz.")
            _night_flavor(game, chat_id, "kom", mode)
        bot.answer_callback_query(call.id, "Qabul qilindi!")
        return

    # ---- 🧑‍🔬 Kimyogar: avval harakat turi, keyin nishon ----
    if kind == "kim":
        if role != R_KIM:
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return
        if value == "skip":
            acts.pop(uid, None)
            _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
            bot.answer_callback_query(call.id)
            return
        if game.get("kim_used", {}).get(uid, {}).get(value):
            bot.answer_callback_query(call.id, "Bu imkoniyat allaqachon ishlatilgan.", show_alert=True)
            return
        kb = _na_kb(game, chat_id, uid, "kimt", exclude=set() if value == "heal" else {uid}, prefix=f"{value}:")
        try:
            bot.edit_message_text("💉 Kimni davolaysiz?" if value == "heal" else "☠️ Kimga zahar berasiz?",
                                  call.message.chat.id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if kind == "kimt":
        if role != R_KIM:
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return
        mode, _, tv = value.partition(":")
        if tv == "skip" or mode not in ("heal", "poison"):
            acts.pop(uid, None)
            _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
        else:
            tid = int(tv)
            if tid not in game["players"] or not game["players"][tid]["alive"] or game.get("kim_used", {}).get(uid, {}).get(mode):
                bot.answer_callback_query(call.id, "Nishon yaroqsiz.")
                return
            acts[uid] = {"role": role, "kind": "kim", "t": tid, "m": mode}
            _na_edit(call, f"Siz - <b>{_name_of(game, tid)}</b> ni tanladingiz.")
            _night_flavor(game, chat_id, "kim", mode)
        bot.answer_callback_query(call.id, "Qabul qilindi!")
        return

    # ---- 💘 Cupid: ikki bosqichli tanlov ----
    if kind in ("cup", "cupt"):
        if role != R_CUP or game.get("lovers"):
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return
        if kind == "cup":
            if value == "skip":
                acts.pop(uid, None)
                _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
                bot.answer_callback_query(call.id)
                return
            first = int(value)
            if first not in game["players"] or not game["players"][first]["alive"]:
                bot.answer_callback_query(call.id, "Nishon yaroqsiz.")
                return
            kb = _na_kb(game, chat_id, uid, "cupt", exclude={first}, prefix=f"{first}:")
            try:
                bot.edit_message_text("💘 Ikkinchi sevishganni tanlang:", call.message.chat.id, call.message.message_id, reply_markup=kb)
            except Exception:
                pass
            bot.answer_callback_query(call.id)
            return
        first_s, _, sec = value.partition(":")
        if sec == "skip":
            acts.pop(uid, None)
            _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
        else:
            f1, f2 = int(first_s), int(sec)
            if f1 == f2 or any(x not in game["players"] or not game["players"][x]["alive"] for x in (f1, f2)):
                bot.answer_callback_query(call.id, "Nishon yaroqsiz.")
                return
            acts[uid] = {"role": role, "kind": "cup", "t": f2, "m": f1}
            _na_edit(call, f"Siz - <b>{_name_of(game, f1)}</b> va <b>{_name_of(game, f2)}</b> ni tanladingiz.")
            _night_flavor(game, chat_id, "cup")
        bot.answer_callback_query(call.id, "Qabul qilindi!")
        return

    # ---- Oddiy bitta nishonli rollar ----
    spec = NIGHT_PROMPTS.get(kind)
    if not spec or spec[0] != role:
        bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
        return
    if kind == "tin" and game.get("night_count", 0) % 2 != 0:
        bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
        return
    if value == "skip":
        acts.pop(uid, None)
        _na_edit(call, "🚫 Siz bu tun harakat qilmaslikni tanladingiz.")
        bot.answer_callback_query(call.id)
        return
    tid = int(value)
    if tid not in game["players"] or not game["players"][tid]["alive"] or tid in _night_exclude(game, uid, kind):
        bot.answer_callback_query(call.id, "Bu nishonni tanlab bo'lmaydi.", show_alert=True)
        return
    acts[uid] = {"role": role, "kind": kind, "t": tid, "m": None}
    tname = _name_of(game, tid)
    _na_edit(call, f"Siz - <b>{tname}</b> ni tanladingiz.")
    bot.answer_callback_query(call.id, "Qabul qilindi!")
    _night_flavor(game, chat_id, kind)

    # 🤵 Don/Mafia kelishuvi: tanlov mafiachilarga darhol ko'rinadi
    try:
        if kind == "don":
            for tm in alive_role_holders(game, lambda r: r in MAFIA_KNOWN_ROLES):
                if tm != uid:
                    safe_send(tm, f"🤵 Don {mention(tid, tname)}ni tanladi.")
        elif kind == "maf":
            for tm in alive_role_holders(game, lambda r: r in MAFIA_KNOWN_ROLES):
                if tm != uid:
                    safe_send(tm, f"🤵‍♂️ {mention(uid, _name_of(game, uid))} {mention(tid, tname)}ni tavsiya qildi.")
    except Exception:
        _logger.debug("mafia tavsiya xabari", exc_info=True)


def _fake_check_role(game, target_id):
    """Eski moslik funksiyasi — yangi rollarda soxta tekshiruv natijasi Aferist/Advokat/Hujjat orqali hal qilinadi."""
    return None


def _item_guard(game, uid, charge_key, title, attacker_uids=None, silent=False):
    """🛡 Do'kon himoya buyumi: zaxirada bo'lsa va bu o'yindagi limit (3 ta) oshmagan bo'lsa —
    BITTA zaryadni sarflaydi, egasiga xabar beradi va True qaytaradi (hujum o'tmaydi)."""
    try:
        if uid not in game["players"]:
            return False
        used = game.setdefault("item_def_used", {})
        if used.get(uid, 0) >= ITEM_DEF_MAX_PER_GAME:
            return False
        if int(get_charges(uid).get(charge_key, 0) or 0) <= 0:
            return False
        if not is_item_active(uid, charge_key):
            return False   # 🔴 OFF — egasi bu buyumni o'chirib qo'ygan
        if not use_charge(uid, charge_key):
            return False
        used[uid] = used.get(uid, 0) + 1
        if not silent:
            safe_send(uid, f"🛡 <b>{title}</b> ishladi — sizni tahdiddan qutqardi.")
            for a_uid in (attacker_uids or []):
                safe_send(a_uid, "🛡 <i>Nishoningiz himoyalangan edi — hujum o'tmadi.</i>")
        return True
    except Exception:
        _logger.warning("_item_guard xatosi (uid=%s, key=%s)", uid, charge_key, exc_info=True)
        return False


def apply_kill(game, uid, killed_set, bypass_protection=False, attacker_uids=None, kind=None):
    """Bitta o'yinchini o'ldirish urinishi — buyum himoyalari, geroy, qalqon, tirilish hisobga olinadi.
    Doktor/Kimyogar davolashi resolve_night ichida (game['night_protected']) tekshiriladi."""
    if uid is None or uid == "skip" or uid not in game["players"]:
        return False
    p = game["players"][uid]
    if not p["alive"] or uid in killed_set:
        return False
    if not bypass_protection:
        if uid in game.get("night_protected", set()):
            return False
        # 🛡 Do'kon himoyalari
        if kind == "bite" and _item_guard(game, uid, "verbena_def", "Verbena", attacker_uids, silent=True):
            safe_send(uid, "🌿 Vampir sizni tishlamoqchi bo'ldi, Verbena himoya qildi.")
            for a_uid in (attacker_uids or []):
                safe_send(a_uid, "🧛 Nishon tishlashdan omon qoldi.")
            return False
        if kind in ("killer",) and _item_guard(game, uid, "killer_def", "Qotildan himoya", attacker_uids):
            return False
        if kind in ("mafia", "shot", "killer", "bite", "poison", "magic", "mine") \
                and _item_guard(game, uid, "basic_def", "Himoya", attacker_uids):
            return False
        # 🏆 Geroy — FAQAT o'zi shu tunga faollashtirgan bo'lsa (yoki Avto-rejimda) ishlaydi
        if uid in game.get("hero_armed_defense", set()):
            if hero_has_ability(uid, "revive_once") and uid not in game.setdefault("hero_revive_used", set()):
                game["hero_revive_used"].add(uid)
                _hero_ab = next((a for a in hero_unlocked_abilities(uid) if a["key"] == "revive_once"), None)
                _hero = get_hero(uid)
                announce_hero_ability_use(game["chat_id"], _hero["name"], _hero_ab["name"] if _hero_ab else "⚰️ O'lmas ruh", uid=uid, hero_key=_hero["key"])
                safe_send(uid, "🔥 Geroyingizning bir martalik qobiliyati ishga tushdi — bu safar o'limdan qutuldingiz! (Endi sarflandi.)")
                for a_uid in (attacker_uids or []):
                    safe_send(a_uid, "🏆 <i>Nishoningiz kimningdir geroy qobiliyati tufayli o'limdan qutulib qoldi...</i>")
                return False
            h_chance = hero_survive_chance(uid)
            if h_chance > 0 and random.random() < h_chance:
                _hero_ab = next((a for a in hero_unlocked_abilities(uid) if a["key"] == "survive"), None)
                _hero = get_hero(uid)
                announce_hero_ability_use(game["chat_id"], _hero["name"], _hero_ab["name"] if _hero_ab else "🛡 Tungi chidamlilik", uid=uid, hero_key=_hero["key"])
                safe_send(uid, "🏆 Geroyingiz faollashtirilgan edi — bu kecha sizga hujum qilishdi, lekin geroyingiz sizni qutqardi!")
                for a_uid in (attacker_uids or []):
                    safe_send(a_uid, "🏆 <i>Nishoningiz kimningdir geroy qobiliyati tufayli hujumdan omon qoldi...</i>")
                return False
        # 🛡 Tungi himoya (do'kon qalqoni)
        _nsu = game.setdefault("night_shield_used", {})
        if _nsu.get(uid, 0) < NIGHT_SHIELD_MAX_PER_GAME and consume_shield(uid):
            _nsu[uid] = _nsu.get(uid, 0) + 1
            left_uses = NIGHT_SHIELD_MAX_PER_GAME - _nsu[uid]
            safe_send(uid, f"🛡 Bu kecha sizga hujum qilishdi, lekin buyumingiz sizni himoya qildi! (Bu o'yinda yana {left_uses} marta ishlatish mumkin.)")
            return False
        if (is_item_active(uid, "revive") and uid not in game.setdefault("revive_used", set())
                and use_charge(uid, "revive")):
            game["revive_used"].add(uid)
            safe_send(uid, "⚡️ Bu kecha sizga hujum qilishdi, lekin Tezkor jonlanish tumoringiz sizni qutqardi!")
            return False
    # 🏆 Geroy "Qasos nafasi" — o'lim muqarrar bo'lganda, o'yinda 1 marta qotilning aniq rolini biladi
    if (hero_has_ability(uid, "death_reveal_once") and attacker_uids
            and uid not in game.setdefault("hero_death_reveal_used", set())):
        game["hero_death_reveal_used"].add(uid)
        _hero = get_hero(uid)
        _killer_role = game["players"].get(attacker_uids[0], {}).get("role", "Noma'lum")
        safe_send(uid, f"🩸 So'nggi nafasingizda geroyingiz sizga pichirladi — sizni halok qilgan kishining roli: <b>{_killer_role}</b>!")
        announce_hero_ability_use(game["chat_id"], _hero["name"], "🩸 Qasos nafasi", uid=uid, hero_key=_hero["key"])
    killed_set.add(uid)
    try:
        _att = (attacker_uids or [None])[0]
        _att_role = game["players"].get(_att, {}).get("role") if _att else None
        game.setdefault("death_info", {})[uid] = {"how": "kill", "side": team_of(_att_role) if _att_role else None,
                                                            "role": _att_role, "kind": kind}
    except Exception:
        pass
    return True


