def _invoke_as_command(call, handler_fn, command_text):
    """🔘 Menyu tugmasidan turib, xuddi foydalanuvchi shu buyruqni yozgandek
    mavjud funksiyani ishga tushiradi (kodni ikki marta yozmaslik uchun)."""
    fake_msg = call.message
    fake_msg.from_user = call.from_user
    fake_msg.text = command_text
    try:
        handler_fn(fake_msg)
    except Exception as e:
        _logger.warning("_invoke_as_command(%s) xatolik: %s", command_text, e)
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass


KLAN_MENU_ACTIONS = {
    "klanim": "🏛 Mening klanim",
    "klanlar": "📋 Klanlar reytingi",
    "klanga_qoshil": "➕ Klanga qo'shilish",
    "klan_tark": "🚪 Klandan chiqish",
    "klan_chetlash": "👢 A'zoni chetlashtirish",
    "klan_orinbosar": "🥈 O'rinbosar tayinlash",
    "klan_azo_daraja": "📈 A'zo darajasi",
    "klan_lvl": "🔼 Klan darajasi",
    "klan_nomi": "✏️ Nomini o'zgartirish",
    "klan_maqom": "🎖 Klan maqomi",
    "klan_hazna": "💰 Xazina",
    "klan_taqsimla": "💸 Xazinani taqsimlash",
    "klanjang": "⚔️ Klan jangi",
    "klan_mukofot": "🎁 Mukofot",
}
_KLAN_ACTION_FUNCS = {}  # fayl oxirida (funksiyalar e'lon qilingach) to'ldiriladi


def _klan_menu_kb():
    kb = types.InlineKeyboardMarkup(row_width=2)
    buttons = [types.InlineKeyboardButton(label, callback_data=f"klanmenu|{key}") for key, label in KLAN_MENU_ACTIONS.items()]
    for i in range(0, len(buttons), 2):
        kb.add(*buttons[i:i + 2])
    return kb


def _open_klan_menu(chat_id, uid):
    bot.send_message(chat_id, "🏛 <b>Klan boshqaruvi</b>\n\nKerakli amalni tanlang:", reply_markup=_klan_menu_kb())


@bot.callback_query_handler(func=lambda c: c.data.startswith("klanmenu|"))
def cb_klan_menu(call):
    maybe_capture_owner(call.from_user)
    _, key = call.data.split("|", 1)
    if key not in KLAN_MENU_ACTIONS:
        bot.answer_callback_query(call.id, "Noma'lum amal.")
        return
    fn = _KLAN_ACTION_FUNCS.get(key)
    if not fn:
        bot.answer_callback_query(call.id, "⚠️ Funksiya hali tayyor emas.")
        return
    _invoke_as_command(call, fn, "/" + key)


@bot.message_handler(commands=["klan"])
def cmd_klan(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        # 📋 /klan argumentsiz — endi to'liq harakatlar menyusini ko'rsatadi
        # (avvalgi 14 ta alohida klan_* buyrug'i o'rniga)
        _open_klan_menu(message.chat.id, uid)
        return
    if not oc_feature_on("clan_create"):   # 👑 Owner Center
        bot.send_message(message.chat.id, "⛔ Yangi klan ochish hozircha o'chirilgan.")
        return
    if get_charges(uid).get("klan_license", 0) <= 0:
        bot.send_message(message.chat.id, "❌ Klan ochish uchun avval 🏛 Klan litsenziyasini (Hunter Coin do'koni) sotib oling.")
        return
    if get_clan(uid):
        bot.send_message(message.chat.id, "❌ Sizda allaqachon klan bor.")
        return
    if find_member_clan(uid):
        bot.send_message(message.chat.id, "❌ Siz boshqa klanning a'zosisiz — avval /klan_tark deb chiqing.")
        return
    name = esc(parts[1].strip()[:32])
    use_charge(uid, "klan_license")
    with db_lock:
        cur.execute(
            "INSERT OR REPLACE INTO clans (owner_id, name, level, deputy_id, leader_level, treasury_dollar, "
            "treasury_diamond, levelup_tokens, wins, losses, win_streak, war_declines_streak, last_war_at, deputy_levelups_used) "
            "VALUES (?,?,1,NULL,3,0,0,10,0,0,0,0,?,0)",
            (uid, name, time.time()),
        )
        conn.commit()
    bot.send_message(
        message.chat.id,
        f"🏛 Klan yaratildi: <b>{name}</b>!\n\n"
        f"👑 Siz lider — <b>3 lvl</b>\n"
        f"🎁 <b>10 ta lvl-up</b> berildi — /klan_azo_daraja orqali taqsimlang.",
    )


