@bot.message_handler(commands=["klan_taqsimla"])
def cmd_klan_taqsimla(message):
    """Lider klan xazinasidagi dollarni a'zolarga (yoki o'ziga) taqsimlaydi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if message.chat.type not in ("group", "supergroup") or not message.reply_to_message:
        bot.send_message(message.chat.id, "❌ Pul bermoqchi bo'lgan a'zoning xabariga reply qilib, miqdorni yozing.")
        return
    uid = message.from_user.id
    clan = get_clan(uid)
    if not clan:
        bot.send_message(message.chat.id, "❌ Bu buyruq faqat klan lideri uchun.")
        return
    parts = message.text.split()
    if len(parts) != 2 or not parts[1].isdigit():
        bot.send_message(message.chat.id, "Foydalanish: <code>/klan_taqsimla &lt;dollar&gt;</code> (a'zoning xabariga reply qiling)")
        return
    amount = int(parts[1])
    if amount <= 0:
        bot.send_message(message.chat.id, "❌ Miqdor musbat bo'lishi kerak.")
        return
    target = message.reply_to_message.from_user
    # 🔒 ATOMIK: xazinani tekshirish + yechish bitta UPDATE'da (parallel buyruqlar xazinadan ortiq pul ola olmaydi)
    with db_lock:
        cur.execute("UPDATE clans SET treasury_dollar = treasury_dollar - ? WHERE owner_id=? AND treasury_dollar >= ?",
                    (amount, uid, amount))
        taken = cur.rowcount > 0
        conn.commit()
    if not taken:
        bot.send_message(message.chat.id, f"❌ Xazinada yetarli mablag' yo'q (bor: ${get_clan(uid)['treasury_dollar']}).")
        return
    add_balance(target.id, dollar=amount, ledger=False)
    bot.send_message(message.chat.id, f"💰 {esc(target.first_name)}ga klan xazinasidan ${amount} berildi.")


