def _tag_name_of(uid):
    try:
        nm = (user_dict(uid).get("name") or "").strip()
    except Exception:
        nm = ""
    return nm or "O'yinchi"


def _tag_link(uid):
    return f'<a href="tg://user?id={uid}">{esc(_tag_name_of(uid))}</a>'


def _tag_random_text(uid):
    t = random.choice(_TAG_JOKES)
    role = re.sub(r"\s*[^\w\s'’]+\s*$", "", random.choice(list(ROLES_INFO)))   # emojisiz rol nomi
    return f"{_tag_link(uid)}, {t.format(role=role)}"


def _tag_group_members(chat_id):
    with db_lock:
        cur.execute("SELECT user_id, last_seen FROM group_members WHERE chat_id=?", (chat_id,))
        rows = cur.fetchall()
    return [(int(u), int(ls or 0)) for u, ls in rows]


def _tag_pick(chat_id, mode, limit, skip_uid=None):
    """mode: 'm' (faol o'yinchilar), 'o' (onlayn), 'r' (tasodifiy). Ro'yxat [uid, ...] qaytaradi."""
    now = time.time()
    members = [(u, ls) for u, ls in _tag_group_members(chat_id) if u != skip_uid]
    ids = []
    if mode == "o":
        for u, ls in members:
            last = max(_LAST_MSG_AT.get((chat_id, u), 0), ls)
            if now - last <= TAG_ONLINE_WINDOW:
                ids.append(u)
    elif mode == "m":
        for u, _ls in members:
            try:
                last_game = float((get_charges(u).get("ret") or {}).get("last_game", 0) or 0)
            except Exception:
                last_game = 0
            if last_game and now - last_game <= TAG_ACTIVE_DAYS * 86400:
                ids.append(u)
    else:
        ids = [u for u, _ls in members]
    random.shuffle(ids)
    return ids[:limit]


def _tag_worker(chat_id, ids, mode, stop):
    sent = 0
    try:
        for uid in ids:
            if stop.is_set():
                break
            text = _tag_random_text(uid) if mode == "r" else _tag_link(uid)
            for attempt in range(3):
                try:
                    bot.send_message(chat_id, text, disable_notification=False)
                    sent += 1
                    break
                except Exception as e:
                    msg = str(e)
                    m_ = re.search(r"retry after (\d+)", msg)
                    if m_:
                        if stop.wait(min(30, int(m_.group(1)) + 1)):
                            break
                        continue
                    if "chat not found" in msg or "kicked" in msg or "not enough rights" in msg:
                        stop.set()
                    break
            if stop.wait(TAG_DELAY):
                break
        try:
            bot.send_message(chat_id, f"✅ Chaqiruv yakunlandi: {sent} ta ishtirokchi tag qilindi." if not stop.is_set()
                             else f"⏹ Chaqiruv to'xtatildi: {sent} ta ishtirokchi tag qilindi.")
        except Exception:
            pass
    finally:
        with _TAG_RUNS_LOCK:
            _TAG_RUNS.pop(chat_id, None)


def _tag_start(message, mode):
    chat_id = message.chat.id
    uid = message.from_user.id
    if message.chat.type not in ("group", "supergroup"):
        bot.send_message(chat_id, "📣 Bu buyruq faqat guruhda ishlaydi.")
        return
    if not is_authorized(message):
        bot.send_message(chat_id, "⛔ Bu buyruq faqat guruh adminlari uchun.")
        return
    g = GAMES.get(chat_id)
    if g and g.get("phase") != "waiting":
        bot.send_message(chat_id, "🎮 O'yin ketayotgan paytda chaqiruv mumkin emas. O'yin tugagach urinib ko'ring.")
        return
    parts = (message.text or "").split()
    cap = TAG_MAX_COUNT_OWNER if is_owner(uid) else TAG_MAX_COUNT
    default = 10 if mode == "r" else cap
    count = default
    if len(parts) > 1:
        if not parts[1].isdigit() or int(parts[1]) < 1:
            bot.send_message(chat_id, f"ℹ️ Foydalanish: <code>/{parts[0].lstrip('/').split('@')[0]} 20</code> — nechta ishtirokchi chaqirilishi (1–{cap}).")
            return
        count = min(int(parts[1]), cap)
    with _TAG_RUNS_LOCK:
        if chat_id in _TAG_RUNS:
            bot.send_message(chat_id, "⏳ Chaqiruv allaqachon ketyapti. To'xtatish: /stoptag")
            return
        stop = threading.Event()
        _TAG_RUNS[chat_id] = {"stop": stop, "by": uid}
    ids = _tag_pick(chat_id, mode, count)
    if not ids:
        with _TAG_RUNS_LOCK:
            _TAG_RUNS.pop(chat_id, None)
        hint = {"o": "Oxirgi 15 daqiqada guruhda yozgan ishtirokchi topilmadi.",
                "m": f"Oxirgi {TAG_ACTIVE_DAYS} kunda o'yin o'ynagan ishtirokchi topilmadi.",
                "r": "Bot hali bu guruhda hech kimni ko'rmagan."}[mode]
        bot.send_message(chat_id, f"🤷 {hint}")
        return
    label = {"m": "faol o'yinchilar", "o": "onlayn ishtirokchilar", "r": "tasodifiy ishtirokchilar"}[mode]
    secs = int(len(ids) * TAG_DELAY)
    bot.send_message(chat_id, f"📣 Chaqiruv boshlandi: <b>{len(ids)}</b> ta {label}. Taxminan {secs} soniya. To'xtatish: /stoptag")
    threading.Thread(target=_tag_worker, args=(chat_id, ids, mode, stop), daemon=True).start()


@bot.message_handler(commands=["Mutag", "mutag"])
def cmd_mutag(message):
    _tag_start(message, "m")


@bot.message_handler(commands=["Outag", "outag"])
def cmd_outag(message):
    _tag_start(message, "o")


@bot.message_handler(commands=["Rutag", "rutag"])
def cmd_rutag(message):
    _tag_start(message, "r")


@bot.message_handler(commands=["stoptag", "Stoptag"])
def cmd_stoptag(message):
    chat_id = message.chat.id
    if not is_authorized(message):
        return
    with _TAG_RUNS_LOCK:
        run = _TAG_RUNS.get(chat_id)
    if not run:
        bot.send_message(chat_id, "ℹ️ Hozir ketayotgan chaqiruv yo'q.")
        return
    run["stop"].set()


@bot.message_handler(commands=["hisob"])
def cmd_hisob(message):
    """Qizil vs Ko'k umumiy hisobini ko'rsatadi."""
    pair = get_pair(message.chat.id)
    if not pair:
        bot.send_message(message.chat.id, "Bu guruh hozircha boshqa guruh bilan juftlashtirilmagan.\n(Bot egasi /jufti buyrug'i orqali bog'lashi mumkin.)")
        return
    ca, cb, label_a, label_b, score_a, score_b = pair
    bot.send_message(
        message.chat.id,
        f"📊 <b>Umumiy hisob</b>\n\n"
        f"{label_a}: <b>{score_a}</b> g'alaba\n"
        f"{label_b}: <b>{score_b}</b> g'alaba",
    )


@bot.message_handler(content_types=["migrate_to_chat_id"])
def handle_group_migration(message):
    """Telegram guruhni supergroup'ga aylantirganda chat_id butunlay o'zgaradi —
    shu sababli eski ID'ga bog'langan qora bozor/guruh ma'lumotlari yangi ID'ga
    avtomatik ko'chiriladi, aks holda qora bozor "guruhga qo'shiling" deb xato
    xabar bera boshlaydi, garchi foydalanuvchi allaqachon o'sha guruhda bo'lsa ham."""
    global BLACK_MARKET_CHAT_ID
    old_id = message.chat.id
    new_id = message.migrate_to_chat_id
    if BLACK_MARKET_CHAT_ID == old_id:
        BLACK_MARKET_CHAT_ID = new_id
        set_setting("black_market_chat_id", BLACK_MARKET_CHAT_ID)
    with db_lock:
        cur.execute("SELECT title FROM known_groups WHERE chat_id=?", (old_id,))
        row = cur.fetchone()
    remove_known_group(old_id)
    add_known_group(new_id, row[0] if row else None)
    with db_lock:
        cur.execute("UPDATE group_pairs SET chat_id_a=? WHERE chat_id_a=?", (new_id, old_id))
        cur.execute("UPDATE group_pairs SET chat_id_b=? WHERE chat_id_b=?", (new_id, old_id))
        conn.commit()
    if old_id in GAMES:
        game = GAMES.pop(old_id)
        game["chat_id"] = new_id
        GAMES[new_id] = game
        save_games_state()
    _logger.info("Guruh supergroup'ga ko'chirildi: %s -> %s", old_id, new_id)


@bot.message_handler(commands=["sell"])
def cmd_sell(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not oc_feature_on("black_market"):   # 👑 Owner Center
        bot.send_message(message.chat.id, "⛔ Qora bozor hozircha vaqtincha yopilgan.")
        return
    if not _in_black_market_group(message.chat.id):
        bot.send_message(
            message.chat.id,
            "⛔ Qora bozor faqat maxsus savdo guruhida ishlaydi. Guruhga qo'shiling: "
            "https://t.me/+v9bYoMk-0hAyZTcy",
        )
        return
    uid = message.from_user.id
    if is_banned(uid):
        return
    user_dict(uid, message.from_user.first_name)

    u = user_dict(uid)
    try:
        inv = json.loads(u["inventory"] or "[]")
    except Exception:
        inv = []

    parts = message.text.split()
    if len(parts) < 4:
        # Format yetarli emas — inventarni va to'g'ri formatni ko'rsatamiz
        if not inv:
            bot.send_message(message.chat.id, "🎒 Sizning inventaringiz bo'sh — sotadigan narsangiz yo'q.")
            return
        lines = ["🎒 <b>Sizning inventaringizdagi buyumlar:</b>\n"]
        for idx, item in enumerate(inv, 1):
            lines.append(f"{idx}. {item}")
        lines.append(
            "\n<i>Sotish uchun: </i><code>/sell &lt;raqam&gt; &lt;dollar|diamond|coin&gt; &lt;narx&gt;</code>"
            "\n<i>Masalan: </i><code>/sell 1 diamond 25</code>"
        )
        bot.send_message(message.chat.id, "\n".join(lines))
        return

    currency = parts[2].lower()
    if currency not in CURRENCY_ICON:
        bot.send_message(message.chat.id, "⚠️ Valyuta faqat <code>dollar</code>, <code>diamond</code> yoki <code>coin</code> bo'lishi kerak!")
        return

    try:
        item_index = int(parts[1]) - 1
        price = int(parts[3])
    except ValueError:
        bot.send_message(message.chat.id, "⚠️ Raqam va narx faqat butun sonlardan iborat bo'lishi kerak!")
        return

    if price <= 0:
        bot.send_message(message.chat.id, "⚠️ Narx musbat son bo'lishi kerak!")
        return
    if item_index < 0 or item_index >= len(inv):
        bot.send_message(message.chat.id, "⚠️ Bunday raqamli buyum inventaringizda yo'q!")
        return

    item_to_sell = remove_inventory_item_by_index(uid, item_index)
    if item_to_sell is None:
        bot.send_message(message.chat.id, "⚠️ Bunday raqamli buyum inventaringizda yo'q!")
        return

    icon = CURRENCY_ICON[currency]
    seller_name = message.from_user.first_name
    with db_lock:
        cur.execute(
            "INSERT INTO market_listings (chat_id, seller_id, seller_name, item, price, active, currency) VALUES (?,?,?,?,?,1,?)",
            (message.chat.id, uid, seller_name, item_to_sell, price, currency),
        )
        conn.commit()
        listing_id = cur.lastrowid

    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"🛒 Sotib olish ({price} {icon})", callback_data=f"mbuy|{listing_id}"))
    bot.send_message(
        message.chat.id,
        f"📢 <b>Qora bozorda yangi e'lon!</b>\n\n"
        f"📦 Narsa: <b>{item_to_sell}</b>\n"
        f"💰 Narx: <b>{price}</b> {icon}\n"
        f"👤 Sotuvchi: {seller_name}\n"
        f"🆔 E'lon ID: <code>{listing_id}</code>",
        reply_markup=kb,
    )


@bot.message_handler(commands=["osh"])
def cmd_osh(message):
    """🥘 Milliy osh — o'zingizga emas, GURUHDAGI boshqa bir o'yinchiga ziyofat
    berish uchun: unga bir martalik himoya (shield) va (turiga qarab) qo'shimcha
    qobiliyat sovg'a qiladi — pul emas. Foydalanish: reply qilib /osh <turi>."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not message.reply_to_message:
        lines = ["🥘 <b>Milliy Osh Menyusi</b> — do'stingizga ziyofat bering!\n"]
        for key, item in SHOP_OSH.items():
            extra = f" + 1x {TOGGLABLE_ITEMS.get(item['gift_charge'][0], item['gift_charge'][0])}" if item.get("gift_charge") else ""
            lines.append(f"<code>{key}</code> — {item['name']} (${item['price']}) → {item['gift_shield']}🛡{extra}")
        lines.append("\n<i>Reply qilib: </i><code>/osh &lt;turi&gt;</code>")
        bot.send_message(message.chat.id, "\n".join(lines))
        return
    parts = message.text.split()
    if len(parts) != 2 or parts[1].lower() not in SHOP_OSH:
        bot.send_message(message.chat.id, "Foydalanish: <code>/osh &lt;turi&gt;</code> (masalan: <code>/osh toy</code>)")
        return
    key = parts[1].lower()
    item = SHOP_OSH[key]
    sender = message.from_user
    target = message.reply_to_message.from_user
    if target.id == sender.id:
        bot.send_message(message.chat.id, "❌ O'zingizga ziyofat berolmaysiz — bu boshqa o'yinchiga sovg'a.")
        return
    u = user_dict(sender.id, sender.first_name)
    user_dict(target.id, target.first_name or "O'yinchi")
    if u["dollar"] < item["price"]:
        bot.send_message(message.chat.id, f"❌ Yetarli mablag' yo'q (${item['price']} kerak).")
        return
    update_user(sender.id, dollar=u["dollar"] - item["price"])
    add_shield(target.id, item["gift_shield"])
    extra_text = ""
    if item.get("gift_charge"):
        ck, amount = item["gift_charge"]
        add_charge(target.id, ck, amount)
        extra_text = f" + {amount}x {TOGGLABLE_ITEMS.get(ck, ck)}"
    bot.send_message(
        message.chat.id,
        f"{item['name']}! {mention(sender.id, sender.first_name)} — {mention(target.id, target.first_name)}ga ziyofat berdi!\n"
        f"🎁 {esc(target.first_name)} +{item['gift_shield']}🛡{extra_text} sovg'a oldi.",
    )


