@bot.callback_query_handler(func=lambda c: c.data.startswith("mconfirm|") or c.data == "mcancel")
def cb_market_confirm(call):
    maybe_capture_owner(call.from_user)
    if call.data == "mcancel":
        bot.answer_callback_query(call.id, "🚫 Savdo bekor qilindi.", show_alert=True)
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        return

    if not _in_black_market_group(call.message.chat.id):
        bot.answer_callback_query(call.id, "⛔ Qora bozor faqat maxsus savdo guruhida ishlaydi.", show_alert=True)
        return

    listing_id = int(call.data.split("|")[1])
    buyer_id = call.from_user.id

    # Atomik "reserve-then-charge" naqshi: avval e'lonni band qilamiz (active=0,
    # faqat hali active=1 bo'lsa), keyin xaridordan pul yechamiz. Agar pul
    # yetmasa — bandlovni ORQAGA qaytaramiz (rollback), shunday qilib ikki
    # kishi bir e'lonni parallel sotib ololmaydi va pul yo'qolib ketmaydi.
    with db_lock:
        cur.execute("SELECT item, price, seller_id, seller_name, active, currency FROM market_listings WHERE id=?", (listing_id,))
        row = cur.fetchone()
        if not row or row[4] != 1:
            bot.answer_callback_query(call.id, "❌ Xatolik: e'lon topilmadi yoki allaqachon sotilgan!", show_alert=True)
            return
        item, price, seller_id, seller_name, _, currency = row
        currency = currency or "coin"
        icon = CURRENCY_ICON.get(currency, "🪙")
        if seller_id == buyer_id:
            bot.answer_callback_query(call.id, "❌ O'z narsangizni o'zingiz sotib ololmaysiz!", show_alert=True)
            return
        user_dict(buyer_id, call.from_user.first_name)

        cur.execute("UPDATE market_listings SET active=0 WHERE id=? AND active=1", (listing_id,))
        if cur.rowcount == 0:
            conn.commit()
            bot.answer_callback_query(call.id, "❌ Bu buyum allaqachon sotilgan!", show_alert=True)
            return
        conn.commit()

        if not try_charge(buyer_id, currency, price):
            # Pul yetmadi — bandlovni qaytaramiz, boshqa xaridor sotib olishi mumkin bo'lsin.
            cur.execute("UPDATE market_listings SET active=1 WHERE id=?", (listing_id,))
            conn.commit()
            bot.answer_callback_query(
                call.id,
                f"❌ {icon} yetarli emas! Kerak: {price} {icon}.",
                show_alert=True,
            )
            return

    add_balance_as('market', seller_id, ledger=False, **{currency: price})
    add_inventory_item(buyer_id, item)

    bot.answer_callback_query(call.id, f"🎉 Tabriklaymiz! {item} muvaffaqiyatli sotib olindi!", show_alert=True)
    seller_mention = mention(seller_id, seller_name)
    buyer_mention = mention(buyer_id, call.from_user.first_name)
    try:
        bot.edit_message_text(
            f"✅ <b>Savdo muvaffaqiyatli yakunlandi!</b>\n\n"
            f"📦 Narsa: {item}\n👤 Sotuvchi: {seller_mention}\n🛒 Xaridor: {buyer_mention}\n"
            f"💰 Narx: {price} {icon}",
            call.message.chat.id, call.message.message_id,
        )
    except Exception:
        bot.send_message(
            call.message.chat.id,
            f"✅ <b>Savdo muvaffaqiyatli yakunlandi!</b>\n\n"
            f"📦 Narsa: {item}\n👤 Sotuvchi: {seller_mention}\n🛒 Xaridor: {buyer_mention}\n"
            f"💰 Narx: {price} {icon}",
        )


# ================================================================================
#  KUNDUZGI OVOZ BERISH BOSQICHI
# ================================================================================

def start_day(chat_id):
    """☀️ Kunduzgi bosqich: avval DAY_DISCUSSION_SECONDS soniya muhokama, so'ng
    ovoz berish tugmalari chiqadi va yana DAY_VOTE_SECONDS soniya davom etadi.
    Kunning umumiy uzunligi: DAY_TOTAL_SECONDS (= DAY_DISCUSSION_SECONDS + DAY_VOTE_SECONDS)."""
    game = GAMES.get(chat_id)
    if not game:
        return
    game["phase"] = "day"
    game["votes"] = {}
    game["double_vote_on"] = set()
    game["voting_open"] = False
    game["spoke_before_vote_today"] = set()
    game["vote_order"] = []
    game["no_lynch_today"] = False
    game["fog_today"] = False
    game["hero_armed_vote_shield"] = set()
    _gt = game_times(game)  # ⚙️ v8: guruh tezligi sozlamasi
    vote_seconds = _gt["vote"]
    hero_day_start(chat_id, game)   # 🥷 Geroy: kunduzgi 🛡 / ⚔️ tugmalari

    # 🏆 Geroy (Draven/Zephyrion "Xalq himoyasi") — hali sarflanmagan bo'lsa, kunduzi eslatma
    for uid, p in alive_players(game).items():
        if hero_has_ability(uid, "vote_shield_once") and uid not in game.get("hero_vote_shield_used", set()):
            if hero_auto_enabled(uid):
                # 🤖 v8: Avto-rejim — Xalq himoyasi kunduzi o'zi faollashadi
                game["hero_armed_vote_shield"].add(uid)
                continue
            kb = types.InlineKeyboardMarkup()
            kb.add(types.InlineKeyboardButton("🗳 Xalq himoyasini faollashtirish", callback_data=f"heroarm|voteshield|{chat_id}"))
            safe_send(uid, "🏆 Geroyingizning bir martalik 🗳 Xalq himoyasi bor. Bugun faollashtirmasangiz, ishlamaydi:", kb)

    # 🎲 Random event — har kuni 15% ehtimol bilan, ENDI HAR BIRI HAQIQIY TA'SIR QILADI
    if random.random() < 0.15:
        event = random.choice(RANDOM_EVENTS)
        bot.send_message(chat_id, f"🎲 <b>Kutilmagan hodisa!</b>\n{event['text']}")
        key = event["key"]
        if key == "lucky_all":
            for uid in alive_players(game):
                add_balance(uid, dollar=50)
        elif key == "lucky_one":
            alive_uids = list(alive_players(game).keys())
            if alive_uids:
                lucky_uid = random.choice(alive_uids)
                add_balance(lucky_uid, dollar=100)
                safe_send(lucky_uid, "🎁 Tabriklaymiz! Bugungi tasodifiy hodisadan sizga +100$ tushdi!")
        elif key == "no_lynch":
            game["no_lynch_today"] = True
        elif key == "weak_night":
            game["weak_night_today"] = True
        elif key == "fog":
            game["fog_today"] = True
        elif key == "short_vote":
            vote_seconds = 15
    game["vote_seconds_today"] = vote_seconds

    send_scene_photo(
        chat_id, DAY_PHOTO_LOCAL, DAY_PHOTO,
        caption=f"☀️ <b>{game['day_number']}-kun.</b> Muhokama qiling — {_gt['discuss']} soniyadan so'ng "
                "ovoz berish tugmalari shaxsiy chatingizga tushadi. 🤖",
        reply_markup=_bot_dm_button(),
    )

    t = threading.Timer(_gt["discuss"], lambda: open_day_voting(chat_id))
    t.daemon = True
    t.start()
    game["timers"].append(t)

    # 🔄 checkpoint
    game["day_sub_phase"] = "discussion"
    game["phase_deadline"] = time.time() + _gt["discuss"]
    save_games_state()


def _send_day_vote_time_reminder(chat_id, day_no):
    """⏰ Ovoz berish tugashiga DAY_VOTE_REMINDER_LEAD_SECONDS soniya qolganda
    chaqiriladi — hali ovoz bermagan tirik o'yinchilarga shaxsiy chatda eslatma yuboradi."""
    game = GAMES.get(chat_id)
    if not game or game.get("phase") != "day" or game.get("day_sub_phase") != "voting" or game.get("day_number") != day_no:
        return
    votes = game.get("votes", {})
    for uid, p in alive_players(game).items():
        if uid not in votes and day_vote_block_reason(game, uid) is None:
            safe_send(uid, f"⏰ Vaqtingiz tugayapti! Ovoz berish uchun ~{DAY_VOTE_REMINDER_LEAD_SECONDS} soniya qoldi.")


def _fit_candidates(game):
    """😈 Fitnachi: bugungi ovoz berishda ruxsat etilgan nomzodlar (tirik bo'lganlari); yo'q bo'lsa — bo'sh."""
    fa = game.get("fit_active") or []
    return [c for c in fa if c in game["players"] and game["players"][c]["alive"]]


def day_vote_block_reason(game, uid):
    """🔇 'Nega ovoz bera olmayapman?' — agar o'yinchi biror ta'sir ostida bo'lib
    (masalan, ovozi tiyilgan/band qilingan) bugungi kunduzgi ovoz berishda
    qatnasha olmasa, ANIQ va tushunarli sababni qaytaradi. Hech qanday
    cheklov yo'q bo'lsa — None. Kelajakda yangi cheklov turi qo'shilsa,
    shu funksiyaga qo'shiladi — shunda BARCHA joyda (ovoz tugmalari
    yuborilishidan OLDIN HAM, tugma bosilganda HAM) bir xil, aniq sabab
    ko'rsatiladi — hech qachon "shunchaki ishlamay qoladi" degan holat
    bo'lmaydi."""
    if uid in game.get("day_silenced", set()):
        return "bugun ovoz berish huquqingiz yo'q"
    return None


def open_day_voting(chat_id):
    """Muhokama vaqti (DAY_DISCUSSION_SECONDS) tugagach chaqiriladi — ovoz berish tugmalarini
    tirik o'yinchilarning shaxsiy chatiga yuboradi va DAY_VOTE_SECONDS soniyalik hisobni boshlaydi."""
    game = GAMES.get(chat_id)
    if not game or game["phase"] != "day":
        return
    game["voting_open"] = True
    vote_seconds = game.get("vote_seconds_today", DAY_VOTE_SECONDS)

    bot.send_message(
        chat_id,
        f"⚖️ <b>Aybdorlarni aniqlash va jazolash vaqti keldi.</b>\n"
        f"Ovoz berish uchun <b>{vote_seconds} sekund</b>",
        reply_markup=_bot_dm_button("🗳 Ovoz berish"),
    )

    # 🔴🔵 Qizil va Ko'k rejimida — ovoz berish tugmalari chiqishidan OLDIN, har bir
    # o'yinchiga o'z jamodoshlari ro'yxati eslatma qilib yuboriladi.
    send_squad_reminders(game)

    alive = alive_players(game)
    fit_c = _fit_candidates(game)
    if fit_c:
        bot.send_message(chat_id, f"😈 Bugun faqat {mention(fit_c[0], game['players'][fit_c[0]]['name'])} va "
                                  f"{mention(fit_c[1], game['players'][fit_c[1]]['name'])}ga ovoz beriladi." if len(fit_c) == 2 else
                         f"😈 Bugun faqat {mention(fit_c[0], game['players'][fit_c[0]]['name'])}ga ovoz beriladi.")
    for voter_id in alive:
        # 🔇 Agar bu o'yinchi biror sabab bilan bugun ovoz bera olmasa — unga
        # umuman "ovoz berish" tugmalari YUBORILMAYDI (aks holda tugmani
        # bosgach keyin "ovoz berolmaysiz" deb qaytarish chalkash bo'lardi).
        # Buning o'rniga ANIQ SABABI bilan alohida xabar yuboriladi.
        block_reason = day_vote_block_reason(game, voter_id)
        if block_reason:
            safe_send(voter_id, f"🔇 Siz bugun ovoz bera olmaysiz, chunki {block_reason}.")
            continue
        # 🐺🦅 Har bir o'yinchi uchun tugmalar ALOHIDA quriladi, chunki
        # jamodosh belgisi (🐺/🦅) faqat SHU o'yinchining ko'zida ko'rinishi
        # kerak — boshqalar uchun o'sha odam boshqa jamoada bo'lishi mumkin.
        kb = types.InlineKeyboardMarkup()
        for uid, p in alive.items():
            if fit_c and uid not in fit_c:
                continue
            tag = squad_tag(game, voter_id, uid)
            kb.add(types.InlineKeyboardButton(f"{tag}{p['name']}", callback_data=f"dv|{chat_id}|{uid}"))
        kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"dv|{chat_id}|skip"))
        ok = safe_send(voter_id, "🗳 <b>Kimni mafiya deb hisoblaysiz?</b> Ovoz berish uchun tanlang:", kb)
        if not ok:
            bot.send_message(
                chat_id,
                f"⚠️ {mention(voter_id, alive[voter_id]['name'])}, botga ovoz berish uchun avval "
                f"shaxsiy xabarlarda /start bosing!",
                reply_markup=_bot_dm_button(),
            )

    t = threading.Timer(vote_seconds, lambda: resolve_day(chat_id))
    t.daemon = True
    t.start()
    game["timers"].append(t)

    if vote_seconds > DAY_VOTE_REMINDER_LEAD_SECONDS:
        day_no = game["day_number"]
        rt = threading.Timer(vote_seconds - DAY_VOTE_REMINDER_LEAD_SECONDS,
                              lambda: _send_day_vote_time_reminder(chat_id, day_no))
        rt.daemon = True
        rt.start()
        game["timers"].append(rt)

    # 🔄 checkpoint
    game["day_sub_phase"] = "voting"
    game["phase_deadline"] = time.time() + vote_seconds
    save_games_state()


VOTE_LATE_TEXT = "⏰ Ovoz berish vaqti tugadi — ovozingiz hisobga olinmadi."


def _vote_late(call, game, need_open=True):
    """Ovoz berish vaqti tugagan bo'lsa — foydalanuvchiga ovozi hisobga olinmaganini aytadi."""
    late = (not game or game.get("phase") != "day" or game.get("confirm_vote")
            or (game.get("day_sub_phase") == "voting"
                and game.get("phase_deadline") and time.time() > game["phase_deadline"] + 1))
    if not late:
        return False
    try:
        bot.answer_callback_query(call.id, VOTE_LATE_TEXT, show_alert=True)
    except Exception:
        pass
    try:
        bot.edit_message_text(VOTE_LATE_TEXT, call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    return True


@bot.callback_query_handler(func=lambda c: c.data.startswith("dv|"))
@fast_callback
def cb_vote(call):
    maybe_capture_owner(call.from_user)
    _, chat_id_s, target_s = call.data.split("|")
    chat_id = int(chat_id_s)
    game = GAMES.get(chat_id)
    voter_id = call.from_user.id

    if _vote_late(call, game):
        return
    if not game.get("voting_open"):
        bot.answer_callback_query(call.id, "⏳ Ovoz berish hali boshlanmadi — avval muhokama davri tugashini kuting.", show_alert=True)
        return
    if voter_id not in game["players"] or not game["players"][voter_id]["alive"]:
        bot.answer_callback_query(call.id, "Faqat tirik ishtirokchilar ovoz bera oladi.")
        return
    block_reason = day_vote_block_reason(game, voter_id)
    if block_reason:
        bot.answer_callback_query(call.id, f"🔇 Siz bugun ovoz bera olmaysiz, chunki {block_reason}.", show_alert=True)
        return

    target = target_s if target_s == "skip" else int(target_s)
    _fc = _fit_candidates(game)
    if target != "skip" and _fc and target not in _fc:
        bot.answer_callback_query(call.id, "😈 Bugun faqat nomzodlarga ovoz beriladi.", show_alert=True)
        return
    game["votes"][voter_id] = target
    game.setdefault("day_voted", set()).add(voter_id)
    game.setdefault("activity_score", {})
    game["activity_score"][voter_id] = game["activity_score"].get(voter_id, 0) + 1
    game.setdefault("vote_order", [])
    if voter_id in game["vote_order"]:
        game["vote_order"].remove(voter_id)  # qayta ovoz bersa, oxirgi o'ringa ko'chadi
    game["vote_order"].append(voter_id)
    voter_name = game["players"][voter_id]["name"]
    target_name = "o'tkazib yuborish" if target == "skip" else game["players"][target]["name"]

    revote_left = get_charges(voter_id).get("revote", 0)
    kb = None
    if revote_left > 0:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton(f"🔄 Ovozni o'zgartirish ({revote_left} ta qoldi)", callback_data=f"revote|{chat_id}"))
    try:
        bot.edit_message_text(f"✅ Siz <b>{target_name}</b> deb ovoz berdingiz.", call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        pass
    bot.answer_callback_query(call.id, f"Siz {target_name} deb ovoz berdingiz.")
    target_mention = "o'tkazib yuborish" if target == "skip" else mention(target, game["players"][target]["name"])
    # 🔧 TUZATILDI: avval faqat NISHON ismi bosiladigan edi — endi OVOZ BERUVCHINING
    # ismi ham bosilganda uning profiliga o'tadi (barcha nik-neymlar izchil bosiladigan).
    if gsv(game, "vote_public") == "0":   # ⚙️ v8: guruhda yashirin ovoz berish yoqilgan
        bot.send_message(chat_id, f"🗳 {mention(voter_id, voter_name)} ovoz berdi.")
    else:
        if target == "skip":
            bot.send_message(chat_id, f"{mention(voter_id, voter_name)} - ovoz bermaslikni tanladi")
        else:
            bot.send_message(chat_id, f"{mention(voter_id, voter_name)} - {target_mention}ga ovoz berdi")


@bot.callback_query_handler(func=lambda c: c.data.startswith("revote|"))
@fast_callback
def cb_revote(call):
    """⚡️ Energiya ichimligi — kunduzi ovoz bergandan keyin fikrni o'zgartirib,
    qayta ovoz berish imkonini beradi (charge tugaguncha)."""
    maybe_capture_owner(call.from_user)
    _, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    game = GAMES.get(chat_id)
    voter_id = call.from_user.id
    if _vote_late(call, game):
        return
    if not game.get("voting_open"):
        bot.answer_callback_query(call.id, "Ovoz berish yakunlangan.")
        return
    if voter_id not in game["players"] or not game["players"][voter_id]["alive"]:
        bot.answer_callback_query(call.id, "Faqat tirik ishtirokchilar ovoz bera oladi.")
        return
    if not use_charge(voter_id, "revote"):
        bot.answer_callback_query(call.id, "❌ Qayta ovoz berish huquqingiz qolmagan.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup()
    for target_id, p in alive_players(game).items():
        tag = squad_tag(game, voter_id, target_id)
        kb.add(types.InlineKeyboardButton(f"{tag}{p['name']}", callback_data=f"dv|{chat_id}|{target_id}"))
    kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"dv|{chat_id}|skip"))
    try:
        bot.edit_message_text("🔄 <b>Ovozingizni qayta tanlang:</b>", call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        bot.send_message(chat_id if False else voter_id, "🔄 <b>Ovozingizni qayta tanlang:</b>", reply_markup=kb)
    bot.answer_callback_query(call.id, "✅ Qayta ovoz berishingiz mumkin!")


def resolve_day(chat_id):
    with _glock(chat_id):
        game = GAMES.get(chat_id)
        if not game or game["phase"] != "day":
            return

        for uid, p in alive_players(game).items():
            if uid not in game["votes"]:
                game["votes"][uid] = "skip"

        # 👨‍⚖️ Sudya — agar shu tunda faollashtirgan bo'lsa, uning ovozi 2x kuchga ega
        # 👑 Rais — xuddi Sudya kabi, ammo mafiya tarafida
        # 👑 Geroy (Magnus/Zephyrion "General nufuzi") — qo'shimcha +1 ovoz og'irligi
        tally = {}
        for _dv in list(game["votes"]):
            # 🗳 Ikki ovoz buyumi: ovoz bergan paytda zaxirada bo'lsa — 1 ta zaryad sarflanadi
            if game["votes"][_dv] != "skip" and _dv in game["players"] and use_charge(_dv, "double_vote"):
                game.setdefault("double_vote_on", set()).add(_dv)
                safe_send(_dv, "🗳 <b>Ikki ovoz</b> ishladi — bugungi ovozingiz 2 barobar hisoblandi.")
        for voter, target in game["votes"].items():
            if target == "skip":
                continue
            # 🎖 Janob: ovozi 2 ta hisoblanadi (ro'yxatda oddiy bitta ovoz bo'lib ko'rinadi)
            weight = 2 if game["players"].get(voter, {}).get("role") == R_JAN else 1
            weight += hero_vote_weight_bonus(voter)
            if voter in game.get("double_vote_on", set()):
                weight += 1
            tally[target] = tally.get(target, 0) + weight

        if not tally:
            bot.send_message(chat_id, "🤷 Hech kim ovoz bermadi, shuning uchun bugun hech kim osilmaydi.")
            finish_day_phase(chat_id)
            return

        max_v = max(tally.values())
        top = [uid for uid, v in tally.items() if v == max_v]
        if len(top) > 1:
            bot.send_message(chat_id, "⚖️ <b>Ovoz berish yakunlandi:</b>\nAholi kelisha olmadi... Kelisha olmaslik oqibatida hech kim osilmadi.")
            finish_day_phase(chat_id)
            return

        hanged = top[0]
        if game.get("no_lynch_today"):
            bot.send_message(
                chat_id,
                f"🔍 <b>Taqdir hukmi kuchda!</b> {mention(hanged, game['players'][hanged]['name'])} eng ko'p ovoz oldi, "
                "ammo bugungi tasodifiy hodisa tufayli hech kim osilmaydi.",
            )
            finish_day_phase(chat_id)
            return

        # 🏆 Geroy (Draven "Xalq himoyasi") — FAQAT o'zi /geroy_himoya bilan shu kunga
        # QO'LDA faollashtirgan bo'lsa ishlaydi (avtomatik EMAS), va faqat 1 marta o'yin davomida
        if (hanged in game.get("hero_armed_vote_shield", set())
                and hero_has_ability(hanged, "vote_shield_once")
                and hanged not in game.setdefault("hero_vote_shield_used", set())):
            game["hero_vote_shield_used"].add(hanged)
            _hero = get_hero(hanged)
            _hero_ab = next((a for a in hero_unlocked_abilities(hanged) if a["key"] == "vote_shield_once"), None)
            bot.send_message(
                chat_id,
                f"🗳🏆 <b>Geroy qobiliyati ishga tushdi!</b> {mention(hanged, game['players'][hanged]['name'])} "
                f"eng ko'p ovoz oldi, ammo <b>{_hero['name']}</b>ning "
                f"<b>{_hero_ab['name'] if _hero_ab else '🗳 Xalq himoyasi'}</b> qobiliyati uni qutqarib qoldi!",
            )
            for voter_uid in game["votes"]:
                if game["votes"][voter_uid] == hanged:
                    safe_send(voter_uid, "🗳🏆 <i>Ovoz bergan nishoningiz kimningdir geroy qobiliyati tufayli linchdan qutulib qoldi...</i>")
            finish_day_phase(chat_id)
            return
        if game["players"][hanged].get("smoke_active"):
            game["players"][hanged]["smoke_active"] = False
            bot.send_message(
                chat_id,
                f"💨 Aholi {mention(hanged, game['players'][hanged]['name'])}ni osmoqchi bo'ldi, "
                f"lekin 💣 Tutunli bomba tutuni ostida u qochib qutuldi! Bugun hech kim osilmadi.",
            )
            finish_day_phase(chat_id)
            return

        # 🗳 Eng ko'p ovoz olgan ishtirokchi aniqlandi — endi guruhga uning bosilsa
        # Telegram profiliga o'tadigan nikneymi bilan yakuniy tasdiqlash ovoz berishi ochiladi.
        if gsv(game, "confirm_vote") == "0":
            # ⚙️ v8: guruhda tasdiqlash o'chirilgan — eng ko'p ovoz olgan darhol osiladi
            game["confirm_vote"] = {"target": hanged, "yes": set(alive_players(game).keys()),
                                    "no": set(), "message_id": None, "auto": True}
            resolve_hang_confirmation(chat_id)
        else:
            start_hang_confirmation(chat_id, hanged)


def _confirm_kb(chat_id, yes_n, no_n):
    kb = types.InlineKeyboardMarkup()
    kb.add(
        types.InlineKeyboardButton(f"👍 {yes_n}", callback_data=f"dvc|{chat_id}|yes"),
        types.InlineKeyboardButton(f"👎 {no_n}", callback_data=f"dvc|{chat_id}|no"),
    )
    return kb


def start_hang_confirmation(chat_id, target_uid):
    """Eng ko'p ovoz olgan ishtirokchini haqiqatan ham osish-osmaslik haqida
    guruhda 👍/👎 tasdiqlash ovoz berishini boshlaydi. Har bir tirik o'yinchi
    faqat bitta ovozga ega bo'ladi."""
    game = GAMES.get(chat_id)
    if not game:
        return
    name = game["players"][target_uid]["name"]
    game["confirm_vote"] = {"target": target_uid, "yes": set(), "no": set(), "message_id": None}
    text = (
        f"Rostdan ham {mention(target_uid, name)}ni osmoqchimisiz?"
    )
    sent = bot.send_message(chat_id, text, reply_markup=_confirm_kb(chat_id, 0, 0))
    game["confirm_vote"]["message_id"] = sent.message_id

    _confirm_s = game_times(game)["confirm"]  # ⚙️ v8
    t = threading.Timer(_confirm_s, lambda: resolve_hang_confirmation(chat_id))
    t.daemon = True
    t.start()
    game["timers"].append(t)

    # 🔄 checkpoint
    game["phase_deadline"] = time.time() + _confirm_s
    save_games_state()


@bot.callback_query_handler(func=lambda c: c.data.startswith("dvc|"))
def cb_confirm_vote(call):
    maybe_capture_owner(call.from_user)
    _, chat_id_s, choice = call.data.split("|")
    chat_id = int(chat_id_s)
    game = GAMES.get(chat_id)
    uid = call.from_user.id
    cv = game.get("confirm_vote") if game else None

    if not game or not cv:
        bot.answer_callback_query(call.id, VOTE_LATE_TEXT, show_alert=True)
        return
    if cv.get("deadline") and time.time() > cv["deadline"] + 1:
        bot.answer_callback_query(call.id, VOTE_LATE_TEXT, show_alert=True)
        return
    if uid not in game["players"] or not game["players"][uid]["alive"]:
        bot.answer_callback_query(call.id, "Faqat tirik ishtirokchilar ovoz bera oladi.")
        return

    # bitta o'yinchi — har bir tasdiqlash ovoz berishida bitta ovozga ega
    game.setdefault("day_voted", set()).add(uid)
    cv["yes"].discard(uid)
    cv["no"].discard(uid)
    if choice == "yes":
        cv["yes"].add(uid)
    else:
        cv["no"].add(uid)

    # ⚡ avval javob — tugma "osilib" qolmasin; oynada joriy hisob ko'rinadi
    bot.answer_callback_query(call.id, f"👍 {len(cv['yes'])} | 👎 {len(cv['no'])}", show_alert=True)
    try:
        bot.edit_message_reply_markup(chat_id, cv["message_id"], reply_markup=_confirm_kb(chat_id, len(cv["yes"]), len(cv["no"])))
    except Exception:
        pass

    if len(cv["yes"]) + len(cv["no"]) >= len(alive_players(game)):
        # alohida oqimda: Afsungar tanlovi kutilsa, tugma ishlovchisi band qolmasin
        threading.Thread(target=resolve_hang_confirmation, args=(chat_id,), daemon=True).start()


def resolve_hang_confirmation(chat_id):
    with _glock(chat_id):
        game = GAMES.get(chat_id)
        cv = game.get("confirm_vote") if game else None
        if not game or not cv:
            return
        game["confirm_vote"] = None
        target_uid = cv["target"]
        yes_n, no_n = len(cv["yes"]), len(cv["no"])
        # ⚙️ v8: tasdiqlash o'chirilgan bo'lsa (auto) soxta 👍/👎 hisobi ko'rsatilmaydi
        _score_suffix = "" if cv.get("auto") else f" (👍 {yes_n} — 👎 {no_n})"
        _score_line = "" if cv.get("auto") else f": 👍 {yes_n} — 👎 {no_n}"

        if target_uid not in game["players"] or not game["players"][target_uid]["alive"]:
            finish_day_phase(chat_id)
            return
        name = game["players"][target_uid]["name"]

        if yes_n <= no_n:
            bot.send_message(
                chat_id,
                f"<b>Ovoz berish natijalari:</b>\n{yes_n} 👍 | {no_n} 👎\n\n"
                f"Aholi rahm qildi — bugun hech kim osilmadi.",
            )
            finish_day_phase(chat_id)
            return

        # ⚡ Koldun himoyasi yoki 🛡🌞 Ovozdan himoya buyumi — bittasi bo'lsa yetarli.
        # 🛡🌞 Ovozdan himoya bitta o'yinda FAQAT DAY_SHIELD_MAX_PER_GAME (=1) marta ishlaydi.
        protected_by_koldun = target_uid in game.get("koldun_protect", set())
        _dsu = game.setdefault("day_shield_used", set())
        has_day_shield = (
            target_uid not in _dsu
            and get_charges(target_uid).get("day_shield", 0) > 0
            and is_item_active(target_uid, "day_shield")
        )
        if protected_by_koldun or has_day_shield:
            if has_day_shield:
                use_charge(target_uid, "day_shield")
                _dsu.add(target_uid)
                reason = "⚖️ Ovozdan himoya"
            else:
                reason = "⚡ Himoya"
            bot.send_message(
                chat_id,
                f"{reason} tufayli {mention(target_uid, name)} osilishdan qutulib qoldi!{_score_suffix}",
            )
            finish_day_phase(chat_id)
            return

        game["players"][target_uid]["alive"] = False
        game.setdefault("death_info", {})[target_uid] = {"how": "hang", "side": None}
        role = game["players"][target_uid]["role"]
        bot.send_message(
            chat_id,
            ("" if cv.get("auto") else f"<b>Ovoz berish natijalari:</b>\n{yes_n}👍 | {no_n}👎\n\n")
            + f"{mention(target_uid, name)} - ni osamiz! :)\n\n"
            f"{mention(target_uid, name)} - <b>{role}</b> edi",
        )
        wait_last_words(chat_id, target_uid)

        # 🤦 Suidsid — uni ovoz berib osishsa, u yutgan deb belgilanadi, lekin o'yin
        # TO'XTAMAYDI: boshqa tomonlar o'z g'alabasi uchun o'ynashda davom etadi, Suidsid
        # esa o'yin oxirida g'oliblar qatorida chiqadi.
        if role == R_SUI:
            game.setdefault("sui_won", set()).add(target_uid)
            bot.send_message(chat_id, f"🤦 {mention(target_uid, name)} Suidsid edi. U o'z maqsadiga erishdi — o'yin davom etadi.")
            safe_send(target_uid, "🤦 Siz osildingiz — maqsadingizga erishdingiz! O'yin oxirida g'oliblar qatorida bo'lasiz.")

        # 😈 Fitnachi: fitna nomzodlaridan biri osildi — fitna muvaffaqiyatli
        _fc = game.get("fit_active") or []
        if target_uid in _fc:
            for fu in alive_role_holders(game, lambda r: r == R_FIT):
                game.setdefault("fit_success", set()).add(fu)
                safe_send(fu, f"😈 {name} osildi. Fitna muvaffaqiyatli. Oxirigacha tirik qoling.")
        game["fit_active"] = None
        game["fit_cands"] = []

        handle_death_side_effects(game, chat_id, target_uid)

        # 💣 Afsungar — osilganda bitta o'yinchini o'zi bilan olib ketadi
        if role == R_AFS:
            victim = _afsungar_choose_victim(chat_id, game, target_uid)
            if victim and game["players"].get(victim, {}).get("alive"):
                game["players"][victim]["alive"] = False
                game.setdefault("death_info", {})[victim] = {"how": "blast", "side": None}
                bot.send_message(chat_id, f"💣 Afsungar portladi: {mention(victim, game['players'][victim]['name'])} ham halok bo'ldi.\n"
                                          f"💀 U {game['players'][victim]['role']} edi.")
                wait_last_words(chat_id, victim)
                handle_death_side_effects(game, chat_id, victim)

        finish_day_phase(chat_id)


def finish_day_phase(chat_id):
    game = GAMES.get(chat_id)
    if not game:
        return

    # 🤡 Kun tugadi — tanlanmagan Joker kartasi: nishon halok bo'ladi, Joker yutmaydi
    try:
        _joker_expire(chat_id, game)
    except Exception:
        _logger.warning("Joker kartasi muddati xatosi", exc_info=True)

    # 👁 Kuzatish ko'zi — to'liq ovoz taqsimotini DM orqali yuborish
    # 💼 Shubhali sumka — "hidden_vote" charge'i faol bo'lgan o'yinchining ovozi
    # bu hisobotda "noma'lum" bo'lib ko'rinadi (1 marta ishlatiladi)
    vote_lines = []
    for voter, target in game["votes"].items():
        voter_name = game["players"].get(voter, {}).get("name", "?")
        if get_charges(voter).get("hidden_vote", 0) > 0 and is_item_active(voter, "hidden_vote"):
            use_charge(voter, "hidden_vote")
            vote_lines.append(f"• {voter_name} → 🕵️ noma'lum (buyum bilan yashiringan)")
            # 🔧 TUZATILDI: avval bu yerda hech qanday DM yuborilmas edi
            safe_send(voter, "💼 Sizning <b>Shubhali sumka</b> buyumingiz ishladi — bu safar ovozingiz boshqalardan yashirildi!")
            continue
        target_name = "o'tkazib yuborish" if target == "skip" else game["players"].get(target, {}).get("name", "?")
        vote_lines.append(f"• {voter_name} → {target_name}")
    for uid, p in list(game["players"].items()):
        ch = get_charges(uid)
        if p["alive"] and ch.get("watch_eyes", 0) > 0 and is_item_active(uid, "watch_eyes"):
            use_charge(uid, "watch_eyes")
            safe_send(uid, "👁 <b>To'liq ovoz taqsimoti:</b>\n" + "\n".join(vote_lines))

    if check_and_end_game(chat_id):
        return
    if game.get("squad_mode"):
        wolf_alive = sum(1 for u,p in game["players"].items() if p.get("alive") and game.get("squads",{}).get(u)=="wolf")
        eagle_alive = sum(1 for u,p in game["players"].items() if p.get("alive") and game.get("squads",{}).get(u)=="eagle")
        _send_status_safe(chat_id, f"📊 Jamoalar: 🔴 {wolf_alive} tirik · 🔵 {eagle_alive} tirik")
    elif game.get("couple_mode"):
        _send_status_safe(chat_id, f"📊 Para o'yin: {len(alive_players(game))} ta tirik.")
    game["day_number"] += 1
    start_night(chat_id)


# ================================================================================
#  G'ALABA SHARTI VA MUKOFOTLAR
# ================================================================================

def evaluate_game_end(game):
    """🏁 25 rolli g'alaba qoidalari (jamoaviy/para rejimlaridan tashqari):
      • "town" — barcha mafia va yakka qotillar (Qotil, Kimyogar, Minior, Vampir, Joker) halok bo'lsa;
      • "mafia" — tirik mafiachilar soni qolgan hammadan (qotillar ham) kam bo'lmasa;
      • "killers" — mafia yo'q va tirik yakka qotillar qolgan hammadan kam bo'lmasa;
      • "mafia" (birga) — faqat bitta mafiachi va bitta yakka qotil qolsa (1 ga 1).
    Hali hech narsa hal bo'lmagan bo'lsa None."""
    alive = alive_players(game)
    mafia = [u for u, p in alive.items() if p["role"] in MAFIA_ROLES]
    _jwon = game.get("joker_won", set())
    killers = [u for u, p in alive.items() if p["role"] in KILLER_SOLO_ROLES
               and not (p["role"] == R_JOK and u in _jwon)]   # yutgan Joker — neytral
    real_killers = [u for u in killers if alive[u]["role"] != R_JOK]
    others = len(alive) - len(mafia) - len(killers)
    if not mafia and not killers:
        return "town"
    # Mafiya soni qolgan hamma (qotillar ham) yig'indisidan kam bo'lmasa — mafiya yutadi
    if mafia and len(mafia) >= len(alive) - len(mafia):
        return "mafia"
    if not mafia and real_killers and len(killers) >= others:
        return "killers"
    if mafia and killers and others == 0 and len(alive) <= 2:
        return "mafia"
    return None


def check_and_end_game(chat_id):
    game = GAMES.get(chat_id)
    if not game:
        return True
    alive = alive_players(game)

    # 💍 Para (couple) rejimi: g'alaba sharti ODDIY mafiya/tinch aholi balansi
    # EMAS — faqat oxirgi tirik qolgan aynan BITTA juftlikning ikkalasi qolsa
    # (rollaridan qat'i nazar) g'olib deb e'lon qilinadi. Shu sababli couple_mode
    # yoqilgan o'yinlarda pastdagi oddiy tekshiruv HECH QACHON ishlamaydi —
    # o'yin faqat bitta juftlikkacha qisqarganda tugaydi (🔧 TUZATILDI: avval
    # "2 kishi-yu ular juftlik emas" holatida pastdagi oddiy tekshiruvga tushib,
    # noto'g'ri g'olib e'lon qilinardi).
    if game.get("couple_mode") and game.get("couple_of") is not None:
        if len(alive) == 0:
            end_game(chat_id, "couple_draw")
            return True
        if len(alive) == 2:
            u1, u2 = list(alive.keys())
            if game["couple_of"].get(u1) == u2:
                end_game(chat_id, "couple", couple_pair=(u1, u2))
                return True
        return False

    # 🔴🔵 Jamoaviy (squad) rejimi: g'alaba sharti ODDIY mafiya/tinch aholi
    # balansi EMAS — faqat ikkala jamoning BIRI butunlay qirilib ketsa,
    # boshqa jamoa (tirik qolganlar) g'olib deb e'lon qilinadi. Shu sababli
    # squad_mode yoqilgan o'yinlarda pastdagi oddiy tekshiruv o'tkazib
    # yuboriladi — o'yin faqat jamo qirilganda tugaydi.
    if game.get("squad_mode") and game.get("squads") is not None:
        wolf_alive = [uid for uid in alive if game["squads"].get(uid) == "wolf"]
        eagle_alive = [uid for uid in alive if game["squads"].get(uid) == "eagle"]
        if not wolf_alive and not eagle_alive:
            end_game(chat_id, "squad_draw")
            return True
        if not wolf_alive:
            end_game(chat_id, "squad_eagle")
            return True
        if not eagle_alive:
            end_game(chat_id, "squad_wolf")
            return True
        return False

    winners_team = evaluate_game_end(game)
    if winners_team is None:
        return False

    end_game(chat_id, winners_team)
    return True


@bot.message_handler(commands=["tark_et", "leave"])
def cmd_tark_et(message):
    """🚪 O'yinchi o'zi xohlab o'yinni tark etadi — u avtomatik mag'lub hisoblanadi
    va o'yin oxirida g'olib jamoada bo'lsa ham mukofot olmaydi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    game = None
    chat_id = None
    for cid, g in GAMES.items():
        if uid in g["players"] and g["players"][uid]["alive"]:
            game, chat_id = g, cid
            break
    if not game:
        bot.send_message(message.chat.id, "❌ Siz hozir hech qanday faol o'yinda emassiz.")
        return
    game["players"][uid]["alive"] = False
    game["players"][uid]["left_game"] = True
    add_points(uid, -10, "left_game")
    name = game["players"][uid]["name"]
    bot.send_message(chat_id, f"🚪 {mention(uid, name)} o'yinni o'z xohishi bilan tark etdi. U mag'lub hisoblanadi.")
    safe_send(uid, "🚪 O'yinni tark etdingiz — bu o'yin uchun avtomatik mag'lub hisoblanasiz va yakuniy mukofot olmaysiz.")
    handle_death_side_effects(game, chat_id, uid)  # 👑 Don vorisligi / 👻 Arvoh faollashuvi
    check_and_end_game(chat_id)


def _send_result_robust(chat_id, text):
    """🏁 O'yin natijasini ALBATTA yetkazadi: uzun bo'lsa bo'laklarga bo'ladi, HTML xato bersa
    teglarsiz oddiy matn bilan, 429 bo'lsa kutib qayta urinadi."""
    chunks, cur_chunk = [], ""
    for line in text.split("\n"):
        if len(cur_chunk) + len(line) + 1 > 3800 and cur_chunk:
            chunks.append(cur_chunk)
            cur_chunk = ""
        cur_chunk += line + "\n"
    if cur_chunk.strip():
        chunks.append(cur_chunk)
    for ch in chunks:
        for attempt in range(4):
            try:
                bot.send_message(chat_id, ch)
                break
            except Exception as e:
                msg = str(e)
                m_ = re.search(r"retry after (\d+)", msg)
                if m_:
                    time.sleep(min(30, int(m_.group(1)) + 1))
                    continue
                if "parse entities" in msg or "can't parse" in msg or "Bad Request" in msg:
                    try:
                        bot.send_message(chat_id, re.sub(r"<[^>]+>", "", ch), parse_mode=None)
                        break
                    except Exception:
                        _logger.warning("natija oddiy matn bilan ham yuborilmadi", exc_info=True)
                        break
                time.sleep(1.5 * (attempt + 1))
        else:
            _logger.error("O'yin natijasi yuborilmadi (chat=%s)", chat_id)


def _role_won(game, uid, p, winners_team):
    """🏆 25 rolli g'alaba qoidasi: o'yinchi shu yakun bo'yicha yutdimi (tark etganlik alohida tekshiriladi)."""
    role = p.get("role")
    alive = p.get("alive")
    if role == R_CUP:
        _lv = game.get("lovers") or []                      # ikki sevishgan ham tirik bo'lsa — Cupid yutadi
        return len(_lv) == 2 and all(game["players"].get(x, {}).get("alive") for x in _lv)
    if role == R_GAZ:
        return uid in game.get("gaz_won", set())          # o'lib ham yutishi mumkin
    if role == R_SUI:
        return uid in game.get("sui_won", set())           # osilgan Suidsid — har qanday yakunda g'olib
    if role == R_JOK and uid in game.get("joker_won", set()):
        return True                                        # maqsadiga erishgan Joker — har qanday yakunda g'olib
    if not alive:
        return False
    if role == R_FIT:
        return uid in game.get("fit_success", set())
    if role in SURVIVOR_ROLES:
        return True                                        # oxirigacha tirik qolish — har qanday yakunda
    if role in KILLER_SOLO_ROLES:
        # "mafia" yakunida qotil faqat 1 ga 1 holatida (2 tirik) birga yutadi
        return winners_team == "killers" or (winners_team == "mafia" and len(alive_players(game)) <= 2)
    if role in MAFIA_ROLES:
        return winners_team == "mafia"
    return winners_team == "town"                          # Shahar tomoni


def end_game(chat_id, winners_team, couple_pair=None):
    game = GAMES.get(chat_id)
    if not game:
        return
    # 🔒 Ikki marta yakunlanishning (double-finalize) oldini olish: masalan admin
    # /stop bilan bir vaqtda tabiiy g'alaba shartlari ham ishga tushsa, faqat
    # BIRINCHI chaqiruv haqiqatan ishlov beradi, qolganlari darhol chiqib ketadi.
    with db_lock:
        if game.get("_ending"):
            return
        game["_ending"] = True
    try:
        _k = "games_day_" + time.strftime("%Y-%m-%d")
        set_setting(_k, str(int(get_setting(_k) or 0) + 1))
    except Exception:
        pass
    try:
        reveal_anonymity(game)   # 🦊 anonim rejim: natijada haqiqiy ismlar ochiladi
    except Exception:
        _logger.warning("reveal_anonymity xatosi", exc_info=True)
    try:
        for _u in list(game["players"]):
            if not game["players"][_u].get("left_game"):
                offer_bildirish(_u, chat_id, game.get("chat_title"))
    except Exception:
        pass
    lines = ["🏁 <b>O'yin tugadi!</b>\n"]
    if winners_team == "couple_draw":
        lines.append("💍 <b>Para o'yin — DURRANG!</b>\nBarcha juftliklar o'yindan chiqdi. G'olib juftlik qolmadi.\n")
    elif winners_team == "couple":
        u1, u2 = couple_pair
        n1 = game["players"].get(u1, {}).get("name", "O'yinchi")
        n2 = game["players"].get(u2, {}).get("name", "O'yinchi")
        lines.append(
            f"💍 <b>G'OLIB JUFTLIK:</b> 💍 {mention(u1, n1)} + 💍 {mention(u2, n2)}!\n"
            f"🎉 Juftlikning ikkala a'zosi oxirigacha tirik qoldi.\n"
        )
    elif winners_team == "squad_draw":
        lines.append("🔴🔵 <b>Ikkala jamoa ham butunlay qirilib bitdi — DURRANG!</b>\n")
    elif winners_team in ("squad_wolf", "squad_eagle"):
        winner_squad = "wolf" if winners_team == "squad_wolf" else "eagle"
        squad_label = "🔴 Qizil" if winner_squad == "wolf" else "🔵 Ko'k"
        lines.append(f"🏆 <b>G'olib jamoa: {squad_label}!</b>\n"
                     f"🎉 Raqib jamoa butunlay qirilib bitdi!\n")
    elif winners_team == "joker":
        lines.append("🤡 <b>JOKER G'OLIB!</b>\nNishon o'lim kartasini tanladi.\n")
    elif winners_team == "suidsid":
        lines.append("🤦 <b>SUIDSID G'OLIB!</b>\nU osilishga erishdi.\n")
    elif winners_team == "killers":
        lines.append("🔪 <b>Yakka qotillar g'olib!</b>\nShaharda ulardan boshqa kuch qolmadi.\n")
    else:
        lines.append(f"🎉 G'oliblar jamoasi: <b>{'Mafia' if winners_team == 'mafia' else 'Shahar'}</b>\n")

    _lv = game.get("lovers") or []
    if len(_lv) == 2 and all(x in game["players"] for x in _lv):
        lines.append(f"💘 <b>Sevishganlar:</b> {mention(_lv[0], game['players'][_lv[0]]['name'])} va {mention(_lv[1], game['players'][_lv[1]]['name'])}\n")
    # 🤦🤡 O'yin davomida maqsadiga erishgan Suidsid/Joker — yakunda ham g'olib sifatida ko'rsatiladi
    for _su in game.get("sui_won", set()):
        if _su in game["players"]:
            lines.append(f"🤦 <b>Suidsid ham yutdi:</b> {mention(_su, game['players'][_su]['name'])}\n")
    for _ju in game.get("joker_won", set()):
        if _ju in game["players"]:
            lines.append(f"🤡 <b>Joker ham yutdi:</b> {mention(_ju, game['players'][_ju]['name'])}\n")

    # 🏅 Eng faol o'yinchini aniqlaymiz (tun/kun harakatlari soni bo'yicha)
    activity = game.get("activity_score", {})
    most_active_uid = max(activity, key=activity.get) if activity else None
    winners, losers = [], []
    _won_map = {}
    for uid, p in game["players"].items():
        try:
            _left0 = p.get("left_game", False)
            if winners_team == "couple":
                _w0 = (uid in couple_pair) and not _left0
            elif winners_team in ("couple_draw", "squad_draw"):
                _w0 = False
            elif winners_team in ("squad_wolf", "squad_eagle"):
                _ws = "wolf" if winners_team == "squad_wolf" else "eagle"
                _w0 = (game.get("squads", {}).get(uid) == _ws) and not _left0 and bool(p.get("alive"))
            else:
                _w0 = bool(_role_won(game, uid, p, winners_team)) and not _left0
        except Exception:
            _logger.warning("end_game: g'alaba aniqlashda xato (uid=%s)", uid, exc_info=True)
            _w0 = False
        _won_map[uid] = _w0
        try:
            _tag0 = _special_member_tag(game, uid)
        except Exception:
            _tag0 = ""
        _entry0 = f"{_tag0 + ' ' if _tag0 else ''}{mention(uid, p.get('name') or "O'yinchi")} — <b>{role_portrait(p.get('role') or '—')}</b>"
        (winners if _w0 else losers).append((uid, _entry0))
    winners.sort(key=lambda t: activity.get(t[0], 0), reverse=True)
    losers.sort(key=lambda t: activity.get(t[0], 0), reverse=True)

    lines.append("🏆 <b>G'oliblar:</b>")
    if winners:
        for i, (_uid, e) in enumerate(winners, start=1):
            lines.append(f"{i}. {e}")
    else:
        lines.append("— Yo'q —")
    lines.append("")
    lines.append("💀 <b>Mag'lublar:</b>")
    if losers:
        for i, (_uid, e) in enumerate(losers, start=1):
            lines.append(f"{i}. {e}")
    else:
        lines.append("— Yo'q —")
    if most_active_uid and most_active_uid in game["players"]:
        lines.append(f"\n🏅 Eng faol o'yinchi: {mention(most_active_uid, game['players'][most_active_uid]['name'])}")
    if game.get("started_ts"):
        _mins = max(1, int(round((time.time() - game["started_ts"]) / 60)))
        lines.append(f"\n⏱ O'yin: <b>{_mins} daqiqa</b> davom etdi")
    if game.get("squad_mode") and game.get("squads"):
        wolf_wins = sum(1 for uid, _ in winners if game["squads"].get(uid) == "wolf")
        eagle_wins = sum(1 for uid, _ in winners if game["squads"].get(uid) == "eagle")
        if winners_team == "squad_wolf":
            squad_winner = "🔴 QIZIL"
        elif winners_team == "squad_eagle":
            squad_winner = "🔵 KO'K"
        else:
            squad_winner = "🤝 DURRANG"
        lines.append(
            f"\n🏆 <b>G'OLIB JAMOA: {squad_winner}</b>\n"
            f"🔴 Qizil: {wolf_wins} g'olib · 🔵 Ko'k: {eagle_wins} g'olib"
        )
        for side, emblem, label in (("wolf","🔴","Qizil"),("eagle","🔵","Ko'k")):
            members=[mention(uid, game["players"][uid]["name"]) for uid in game["players"] if game["squads"].get(uid)==side]
            if members:
                lines.append(f"{emblem} <b>{label}:</b> " + ", ".join(members))
    # 📨 Natija guruhga DARHOL yuboriladi (mukofot/DM ishlari uzoq cho'zilsa ham, xato bersa ham yo'qolmaydi)
    _send_result_robust(chat_id, "\n".join(lines))
    winners, losers = [], []   # quyidagi sikl o'z natijasini qayta yig'adi (Theron tabrigi uchun)

    for uid, p in game["players"].items():
        try:
            left = p.get("left_game", False)
            if winners_team == "couple":
                won = (uid in couple_pair) and not left
            elif winners_team == "couple_draw":
                won = False
            elif winners_team == "squad_draw":
                won = False
            elif winners_team in ("squad_wolf", "squad_eagle"):
                winner_squad = "wolf" if winners_team == "squad_wolf" else "eagle"
                won = (game.get("squads", {}).get(uid) == winner_squad) and not left and p["alive"]
            else:
                won = _role_won(game, uid, p, winners_team) and not left
            won = _won_map.get(uid, won)
            base_reward = WIN_REWARD if won else LOSE_REWARD
            reward = 0 if left else int(base_reward * luck_mult(uid) * _newbie_mult(uid))
            if reward:
                add_balance(uid, dollar=reward)
            _sub_bonus = 0
            if not left and CHANNEL_SUB_BONUS > 0 and is_channel_subscriber(uid):
                _sub_bonus = int(CHANNEL_SUB_BONUS)
                add_balance(uid, dollar=_sub_bonus)
                safe_send(uid, f"📣 Kanalga obuna bo'lganingiz uchun qo'shimcha <b>+{_sub_bonus}$</b> oldingiz!")
            u = user_dict(uid)
            update_user(uid, games=u["games"] + 1, wins=u["wins"] + (1 if won else 0))
            try:
                _retention_after_game(uid, u, won, left, draw=(winners_team == "squad_draw"))
            except Exception:
                _logger.warning("retention bonus xatosi (uid=%s)", uid, exc_info=True)
            if not left:
                record_role_result(uid, p.get("role"), won)
                _hunter_world_game_result(uid, won, p.get("role"), chat_id)   # 🪪 v9: rol bo'yicha statistika
            died_in_game = (not p["alive"]) and not left and not won
            _tag = _special_member_tag(game, uid)
            _tag_prefix = f"{_tag} " if _tag else ""
            entry = f"{_tag_prefix}{mention(uid, p['name'])} — <b>{role_portrait(p['role'])}</b>"
            (winners if won else losers).append((uid, entry))  # 🔧 (uid, matn) — pastda aktivlikka qarab tartiblanadi
            # 🔧 TUZATILDI: guruhga yuboriladigan xabarda endi PUL VA BALL miqdorlari
            # KO'RSATILMAYDI (faqat ism+rol) — bularning barchasi FAQAT shaxsiy DM'da
            # ko'rsatiladi (pastdagi safe_send(uid, ...) qismida, o'zgarishsiz qoladi).

            # 🏅 Faollik ballari: g'alaba +5, mag'lubiyat -5, eng faol o'yinchi qo'shimcha +25,
            # tark etgan/AFK bo'lganlar allaqachon -10 olgan (start_night/cmd_tark_et'da)
            points_note = ""
            pts_val = 0  # 🏁 v8: yakuniy profil kartasi uchun bu o'yindagi jami ball o'zgarishi
            if not left:
                pts = 5 if won else -5
                add_points(uid, pts, "game_result")
                pts_val += pts
                points_note = f" ({'+'if pts >= 0 else ''}{pts} ball)"
            if uid == most_active_uid and not left:
                add_points(uid, 25, "most_active")
                pts_val += 25
                points_note += " (+25 ball — eng faol o'yinchi)"
            game["_gp"] = game.get("_gp", 0) + max(0, pts_val)   # 🏘 guruh ball statistikasi uchun

            # 🃏 v10: o'yin natijasiga qarab tasodifiy noyob xarakter kartasi tushishi mumkin
            if not left:
                _v10_card = v10_maybe_drop_card(uid, p.get("role"), won, is_mvp=(uid == most_active_uid))
                if _v10_card:
                    safe_send(uid, f"🃏 <b>Noyob karta topdingiz!</b>\n{_v10_card}\n\n/kartalarim orqali to'plamingizni ko'ring.")

            # 📬 Har bir o'yinchiga shaxsiy yakuniy xabar — yutilgan/yechilgan pul VA ball
            # shu yerda ko'rsatiladi. LOSE_REWARD manfiy bo'lsa, mag'lubiyat uchun pul
            # berilmaydi — AKSINCHA, balansdan yechiladi, shuning uchun matn ham shunga
            # mos ("+N$" emas, "-N$ yechildi") ko'rsatiladi.
            _lose_money_line = (f"+{reward}$ (ishtirok uchun) oldingiz" if reward >= 0
                                 else f"{reward}$ balansingizdan yechildi")
            if left:
                outcome_line = "🚪 Siz o'yinni tark etgansiz — shu sabab bu o'yin uchun <b>mag'lub</b> hisoblanasiz va mukofot berilmaydi."
            elif won:
                outcome_line = f"🎉 <b>G'alaba qozondingiz!</b> +{reward}$ mukofot oldingiz{points_note}."
            elif died_in_game:
                outcome_line = (f"😔 <b>Mag'lub bo'ldingiz.</b> Jamoangiz g'alaba qozongan bo'lsa-da, siz o'yin davomida "
                                 f"halok bo'lganingiz sababli g'olib hisoblanmaysiz. {_lose_money_line}{points_note}.") \
                    if p["team"] == winners_team else \
                    f"😔 <b>Mag'lub bo'ldingiz.</b> {_lose_money_line}{points_note}."
            else:
                outcome_line = f"😔 <b>Mag'lub bo'ldingiz.</b> {_lose_money_line}{points_note}."
            # 🏁 v8: oddiy matn o'rniga rangli tugmali, yutuqli PROFIL KARTASI yuboriladi
            if not send_game_end_card(uid, p.get("role", ""), won, left, reward, pts_val,
                                      draw=(winners_team == "squad_draw")):
                safe_send(uid, f"🏁 O'yin tugadi!\n{outcome_line}")
        except Exception:
            _logger.warning("end_game: o'yinchi (uid=%s) natijasini yakunlashda xatolik", uid, exc_info=True)
            if uid not in {_w[0] for _w in winners} and uid not in {_l[0] for _l in losers}:
                (winners if (p.get('team') == winners_team and p.get('alive') and not p.get('left_game')) else losers).append(
                    (uid, f"{mention(uid, p['name'])} — <b>{role_portrait(p['role'])}</b>"))

    winners.sort(key=lambda t: activity.get(t[0], 0), reverse=True)
    losers.sort(key=lambda t: activity.get(t[0], 0), reverse=True)
    record_group_game(chat_id, game.pop("_gp", 0))

    # 🧠 Theron AI — g'oliblarni shaxsan tabriklaydi
    if winners_team == "squad_wolf":
        team_label = "🔴 Qizil jamoa"
    elif winners_team == "squad_eagle":
        team_label = "🔵 Ko'k jamoa"
    elif winners_team == "couple":
        team_label = "💍 G'olib juftlik"
    elif winners_team == "couple_draw":
        team_label = "💍 Para durrang"
    else:
        team_label = {"mafia": "Mafia", "town": "Shahar", "killers": "Yakka qotillar",
                      "joker": "Joker", "suidsid": "Suidsid"}.get(winners_team, "Shahar")
    winner_first_names = [game["players"][u]["name"] for u, _ in winners if u in game["players"]]
    # (o'yin oxiridagi "g'alaba sizniki!" tabrigi olib tashlandi)

    try:
        pair = add_pair_score(chat_id, winning_chat_id=chat_id)
    except Exception:
        _logger.warning("add_pair_score xatosi", exc_info=True)
        pair = None
    if pair:
        ca, cb, label_a, label_b, score_a, score_b = pair
        scoreboard = (
            f"🔴🔵 <b>Qizil vs Ko'k — umumiy hisob</b>\n\n"
            f"{label_a}: <b>{score_a}</b> g'alaba\n"
            f"{label_b}: <b>{score_b}</b> g'alaba"
        )
        other_id = cb if ca == chat_id else ca
        bot.send_message(chat_id, scoreboard)
        try:
            bot.send_message(other_id, scoreboard)
        except Exception:
            pass

    # (o'yin oxiridagi "afsona" xabari ("Yoqdi" tugmali) olib tashlandi)

    GAMES.pop(chat_id, None)
    save_games_state()

    # 🏛 Klan tizimi: klan lideri bo'lgan o'yinchilar har o'ynagan Hunter Mafia
    # o'yinidan keyin avtomatik +2 lvl oladi (klan spetsifikatsiyasi bo'yicha)
    for uid in game["players"]:
        clan = get_clan(uid)
        if clan:
            with db_lock:
                cur.execute("UPDATE clans SET leader_level = leader_level + 2 WHERE owner_id=?", (uid,))
                conn.commit()


