def parse_amount(message, default):
    for p in message.text.split()[1:]:
        if p.isdigit():
            return int(p)
    return default


def do_gift(message, currency, default_amount, joke_list):
    if not message.reply_to_message:
        return
    target, sender = message.reply_to_message.from_user, message.from_user
    if target.id == sender.id:
        return
    amount = parse_amount(message, default_amount)
    if amount <= 0 or getattr(target, "is_bot", False) or is_banned(sender.id):
        return
    user_dict(sender.id, sender.first_name)
    user_dict(target.id, target.first_name or "O'yinchi")
    # 🔒 ATOMIK: balansni tekshirish + yechish bitta UPDATE'da (avval tekshiruv va yechish alohida edi —
    # parallel /give'lar bilan pul "ko'paytirish" mumkin edi). Sovg'a "topilgan daromad" jurnaliga kirmaydi.
    if not try_charge(sender.id, currency, amount):
        bot.send_message(message.chat.id, f"❌ Sizda yetarli {currency} yo'q.")
        return
    add_balance_as('transfer', target.id, ledger=False, **{currency: amount})
    icon = {"dollar": "💵", "diamond": "💎", "coin": "🪙"}[currency]
    bot.send_message(
        message.chat.id,
        f"{mention(sender.id, sender.first_name)} → {mention(target.id, target.first_name)}: {icon} {amount}",
    )
    # 📩 Qabul qiluvchiga shaxsiy xabar (agar botni ishga tushirgan bo'lsa)
