def _group_lang(chat_id):
    try:
        lg = str(get_setting(f"grp_lang_{chat_id}") or "").lower()
    except Exception:
        lg = ""
    return lg if lg in V3 else "uz"


def _group_lang_kb(chat_id, lg):
    kb = types.InlineKeyboardMarkup()
    kb.row(types.InlineKeyboardButton("🌐 " + v3t(lg, "lang") + " / Language", callback_data=f"glang|menu|{chat_id}"),
           types.InlineKeyboardButton("❓ " + v3t(lg, "help"), callback_data="glang|help|0"))
    return kb


def _send_group_welcome(chat_id, is_admin=False):
    """👋 Bot guruhga qo'shilganda: True Mafia uslubidagi salom + til/yordam tugmalari."""
    lg = _group_lang(chat_id)
    if is_admin:
        text = "✅ " + v3t(lg, "g_ok")
    else:
        perms = "\n".join("✅ " + x for x in v3t(lg, "g_perms").split("|"))
        text = f"{v3t(lg, 'g_hello')}\n\n{perms}"
    try:
        bot.send_message(chat_id, text, reply_markup=_group_lang_kb(chat_id, lg))
    except Exception:
        _logger.warning("guruh salomi yuborilmadi", exc_info=True)


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("glang|"))
def cb_group_lang(call):
    parts = call.data.split("|")
    act = parts[1]
    chat_id = call.message.chat.id
    lg = _group_lang(chat_id)
    if act == "help":
        bot.answer_callback_query(call.id, "/game · /para · /duel · /roles", show_alert=True)
        return
    # faqat admin tilni o'zgartira oladi
    try:
        st = bot.get_chat_member(chat_id, call.from_user.id).status
    except Exception:
        st = "member"
    if st not in ("administrator", "creator") and not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Admin", show_alert=True)
        return
    if act == "menu":
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.add(*[types.InlineKeyboardButton(lbl, callback_data=f"glang|set|{code}") for code, lbl in LANG_LIST])
        try:
            bot.edit_message_text("🌐 Til / Language", chat_id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
    elif act == "set" and parts[2] in V3:
        set_setting(f"grp_lang_{chat_id}", parts[2])
        lg = parts[2]
        try:
            bot.edit_message_text("✅ " + v3t(lg, "langset"), chat_id, call.message.message_id,
                                  reply_markup=_group_lang_kb(chat_id, lg))
        except Exception:
            pass
    bot.answer_callback_query(call.id)


@bot.my_chat_member_handler()
def handle_my_chat_member(update: types.ChatMemberUpdated):
    me = bot.get_me()
    if update.new_chat_member.user.id != me.id:
        return
    chat = update.chat
    old_status, new_status = update.old_chat_member.status, update.new_chat_member.status
    adder = update.from_user

    if new_status in ("member", "administrator") and old_status in ("left", "kicked"):
        add_known_group(chat.id, chat.title or "Nomsiz guruh")
        _send_group_welcome(chat.id, new_status == "administrator")
        if OWNER_ID:
            adder_info = esc(adder.first_name) + (f" (@{esc(adder.username)})" if adder.username else "")
            # 🔗 Egasi shu guruhga bir bosishda kira olishi uchun taklif havolasi
            invite_line = ""
            try:
                inv = bot.create_chat_invite_link(chat.id, name="Owner kirish", member_limit=1)
                invite_line = f"\n\n🔗 <a href=\"{inv.invite_link}\">Guruhga kirish</a>"
            except Exception as e:
                _logger.warning("Yangi guruh uchun taklif havolasi yaratilmadi (%s): %s", chat.id, e)
            kb = types.InlineKeyboardMarkup()
            kb.add(
                types.InlineKeyboardButton("✅ Qabul qilish", callback_data=f"grp|accept|{chat.id}"),
                types.InlineKeyboardButton("❌ Rad etish", callback_data=f"grp|reject|{chat.id}"),
            )
            try:
                bot.send_message(
                    OWNER_ID,
                    f"🆕 <b>Bot yangi guruhga qo'shildi!</b>\n\n"
                    f"📛 Nomi: {chat.title}\n🆔 ID: <code>{chat.id}</code>\n👤 Qo'shgan: {adder_info}"
                    f"{invite_line}",
                    reply_markup=kb,
                    disable_web_page_preview=True,
                )
            except Exception:
                pass
    elif new_status == "administrator" and old_status == "member":
        try:
            lg = _group_lang(chat.id)
            bot.send_message(chat.id, "✅ " + v3t(lg, "g_ok"))
        except Exception:
            pass
    elif new_status in ("left", "kicked"):
        remove_known_group(chat.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("grp|"))
def cb_group_decision(call):
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.")
        return
    _, action, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    if action == "accept":
        bot.answer_callback_query(call.id, "✅ Qabul qilindi.")
        try:
            bot.edit_message_text(f"✅ Guruh qabul qilindi (ID: {chat_id}).", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        try:
            bot.send_message(chat_id, "🎉 Salom! Men Hunter Mafia botiman. /NewGame buyrug'i bilan o'yin boshlashingiz mumkin.")
        except Exception:
            pass
    else:
        bot.answer_callback_query(call.id, "❌ Rad etildi.")
        try:
            bot.edit_message_text(f"❌ Guruh rad etildi (ID: {chat_id}). Bot chiqib ketmoqda.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        try:
            bot.leave_chat(chat_id)
        except Exception:
            pass
        remove_known_group(chat_id)


