    """📜 O'z geroy mahorati tarixini ko'rish. Bot egasi kimningdir xabariga
    reply qilib yuborsa — o'sha foydalanuvchining tarixi ko'rsatiladi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    display_name = message.from_user.first_name or "Siz"
    if message.reply_to_message and is_owner(uid):
        target = message.reply_to_message.from_user
        uid = target.id
        display_name = target.first_name or "Foydalanuvchi"
    bot.send_message(message.chat.id, build_hero_history_text(uid, display_name))


