def hero_attack_range(level):
    """Daraja bo'yicha zarba kuchi (jonning %): 1-darajada 37–44%, 30-darajada 100% (bir zarba)."""
    lv = max(1, min(HERO_MAX_LEVEL, int(level)))
    lo = round(37 + (lv - 1) * 63 / (HERO_MAX_LEVEL - 1))
    hi = round(44 + (lv - 1) * 56 / (HERO_MAX_LEVEL - 1))
    return min(100, lo), min(100, hi)


def hero_zaryad(uid):
    v = get_charges(uid).get("hero_zaryad")
    return HERO_ZARYAD_MAX if v is None else max(0, int(v))


def hero_is_named(uid):
    return bool(get_charges(uid).get("hero_name"))


def hero_rename_price(uid):
    """Birinchi nom berish BEPUL; keyingi o'zgartirishlar — narxi bo'yicha."""
    return 0 if not hero_is_named(uid) else hero_price("soya", "rename_dollar")


def hero_display_name(uid):
    nm = get_charges(uid).get("hero_name")
    return str(nm) if nm else user_dict(uid).get("name") or "Geroy"


def hero_is_aggressive(role):
    """Kunduzi hujum tugmasi faqat hujumkor rollarga: mafiya jamoasi, yakka rollar, qotillar, Komissar."""
    if not role:
        return False
    try:
        if team_of(role) in ("mafia", "independent"):
            return True
    except Exception:
        pass
    return role in (R_KOM, R_GAZ)


def build_hero_panel(uid):
    """🥷 Geroy kartochkasi: (matn, tugmalar, rasm_yoli)."""
    hero = get_hero(uid)
    if not hero:
        price = hero_price("soya", "buy_diamond")
        h = HEROES["soya"]
        lines = [
            "🥷 <b>Sizda hali geroy yo'q</b>", "",
            f"<b>{h['name']}</b>", f"<i>{h['desc']}</i>", "",
            "• ☀️ Kunduzi dushmanning jonidan foiz olasiz yoki himoyalanasiz",
            "• 1–30 daraja: har daraja zarbani kuchaytiradi",
            "• 🔋 10 ta zaryad (tugasa 💵 bilan to'ldiriladi)", "",
            f"💰 Narxi: <b>{price} 💎</b> — Olmos do'konida.",
        ]
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton(f"🛒 Do'kondan olish — {price} 💎", callback_data="shopitem|diamond|geroy"))
        return "\n".join(lines), kb, None

    level = hero["level"]
    lo, hi = hero_attack_range(level)
    cost = hero_level_up_cost(level, hero["key"])
    zr = hero_zaryad(uid)
    lines = [
        f"🥷 <b>Geroy: {esc(hero_display_name(uid))}</b>", "",
        f"⭐ Daraja: <b>{level}</b>/{HERO_MAX_LEVEL}",
        f"👊 Kuch: <b>{lo}-{hi}</b> oralig'ida" if lo != hi else f"👊 Kuch: <b>{lo}</b> (bir zarbada yo'q qiladi)",
        f"🔋 Zaryad miqdori: <b>{zr}</b>/{HERO_ZARYAD_MAX}",
    ]
    if hero.get("temp_until"):
        qolgan_soat = max(0, int((hero["temp_until"] - time.time()) // 3600))
        lines.append(f"⏳ Vaqtinchalik geroy — taxminan {qolgan_soat} soatdan keyin tugaydi")
    if cost is not None:
        nlo, nhi = hero_attack_range(level + 1)
        lines += ["", f"⏫ Keyingi daraja = {level + 1} → kuch {nlo}-{nhi}% ({cost} 💎)"]
    else:
        lines += ["", "🌟 Geroyingiz eng yuqori darajada!"]
    lines += [
        "", "🛒 <b>Xaridlar uchun:</b>",
        f"➕ Daraja ko'tarish = 💎 {cost if cost is not None else '—'}",
        f"🔋 Qurolni zaryadlash = 💵 {hero_price('soya', 'charge_dollar')}",
        f"🖊 Geroy nomini o'zgartirish = 💵 {hero_price('soya', 'rename_dollar')}" if hero_is_named(uid) else "🖊 Geroyingizga hali nom bermadingiz — birinchi nom BEPUL!",
        "", "☀️ <i>Har kuni shaxsiy chatga tugmalar keladi: 🛡 Himoyalanish yoki ⚔️ Hujum (hujumkor rollarga, kuniga 1 marta).</i>",
    ]
    kb = types.InlineKeyboardMarkup()
    if cost is not None:
        kb.add(types.InlineKeyboardButton(f"➕ Daraja ko'tarish ({cost} 💎)", callback_data=f"herolvl|{uid}"))
    kb.add(types.InlineKeyboardButton("🔋 Qurolni zaryadlash", callback_data=f"herochg|{uid}"))
    kb.add(types.InlineKeyboardButton("🖊 Ismni o'zgartirish" if hero_is_named(uid) else "🖊 Geroyga nom berish (bepul)", callback_data=f"heroname|{uid}"))
    kb.add(types.InlineKeyboardButton("🏆 Darajalar ro'yxati", callback_data=f"herolist|{uid}"))
    return "\n".join(lines), kb, hero_image_path(hero["key"])


def show_hero_panel(chat_id, uid, call=None):
    text, kb, image_path = build_hero_panel(uid)
    kb = with_back_button(kb)
    if image_path:
        try:
            with open(image_path, "rb") as photo:
                if call:
                    try:
                        bot.delete_message(call.message.chat.id, call.message.message_id)
                    except Exception:
                        pass
                bot.send_photo(chat_id, photo, caption=text, reply_markup=kb)
            return
        except Exception:
            pass
    if call:
        smart_render(call, text, kb)
    else:
        bot.send_message(chat_id, text, reply_markup=kb)


