@bot.message_handler(commands=["gif"])
def cmd_scene_gif(message):
    """🎞 OWNER: tun/kun e'lonlariga GIF o'rnatish.
    /gif — holat · GIFga reply qilib: /gif tun yoki /gif kun · /gif ochir tun|kun"""
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    parts = (message.text or "").split()[1:]
    names = {"tun": "night", "kun": "day"}
    label = {"night": "🌙 Tun", "day": "☀️ Kun"}
    if not parts:
        lines = ["🎞 <b>Tun/kun GIF holati</b>"]
        for k in ("night", "day"):
            g = _scene_gif_get(k)
            lines.append(f"{label[k]}: " + ("✅ o'rnatilgan" if g else "— (oddiy rasm ishlatiladi)"))
        lines.append("\n<b>O'rnatish:</b> GIFni shu botga yuboring, so'ng GIFga reply qilib <code>/gif tun</code> yoki <code>/gif kun</code> deb yozing."
                     "\n<b>O'chirish:</b> <code>/gif ochir tun</code> yoki <code>/gif ochir kun</code>")
        bot.send_message(message.chat.id, "\n".join(lines))
        return
    if parts[0].lower() in ("ochir", "o'chir", "off") and len(parts) > 1 and parts[1].lower() in names:
        k = names[parts[1].lower()]
        set_setting(f"scene_gif_{k}", "")
        bot.send_message(message.chat.id, f"🗑 {label[k]} GIF o'chirildi — endi oddiy rasm ishlatiladi.")
        return
    if parts[0].lower() not in names:
        bot.send_message(message.chat.id, "❌ Format: <code>/gif tun</code> yoki <code>/gif kun</code> (GIFga reply qilib).")
        return
    k = names[parts[0].lower()]
    r = message.reply_to_message
    fid = None
    if r is not None:
        if getattr(r, "animation", None):
            fid = r.animation.file_id
        elif getattr(r, "video", None):
            fid = r.video.file_id
        elif getattr(r, "document", None) and (getattr(r.document, "mime_type", "") or "").startswith(("video/", "image/gif")):
            fid = r.document.file_id
    if not fid:
        bot.send_message(message.chat.id, "❌ Avval GIF (yoki qisqa video) yuboring, so'ng UNGA reply qilib yozing: "
                                          f"<code>/gif {parts[0].lower()}</code>")
        return
    set_setting(f"scene_gif_{k}", fid)
    try:
        bot.send_animation(message.chat.id, fid, caption=f"✅ {label[k]} GIF o'rnatildi. Keyingi o'yindan boshlab shu ko'rinadi.")
    except Exception:
        bot.send_message(message.chat.id, f"✅ {label[k]} GIF saqlandi.")


@bot.message_handler(commands=["geroy_narx"])
def cmd_geroy_narx(message):
    """💰 FAQAT bot egasi — geroy narxlarini ko'rish/o'zgartirish.
    /geroy_narx  — hozirgi narxlar
    /geroy_narx <lv2_diamond|charge_dollar|rename_dollar> <son>"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = (message.text or "").split()
    if len(parts) == 3:
        item, val = parts[1].lower(), parts[2]
        if item not in ("lv2_diamond", "charge_dollar", "rename_dollar") or not val.isdigit() or int(val) < 1:
            bot.send_message(message.chat.id, "❌ Foydalanish: <code>/geroy_narx lv2_diamond 5</code>\n(lv2_diamond, charge_dollar, rename_dollar)")
            return
        _old_hp = hero_price("soya", item)
        set_setting(f"hero_price_oddiy_{item}", int(val))
        oc_log_external(message.from_user.id, f"hero:oddiy:{item}", f"hero narx {item}", _old_hp, int(val), "legacy-command")
    lines = ["💰 <b>Geroy narxlari</b>", "",
             f"• sotib olish: {hero_price('soya', 'buy_diamond')} 💎 (Olmos do'koni narxi)",
             f"• 2-daraja: {hero_price('soya', 'lv2_diamond')} 💎 (keyingilari {int(HERO_LVL_STEP*100)}% dan oshib boradi)",
             f"• 30-daraja: {hero_price('soya', 'lv30_diamond')} 💎",
             f"• zaryadlash: {hero_price('soya', 'charge_dollar')} 💵",
             f"• nomni o'zgartirish: {hero_price('soya', 'rename_dollar')} 💵", "",
             "O'zgartirish: <code>/geroy_narx lv2_diamond 5</code>"]
    bot.send_message(message.chat.id, "\n".join(lines))


@bot.callback_query_handler(func=lambda c: c.data.startswith("herolvl|"))
@hero_safe("cb_hero_level_up (herolvl|)")
def cb_hero_level_up(call):
    maybe_capture_owner(call.from_user)
    _, owner_id_s = call.data.split("|")
    owner_id = int(owner_id_s)
    uid = call.from_user.id
    if uid != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning geroyingiz emas.", show_alert=True)
        return
    hero = get_hero(uid)
    if not hero:
        bot.answer_callback_query(call.id, "❌ Sizda geroy yo'q.", show_alert=True)
        return
    cost = hero_level_up_cost(hero["level"], hero["key"])
    if cost is None:
        bot.answer_callback_query(call.id, "🌟 Geroyingiz allaqachon eng yuqori darajada!", show_alert=True)
        return
    # 🔧 v8: balansni tekshirish + yechish + darajani oshirish BITTA atomik amalda
    # (ikki marta bosilganda ham ikki marta yechilmaydi).
    with db_lock:
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (cost, uid, cost))
        paid = cur.rowcount > 0
        if paid:
            cur.execute("UPDATE heroes SET level=? WHERE user_id=? AND level=?", (hero["level"] + 1, uid, hero["level"]))
            if cur.rowcount == 0:  # daraja shu orada o'zgargan — pulni qaytaramiz
                cur.execute("UPDATE users SET diamond = diamond + ? WHERE user_id=?", (cost, uid))
                paid = False
        conn.commit()
    if not paid:
        bot.answer_callback_query(call.id, f"❌ Yetarli olmos yo'q ({cost} 💎 kerak) yoki daraja allaqachon o'zgargan.", show_alert=True)
        return
    new_level = hero["level"] + 1
    bot.answer_callback_query(call.id, f"🎉 Geroyingiz {new_level}-darajaga ko'tarildi!", show_alert=True)
    try:
        text, kb, _ = build_hero_panel(uid)
        if _msg_has_media(call.message):
            bot.edit_message_caption(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
        else:
            bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        pass


