# ---------------------------------------------------------------- ☀️ KUNDUZGI HARAKATLAR
def hero_day_start(chat_id, game):
    """Kun boshlanganda: har bir tirik geroy egasiga 🛡 / ⚔️ tugmalari yuboriladi."""
    game["hero_day_protected"] = set()
    game["hero_acted_today"] = set()
    day = game.get("day_number", 1)
    for uid, p in list(alive_players(game).items()):
        try:
            hero = get_hero(uid)
            if not hero:
                continue
            zr = hero_zaryad(uid)
            if zr <= 0:
                safe_send(uid, "🥷 Geroyingizning zaryadi tugadi. /geroyim orqali zaryadlang.")
                continue
            last = game.setdefault("hero_last_attack", {}).get(uid, -99)
            can_attack = hero_is_aggressive(p.get("role")) and (day - last) >= HERO_ATTACK_COOLDOWN_DAYS
            kb = types.InlineKeyboardMarkup()
            row = [types.InlineKeyboardButton("🛡 Himoyalanish", callback_data=f"hd|{chat_id}|protect")]
            if can_attack:
                row.append(types.InlineKeyboardButton("⚔️ Hujum qilish", callback_data=f"hd|{chat_id}|attack"))
            kb.row(*row)
            kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"hd|{chat_id}|skip"))
            note = ""
            if hero_is_aggressive(p.get("role")) and not can_attack:
                note = f"\n<i>Hujum {HERO_ATTACK_COOLDOWN_DAYS - (day - last)} kundan keyin tayyor bo'ladi.</i>"
            safe_send(uid, f"🥷 <b>Nima qilamiz?</b>  (🔋 {zr}/{HERO_ZARYAD_MAX}){note}", kb)
        except Exception:
            _logger.warning("hero_day_start xatosi (uid=%s)", uid, exc_info=True)


def _hero_day_guard(call, game, uid):
    if not game or game.get("phase") != "day":
        bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
        return False
    p = game["players"].get(uid)
    if not p or not p.get("alive"):
        bot.answer_callback_query(call.id, "Siz o'yinda emassiz.")
        return False
    if not get_hero(uid):
        bot.answer_callback_query(call.id, "Sizda geroy yo'q.")
        return False
    if uid in game.setdefault("hero_acted_today", set()):
        bot.answer_callback_query(call.id, "Bugun geroy harakatini allaqachon tanlagansiz.", show_alert=True)
        return False
    return True


@bot.callback_query_handler(func=lambda c: c.data.startswith("hd|"))
@fast_callback
def cb_hero_day(call):
    maybe_capture_owner(call.from_user)
    parts = call.data.split("|")
    chat_id, kind = int(parts[1]), parts[2]
    uid = call.from_user.id
    with _glock(chat_id):
        game = GAMES.get(chat_id)
        if not _hero_day_guard(call, game, uid):
            return
        if kind == "skip":
            game["hero_acted_today"].add(uid)
            try:
                bot.edit_message_text("🚫 Bugun geroy harakat qilmaydi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id)
            return
        if hero_zaryad(uid) <= 0:
            bot.answer_callback_query(call.id, "🔋 Zaryad tugagan. /geroyim orqali zaryadlang.", show_alert=True)
            return
        if kind == "protect":
            n = hero_zaryad(uid)
            set_charge_value(uid, "hero_zaryad", n - 1)
            game["hero_acted_today"].add(uid)
            game["hero_day_protected"].add(uid)
            try:
                bot.edit_message_text(f"🛡 Bugun geroy hujumlaridan himoyalandingiz. (🔋 {n - 1}/{HERO_ZARYAD_MAX})",
                                      call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Himoya yoqildi!")
            return
        if kind == "attack":
            p = game["players"][uid]
            day = game.get("day_number", 1)
            last = game.setdefault("hero_last_attack", {}).get(uid, -99)
            if not hero_is_aggressive(p.get("role")) or (day - last) < HERO_ATTACK_COOLDOWN_DAYS:
                bot.answer_callback_query(call.id, "⚔️ Hujum hozir mumkin emas.", show_alert=True)
                return
            kb = types.InlineKeyboardMarkup()
            for tid, tp in alive_players(game).items():
                if tid == uid:
                    continue
                kb.add(types.InlineKeyboardButton(tp["name"], callback_data=f"hd|{chat_id}|hit|{tid}"))
            kb.add(types.InlineKeyboardButton("🚫 Bekor qilish", callback_data=f"hd|{chat_id}|skip"))
            try:
                bot.edit_message_text("⚔️ <b>Kimga hujum qilamiz?</b>", call.message.chat.id, call.message.message_id, reply_markup=kb)
            except Exception:
                pass
            bot.answer_callback_query(call.id)
            return
        if kind == "hit":
            _hero_do_hit(call, game, chat_id, uid, int(parts[3]))
            return
    bot.answer_callback_query(call.id)


def _hero_do_hit(call, game, chat_id, uid, tid):
    p = game["players"][uid]
    day = game.get("day_number", 1)
    last = game.setdefault("hero_last_attack", {}).get(uid, -99)
    t = game["players"].get(tid)
    if (not hero_is_aggressive(p.get("role")) or (day - last) < HERO_ATTACK_COOLDOWN_DAYS
            or not t or not t.get("alive") or tid == uid):
        bot.answer_callback_query(call.id, "⚔️ Hujum hozir mumkin emas.", show_alert=True)
        return
    hero = get_hero(uid)
    n = hero_zaryad(uid)
    set_charge_value(uid, "hero_zaryad", n - 1)
    game["hero_acted_today"].add(uid)
    game["hero_last_attack"][uid] = day
    try:
        log_hero_ability_use(uid, "soya", "⚔️ Kunduzgi hujum")
    except Exception:
        pass
    t_mention = mention(tid, t["name"])
    try:
        bot.edit_message_text("⚔️ Hujum amalga oshirildi.", call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    bot.answer_callback_query(call.id, "Hujum!")
    if tid in game.get("hero_day_protected", set()):
        bot.send_message(chat_id, f"🛡 <b>Geroy hujumi</b> — {t_mention} himoyalanganligi tufayli omon qoldi!")
        safe_send(tid, "🛡 Geroy himoyangiz sizni hujumdan qutqardi!")
        safe_send(uid, "🛡 Nishoningiz himoyalangan edi — hujum o'tmadi.")
        return
    if int(get_charges(tid).get("hero_def", 0) or 0) > 0 and is_item_active(tid, "hero_def") and use_charge(tid, "hero_def"):
        bot.send_message(chat_id, f"🔰 <b>Geroy hujumi</b> — {t_mention} «Geroydan himoya» tufayli omon qoldi!")
        safe_send(tid, "🔰 <b>Geroydan himoya</b> ishladi — hujum o'tmadi!")
        safe_send(uid, "🔰 Nishoningizda «Geroydan himoya» bor edi — hujum o'tmadi.")
        return
    lo, hi = hero_attack_range(hero["level"])
    dmg = random.randint(lo, hi)
    hp = game.setdefault("hero_hp", {}).get(tid, 100)
    hp = max(0, hp - dmg)
    game["hero_hp"][tid] = hp
    if hp > 0:
        bot.send_message(chat_id, f"⚔️ <b>Geroy hujumi!</b> {t_mention} jonining <b>{dmg}%</b>ini yo'qotdi. Qolgan jon: <b>{hp}%</b>")
        safe_send(tid, f"⚔️ Sizga geroy hujum qildi: -{dmg}% jon. Qolgan jon: {hp}%")
        safe_send(uid, f"⚔️ Zarba: -{dmg}%. Nishonda {hp}% jon qoldi.")
        return
    t["alive"] = False
    game.setdefault("death_info", {})[tid] = {"how": "hero", "side": None}
    game.get("votes", {}).pop(tid, None)
    bot.send_message(chat_id, f"💀 <b>Geroy hujumi!</b> {t_mention} halok bo'ldi.\nFosh qilingan roli: <b>{role_portrait(t['role'])}</b>")
    safe_send(uid, "💀 Nishon yo'q qilindi.")
    wait_last_words(chat_id, tid)
    handle_death_side_effects(game, chat_id, tid)


def _hero_cmd_target(message, args):
    """Owner buyruqlari uchun nishon: reply YOKI birinchi argument (user_id / @username).
    Qaytaradi: (target_id, ism, qolgan_argumentlar) yoki (None, None, args)."""
    if message.reply_to_message and message.reply_to_message.from_user:
        t = message.reply_to_message.from_user
        user_dict(t.id, t.first_name)
        return t.id, t.first_name, args
    if args:
        a = args[0]
        tid = int(a) if a.lstrip("-").isdigit() else find_uid_by_username(a)
        if tid:
            user_dict(tid)
            nm = user_dict(tid).get("name") or str(tid)
            return tid, nm, args[1:]
    return None, None, args


def _hero_level_arg(args):
    """Ixtiyoriy daraja argumenti (1..HERO_MAX_LEVEL). Qaytaradi (daraja yoki None, xato_bormi)."""
    if not args:
        return 1, False
    if len(args) == 1 and args[0].isdigit() and 1 <= int(args[0]) <= HERO_MAX_LEVEL:
        return int(args[0]), False
    return None, True


@bot.message_handler(commands=["geroy_ber"])
@hero_safe("cmd_geroy_ber (/geroy_ber)")
def cmd_geroy_ber(message):
    """👑 Faqat bot egasi — geroyni DOIMIYGA beradi.
    /geroy_ber <user_id|@username> [daraja]   yoki   xabariga reply: /geroy_ber [daraja]"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    tid, tname, rest = _hero_cmd_target(message, message.text.split()[1:])
    lvl, bad = _hero_level_arg(rest)
    if not tid or bad:
        bot.send_message(message.chat.id, "Foydalanish:\n<code>/geroy_ber &lt;user_id|@username&gt; [daraja 1-30]</code>\nyoki xabariga reply qilib: <code>/geroy_ber [daraja]</code>")
        return
    with db_lock:
        cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, 'soya', ?, ?, 0)",
                    (tid, lvl, time.time()))
        conn.commit()
    set_charge_value(tid, "hero_zaryad", HERO_ZARYAD_MAX)
    bot.send_message(message.chat.id, f"👑 {mention(tid, tname)}ga <b>{HEROES['soya']['name']}</b> (<b>{lvl}-daraja</b>) DOIMIYGA berildi!")
    safe_send(tid, f"🏆 Bot egasi sizga <b>{HEROES['soya']['name']}</b> ({lvl}-daraja) in'om qildi! /geroyim orqali ko'ring.")
    if not hero_is_named(tid):
        try:
            hero_ask_name(tid)
        except Exception:
            pass


@bot.message_handler(commands=["geroy_vaqtincha"])
@hero_safe("cmd_geroy_vaqtincha (/geroy_vaqtincha)")
def cmd_geroy_vaqtincha(message):
    """👑 Faqat bot egasi — geroyni MUDDATGA beradi, muddat tugagach avtomatik olinadi.
    /geroy_vaqtincha <user_id|@username> <kun> [daraja]   yoki   reply: /geroy_vaqtincha <kun> [daraja]
    Foydalanuvchida DOIMIY geroy bo'lsa — tegilmaydi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    tid, tname, rest = _hero_cmd_target(message, message.text.split()[1:])
    if not tid or not rest or not rest[0].isdigit() or int(rest[0]) <= 0:
        bot.send_message(message.chat.id, "Foydalanish:\n<code>/geroy_vaqtincha &lt;user_id|@username&gt; &lt;kun&gt; [daraja 1-30]</code>\nyoki xabariga reply qilib: <code>/geroy_vaqtincha &lt;kun&gt; [daraja]</code>")
        return
    days = int(rest[0])
    lvl, bad = _hero_level_arg(rest[1:])
    if bad:
        bot.send_message(message.chat.id, "❌ Daraja 1 dan 30 gacha bo'lishi kerak.")
        return
    with db_lock:
        cur.execute("SELECT level, temp_until FROM heroes WHERE user_id=?", (tid,))
        row = cur.fetchone()
    if row and not (row[1] and row[1] > 0):
        bot.send_message(message.chat.id, f"❌ {mention(tid, tname)}da DOIMIY geroy bor (daraja {row[0]}). Vaqtincha berilmadi.")
        return
    base = max(time.time(), row[1]) if row else time.time()     # mavjud vaqtinchalik muddat uzaytiriladi
    until = base + days * 86400
    keep_lvl = max(row[0], lvl) if row else lvl
    with db_lock:
        cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, 'soya', ?, ?, ?)",
                    (tid, keep_lvl, time.time(), until))
        conn.commit()
    set_charge_value(tid, "hero_zaryad", HERO_ZARYAD_MAX)
    tugash = time.strftime("%d.%m.%Y %H:%M", time.localtime(until))
    bot.send_message(message.chat.id, f"👑 {mention(tid, tname)}ga <b>{HEROES['soya']['name']}</b> ({keep_lvl}-daraja) <b>{days} kunga</b> berildi (tugash: {tugash}).")
    safe_send(tid, f"🏆 Bot egasi sizga <b>{HEROES['soya']['name']}</b> geroyini <b>{days} kunga</b> in'om qildi! Muddat: <b>{tugash}</b> gacha. /geroyim")
    if not hero_is_named(tid):
        try:
            hero_ask_name(tid)
        except Exception:
            pass


