# ================================================================================
#  🧪 /geroy_test — Faqat bot egasi uchun AVTOMATIK TEST-REJIM.
#
#  1) STATIK tekshiruv — HEROES lug'ati to'g'ri tuzilganmi (unlock darajalari,
#     base/cap qiymatlari, rasm fayllari).
#  2) DINAMIK tekshiruv — ownerga vaqtincha (xotirada emas, DB'da, lekin test
#     tugagach 100% ASL holatiga tiklanadigan) har bir geroyni 15-darajada
#     "kiydirib", hero_unlocked_abilities() barcha mahoratlarni to'g'ri
#     ochayotganini tekshiradi.
#  3) SOXTA O'YIN — GAMES ichiga vaqtincha, hech qanday real guruh bilan
#     to'qnashmaydigan maxsus chat_id ostida yasama o'yin qo'shib, "faol o'yin"
#     gate-mantig'i (/geroy_koz, /geroy_daromad va h.k. tekshiruvi) to'g'ri
#     ishlayotganini tekshiradi.
#
#  MUHIM: test davomida real balans o'zgartirilmaydi, real guruhga xabar
#  yuborilmaydi — faqat owner'ning shaxsiy chatiga natija chiqadi.
# ================================================================================

@bot.message_handler(commands=["geroy_test"])
@hero_safe("cmd_geroy_test (/geroy_test)")
def cmd_geroy_test(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    owner_id = message.from_user.id
    if not is_owner(owner_id):
        return
    run_hero_test(owner_id, message.chat.id)


def run_hero_test(owner_id, reply_chat_id):
    """🧪 /geroy_test buyrug'i VA ⚙️ Admin paneldagi '🧪 Geroy test-rejimi' tugmasi
    UCHUN UMUMIY funksiya — natija `reply_chat_id`ga yuboriladi."""
    bot.send_message(reply_chat_id, "🧪 Geroy test-rejimi boshlandi, biroz kuting...")

    results = []  # [(ok: bool, matn)]

    # --- 1) STATIK TEKSHIRUV ---
    for hero_key, hero_data in HEROES.items():
        try:
            abilities = hero_data.get("abilities", [])
            unlocks = [a["unlock"] for a in abilities]
            problem = None
            if unlocks != sorted(unlocks):
                problem = "unlock darajalari o'sish tartibida emas"
            for ab in abilities:
                if not (1 <= ab["unlock"] <= HERO_MAX_LEVEL):
                    problem = f"'{ab['name']}' uchun unlock darajasi chegaradan tashqarida"
                if "base" in ab and "cap" in ab and ab["cap"] < ab["base"]:
                    problem = f"'{ab['name']}' uchun cap < base"
            img_note = "✅ rasm topildi" if hero_image_path(hero_key) else "ℹ️ rasm fayli topilmadi (ixtiyoriy)"
            if problem:
                results.append((False, f"❌ {hero_data['name']}: {problem}"))
            else:
                results.append((True, f"✅ {hero_data['name']} — {len(abilities)} ta mahorat, {img_note}"))
        except Exception as e:
            results.append((False, f"❌ {hero_key} (statik): {e}"))
            log_hero_error(f"geroy_test/static/{hero_key}", e)

    # --- 2) DINAMIK TEKSHIRUV (owner geroyi vaqtincha, xavfsiz tiklash bilan) ---
    with db_lock:
        cur.execute("SELECT hero_key, level, acquired_at, temp_until FROM heroes WHERE user_id=?", (owner_id,))
        _backup_row = cur.fetchone()
    try:
        for hero_key, hero_data in HEROES.items():
            try:
                with db_lock:
                    cur.execute(
                        "INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, ?, ?, ?, 0)",
                        (owner_id, hero_key, HERO_MAX_LEVEL, time.time()),
                    )
                    conn.commit()
                unlocked = hero_unlocked_abilities(owner_id)
                expected = len(hero_data.get("abilities", []))
                if len(unlocked) != expected or not all(a["unlocked"] for a in unlocked):
                    results.append((False, f"❌ {hero_data['name']} (dinamik): {HERO_MAX_LEVEL}-darajada hamma mahorat ochilishi kerak edi"))
                else:
                    results.append((True, f"✅ {hero_data['name']} (dinamik): {expected} mahorat {HERO_MAX_LEVEL}-darajada to'g'ri ochildi"))
            except Exception as e:
                results.append((False, f"❌ {hero_data['name']} (dinamik): {e}"))
                log_hero_error(f"geroy_test/dynamic/{hero_key}", e)
    finally:
        # ♻️ Ownerning ASL geroyi (yoki geroysizligi) har doim tiklanadi
        with db_lock:
            if _backup_row:
                cur.execute(
                    "INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, ?, ?, ?, ?)",
                    (owner_id, *_backup_row),
                )
            else:
                cur.execute("DELETE FROM heroes WHERE user_id=?", (owner_id,))
            conn.commit()

    # --- 3) SOXTA O'YIN (faol o'yin gate-mantig'ini tekshirish) ---
    test_chat_id = -(10 ** 15) - owner_id  # ⚠️ haqiqiy guruh chat_id bilan HECH QACHON to'qnashmaydi
    GAMES[test_chat_id] = {
        "chat_id": test_chat_id, "phase": "night",
        "players": {owner_id: {"alive": True, "role": R_TIN}},
        "responded_tonight": set(),
    }
    try:
        cid, g = _find_active_game_for(owner_id)
        if cid == test_chat_id and g is not None:
            results.append((True, "✅ Soxta o'yin holati to'g'ri aniqlandi (faol o'yin gate ishlayapti)"))
        else:
            results.append((False, "❌ Soxta o'yin holati aniqlanmadi — gate mantig'ida muammo bo'lishi mumkin"))
    except Exception as e:
        results.append((False, f"❌ Soxta o'yin tekshiruvi: {e}"))
        log_hero_error("geroy_test/fake_game", e)
    finally:
        GAMES.pop(test_chat_id, None)

    ok_count = sum(1 for ok, _ in results if ok)
    fail_count = len(results) - ok_count
    header = f"🧪 <b>Geroy test-rejimi yakunlandi</b>\n✅ {ok_count} muvaffaqiyatli, ❌ {fail_count} xatolik\n\n"
    body = "\n".join(text for _, text in results)
    for chunk_start in range(0, len(body), 3500):
        bot.send_message(reply_chat_id, (header if chunk_start == 0 else "") + body[chunk_start:chunk_start + 3500])


