    with db_lock:
        cur.execute("SELECT COUNT(*), COALESCE(SUM(games),0), COALESCE(SUM(wins),0), "
                     "COALESCE(SUM(dollar),0), COALESCE(SUM(diamond),0), COALESCE(SUM(coin),0) FROM users")
        row = cur.fetchone()
