@bot.message_handler(commands=["stop"])
def cmd_stop(message):
    """🛑 Guruhdagi FAOL o'yinni (asosiy/Team/Para — qaysi turi bo'lsa ham) darhol
    to'xtatadi. Avvalgi /stop_team, /stop_para, /oyinni_zorla_tugat o'rniga."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if message.chat.type not in ("group", "supergroup"):
        return
    if not is_authorized(message):
        bot.send_message(message.chat.id, "⛔ Siz admin emassiz.")
        return
    chat_id = message.chat.id
    game = GAMES.get(chat_id)
    if not game:
        bot.send_message(chat_id, "❌ Bu guruhda hozir faol o'yin yo'q.")
        return
    if game.get("squad_mode"):
        label = _special_mode_label("squad")
    elif game.get("couple_mode"):
        label = _special_mode_label("couple")
    else:
        label = "🎮 O'yin"
    for t in game.get("timers", []):
        try:
            t.cancel()
        except Exception:
            pass
    GAMES.pop(chat_id, None)
    save_games_state()
    bot.send_message(chat_id, f"🛑 {label} to'xtatildi. Hech kimga mukofot/jarima berilmadi.")


