def format_active_effects(uid):
    ch = get_charges(uid)
    lines = []

    def add(cond, text):
        if cond:
            lines.append(text)

    add(ch.get("fake_doc", 0) > 0, f"📜 Soxta hujjat: {ch.get('fake_doc', 0)} ta")
    add(ch.get("night_vision", 0) > 0, f"🥽 Tungi ko'zoynak: {ch.get('night_vision', 0)} ta")
    add(ch.get("confuse", 0) > 0, f"✉️ Tushunarsiz xat: {ch.get('confuse', 0)} ta")
    add(ch.get("poison", 0) > 0, f"🧪 Zaharli flakon: {ch.get('poison', 0)} ta")
    add(ch.get("gps", 0) > 0, f"📍 GPS Mayak: {ch.get('gps', 0)} ta")
    add(ch.get("compass", 0) > 0, f"🧭 Sirli kompas: {ch.get('compass', 0)} ta")
    add(ch.get("antidote", 0) > 0, f"🩹 Kichik Aptechka (zaharga qarshi): {ch.get('antidote', 0)} ta")
    add(ch.get("hidden_vote", 0) > 0, f"💼 Shubhali sumka (ovozni yashirish): {ch.get('hidden_vote', 0)} ta")
    add(ch.get("revote", 0) > 0, f"⚡️ Energiya ichimligi (qayta ovoz berish): {ch.get('revote', 0)} ta")
    add(ch.get("smoke_bomb", 0) > 0, f"💣 Tutunli bomba: {ch.get('smoke_bomb', 0)} ta")
    add(ch.get("flash_light", 0) > 0, f"🔦 Katta Fonar: {ch.get('flash_light', 0)} ta")
    add(ch.get("cloak", 0) > 0, f"🧥 Yashirin plash: {ch.get('cloak', 0)} ta")
    add(ch.get("duel_adv", 0) > 0, f"⚔️ Olmos Qilich (duel ustunligi): {ch.get('duel_adv', 0)} ta")
    add(ch.get("golden_bullet", 0) > 0, f"🟡 Oltin o'q: {ch.get('golden_bullet', 0)} ta")
    add(ch.get("radar", 0) > 0, f"📡 Maxfiy radar: {ch.get('radar', 0)} ta")
    add(ch.get("revive", 0) > 0, f"⚡️ Tezkor jonlanish: {ch.get('revive', 0)} ta")
    add(ch.get("watch_eyes", 0) > 0, f"👁 Kuzatish ko'zi: {ch.get('watch_eyes', 0)} ta")
    add(ch.get("day_shield", 0) > 0, f"🛡🌞 Kunduzgi himoya: {ch.get('day_shield', 0)} ta")

    imp_until = ch.get("imperator_until", 0)
    if imp_until and imp_until > time.time():
        rem = int(imp_until - time.time())
        add(True, f"👑 Imperator maqomi: {rem // 3600} soat {(rem % 3600) // 60} daqiqa qoldi")

    elite_until_line = ch.get("vip_until", 0)
    if elite_until_line and elite_until_line > time.time():
        rem_days = int((elite_until_line - time.time()) // 86400)
        add(True, f"👑 HUNTER ELITE: {rem_days} kun qoldi")

    admin_until = ch.get("temp_admin_until", 0)
    if admin_until and admin_until > time.time():
        rem = int(admin_until - time.time())
        add(True, f"⚡️ Vaqtinchalik admin huquqi: {rem // 3600} soat qoldi")

    night_vision_left = ch.get("night_vision", 0)  # (yuqorida "🥽 Tungi ko'zoynak" bilan bir xil hisoblanadi)

    hero = get_hero(uid)
    if hero:
        add(True, f"{hero['name']} — {hero['level']}-lvl (/geroyim)")

    def _rem_days(key):
        until = ch.get(key, 0)
        return int((until - time.time()) // 86400) + 1 if until > time.time() else 0

    ramka_days = _rem_days("ramka_until")
    add(ramka_days > 0, f"🖼 Mifik ramka: {ramka_days} kun qoldi")
    toj_days = _rem_days("toj_until")
    add(toj_days > 0, f"👑 Hukmdor toj: {toj_days} kun qoldi")
    qirol_days = _rem_days("qirol_until")
    add(qirol_days > 0, f"🐉 Hunter Mafia Qiroli unvoni: {qirol_days} kun qoldi")
    dgw = ch.get("duel_guaranteed_win", 0)
    if dgw > 0:
        add(True, f"🗡 Kafolatlangan duel g'alabasi — {dgw} marta qoldi")
    add(ch.get("klan_license", 0) > 0, f"🏛 Klan litsenziyasi: {ch.get('klan_license', 0)} marta ishlatish mumkin")

    bm_days = _rem_days("bonus_mult_until")
    bm = ch.get("bonus_mult_val", 1) if bm_days > 0 else 1
    if bm > 1:
        add(True, f"🎁 Kunlik bonus ko'paytiruvchi: x{bm} ({bm_days} kun qoldi)")
    lm_days = _rem_days("luck_mult_until")
    lm = ch.get("luck_mult_val", 1) if lm_days > 0 else 1
    if lm > 1:
        add(True, f"🦊 Umumiy yutuq ko'paytiruvchi: x{lm} ({lm_days} kun qoldi)")

    if not lines:
        return "Hozircha faol kuchlaringiz yo'q. Do'kondan xarid qiling!"
    return "✨ <b>FAOL KUCHLARINGIZ</b>\n\n" + "\n".join(lines)


# ================================================================================
#  🏁 v8 — O'YIN TUGAGACH SHAXSIY PROFIL KARTASI (yutuqlar bilan)
# ================================================================================
# Har bir o'yin tugagach har bir ishtirokchining shaxsiy chatiga RANGLI tugmali
# profil kartasi yuboriladi: natija (g'alaba/mag'lubiyat/durrang), o'yindagi rol,
# olingan dollar, ball va XP, daraja chizig'i, g'alaba seriyasi, umumiy statistika.
# G'oliblarga Telegramning 🎉 xabar effekti (konfeti) qo'shiladi — agar kutubxona yoki
# Telegram effektni qabul qilmasa, karta effektsiz yuboriladi (xato bermaydi).
#
# Daraja tizimi: XP = g'alaba × 20 + boshqa o'yinlar × 8 (bazadagi games/wins'dan
# hisoblanadi — eski foydalanuvchilarga ham retroaktiv ishlaydi, hech narsa
# yo'qolmaydi). Har 500 XP = 1 daraja.
XP_PER_WIN = 20
XP_PER_LOSS = 8
XP_PER_LEVEL = 500
MSG_EFFECT_WIN = os.environ.get("HUNTER_EFFECT_WIN", "5046509860389126442").strip()  # 🎉 konfeti


def xp_of_user(u):
    wins = int(u.get("wins") or 0)
    games = int(u.get("games") or 0)
    return wins * XP_PER_WIN + max(0, games - wins) * XP_PER_LOSS


def level_progress(xp):
    """(daraja, joriy darajadagi XP) qaytaradi."""
    xp = max(0, int(xp))
    return xp // XP_PER_LEVEL + 1, xp % XP_PER_LEVEL


def xp_bar(cur_xp, total=None, segments=8):
    if total is None:
        total = XP_PER_LEVEL   # 👑 Owner Center o'zgartirgan qiymat darhol hisobga olinadi
    filled = int(round(max(0, cur_xp) / float(total) * segments))
    filled = max(0, min(segments, filled))
    return "▰" * filled + "▱" * (segments - filled)


def _points_summary(uid):
    """(jami ball, ketma-ket g'alaba seriyasi) — points_log jadvalidan."""
    try:
        with db_lock:
            cur.execute("SELECT COALESCE(SUM(points),0) FROM points_log WHERE user_id=?", (uid,))
            total = cur.fetchone()[0] or 0
            cur.execute(
                "SELECT points FROM points_log WHERE user_id=? AND reason='game_result' "
                "ORDER BY ts DESC, rowid DESC LIMIT 50", (uid,))
            rows = [r[0] for r in cur.fetchall()]
    except Exception:
        return 0, 0
    streak = 0
    for pts in rows:
        if pts > 0:
            streak += 1
        else:
            break
    return int(total), streak


def build_game_end_card(uid, role, won, left, reward, pts_delta, draw=False):
    """(matn, klaviatura) — o'yin tugagach yuboriladigan ixcham karta (referens ko'rinishida)."""
    u = user_dict(uid)
    xp_now = xp_of_user(u)
    gain = XP_PER_WIN if won else XP_PER_LOSS
    lvl, _cur_xp = level_progress(xp_now)
    prev_lvl, _ = level_progress(xp_now - gain)
    sign = lambda n: f"+{n}" if n > 0 else str(n)
    if left:
        _res = "🚪 <b>Siz o'yinni tark etdingiz.</b>"
    elif draw:
        _res = "🤝 <b>O'yin durang tugadi.</b>"
    elif won:
        _res = "🏆 <b>Siz yutdingiz!</b>"
    else:
        _res = "💔 <b>Siz yutqazdingiz.</b>"
    head = ["🏁 O'yin tugadi.",
            f"Sizga 💵 {sign(int(reward))}, {sign(int(pts_delta))} 🎯 berildi!"]
    if lvl > prev_lvl:
        head.append(f"🆙 Yangi daraja: <b>{lvl}</b>!")
    if left:
        head.append("🚪 O'yinni tark etganingiz uchun bu o'yin mag'lubiyat hisoblanadi va mukofot berilmaydi.")
    _prof = build_profile_text(uid).split("\n")
    _prof = [_prof[0]] + [re.sub(r"</?b>", "", ln) for ln in _prof[1:]]   # Dark Night: qiymatlar oddiy (qalinsiz)
    text = "\n".join(head) + "\n\n" + "\n".join(_prof)

    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("Do'kon", callback_data="menu|shop"))
    kb.add(types.InlineKeyboardButton("Xarid olish 💵", callback_data="menu|dollarshop"),
           types.InlineKeyboardButton("Xarid olish 💎", callback_data="menu|birja"))
    kb.add(types.InlineKeyboardButton("🎲 Premium guruhlar", callback_data="premium|list"))
    kb.add(types.InlineKeyboardButton("Yangiliklar", callback_data="menu|news"))
    return text, kb


def send_game_end_card(uid, role, won, left, reward, pts_delta, draw=False):
    """Kartani yuboradi. G'olibga 🎉 effekt bilan; effekt ishlamasa — oddiy yuboriladi."""
    try:
        text, kb = build_game_end_card(uid, role, won, left, reward, pts_delta, draw)
    except Exception:
        _logger.exception("Yakuniy karta qurishda xatolik (uid=%s)", uid)
        return False
    if won and not left and MSG_EFFECT_WIN:
        try:
            bot.send_message(uid, text, reply_markup=kb, message_effect_id=MSG_EFFECT_WIN)
            return True
        except Exception:
            pass  # effekt qo'llab-quvvatlanmadi — pastda oddiy yuboriladi
    return safe_send(uid, text, kb)


# Do'kondan olib tashlangan, lekin foydalanuvchilarda zaxirasi qolgan himoyalar (o'yinda ishlashda davom etadi)
LEGACY_CHARGE_LABELS = {
    "zombi_def": "🧟 Zombidan himoya", "afsungar_def": "🔮 Afsungardan himoya", "tuhmat_def": "🐍 Tuhmatdan himoya",
    "blast_def": "💣 Portlashdan himoya", "fire_def": "🔥 Yong'indan himoya", "breaker_def": "💥 Buzg'unchidan himoya",
    "mashuqa_def": "💋 Mashuqadan himoya",
}


# Dark Night uslubi: bu buyumlar sizda 0 ta bo'lsa ham profilda ko'rinib turadi
PROFILE_ALWAYS_ITEMS = [
    ("fake_doc", "📜 Hujjat"),
    ("day_shield", "⚖️ Osishdan himoya qilish"),
    ("killer_def", "🗡 Qotildan himoya"),
    ("rifle", "🔫 Miltiq"),
    ("poison_def", "💊 Doridan himoya"),
    ("verbena_def", "🌿 Verbana"),
    ("mask_def", "🎭 Maska"),
    ("hero_def", "🔰 Geroydan himoya"),
]
# ON/OFF tugmalar tartibi (sizda bo'lmasa ham ko'rinadi)
PROFILE_TOGGLE_ORDER = ["killer_def", "fake_doc", "day_shield", "poison_def", "mask_def", "basic_def", "verbena_def", "hero_def"]


def _profile_item_lines(uid):
    """📦 Profilda buyum zaxiralari: asosiy 7 himoya har doim (0 ham), qolganlari faqat bor bo'lsa."""
    ch = get_charges(uid)

    def _n(ck):
        n = ch.get(ck, 0)
        return int(n) if isinstance(n, (int, float)) and not isinstance(n, bool) and n > 0 else 0

    out, seen = [], set()
    for ck, label in PROFILE_ALWAYS_ITEMS:
        seen.add(ck)
        out.append(f"{label}: <b>{_n(ck)}</b>")
    for _cat, (_title, items) in SHOP_CATEGORIES.items():
        for _k, it in items.items():
            ck = it.get("charge_key")
            if not ck or ck in seen or it.get("mode") not in ("charge", None) and not it.get("perm"):
                continue
            n = _n(ck)
            if n <= 0:
                continue
            seen.add(ck)
            out.append(f"{it['name']}: <b>{n}</b>")
    for ck, label in LEGACY_CHARGE_LABELS.items():
        n = _n(ck)
        if n > 0:
            out.append(f"{label}: <b>{n}</b>")
    return out


def _profile_toggle_rows(uid):
    """🟢 ON / 🔴 OFF tugmalari — buyum sizda bo'lmasa ham ko'rinib turadi (Dark Night kabi)."""
    btns = []
    for key in PROFILE_TOGGLE_ORDER:
        label = TOGGLABLE_ITEMS.get(key)
        if not label:
            continue
        icon = label.split(" ", 1)[0]
        on = is_item_active(uid, key)
        btns.append(types.InlineKeyboardButton(f"{icon} - {'🟢 ON' if on else '🔴 OFF'}", callback_data=f"proftog|{key}"))
    return btns


def build_profile_text(uid, name=None):
    """👤 Profil matni (profil ekrani VA o'yin tugagandagi xabar uchun umumiy)."""
    u = user_dict(uid, name)
    xp = xp_of_user(u)
    lvl, xp_in = level_progress(xp)
    rank = _rank_label(lvl)

    lines = [f"👤 <b><i>{esc(u['name'])}</i></b>"]
    elite_line = elite_status_line(uid)
    if elite_line and "faol emas" not in elite_line:
        lines.append(elite_line)
    _tl = toifa_profile_line(uid) if toifa_get(uid) != "overlord" else ""
    if _tl:
        lines.append(_tl)
    if u.get("bio"):
        lines.append(f"📝 <i>{esc(u['bio'])}</i>")
    lines += [
        "",
        f"💵 Dollar: <b>{u['dollar']}</b>",
        f"💎 Olmos: <b>{u['diamond']}</b>",
        f"🪙 Hunter Coin: <b>{u['coin']}</b>",
    ]
    inv = _profile_item_lines(uid)
    inv.insert(0, f"🛡 Himoya: <b>{u.get('shield') or 0}</b>")
    if inv:
        lines += [""] + inv
    hero = get_hero(uid)
    if hero:
        lines.append(f"🥷 Geroy: <b>{esc(hero_display_name(uid))}</b> · {hero['level']}-daraja")
    lines += [
        "",
        f"🏆 G'alaba: <b>{u['wins']}</b>",
        f"🎲 Barcha o'yinlar: <b>{u['games']}</b>",
    ]
    partner = get_partner_mention(uid)
    if partner:
        lines.append(f"💍 Juft: {partner}")
    badge = clan_badge(uid)
    if badge:
        clan_name, is_leader = badge
        lines.append(f"🏛 Klan: <b>{esc(clan_name)}</b>" + (" 👑" if is_leader else ""))
    try:
        _nr = role_ticket_get(uid)
    except Exception:
        _nr = None
    lines += ["", f"🎭 Faol rollar: <i>{esc(_nr) if _nr else 'Yo‘q'}</i>"]
    return "\n".join(lines)


def show_profile(chat_id, uid, name, call=None):
    """👤 Profil — ixcham, referens (Dark Night Mafia 2) ko'rinishida: balans, buyum zaxirasi,
    G'alaba/O'yinlar, yoqish-o'chirish (ON/OFF) tugmalari va asosiy bo'limlarga tezkor tugmalar."""
    text = build_profile_text(uid, name)

    kb = types.InlineKeyboardMarkup(row_width=2)
    tog = _profile_toggle_rows(uid)
    if tog:
        hidden = bool(get_charges(uid).get("prof_grid_hidden"))
        if not hidden:
            # 3 tadan, oxirgi qator ▲ (yig'ish) tugmasi bilan
            row = []
            for b in tog:
                row.append(b)
                if len(row) == 3:
                    kb.row(*row); row = []
            if row:
                kb.row(*row)
            kb.add(types.InlineKeyboardButton("▲", callback_data="profgrid|hide"))
        else:
            kb.add(types.InlineKeyboardButton("▼", callback_data="profgrid|show"))
    kb.add(types.InlineKeyboardButton("Do'kon", callback_data="menu|shop"))
    kb.add(types.InlineKeyboardButton("Xarid olish 💵", callback_data="menu|dollarshop"),
           types.InlineKeyboardButton("Xarid olish 💎", callback_data="menu|birja"))
    kb.add(types.InlineKeyboardButton("👑 " + v3t(uid, "elite"), callback_data="menu|elite"))
    kb.add(types.InlineKeyboardButton("🎲 Premium guruhlar", callback_data="premium|list"))
    kb.add(types.InlineKeyboardButton("Yangiliklar", callback_data="menu|news"))
    kb = with_back_button(kb)
    if call:
        smart_render(call, text, kb)
    else:
        bot.send_message(chat_id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("proftog|") or c.data.startswith("profgrid|") or c.data.startswith("profmore|"))
@hero_safe("cb_profile_ui (proftog/profgrid/profmore)")
def cb_profile_ui(call):
    maybe_capture_owner(call.from_user)
    uid = call.from_user.id
    kind, arg = call.data.split("|", 1)
    if kind == "proftog":
        if arg not in TOGGLABLE_ITEMS:
            bot.answer_callback_query(call.id)
            return
        new_state = toggle_item_active(uid, arg)
        bot.answer_callback_query(call.id, f"{TOGGLABLE_ITEMS[arg]}: {'yoqildi' if new_state else 'o‘chirildi'}")
        show_profile(call.message.chat.id, uid, call.from_user.first_name, call)
        return
    if kind == "profgrid":
        set_charge_value(uid, "prof_grid_hidden", 1 if arg == "hide" else 0)
        bot.answer_callback_query(call.id)
        show_profile(call.message.chat.id, uid, call.from_user.first_name, call)
        return
    # profmore — qolgan bo'limlar (eski tezkor havolalar, statistika, Mini App)
    if str(uid) != arg:
        bot.answer_callback_query(call.id, "❌ Bu sizning profilingiz emas.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("⬅️ Profilga qaytish", callback_data="menu|cabinet"))
    u = user_dict(uid)
    duel_total = u["duel_wins"] + u["duel_losses"]
    duel_rate = f"{(u['duel_wins'] / duel_total * 100):.1f}%" if duel_total else "0.0%"
    lines = ["⋯ <b>Qo'shimcha</b>", "",
             f"⚔️ Duellar: {duel_total} ta ({u['duel_wins']} g'alaba / {u['duel_losses']} mag'lubiyat, {duel_rate})"]
    fav = favorite_role(uid)
    if fav:
        lines.append(f"🏅 Sevimli rol: <b>{fav}</b>")
    ach = achievements_state(uid)
    lines.append(f"🎖 Yutuqlar: {ach['unlocked']}/{ach['total']}")
    lines += couple_card_lines(uid)
    bot.answer_callback_query(call.id)
    smart_render(call, "\n".join(lines), kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("profrolestats|"))
def cb_profile_role_stats(call):
    maybe_capture_owner(call.from_user)
    try:
        owner_id = int(call.data.split("|")[1])
    except Exception:
        bot.answer_callback_query(call.id)
        return
    if call.from_user.id != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning profilingiz emas.", show_alert=True)
        return
    stats = role_stats_of(owner_id)
    if not stats:
        bot.answer_callback_query(call.id, "📊 Siz hali birorta o'yinni yakunlamagansiz.", show_alert=True)
        return
    lines = ["📊 <b>Rol bo'yicha statistika</b>", ""]
    for r in stats[:15]:
        rate = f"{r['wins'] / r['games'] * 100:.0f}%"
        lines.append(f"{r['role']} — {r['games']} o'yin, {r['wins']} g'alaba ({rate})")
    bot.answer_callback_query(call.id)
    smart_render(call, "\n".join(lines), with_back_button())


