ROLE_LIST = list(ROLES_INFO.items())


def _role_parts(role):
    """'Komissar katani 🕵️' -> ('🕵️', 'Komissar katani')"""
    name, _, emo = role.rpartition(" ")
    return (emo, name) if name else ("", role)


def send_roles_list(chat_id):
    """🎭 Rollar ro'yxati: 2 ustunli tugmalar; tugma bosilsa — rol tavsifi popup oynada chiqadi."""
    kb = types.InlineKeyboardMarkup(row_width=2)
    btns = []
    for i, (role, _d) in enumerate(ROLE_LIST):
        emo, name = _role_parts(role)
        btns.append(types.InlineKeyboardButton(f"{emo} {name}", callback_data=f"rl|{i}"))
    for j in range(0, len(btns), 2):
        kb.row(*btns[j:j + 2])
    bot.send_message(chat_id, f"🎭 <b>Rollar ro'yxati</b> ({len(ROLE_LIST)} ta)\nRolni bosing — tavsifi oynada chiqadi.",
                     reply_markup=with_back_button(kb))


@bot.callback_query_handler(func=lambda c: c.data.startswith("rl|"))
def cb_role_popup(call):
    try:
        role, desc = ROLE_LIST[int(call.data.split("|")[1])]
    except Exception:
        bot.answer_callback_query(call.id)
        return
    emo, name = _role_parts(role)
    bot.answer_callback_query(call.id, f"Siz — {emo} {name}!\n\n{desc}"[:200], show_alert=True)


def with_back_button(kb=None):
    """🔙 Istalgan inline klaviaturaga pastiga "Bosh menyu" tugmasini qo'shadi
    (kb bo'lmasa, yangisini yaratadi) — foydalanuvchi hech qachon biror
    bo'limda "qolib ketmasligi", har doim bitta bosish bilan bosh menyuga
    qaytishi uchun. Barcha menyu ekranlarida shu funksiya ishlatiladi."""
    if kb is None:
        kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("🔙 Bosh menyu", callback_data="menu|main_back"))
    return kb


def smart_render(call, text, reply_markup=None, **kwargs):
    """📱 "Jonli panel": menyu bosilganda YANGI xabar yubormaydi va eski
    xabarni o'chirib-qayta yaratmaydi — ekran JOYIDA (edit_message_text)
    silliq almashadi, xuddi referens botdagi kabi. Faqat texnik jihatdan
    tahrirlab bo'lmasa (masalan eski xabar RASM bo'lsa, yoki xabar juda
    eski/o'chirilgan bo'lsa) — chekinib, eskisini o'chirib yangisini
    yuboradi, shunda foydalanuvchi hech qachon xatolik ko'rmaydi.
    **kwargs — disable_web_page_preview kabi qo'shimcha parametrlarni
    send_message/edit_message_text'ga uzatish uchun."""
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    try:
        bot.edit_message_text(text, chat_id, msg_id, reply_markup=reply_markup, **kwargs)
        return
    except Exception as e:
        if "message is not modified" in str(e).lower():
            try:
                bot.edit_message_reply_markup(chat_id, msg_id, reply_markup=reply_markup)
            except Exception:
                pass
            return
    try:
        bot.delete_message(chat_id, msg_id)
    except Exception:
        pass
    bot.send_message(chat_id, text, reply_markup=reply_markup, **kwargs)


_MENU_MEDIA_SETTING = "menu_media"     # {"kind": "animation"|"photo", "file_id": "..."}
_MENUMEDIA_WAIT = set()                # media kutilayotgan owner ID'lari


def _menu_media():
    """Owner o'rnatgan bosh menyu media'si: (kind, file_id) yoki None (standart rasm)."""
    try:
        d = json.loads(get_setting(_MENU_MEDIA_SETTING) or "{}")
        if isinstance(d, dict) and d.get("file_id") and d.get("kind") in ("animation", "photo"):
            return d["kind"], d["file_id"]
    except Exception:
        pass
    return None


def send_menu_media(chat_id, caption=None, reply_markup=None, **kw):
    """Bosh menyu rasm/GIF'ini yuboradi. Owner GIF o'rnatgan bo'lsa — GIF, aks holda
    standart rasm. GIF yuborilmasa, xavfsiz tarzda standart rasmga qaytadi."""
    # v3: bosh menyu endi GIF/rasmsiz — oddiy matn (True Mafia kabi)
    return bot.send_message(chat_id, caption or "🏠", reply_markup=reply_markup, **kw)


def _msg_has_media(msg):
    """Xabar rasm/GIF/video bo'lsa True (sarlavhasi tahrirlanadi, matni emas)."""
    return bool(getattr(msg, "photo", None) or getattr(msg, "animation", None) or getattr(msg, "video", None))


def smart_render_photo(call, photo, caption, reply_markup=None):
    """📱 smart_render'ning RASMLI/GIF'li ekranlar (masalan bosh menyu) uchun
    varianti — edit_message_media orqali joyida almashtiradi, faqat
    imkonsiz bo'lsagina o'chirib-qayta yuboradi."""
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    custom = _menu_media() if photo == MAIN_PHOTO else None
    try:
        if custom and custom[0] == "animation":
            media = types.InputMediaAnimation(custom[1], caption=caption, parse_mode="HTML")
        else:
            media = types.InputMediaPhoto(custom[1] if custom else photo, caption=caption, parse_mode="HTML")
        bot.edit_message_media(media, chat_id, msg_id, reply_markup=reply_markup)
        return
    except Exception as e:
        if "message is not modified" in str(e).lower():
            try:
                bot.edit_message_reply_markup(chat_id, msg_id, reply_markup=reply_markup)
            except Exception:
                pass
            return
    try:
        bot.delete_message(chat_id, msg_id)
    except Exception:
        pass
    if photo == MAIN_PHOTO:
        send_menu_media(chat_id, caption=caption, reply_markup=reply_markup)
    else:
        bot.send_photo(chat_id, photo, caption=caption, reply_markup=reply_markup)


def _extract_menu_media(msg):
    """Xabardan (GIF/rasm/video/gif-hujjat) (kind, file_id) ni ajratadi."""
    if getattr(msg, "animation", None):
        return "animation", msg.animation.file_id
    if getattr(msg, "photo", None):
        return "photo", msg.photo[-1].file_id
    if getattr(msg, "video", None):
        return "animation", msg.video.file_id
    d = getattr(msg, "document", None)
    if d and (d.mime_type or "") in ("image/gif", "video/mp4"):
        return "animation", d.file_id
    return None


def _apply_menu_media(message, media):
    """Sinov uchun egasiga ko'rsatib, so'ng saqlaydi. Yuborilmasa — saqlanmaydi."""
    kind, fid = media
    try:
        if kind == "animation":
            bot.send_animation(message.chat.id, fid, caption="👀 Bosh menyu ko'rinishi shunday bo'ladi.")
        else:
            bot.send_photo(message.chat.id, fid, caption="👀 Bosh menyu ko'rinishi shunday bo'ladi.")
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ Bu faylni menyuga qo'yib bo'lmadi: <code>{esc(str(e))[:200]}</code>\n"
                                          "GIF'ni Telegramda oddiy GIF/animatsiya sifatida yuboring.")
        return
    set_setting(_MENU_MEDIA_SETTING, json.dumps({"kind": kind, "file_id": fid}))
    bot.send_message(message.chat.id, "✅ Bosh menyu media'si yangilandi. Hamma uchun darhol kuchga kirdi.")


@bot.message_handler(commands=["menyu_media"])
def cmd_menyu_media(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    rep = getattr(message, "reply_to_message", None)
    media = _extract_menu_media(rep) if rep else None
    if media:
        _apply_menu_media(message, media)
        return
    _MENUMEDIA_WAIT.add(message.from_user.id)
    cur_m = _menu_media()
    now = {"animation": "GIF", "photo": "rasm"}.get(cur_m[0]) if cur_m else "standart rasm"
    bot.send_message(message.chat.id, f"🎞 <b>Bosh menyu media'si</b> (hozir: {now})\n\n"
                                      "Yangi <b>GIF</b> (yoki rasm) yuboring.\n"
                                      "Standartga qaytarish: /menyu_media_ol")


@bot.message_handler(commands=["menyu_media_ol"])
def cmd_menyu_media_ol(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    _MENUMEDIA_WAIT.discard(message.from_user.id)
    set_setting(_MENU_MEDIA_SETTING, "")
    bot.send_message(message.chat.id, "♻️ Bosh menyu standart rasmga qaytarildi.")


@bot.message_handler(
    func=lambda m: m.chat.type == "private" and m.from_user and m.from_user.id in _MENUMEDIA_WAIT,
    content_types=["animation", "photo", "video", "document"],
)
def on_menyu_media_upload(message):
    if not is_owner(message.from_user.id):
        return
    media = _extract_menu_media(message)
    if not media:
        bot.send_message(message.chat.id, "❌ GIF, rasm yoki qisqa video yuboring. Bekor qilish: /menyu_media_ol")
        return
    _MENUMEDIA_WAIT.discard(message.from_user.id)
    _apply_menu_media(message, media)


# ================================================================================
#  👑 TOIFALAR (maxsus maqomlar): OVERLORD > HUNTER A'ZOSI > GURUH EGASI (+ ELITE alohida)
#  • OVERLORD va HUNTER A'ZOSI — faqat bot egasi beradi (/toifa_ber yoki murojaat tugmasi).
#  • GURUH EGASI — bot qo'shilgan guruhning haqiqiy egasi bo'lsa, tugma orqali avtomatik beriladi.
#  • Nishon ism yonida HAMMA joyda (o'yin, reyting, profil) ko'rinadi — mention() orqali.
#  • Har toifaning emojisi bot orqali (/toifa_emoji) almashtiriladi — kodga tegmasdan.
# ================================================================================
TOIFA_ORDER = ["overlord", "member", "group_owner"]   # yuqoridan pastga
TOIFA_INFO = {
    "overlord":    {"name": "OVERLORD", "icon": "🐺", "id": "",
                    "desc": "Eng yuqori toifa. Faqat bot egasi tomonidan beriladi."},
    "member":      {"name": "HUNTER A'ZOSI", "icon": "🎖", "id": "",
                    "desc": "Hunter jamoasi a'zolari uchun. Bot egasi tomonidan beriladi."},
    "group_owner": {"name": "GURUH EGASI", "icon": "🏛", "id": "",
                    "desc": "Bot qo'shilgan guruhning egasi bo'lsangiz, avtomatik olasiz."},
}
_TOIFA_EMOJI_SETTING = "toifa_emoji"
_TOIFA_WAIT = {}      # owner_id -> toifa kaliti (yangi premium emoji kutilmoqda)
_TOIFA_REQ_TS = {}    # uid -> oxirgi murojaat vaqti (xotirada; qayta ishga tushsa tozalanadi)
_TOIFA_GO_TS = {}     # uid -> oxirgi "guruh egasi" tekshiruvi vaqti
_TOIFA_REQ_COOLDOWN = 24 * 3600
_TOIFA_GO_COOLDOWN = 60


def _toifa_emoji_overrides():
    try:
        d = json.loads(get_setting(_TOIFA_EMOJI_SETTING) or "{}")
        return {k: str(v) for k, v in d.items() if k in TOIFA_INFO} if isinstance(d, dict) else {}
    except Exception:
        return {}


def toifa_emoji_id(key):
    return _toifa_emoji_overrides().get(key) or TOIFA_INFO[key]["id"]


def toifa_emoji_html(key):
    info = TOIFA_INFO[key]
    eid = toifa_emoji_id(key)
    return f'<tg-emoji emoji-id="{eid}">{info["icon"]}</tg-emoji>' if eid else info["icon"]


def toifa_get(uid, ch=None):
    """Foydalanuvchining eng yuqori faol toifasi kaliti yoki None."""
    try:
        ch = ch if ch is not None else get_charges(uid)
    except Exception:
        return None
    found = set()
    try:
        if uid is not None and int(uid) == int(_toifa_owner_target()):
            return "overlord"     # bot egasi — doim eng yuqori toifa (🐺)
    except Exception:
        pass
    t = ch.get("toifa")
    if isinstance(t, dict) and t.get("key") in ("overlord", "member"):
        until = float(t.get("until") or 0)
        if not until or until > time.time():
            found.add(t["key"])
    if ch.get("toifa_go"):
        found.add("group_owner")
    for k in TOIFA_ORDER:
        if k in found:
            return k
    return None


def toifa_prefix(uid, ch=None):
    k = toifa_get(uid, ch)
    return f"{toifa_emoji_html(k)} <b>{TOIFA_INFO[k]['name']}</b> " if k else ""


def toifa_badge(uid, ch=None):
    """Ism OXIRIGA qo'yiladigan toifa belgisi: ' 🎖' / ' 🏛' / ' 🐺' (matnsiz, faqat emoji)."""
    k = toifa_get(uid, ch)
    return f" {toifa_emoji_html(k)}" if k else ""


def toifa_profile_line(uid):
    k = toifa_get(uid)
    return f"👑 Toifa: {toifa_emoji_html(k)} <b>{TOIFA_INFO[k]['name']}</b>" if k else ""


def toifa_public(uid):
    """Mini ilova uchun: {'key','name','icon'} yoki None."""
    k = toifa_get(uid)
    return {"key": k, "name": TOIFA_INFO[k]["name"], "icon": TOIFA_INFO[k]["icon"]} if k else None


def toifa_grant(uid, key, days=0):
    """Owner tomonidan beriladigan toifa (overlord/member). days=0 — doimiy."""
    if key == "group_owner":   # doimiy bayroq (avto-tekshiruv bilan bir xil)
        set_charge_value(uid, "toifa_go", True)
        return
    until = (time.time() + days * 86400) if days and days > 0 else 0
    set_charge_value(uid, "toifa", {"key": key, "until": until})


def toifa_revoke(uid):
    def _mut(ch):
        ch = dict(ch)
        ch.pop("toifa", None)
        ch.pop("toifa_go", None)
        return ch, True
    return _atomic_json_field_update(uid, "charges", _mut)


def _toifa_owner_target():
    return OWNER_ID_FROM_ENV if OWNER_ID_FROM_ENV is not None else OWNER_ID


def _toifa_parse_key(word):
    w = (word or "").lower().replace("'", "").replace("’", "")
    if w in ("overlord", "ovl", "ol"):
        return "overlord"
    if w in ("member", "azo", "a'zo", "hunter", "azosi"):
        return "member"
    if w in ("guruh", "go", "groupowner", "group_owner", "egasi", "guruhegasi"):
        return "group_owner"
    return None


