def _toifa_verify_group_owner(uid):
    """Foydalanuvchi bot kuzatgan guruhlardan birining HAQIQIY egasi (creator) ekanini tekshiradi.
    Qaytaradi: (topildi: bool, guruh_nomi yoki None, tekshirilgan_guruhlar_soni)."""
    with db_lock:
        cur.execute("SELECT g.chat_id, COALESCE(k.title,'') FROM group_members g "
                    "LEFT JOIN known_groups k ON k.chat_id=g.chat_id "
                    "WHERE g.user_id=? ORDER BY g.last_seen DESC LIMIT 40", (uid,))
        rows = cur.fetchall()
    checked = 0
    for chat_id, title in rows:
        try:
            st = bot.get_chat_member(chat_id, uid).status
            checked += 1
        except Exception:
            continue
        if st == "creator":
            return True, (title or str(chat_id)), checked
    return False, None, checked


@bot.callback_query_handler(func=lambda c: c.data.startswith("toifa|"))
def cb_toifa(call):
    uid = call.from_user.id
    chat_id = call.message.chat.id
    action = call.data.split("|", 1)[1]
    user_dict(uid, call.from_user.first_name)
    if action == "go":
        now = time.time()
        if now - _TOIFA_GO_TS.get(uid, 0) < _TOIFA_GO_COOLDOWN:
            bot.answer_callback_query(call.id, "⏳ Biroz kuting va qayta urinib ko'ring.", show_alert=True)
            return
        _TOIFA_GO_TS[uid] = now
        bot.answer_callback_query(call.id, "🔍 Tekshirilmoqda...")
        ok, title, checked = _toifa_verify_group_owner(uid)
        if ok:
            set_charge_value(uid, "toifa_go", True)
            txt = (f"🎉 <b>Tabriklaymiz!</b> Siz <b>{esc(title)}</b> guruhining egasisiz.\n\n"
                   f"Sizga {toifa_emoji_html('group_owner')} <b>GURUH EGASI</b> toifasi berildi!")
        else:
            txt = ("❌ Siz bot qo'shilgan guruhlarning egasi sifatida topilmadingiz.\n\n"
                   "Bot sizni guruhda ko'rgan bo'lishi kerak — guruhda biror xabar yozing yoki o'yinda "
                   "qatnashing, so'ng qayta urinib ko'ring.")
        try:
            bot.edit_message_text(txt, chat_id, call.message.message_id,
                                  reply_markup=_toifa_screen_kb(uid))
        except Exception:
            bot.send_message(chat_id, txt, reply_markup=_toifa_screen_kb(uid))
        return
    if action == "req":
        now = time.time()
        if now - _TOIFA_REQ_TS.get(uid, 0) < _TOIFA_REQ_COOLDOWN:
            bot.answer_callback_query(call.id, "⏳ Murojaatingiz allaqachon yuborilgan. Javobni kuting.", show_alert=True)
            return
        target = _toifa_owner_target()
        if not target:
            bot.answer_callback_query(call.id, "❌ Hozir murojaat qabul qilinmayapti.", show_alert=True)
            return
        _TOIFA_REQ_TS[uid] = now
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.add(types.InlineKeyboardButton("🎖 A'zo berish", callback_data=f"toifa_ap|{uid}|member"),
               types.InlineKeyboardButton("🐉 OVERLORD", callback_data=f"toifa_ap|{uid}|overlord"))
        kb.add(types.InlineKeyboardButton("❌ Rad etish", callback_data=f"toifa_ap|{uid}|no"))
        uname = get_username(uid)
        safe_send(target,
                  f"👑 <b>Toifa murojaati</b>\n\n{mention(uid, call.from_user.first_name)}"
                  f"{(' (@' + esc(uname) + ')') if uname else ''}\nID: <code>{uid}</code>",
                  reply_markup=kb)
        bot.answer_callback_query(call.id, "✅ Murojaatingiz yuborildi!", show_alert=True)
        return
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("toifa_ap|"))
def cb_toifa_approve(call):
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Faqat bot egasi uchun.", show_alert=True)
        return
    _, uid_s, decision = call.data.split("|")
    target = int(uid_s)
    if decision == "no":
        res = "❌ Rad etildi."
        safe_send(target, "❌ Toifa murojaatingiz hozircha qabul qilinmadi.")
    else:
        toifa_grant(target, decision)
        res = f"✅ {TOIFA_INFO[decision]['name']} berildi."
        safe_send(target, f"🎉 Sizga {toifa_emoji_html(decision)} <b>{TOIFA_INFO[decision]['name']}</b> toifasi berildi!")
    try:
        bot.edit_message_text((call.message.text or "") + f"\n\n{res}", call.message.chat.id, call.message.message_id)
    except Exception:
        pass
    bot.answer_callback_query(call.id, res)


def _toifa_target_from(message, args):
    """(target_uid, qolgan_argumentlar) — reply yoki birinchi argument (ID)."""
    if message.reply_to_message and message.reply_to_message.from_user:
        return message.reply_to_message.from_user.id, args
    if args and args[0].lstrip("-").isdigit():
        return int(args[0]), args[1:]
    return None, args


@bot.message_handler(commands=["toifa_ber"])
def cmd_toifa_ber(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    args = (message.text or "").split()[1:]
    target, rest = _toifa_target_from(message, args)
    key = _toifa_parse_key(rest[0]) if rest else None
    if not target or not key:
        bot.send_message(message.chat.id, "Foydalanish: <code>/toifa_ber &lt;id&gt; overlord|member|guruh [kun]</code>\n"
                                          "yoki biror xabarga reply qilib: <code>/toifa_ber overlord</code>")
        return
    days = int(rest[1]) if len(rest) > 1 and rest[1].isdigit() else 0
    user_dict(target)
    toifa_grant(target, key, days)
    bot.send_message(message.chat.id, f"✅ <code>{target}</code> ga {toifa_emoji_html(key)} <b>{TOIFA_INFO[key]['name']}</b> "
                                      f"berildi ({'doimiy' if not days else str(days) + ' kun'}).")
    safe_send(target, f"🎉 Sizga {toifa_emoji_html(key)} <b>{TOIFA_INFO[key]['name']}</b> toifasi berildi!")


