@bot.message_handler(commands=["toifalar"])
def cmd_toifalar(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    with db_lock:
        cur.execute("SELECT user_id FROM users WHERE charges LIKE '%\"toifa\"%' OR charges LIKE '%\"toifa_go\"%'")
        ids = [r[0] for r in cur.fetchall()]
    rows = []
    for u in ids:
        k = toifa_get(u)
        if k:
            rows.append((TOIFA_ORDER.index(k), u, k))
    rows.sort()
    if not rows:
        bot.send_message(message.chat.id, "👑 Hozircha toifa egalari yo'q.")
        return
    lines = ["👑 <b>Toifa egalari</b>", ""]
    for _r, u, k in rows[:60]:
        lines.append(f"{toifa_emoji_html(k)} {TOIFA_INFO[k]['name']} — {mention(u, user_dict(u)['name'])} <code>{u}</code>")
    bot.send_message(message.chat.id, "\n".join(lines))


