def _toifa_try_consume(message, found):
    """Owner toifa emojisini almashtirish kutayotgan bo'lsa, yuborilgan birinchi premium emojini saqlaydi."""
    key = _TOIFA_WAIT.get(message.from_user.id)
    if not key:
        return False
    new_id = str(found[0][0])
    if not _pe_valid_id(new_id):
        bot.send_message(message.chat.id, "❌ Emoji ID noto'g'ri. Qaytadan yuboring.")
        return True
    _TOIFA_WAIT.pop(message.from_user.id, None)
    ovr = _toifa_emoji_overrides()
    ovr[key] = new_id
    set_setting(_TOIFA_EMOJI_SETTING, json.dumps(ovr))
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(types.InlineKeyboardButton("✅ Tayyor — ro'yxatga qaytish", callback_data="tem|menu"))
    bot.send_message(message.chat.id, f"✅ <b>Almashtirildi!</b>\n\n{toifa_emoji_html(key)} <b>{TOIFA_INFO[key]['name']}</b>", reply_markup=kb)
    return True


