def _stats_text(uid, name):
    h = home_state(uid)
    fav = favorite_role(uid)
    lines = [
        f"📊 <b>Statistika — {esc(name)}</b>",
        "━━━━━━━━━━━━━━━━━━",
        f"🎮 Jami o'yinlar: <b>{h['games']}</b>",
        f"🏆 G'alabalar: <b>{h['wins']}</b>",
        f"💀 Mag'lubiyatlar: <b>{h['losses']}</b>",
        f"📈 G'alaba foizi: <b>{h['winrate']}%</b>",
        f"🔥 Ketma-ket g'alaba: <b>{h.get('win_streak', 0)}</b>",
        f"🎖 Daraja: <b>{h['level']}</b> ({h['rank']})",
    ]
    if fav:
        lines.append(f"🏅 Sevimli rol: <b>{fav}</b>")
    lines.append("━━━━━━━━━━━━━━━━━━")
