def _news_text(uid):
    items = news_items(uid)
    if not items:
        return "📰 <b>Yangiliklar</b>\n\nHozircha yangilik yo'q. Tez orada! 🌙"
    lines = ["📰 <b>Yangiliklar</b>", ""]
    for n in items[:8]:
        dot = "🔴 " if n.get("unread") else ""
        lines.append(f"{dot}{n['icon']} <b>{esc(n['title'])}</b>  <i>{esc(n['time'])}</i>")
        if n.get("desc"):
            lines.append(esc(n["desc"]))
        lines.append("")
    return "\n".join(lines).strip()


