# ================================================================================
#  🎭 v8 — ROLLAR DO'KONI: istalgan rolni to'g'ridan-to'g'ri sotib olish
# ================================================================================
# Foydalanuvchi rolni tanlab sotib oladi → "chipta" beriladi → keyingi safar
# /join qilganda (istalgan guruhda) chipta AVTOMATIK ishlatiladi va o'sha
# o'yinda aynan shu rol beriladi (mavjud `forced_roles` mexanizmi orqali —
# o'zgartirilmadi, faqat ustiga qurildi). Bir vaqtda faqat bitta chipta bo'lishi
# mumkin; yangisini sotib olish eskisini ALMASHTIRADI (pul qaytarilmaydi —
# xarid tugmasi bosishdan oldin buni ochiq ogohlantiradi).
ROLE_SHOP_TIERS = {
    # price — tanlangan valyutada (currency: "diamond" yoki "dollar"). Hammasi Owner Center'dan o'zgaradi.
    "t_top":    {"label": "Eng kuchli rollar", "currency": "diamond", "price": 2, "desc_tail": "— eng kuchli rollardan biri."},
    "t_strong": {"label": "Kuchli rollar", "currency": "diamond", "price": 1, "desc_tail": "— kuchli rol."},
    "t_high":   {"label": "Yuqori rollar", "currency": "dollar", "price": 600, "desc_tail": "— muhim rol."},
    "t_mid":    {"label": "O'rta rollar", "currency": "dollar", "price": 500, "desc_tail": "— foydali rol."},
    "t_basic":  {"label": "Oddiy rollar", "currency": "dollar", "price": 400, "desc_tail": "— o'ziga xos rol."},
    "t_peace":  {"label": "Tinch aholi", "currency": "dollar", "price": 100, "desc_tail": "— oddiy tinch aholi."},
}
ROLE_SHOP_ROLE_TIER = {
    "t_top": [R_QOT, R_JOK, R_VAM, R_MIN],
    "t_strong": [R_DON, R_MAF, R_UBI, R_SER, R_AFE, R_GAZ, R_SEH, R_KIM],
    "t_high": [R_DOK, R_KOM],
    "t_mid": [R_JUR, R_ADV, R_AFS, R_KOL, R_JAN, R_FIT, R_BUQ, R_FOT, R_ADM, R_ROB, R_RIK, R_SOY, R_CUP],
    "t_peace": [R_TIN],
}   # qolgan barcha rollar — "t_basic"
ROLE_SHOP_MISC = {"cancel_price": 100}   # 🗑 Faol rolni o'chirish narxi ($)
ROLE_SHOP_PRICE_OVERRIDES = {}           # (eski nom — moslik uchun; endi ishlatilmaydi)


def _role_shop_tier(role):
    for tier, roles in ROLE_SHOP_ROLE_TIER.items():
        if role in roles:
            return tier
    return "t_basic"


def role_shop_catalog():
    """[{role, tier, tier_label, currency, price, diamond, stars, desc}] — 'diamond'/'stars' faqat 💎 rollar uchun
    (mini-app moslik), boshqalar uchun None."""
    out = []
    for role in ALL_ROLES:
        tier = _role_shop_tier(role)
        t = ROLE_SHOP_TIERS[tier]
        is_d = t["currency"] == "diamond"
        out.append({"role": role, "tier": tier, "tier_label": t["label"], "currency": t["currency"], "price": int(t["price"]),
                    "diamond": int(t["price"]) if is_d else None,
                    "stars": int(t["price"]) * DIAMOND_STARS_RATE if is_d else None,
                    "desc": f"{ROLES_INFO.get(role, '')} {t['desc_tail']}".strip()})
    out.sort(key=lambda r: (0 if r["currency"] == "diamond" else 1, -r["price"]))
    return out


def _role_price_label(r):
    return f"{r['price']}{'💎' if r['currency'] == 'diamond' else '💵'}"


def role_ticket_get(uid):
    _t = get_charges(uid).get("role_ticket") or None
    return _t if _t in ROLES_INFO else None


def role_ticket_buy(uid, role):
    info = next((r for r in role_shop_catalog() if r["role"] == role), None)
    if not info:
        return False, "Bunday rol yo'q.", 0
    price, cur_name = info["price"], info["currency"]
    if not try_charge(uid, cur_name, price):
        return False, f"Yetarli {'olmos' if cur_name == 'diamond' else 'dollar'} yo'q ({_role_price_label(info)} kerak).", price
    ch = get_charges(uid)
    ch["role_ticket"] = role
    set_charges(uid, ch)
    return True, f"🎭 Chiptangiz tayyor: keyingi o'yinda <b>{role}</b> siz bo'lasiz!", price


def role_ticket_cancel(uid):
    """🗑 Faol rolni o'chirish — narxi ROLE_SHOP_MISC['cancel_price'] 💵 (puli qaytarilmaydi)."""
    ch = get_charges(uid)
    if not ch.get("role_ticket"):
        return False, "Sizda faol rol yo'q."
    price = int(ROLE_SHOP_MISC["cancel_price"])
    if not try_charge(uid, "dollar", price):
        return False, f"Yetarli dollar yo'q ({price}💵 kerak)."
    ch = get_charges(uid)
    ch.pop("role_ticket", None)
    set_charges(uid, ch)
    return True, f"🗑 Faol rol o'chirildi (−{price}💵)."


def _apply_role_ticket_on_join(uid, chat_id):
    """do_join muvaffaqiyatli bo'lgach chaqiriladi: chiptasi bo'lsa, shu o'yinga forced_roles orqali bog'laydi."""
    role = role_ticket_get(uid)
    if not role:
        return
    game = GAMES.get(chat_id)
    if not game:
        return
    game.setdefault("forced_roles", {})[uid] = role
    ch = get_charges(uid)
    ch.pop("role_ticket", None)
    set_charges(uid, ch)
    safe_send(uid, f"🎭 Chiptangiz ishlatildi: bu o'yinda <b>{role}</b> siz bo'lasiz!")


def _role_shop_kb(uid):
    kb = types.InlineKeyboardMarkup(row_width=1)
    for r in role_shop_catalog():
        kb.add(types.InlineKeyboardButton(f"{r['role']} - {_role_price_label(r)}", callback_data=f"roleshop|buy|{r['role']}"))
    kb.add(types.InlineKeyboardButton(f"🗑 Faol rolni o'chirish - {ROLE_SHOP_MISC['cancel_price']}💵", callback_data="roleshop|cancel"))
    kb.add(types.InlineKeyboardButton("⬅️ Orqaga", callback_data="shopback"))
    return kb


def _role_shop_text(uid):
    ticket = role_ticket_get(uid)
    lines = ["Rolni tanlang — keyingi o'yinda aynan shu rol sizga beriladi."]
    lines.append(f"\n🎟 Faol rol: <b>{ticket}</b>" if ticket else "\n🎟 Faol rol: <i>Yo‘q</i>")
    return "\n".join(lines)


