with db_lock:
    cur.execute("CREATE TABLE IF NOT EXISTS role_stats (user_id INTEGER NOT NULL, role TEXT NOT NULL, "
                "games INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, role))")
    conn.commit()


def _migrate_roles25_cleanup():
    """🧹 Bir martalik: 45 rolli eski tizim qoldiqlari (rol chiptalari, rol statistikasi, sevimli/oxirgi rol) butunlay o'chiriladi."""
    if get_setting("roles25_cleanup_v1") == "1":
        return
    import json as _json
    with db_lock:
        cur.execute("DELETE FROM role_stats")
        cur.execute("UPDATE users SET fav_role=''")
        cur.execute("SELECT user_id, charges FROM users WHERE charges LIKE '%role_ticket%' OR charges LIKE '%last_role%'")
        rows = cur.fetchall()
        for _uid, _raw in rows:
            try:
                _d = _json.loads(_raw or "{}")
            except Exception:
                continue
            if not isinstance(_d, dict):
                continue
            _d.pop("role_ticket", None)
            _d.pop("last_role", None)
            cur.execute("UPDATE users SET charges=? WHERE user_id=?", (_json.dumps(_d, ensure_ascii=False), _uid))
        conn.commit()
    set_setting("roles25_cleanup_v1", "1")


try:
    _migrate_roles25_cleanup()
except Exception as _e:
    print("roles25 cleanup xato:", _e)


def record_role_result(uid, role, won):
    """Har o'yin tugagach (tark etmagan bo'lsa) chaqiriladi — rol bo'yicha statistikani yuritadi."""
    if not role:
        return
    with db_lock:
        cur.execute("INSERT INTO role_stats (user_id, role, games, wins) VALUES (?,?,1,?) "
                    "ON CONFLICT(user_id, role) DO UPDATE SET games=games+1, wins=wins+excluded.wins",
                    (uid, role, 1 if won else 0))
        conn.commit()


def role_stats_of(uid):
    """[{role, games, wins}] — ko'p o'ynalgandan kamiga qarab saralangan."""
    with db_lock:
        cur.execute("SELECT role, games, wins FROM role_stats WHERE user_id=? ORDER BY games DESC", (uid,))
        rows = cur.fetchall()
    return [{"role": r[0], "games": r[1], "wins": r[2]} for r in rows]


def favorite_role(uid):
    """Foydalanuvchi /sevimli_rol bilan qo'lda belgilagan bo'lsa — o'sha; aks holda eng ko'p
    o'ynalgan rol avtomatik hisoblanadi."""
    manual = user_dict(uid).get("fav_role")
    if manual:
        return manual
    stats = role_stats_of(uid)
    return stats[0]["role"] if stats else None


def clan_badge(uid):
    """(klan nomi, lider ekanligi) yoki None."""
    with db_lock:
        cur.execute("SELECT name FROM clans WHERE owner_id=?", (uid,))
        row = cur.fetchone()
        if row:
            return row[0], True
        cur.execute("SELECT c.name FROM clan_members m JOIN clans c ON c.owner_id=m.owner_id WHERE m.member_id=?", (uid,))
        row = cur.fetchone()
        return (row[0], False) if row else None


