# ================================================================================
#  🔄 PROFIL ALMASHTIRISH (5 💎) — ikki Telegram akkaunt o'rtasida profil ALMASHADI
#  Xavfsizlik: ikkala tomon o'yinda bo'lmasligi, qabul qiluvchi roziligi, 7 kunlik limit,
#  💎 faqat almashuv MUVAFFAQIYATLI bo'lgandagina yechiladi, hammasi bitta tranzaksiyada.
# ================================================================================
PSWAP_PRICE = 5
PSWAP_COOLDOWN = 7 * 86400
PSWAP_TTL = 600
_PSWAP_PENDING = {}          # req_id -> {"a": uid, "b": uid, "exp": ts}
_PSWAP_LOCK = threading.Lock()
# (jadval, ustun) — foydalanuvchi ID'si saqlanadigan jadvallar; "users" alohida (ism/ban o'zida qoladi)
_PSWAP_TABLES = [
    ("heroes", "user_id"), ("user_cosmetics", "user_id"), ("role_stats", "user_id"),
    ("hm_user_avatar", "user_id"), ("hunter_character_identity", "user_id"), ("user_cards", "user_id"),
    ("hunter_world2_profiles", "user_id"), ("hunter_world2_quests", "user_id"),
    ("hunter_world2_legacy", "user_id"), ("hunter_world2_factions", "user_id"),
    ("hunter_world2_npc_rel", "user_id"), ("hunter_world2_quest_chain", "user_id"),
    ("hunter_world2_feed", "user_id"), ("clans", "owner_id"),
    ("clan_members", "owner_id"), ("clan_members", "member_id"),
]
_PSWAP_USER_KEEP = ("user_id", "name", "banned")


def _in_active_game(uid):
    for g in list(GAMES.values()):
        try:
            if uid in g.get("players", {}) and g.get("phase") not in (None, "ended", "finished"):
                return True
        except Exception:
            continue
    return False


def _pswap_execute(a, b):
    """Ikki akkauntning profilini bitta tranzaksiyada almashtiradi. (ok, xato_matni) qaytaradi."""
    with db_lock:
        try:
            cur.execute("SELECT * FROM users WHERE user_id=?", (a,))
            ra = cur.fetchone()
            cur.execute("SELECT * FROM users WHERE user_id=?", (b,))
            rb = cur.fetchone()
            if ra is None or rb is None:
                return False, "Akkaunt topilmadi."
            cols = [d[0] for d in cur.description]
            da, db_ = dict(zip(cols, ra)), dict(zip(cols, rb))
            if int(da.get("diamond") or 0) < PSWAP_PRICE:
                return False, "💎 yetarli emas."
            da["diamond"] = int(da["diamond"]) - PSWAP_PRICE      # narx almashuvdan oldin yechiladi
            swap_cols = [c for c in cols if c not in _PSWAP_USER_KEEP]
            for uid_, src in ((a, db_), (b, da)):
                sets = ", ".join(f"{_sql_ident(c, set(cols))}=?" for c in swap_cols)
                cur.execute(f"UPDATE users SET {sets} WHERE user_id=?", [src[c] for c in swap_cols] + [uid_])
            tmp = -abs(a) - 1
            for table, col in _PSWAP_TABLES:
                cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,))
                if cur.fetchone() is None:
                    continue
                cur.execute(f"UPDATE {table} SET {col}=? WHERE {col}=?", (tmp, a))
                cur.execute(f"UPDATE {table} SET {col}=? WHERE {col}=?", (a, b))
                cur.execute(f"UPDATE {table} SET {col}=? WHERE {col}=?", (b, tmp))
            conn.commit()
            return True, ""
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            _logger.exception("profil almashtirish xatosi")
            return False, "Texnik xatolik — hech narsa o'zgarmadi."


@bot.callback_query_handler(func=lambda c: c.data == "svc|profile_swap")
def cb_pswap_start(call):
    uid = call.from_user.id
    if call.message.chat.type != "private":
        bot.answer_callback_query(call.id, "Buni shaxsiy chatda bajaring.", show_alert=True)
        return
    ud = user_dict(uid, call.from_user.first_name)
    if int(ud.get("diamond", 0) or 0) < PSWAP_PRICE:
        bot.answer_callback_query(call.id, f"❌ {PSWAP_PRICE} 💎 kerak.", show_alert=True)
        return
    if _in_active_game(uid):
        bot.answer_callback_query(call.id, "❌ O'yin paytida profilni almashtirib bo'lmaydi.", show_alert=True)
        return
    last = float(get_setting(f"pswap_last_{uid}") or 0)
    if time.time() - last < PSWAP_COOLDOWN:
        days = int((PSWAP_COOLDOWN - (time.time() - last)) // 86400) + 1
        bot.answer_callback_query(call.id, f"❌ Keyingi almashtirish: {days} kundan keyin.", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    m_ = bot.send_message(
        uid,
        "🔄 <b>Profil almashtirish</b>\n\n"
        "Almashmoqchi bo'lgan odamingizning <b>Telegram ID raqamini</b> yuboring.\n"
        f"💰 Narxi: <b>{PSWAP_PRICE} 💎</b> — faqat u rozi bo'lib, almashuv bajarilgandagina yechiladi.\n\n"
        "⚠️ Ikkalangizning profili (balans, buyumlar, geroy, klan, statistika) o'rin almashadi. Bekor qilish: /bekor",
    )
    bot.register_next_step_handler(m_, _pswap_got_id)


def _pswap_got_id(message):
    uid = message.from_user.id
    txt = (message.text or "").strip()
    if txt.lower() in ("/bekor", "bekor"):
        bot.send_message(uid, "Bekor qilindi.")
        return
    if not txt.isdigit():
        m_ = bot.send_message(uid, "❌ Faqat raqamli ID yuboring (yoki /bekor).")
        bot.register_next_step_handler(m_, _pswap_got_id)
        return
    target = int(txt)
    if target == uid:
        bot.send_message(uid, "❌ O'zingiz bilan almashtirib bo'lmaydi.")
        return
    with db_lock:
        cur.execute("SELECT banned FROM users WHERE user_id=?", (target,))
        row = cur.fetchone()
    if row is None:
        bot.send_message(uid, "❌ Bu ID botdan foydalanmagan. U avval botga /start bosishi kerak.")
        return
    if row[0] or is_banned(uid):
        bot.send_message(uid, "❌ Bu amal mumkin emas.")
        return
    if _in_active_game(uid) or _in_active_game(target):
        bot.send_message(uid, "❌ Ikkalangizdan biri o'yinda — o'yin tugagach urinib ko'ring.")
        return
    if int(user_dict(uid).get("diamond", 0) or 0) < PSWAP_PRICE:
        bot.send_message(uid, f"❌ {PSWAP_PRICE} 💎 kerak.")
        return
    rid = f"{uid}{int(time.time())}"
    with _PSWAP_LOCK:
        _PSWAP_PENDING[rid] = {"a": uid, "b": target, "exp": time.time() + PSWAP_TTL}
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("✅ Roziman", callback_data=f"pswap|ok|{rid}"),
           types.InlineKeyboardButton("❌ Rad etish", callback_data=f"pswap|no|{rid}"))
    a_name = user_dict(uid)["name"]
    sent = safe_send(target,
        f"🔄 <b>{a_name}</b> (ID: <code>{uid}</code>) siz bilan <b>profilni almashtirmoqchi</b>.\n\n"
        "Rozi bo'lsangiz, ikkalangizning balans, buyum, geroy, klan va statistikangiz o'rin almashadi. "
        "Tanimasangiz — rad eting.\n⏳ 10 daqiqa amal qiladi.", kb)
    if not sent:
        bot.send_message(uid, "❌ U odamga xabar yuborib bo'lmadi (bot bilan chatni boshlamagan bo'lishi mumkin).")
        return
    bot.send_message(uid, "📨 So'rov yuborildi. U rozi bo'lishini kuting (10 daqiqa).")


@bot.callback_query_handler(func=lambda c: c.data.startswith("pswap|"))
def cb_pswap_answer(call):
    try:
        _, act, rid = call.data.split("|")
    except Exception:
        bot.answer_callback_query(call.id)
        return
    with _PSWAP_LOCK:
        req = _PSWAP_PENDING.get(rid)
        if not req or req["exp"] < time.time() or call.from_user.id != req["b"]:
            _PSWAP_PENDING.pop(rid, None) if req and req["exp"] < time.time() else None
            bot.answer_callback_query(call.id, "So'rov eskirgan yoki sizga tegishli emas.", show_alert=True)
            return
        _PSWAP_PENDING.pop(rid, None)
    a, b = req["a"], req["b"]
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    except Exception:
        pass
    if act != "ok":
        bot.answer_callback_query(call.id, "Rad etildi.")
        safe_send(a, "❌ Profil almashtirish so'rovingiz rad etildi. 💎 yechilmadi.")
        return
    if _in_active_game(a) or _in_active_game(b):
        bot.answer_callback_query(call.id, "Kimdir o'yinda.", show_alert=True)
        safe_send(a, "❌ Almashuv bekor bo'ldi: kimdir o'yinda. 💎 yechilmadi.")
        return
    ok, err = _pswap_execute(a, b)
    if not ok:
        bot.answer_callback_query(call.id, "Bajarilmadi.", show_alert=True)
        safe_send(a, f"❌ Almashuv bajarilmadi: {err} 💎 yechilmadi.")
        return
    set_setting(f"pswap_last_{a}", int(time.time()))
    bot.answer_callback_query(call.id, "Bajarildi!")
    safe_send(a, "✅ <b>Profil almashtirildi!</b> /profil orqali yangi profilingizni ko'ring. (-5 💎)")
    safe_send(b, "✅ <b>Profil almashtirildi!</b> /profil orqali yangi profilingizni ko'ring.")
    try:
        _logger.warning("PROFIL ALMASHTIRILDI: %s <-> %s", a, b)
        safe_send(_owner_uid(), f"🔄 Profil almashtirildi: <code>{a}</code> ⇄ <code>{b}</code>")
    except Exception:
        pass


