def _spin_coin_wheel(uid):
    """🎰 Coin Baxt G'ildiragi — sotib olingan uid HAR DOIM biror mukofot yutadi.
    Ehtimollar: kichik pul (ko'p uchraydi) → o'rtacha → nodir (kamdan-kam) → JACKPOT (juda kam)."""
    roll = random.random() * 100
    if roll < 45:
        amt = random.randint(80, 220)
        add_balance(uid, dollar=amt)
        return f"💵 Chiqdi: <b>{amt}$</b> Dollar!"
    if roll < 75:
        amt = random.randint(3, 8) * FREE_DIAMOND_DOLLAR_VALUE
        add_balance(uid, dollar=amt)
        return f"💵 Chiqdi: <b>{amt}$</b> Dollar!"
    if roll < 92:
        add_shield(uid, 1)
        return "🛡 Chiqdi: +1 Himoya (shield)!"
    if roll < 99:
        role = random.choice([r for r in ALL_ROLES if r != R_TIN])
        ch = get_charges(uid)
        ch["role_ticket"] = role
        set_charges(uid, ch)
        return f"🎭 <b>JACKPOT!</b> Bepul rol chiptasi: keyingi o'yinda <b>{role}</b> bo'lasiz!"
    if get_hero(uid):
        add_balance(uid, dollar=5000)
        return "🏆 <b>SUPER JACKPOT!</b> Sizda allaqachon geroy bo'lgani uchun o'rniga <b>5000$</b> Dollar berildi!"
    hero_key = roll_hero()
    with db_lock:
        cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)", (uid, hero_key, time.time()))
        conn.commit()
    hero = HEROES[hero_key]
    return f"🏆🎉 <b>SUPER JACKPOT!!!</b> Sizga bepul GEROY tushdi: <b>{hero['name']}</b>! /geroyim orqali ko'ring."


def _perform_shop_purchase(uid, first_name, cat, key):
    """🛒 Do'kondan xarid qilish — markazlashtirilgan funksiya (Telegram tugmasi VA
    Mini App'dan kelgan /start chuqur havolasi ORQALI bir xil ishlatiladi)."""
    _, items = SHOP_CATEGORIES[cat]
    item = items.get(key)
    if not item:
        return False, "❌ Bunday buyum topilmadi."
    if not oc_shop_on(cat, key):   # 👑 Owner Center: mahsulot sotuvdan olingan
        return False, "🔴 Bu mahsulot hozircha sotuvda emas."
    user_dict(uid, first_name)  # qatorni yaratish/ismni yangilash (agar yo'q bo'lsa)

    if item.get("mode") == "service":
        return False, "ℹ️ Bu xizmat tugma orqali ishga tushiriladi."
    if item.get("mode") == "charge" and item.get("charge_key"):
        _have = int(get_charges(uid).get(item["charge_key"], 0) or 0)
        _cap = int(item.get("max_stock", SHOP_MAX_STOCK))
        if _have + int(item.get("charge_amount", 1)) > _cap:
            return False, f"❌ Zaxirangiz to'la: bu buyumdan ko'pi bilan {_cap} ta saqlash mumkin (hozir {_have} ta)."

    if item.get("mode") == "hero_buy" and get_hero(uid):
        return False, "❌ Sizda allaqachon geroy bor. /geroyim"

    # Atomik: balans tekshirish va yechish bitta amalda — parallel bosishda
    # ikki marta xarid qilib balansni minusga tushirib qo'yish mumkin emas.
    if not try_charge(uid, item["currency"], item["price"]):
        return False, "❌ Balansingiz yetarli emas!"

    mode = item["mode"]
    result_note = ""
    if mode == "shield":
        _n = int(item.get("shield_amount", 1))
        add_shield(uid, _n, ttl=ITEM_TTL_SECONDS)
        result_note = f"🛡 Himoya (+{_n} shield) hisobingizga qo'shildi (7 kun amal qiladi)."
    elif mode == "bundle":
        _parts = []
        for _k, _n in item["bundle"]:
            if _k == "shield":
                add_shield(uid, _n, ttl=ITEM_TTL_SECONDS)
                _parts.append(f"🛡×{_n}")
            else:
                add_charge(uid, _k, _n, ttl=ITEM_TTL_SECONDS)
                _parts.append(f"{TOGGLABLE_ITEMS.get(_k, _k)}×{_n}")
        result_note = "✅ To'plam qo'shildi: " + ", ".join(_parts) + " (7 kun amal qiladi)."
    elif mode == "gamble_ability":
        if key == "zar":
            options = [("shield", None), ("night_vision", 1)]
        else:  # "quti"
            options = [("gps", 1), ("compass", 1), ("shield", None)]
        picked_key, picked_amount = random.choice(options)
        if picked_key == "shield":
            add_shield(uid, 1, ttl=ITEM_TTL_SECONDS)
            result_note = "🛡 Chiqdi: Himoya (+1 shield)!"
        else:
            add_charge(uid, picked_key, picked_amount, ttl=ITEM_TTL_SECONDS)
            result_note = f"✨ Chiqdi: {TOGGLABLE_ITEMS.get(picked_key, picked_key)} ({picked_amount} ta)!"
    elif mode == "charge":
        if item.get("perm"):
            add_charge(uid, item["charge_key"], item.get("charge_amount", 1), perm=True)
            result_note = f"✅ Tayyor — kerak bo'lganda o'zi ishlaydi.\n{item.get('desc', '')}"
        else:
            add_charge(uid, item["charge_key"], item.get("charge_amount", 1), ttl=ITEM_TTL_SECONDS)
            result_note = f"✅ Ishlatish uchun tayyor — {item.get('desc', '')}"
    elif mode == "multiplier":
        mkey = item["charge_key"]
        _box = {}
        def _mut(ch, _box=_box, mkey=mkey):
            ch = dict(ch)
            cur_until = ch.get(mkey + "_until", 0)
            _dur = min(int(item.get("duration_seconds", MULTIPLIER_DURATION_SECONDS)), ITEM_TTL_SECONDS)
            new_until = min(max(cur_until, time.time()) + _dur, time.time() + ITEM_TTL_SECONDS)
            ch[mkey + "_val"] = item["mult_value"]
            ch[mkey + "_until"] = new_until
            _box["new_until"] = new_until
            return ch, True
        _atomic_json_field_update(uid, "charges", _mut)
        new_until = _box["new_until"]
        days_left = round((new_until - time.time()) / 86400, 1)
        result_note = f"✅ Multiplikator faollashtirildi: x{item['mult_value']} — {days_left} kun davomida amal qiladi."
    elif mode == "expiry":
        _dur = min(int(item["duration_seconds"]), ITEM_TTL_SECONDS)
        until = time.time() + _dur
        set_charge_value(uid, item["charge_key"], until)
        result_note = (f"✅ {_dur // 86400} kunga faollashtirildi." if _dur >= 86400 else f"✅ {_dur // 3600} soatga faollashtirildi.")
    elif mode == "permanent_flag":
        set_charge_value(uid, item["charge_key"], 1)
        result_note = "✅ Doimiy maqom faollashtirildi."
    elif mode == "hero_buy":
        if _grant_hero(uid, "soya"):
            set_charge_value(uid, "hero_zaryad", HERO_ZARYAD_MAX)
            result_note = "🎉 <b>Geroy</b> endi sizniki! /geroyim orqali ko'ring va rivojlantiring.\n🖊 Hozir geroyingizga nom berasiz — botning keyingi xabariga javob yozing."
            try:
                hero_ask_name(uid)
            except Exception:
                _logger.warning("hero_ask_name xatosi (uid=%s)", uid, exc_info=True)
        else:
            add_balance_as('refund', uid, diamond=int(item["price"]), ledger=False)
            return False, "❌ Sizda allaqachon geroy bor. 💎 qaytarildi."
    elif mode == "hero_chest":
        existing = get_hero(uid)
        if existing:
            refund = item["price"] // 2
            add_balance_as('refund', uid, diamond=refund, ledger=False)
            result_note = f"📦 Sizda allaqachon geroy bor ({existing['name']})! Sandiq {refund} 💎 ga aylantirildi."
        else:
            hero_key = roll_hero()
            with db_lock:
                cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)", (uid, hero_key, time.time()))
                conn.commit()
            hero = HEROES[hero_key]
            extra = "\n🎊🎊 NODIR TUSHISH! Siz eng kuchli geroyni qo'lga kiritdingiz! 🎊🎊" if False else ""
            result_note = f"🎉 Sandiqdan chiqdi: <b>{hero['name']}</b> (1-lvl)!{extra}\n{hero['desc']}\n/geroyim orqali ko'ring va rivojlantiring."

    add_inventory_item(uid, item["name"])
    return True, f"✅ {item['name']} sotib olindi!\n{result_note}"


