#  🔐 STARS TO'LOVLARI — IDEMPOTENT + ATOMIK QATLAM (B bosqich)
#  Mantiq alohida faylda: payments_idempotent.py. Bu yerda faqat ulanish ("glue").
# ================================================================================

def _pay_expected_stars(p):
    """Payload bo'yicha KERAKLI Stars narxi (narxlar manbai — botning o'zi). None = yaroqsiz."""
    k = p["kind"]
    try:
        if k == "diamondbuy":
            t, s_ = _stars_for("diamond", p["qty"]); return s_ if t else None
        if k == "dollarbuy":
            t, s_ = _stars_for("dollar", p["qty"]); return s_ if t else None
        if k == "hc":
            return hc_star_price(p["qty"]) if 1 <= p["qty"] <= 1000 else None
        if k in ("elitepay", "elitegift"):
            plan = next((x for x in ELITE_PLANS if x["days"] == p["days"]), None)
            return plan["stars"] if plan else None
        if k == "namestyle":
            e = NAME_STYLE_CATALOG.get(p["key"]); return e[1] if e else None
        if k == "namecolor":
            e = NAME_COLOR_CATALOG.get(p["key"]); return e[2] if e else None
        if k == "herobuy":
            return hero_price(p["key"], "buy_stars") if p["key"] in HEROES else None
        if k == "herolv":
            hero = get_hero(p["uid"])
            if not hero or not (2 <= p["level"] <= HERO_MAX_LEVEL):
                return None
            return hero_price(hero["key"], f"lv{p['level']}_stars")
    except Exception:
        _logger.exception("_pay_expected_stars xatolik (payload=%r)", p)
    return None


def _pay_hero_compensation(kind, hero_key, level):
    try:
        if kind == "herobuy":
            return hero_price(hero_key, "buy_diamond") if hero_key in HEROES else 0
        if kind == "herolv" and 2 <= level <= HERO_MAX_LEVEL:
            return hero_price(hero_key, f"lv{level}_diamond")
    except Exception:
        _logger.exception("_pay_hero_compensation xatolik")
    return 0


_PAY = _payments.PaymentStore(conn, db_lock, _payments.PaymentConfig(
    expected_stars=_pay_expected_stars,
    name_styles={k: v[2] for k, v in NAME_STYLE_CATALOG.items()},
    name_colors={k: v[3] for k, v in NAME_COLOR_CATALOG.items()},
    hero_keys=set(HEROES),
    hero_max_level=HERO_MAX_LEVEL,
    hero_compensation=_pay_hero_compensation,
    referral_bonus=lambda: 0,   # 🔒 bepul 💎 yo'q: bonus dollar sifatida pastda beriladi   # konstanta fayl pastida e'lon qilingan — kechiktirilgan o'qish
))
_PAY_MIGRATION = _PAY.migrate()   # faqat CREATE ... IF NOT EXISTS / INSERT OR IGNORE — eski ma'lumotga tegmaydi
_logger.info("💳 payments migratsiyasi: %s", _PAY_MIGRATION)


@bot.pre_checkout_query_handler(func=lambda q: True)
def checkout_handler(pre_checkout_query):
    """Pre-checkout: to'lovni FAQAT tekshirilgan bo'lsa tasdiqlaydi (fail-closed).
    Bu yerda hech narsa BERILMAYDI — berish faqat successful_payment'dan keyin."""
    q = pre_checkout_query
    try:
        ok, err = _PAY.validate_precheckout(payer_id=q.from_user.id, currency=q.currency,
                                            total_amount=q.total_amount, payload=q.invoice_payload)
    except Exception:
        _logger.exception("pre_checkout tekshiruvi xatolik berdi — to'lov RAD etildi (uid=%s)", q.from_user.id)
        ok, err = False, "Vaqtincha xatolik. Birozdan keyin qayta urinib ko'ring."
    try:
        if ok:
            bot.answer_pre_checkout_query(q.id, ok=True)
        else:
            bot.answer_pre_checkout_query(q.id, ok=False, error_message=(err or "To'lov rad etildi.")[:200])
    except Exception:
        _logger.error("answer_pre_checkout_query yuborilmadi (uid=%s, ok=%s)", q.from_user.id, ok, exc_info=True)


