@bot.message_handler(commands=["refund"])
def cmd_refund(message):
    """💸 FAQAT bot egasi — xato yoki noto'g'ri to'lovni Telegram Stars orqali
    qaytaradi (refund). Foydalanuvchining OXIRGI muvaffaqiyatli to'lovi
    avtomatik topiladi va qaytariladi.
    Foydalanish: /refund <user_id>  YOKI  kimningdir xabariga reply qilib /refund
    🔒 XAVFSIZLIK: bu funksiya kutubxona versiyasiga bog'liq (refund_star_payment) —
    agar mavjud bo'lmasa, aniq xabar bilan to'xtaydi, botni yiqitmaydi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return

    target_id = None
    parts = message.text.split()
    if message.reply_to_message and message.reply_to_message.from_user:
        target_id = message.reply_to_message.from_user.id
    elif len(parts) in (2, 3) and parts[1].isdigit():
        target_id = int(parts[1])
    else:
        bot.send_message(message.chat.id, "Foydalanish: <code>/refund &lt;user_id&gt;</code> yoki kimningdir xabariga reply qilib <code>/refund</code>.")
        return

    charge_id = parts[2] if (len(parts) == 3 and not message.reply_to_message) else None
    charge_id = charge_id or _PAY.latest_charge_for(target_id) or get_setting(f"last_charge_{target_id}")
    if not charge_id:
        bot.send_message(message.chat.id, f"❌ <code>{target_id}</code> uchun so'nggi Stars to'lovi topilmadi.")
        return

    try:
        bot.refund_star_payment(target_id, charge_id)
        _PAY.mark_refunded(charge_id)
        bot.send_message(message.chat.id, f"✅ <code>{target_id}</code>ning so'nggi to'lovi muvaffaqiyatli qaytarildi (refund).")
        safe_send(target_id, "💸 So'nggi Stars to'lovingiz bot egasi tomonidan qaytarildi (refund qilindi).")
    except AttributeError:
        bot.send_message(
            message.chat.id,
            "❌ Ushbu botning pyTelegramBotAPI kutubxona versiyasida <code>refund_star_payment</code> "
            "mavjud emas. Kutubxonani yangilang: <code>pip install --upgrade pyTelegramBotAPI</code>",
        )
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ Qaytarishda xatolik: {e}")


