def _pay_notify_granted(message, res):
    """Berish allaqachon COMMIT qilingan — bu faqat xabar yuborish (xato bo'lsa ham to'lov saqlanadi)."""
    i, k = res.info, res.kind
    if k == "namestyle":
        _pay_send(message, f"🎉 To'lov muvaffaqiyatli o'tdi! Ism uslubingiz: {apply_name_style('Hunter', i['key'])} ({i['days']} kun faol).")
    elif k == "namecolor":
        emoji, label, _price, days = NAME_COLOR_CATALOG[i["key"]]
        _pay_send(message, f"🎉 To'lov muvaffaqiyatli o'tdi! Ism rangingiz: {emoji} {label} ({days} kun faol).")
    elif k == "hc":
        _pay_send(message, f"✅ To'lov muvaffaqiyatli o'tdi! +{i['qty']} 🪙 Hunter Coin hisobingizga qo'shildi.\nRahmat!")
    elif k == "diamondbuy":
        _pay_send(message, f"✅ To'lov muvaffaqiyatli o'tdi! +{i['qty']} 💎 Olmos hisobingizga qo'shildi.\nRahmat!")
    elif k == "dollarbuy":
        _pay_send(message, f"✅ To'lov muvaffaqiyatli o'tdi! +{i['qty']} 💵 Dollar hisobingizga qo'shildi.\nRahmat!")
    elif k == "elitepay":
        _pay_send(message, elite_success_text(i["days"], i["new_until"]))
    elif k == "elitegift":
        _pay_send(message, f"✅ To'lov muvaffaqiyatli o'tdi! {esc(user_dict(i['target'])['name'])} ga {i['days']} kunlik 👑 ELITE sovg'a qilindi.")
        safe_send(i["target"], f"🎁 {mention(i['buyer'], user_dict(i['buyer'])['name'])} sizga <b>{i['days']} kunlik 👑 ELITE</b> sovg'a qildi!\n"
                  + elite_success_text(i["days"], i["new_until"]))
    elif k == "herobuy":
        if i.get("hero_granted"):
            _pay_send(message, f"🎉 To'lov muvaffaqiyatli o'tdi! {HEROES[i['key']]['name']} endi sizniki!\n/geroyim orqali ko'ring.")
        else:
            _pay_send(message, f"✅ To'lov qabul qilindi. Sizda allaqachon geroy borligi uchun {i.get('compensation', 0)} 💎 olmos berildi.")
    elif k == "herolv":
        if i.get("level_granted"):
            _pay_send(message, f"🎉 To'lov muvaffaqiyatli o'tdi! Geroyingiz {i['level']}-darajaga ko'tarildi!")
        else:
            _pay_send(message, f"✅ To'lov qabul qilindi. Daraja allaqachon o'zgargani uchun {i.get('compensation', 0)} 💎 olmos berildi.")
    elif k == "cosmetic":
        _pay_send(message, f"🎉 To'lov muvaffaqiyatli o'tdi! {i.get('emoji') or ''} <b>{i.get('name')}</b> endi sizniki!")
    else:
        _pay_send(message, "✅ To'lov muvaffaqiyatli o'tdi!")
    inviter = i.get("referral_inviter")
    if inviter is not None:
        add_balance(inviter, dollar=REFERRAL_FIRST_PURCHASE_BONUS)
        safe_send(inviter, f"💵 {mention(res.uid or message.from_user.id, user_dict(message.from_user.id)['name'])} (siz taklif qilgan do'stingiz) "
                           f"birinchi xaridini qildi — sizga +{REFERRAL_FIRST_PURCHASE_BONUS}$ faollashtirish bonusi berildi!")


@bot.message_handler(content_types=["successful_payment"])
def successful_payment_handler(message):
    """Telegram TASDIQLAGAN to'lov. Idempotent (charge_id bo'yicha UNIQUE) va atomik:
    berish + qayd + homiylik hisobi + referal bonus bitta tranzaksiyada. Qayta kelgan
    update ikkinchi marta HECH NARSA bermaydi. Mantiq: payments_idempotent.py"""
    sp = message.successful_payment
    uid = message.from_user.id
    try:
        res = _PAY.process_successful_payment(
            charge_id=sp.telegram_payment_charge_id, payer_id=uid, currency=sp.currency,
            total_amount=sp.total_amount, payload=sp.invoice_payload,
            provider_charge_id=getattr(sp, "provider_payment_charge_id", None))
    except Exception as e:
        # DB umuman yozilmadi — charge_id'ni owner'ga beramiz, qo'lda hal qilinadi.
        notify_owner_of_error(
            f"successful_payment: to'lov QAYD ETILMADI (uid={uid}, charge_id={getattr(sp, 'telegram_payment_charge_id', None)}, "
            f"payload={getattr(sp, 'invoice_payload', None)})", e)
        _pay_send(message, "✅ To'lovingiz qabul qilindi, ammo buyumni avtomatik berib bo'lmadi. Bot egasi tez orada hal qiladi.")
        return
    if sp.telegram_payment_charge_id:
        try:  # eski /refund bilan moslik (payments jadvali asosiy manba)
            set_setting(f"last_charge_{uid}", sp.telegram_payment_charge_id)
        except Exception:
            _logger.warning("last_charge saqlanmadi (uid=%s)", uid, exc_info=True)

    if res.status == "granted" and res.newly_granted:
        try:
            _pay_notify_granted(message, res)
        except Exception:
            _logger.warning("to'lov xabari yuborilmadi (uid=%s, charge=%s)", uid, res.charge_id, exc_info=True)
    elif res.status == "duplicate":
        _logger.info("successful_payment: takroriy update e'tiborsiz (charge=%s, holat=%s)", res.charge_id, res.db_status)
    else:  # pending | needs_review | rejected — to'lov bor, lekin avtomatik berilmadi
        notify_owner_of_error(
            f"successful_payment: holat={res.status} (uid={uid}, charge_id={res.charge_id}, payload={sp.invoice_payload}, "
            f"summa={sp.total_amount} {sp.currency}) sabab: {res.error}", RuntimeError(res.error or res.status))
        _pay_send(message, "✅ To'lovingiz qabul qilindi, ammo buyumni avtomatik berib bo'lmadi. "
                           "Bot egasi tez orada hal qiladi. To'lov yo'qolmaydi.")


def _pay_retry_pending_and_notify():
    """'received' holatida qolgan to'lovlarni qayta uradi (masalan, jarayon berish paytida o'chgan bo'lsa)."""
    try:
        for res in _PAY.retry_pending():
            if res.status == "granted" and res.newly_granted:
                class _M:  # minimal "message" — faqat chat.id va from_user kerak
                    pass
                m = _M(); m.chat = type("C", (), {"id": res.uid})(); m.from_user = type("U", (), {"id": res.uid})()
                _pay_notify_granted(m, res)
            elif res.status == "needs_review":
                notify_owner_of_error(f"payments: qayta urinish natijasi needs_review (charge={res.charge_id})",
                                      RuntimeError(res.error or "needs_review"))
    except Exception:
        _logger.exception("payments.retry_pending xatolik")


_pay_retry_timer = threading.Timer(30.0, _pay_retry_pending_and_notify)
_pay_retry_timer.daemon = True   # jarayonni to'xtatishni kechiktirmasin
_pay_retry_timer.start()


@bot.message_handler(commands=["tolov_holat"])
def cmd_payment_status(message):
    """👑 Owner: to'lovlar holati + qolib ketganlarini qayta urinish. /tolov_holat [retry]"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    try:
        with db_lock:
            rows = cur.execute("SELECT status, COUNT(*) FROM payments GROUP BY status").fetchall()
            stuck = cur.execute("SELECT charge_id, user_id, kind, status, attempts, error FROM payments "
                                "WHERE status IN ('received','needs_review') ORDER BY id DESC LIMIT 15").fetchall()
    except Exception:
        rows, stuck = [], []
    lines = ["💳 <b>To'lovlar holati</b>", ", ".join(f"{s}: {n}" for s, n in rows) or "hali to'lov yo'q"]
    for cid, u, k, st, att, err in stuck:
        lines.append(f"• <code>{esc(cid)}</code> uid={u} {k} [{st}, urinish {att}] {esc((err or '')[:80])}")
    if len(message.text.split()) > 1 and message.text.split()[1] == "retry":
        _pay_retry_pending_and_notify()
        lines.append("🔁 Qayta urinish bajarildi.")
    bot.send_message(message.chat.id, "\n".join(lines))


