# Bot egasidan .json faylni kutayotgan (shaxsiy chatdagi) userlar to'plami
ADMIN_AWAITING_RESTORE = set()
# 3D manifestni GitHub/SSH orqali emas, botning o'ziga admin fayl sifatida yuborish
# uchun kutish holati. Fayl DB_DIR ichida saqlanadi (Railway Volume bo'lsa persistent).
ADMIN_AWAITING_3D_JSON = set()
THREED_MANIFEST_PATH = None  # JSON alohida fayl sifatida talab qilinmaydi; DB settingda saqlanadi.

@bot.message_handler(commands=["3d_yuklash", "3d_json"])
def cmd_3d_json_upload(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    ADMIN_AWAITING_3D_JSON.add(message.from_user.id)
    bot.send_message(
        message.chat.id,
        "📦 <b>3D JSON yuklash</b>\n\n"
        "Endi <code>3d_quality_manifest.json</code> faylini shu chatga <b>Document/Fayl</b> sifatida yuboring.\n"
        "Bot uni serverning doimiy papkasiga saqlaydi. GitHub'ga qo'lda yuklash shart emas.\n\n"
        "⚠️ Faqat <b>.json</b> fayl qabul qilinadi.",
    )

@bot.message_handler(content_types=["document"])
def handle_3d_manifest_document(message):
    maybe_capture_owner(message.from_user)
    uid = message.from_user.id
    if oc_try_restore_document(message):   # 👑 OWNER CENTER sozlamalarini tiklash
        return
    if message.chat.type != "private" or uid not in ADMIN_AWAITING_3D_JSON:
        return
    ADMIN_AWAITING_3D_JSON.discard(uid)

    doc = message.document
    filename = (doc.file_name or "").strip()
    if not filename.lower().endswith(".json"):
        bot.send_message(message.chat.id, "❌ Bu JSON fayl emas. Qaytadan /3d_yuklash deb yozing.")
        return
    try:
        file_info = bot.get_file(doc.file_id)
        raw = bot.download_file(file_info.file_path)
        if len(raw) > 5 * 1024 * 1024:
            raise ValueError("JSON fayl 5 MB dan katta")
        data = json.loads(raw.decode("utf-8"))
        if not isinstance(data, (dict, list)):
            raise ValueError("JSON object yoki array bo'lishi kerak")

        # 📦 Manifestni diskka alohida fayl qilib yozmaymiz: faqat DB sozlamasida saqlaymiz.
        # Shuning uchun deploy uchun PY + HTML kifoya qiladi.
        set_setting("3d_manifest_json", json.dumps(data, ensure_ascii=False, separators=(",", ":")))

        size_kb = max(1, len(raw) // 1024)
        if isinstance(data, dict):
            shape = f"object · {len(data)} ta kalit"
        else:
            shape = f"array · {len(data)} ta element"
        bot.send_message(
            message.chat.id,
            "✅ <b>3D JSON muvaffaqiyatli qabul qilindi!</b>\n\n"
            f"📄 Fayl: <code>3d_quality_manifest.json</code>\n"
            f"📦 Hajmi: <b>{size_kb} KB</b>\n"
            f"🧩 Tuzilishi: <b>{shape}</b>\n"
            "📍 Bot bazasida saqlandi.\n\n"
            "Endi GitHub'ga JSONni alohida yuklash shart emas.",
        )
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ 3D JSON qabul qilinmadi: <code>{_html.escape(str(e), quote=False)}</code>")

