@bot.message_handler(content_types=["document"])
def handle_restore_document(message):
    maybe_capture_owner(message.from_user)
    uid = message.from_user.id
    # faqat bot egasidan, faqat /bazani_tikla dan keyin va faqat shaxsiy chatda kutamiz —
    # aks holda bu handler guruhlardagi oddiy fayl yuborishlarga aralashmasligi kerak
    if message.chat.type != "private" or uid not in ADMIN_AWAITING_RESTORE:
        return
    ADMIN_AWAITING_RESTORE.discard(uid)

    doc = message.document
    if not doc or not (doc.file_name or "").lower().endswith(".json"):
        bot.send_message(message.chat.id, "❌ Bu .json fayl emas. Tiklash bekor qilindi — qaytadan /bazani_tikla deb yozing.")
        return

    try:
        file_info = bot.get_file(doc.file_id)
        raw = bot.download_file(file_info.file_path)
        data = json.loads(raw.decode("utf-8"))
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ Faylni o'qib bo'lmadi: {e}")
        return

    if not isinstance(data, (list, dict)):
        bot.send_message(message.chat.id, "❌ Fayl formati noto'g'ri — JSON ro'yxat yoki lug'at bo'lishi kerak.")
        return

    # 🔧 Eski formatdagi backup (oddiy list) — faqat foydalanuvchilar bazasi.
    # Yangi formatdagi backup (dict, backup_version:2) — users + heroes + hero_ability_log.
    if isinstance(data, list):
        users_data, heroes_data, hero_log_data = data, [], []
    else:
        users_data = data.get("users", [])
        heroes_data = data.get("heroes", [])
        hero_log_data = data.get("hero_ability_log", [])

    restored = 0
    skipped = 0
    placeholders = ",".join(["?"] * len(USER_COLS))
    col_list = ",".join(USER_COLS)

    with db_lock:
        for entry in users_data:
            if not isinstance(entry, dict) or entry.get("user_id") in (None, ""):
                skipped += 1
                continue
            try:
                row_values = [entry.get(col) for col in USER_COLS]
                row_values[0] = int(entry["user_id"])  # user_id har doim int bo'lishi shart
                cur.execute(f"INSERT OR REPLACE INTO users ({col_list}) VALUES ({placeholders})", row_values)
                restored += 1
            except Exception:
                skipped += 1
        conn.commit()

    heroes_restored, heroes_skipped = 0, 0
    with db_lock:
        for entry in heroes_data:
            if not isinstance(entry, dict) or entry.get("user_id") in (None, ""):
                heroes_skipped += 1
                continue
            try:
                cur.execute(
                    "INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, ?, ?, ?, ?)",
                    (int(entry["user_id"]), entry.get("hero_key"), entry.get("level", 1),
                     entry.get("acquired_at", 0), entry.get("temp_until", 0)),
                )
                heroes_restored += 1
            except Exception:
                heroes_skipped += 1
        conn.commit()

    log_restored = 0
    with db_lock:
        for entry in hero_log_data:
            if not isinstance(entry, dict) or entry.get("user_id") in (None, ""):
                continue
            try:
                cur.execute(
                    "INSERT INTO hero_ability_log (user_id, hero_key, ability_name, used_at) VALUES (?, ?, ?, ?)",
                    (int(entry["user_id"]), entry.get("hero_key"), entry.get("ability_name"), entry.get("used_at", 0)),
                )
                log_restored += 1
            except Exception:
                pass
        conn.commit()

    bot.send_message(
        message.chat.id,
        "✅ <b>Tiklash yakunlandi!</b>\n"
        f"👥 Tiklangan/yangilangan (foydalanuvchilar): {restored} ta\n"
        f"⚠️ O'tkazib yuborilgan: {skipped} ta\n"
        f"🏆 Tiklangan geroylar: {heroes_restored} ta (o'tkazib yuborilgan: {heroes_skipped} ta)\n"
        f"📜 Tiklangan geroy-tarixi yozuvlari: {log_restored} ta",
    )


_PENDING_SENDALL = {}  # owner_id -> xabar matni (Theron ruxsat so'rab kutayotgan ommaviy xabar)


@bot.message_handler(commands=["sendall"])
def cmd_sendall(message):
    """👑 Ommaviy xabar — MUHIM amal bo'lgani uchun endi darhol yuborilmaydi:
    Theron avval xabar matnini ko'rsatib, egadan ANIQ tasdiq (tugma orqali)
    so'raydi, faqat "Ha" bosilgandan keyin haqiqiy yuborish boshlanadi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, "Foydalanish: <code>/sendall Xabar matni</code>")
        return
    text = parts[1]
    uid = message.from_user.id

    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users")
        total = cur.fetchone()[0]

    _PENDING_SENDALL[uid] = text
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("✅ Ha, yuborilsin", callback_data="sendall_confirm|yes"),
        types.InlineKeyboardButton("❌ Bekor qilish", callback_data="sendall_confirm|no"),
    )
    theron_note = (
        f"🧠 <b>{THERON_NAME}:</b> Xo'jayin, <b>{total} ta</b> foydalanuvchiga quyidagi xabarni yuborishni "
        "so'rayapsiz — tasdiqlaysizmi?\n\n"
        f"📢 <i>\"{text}\"</i>\n\n"
        "Xato bo'lsa, «❌ Bekor qilish» tugmasini bosing."
    )
    bot.send_message(message.chat.id, theron_note, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("sendall_confirm|"))
def cb_sendall_confirm(call):
    uid = call.from_user.id
    if not is_owner(uid):
        bot.answer_callback_query(call.id, "⛔ Bu buyruq faqat bot egasi uchun.", show_alert=True)
        return
    decision = call.data.split("|", 1)[1]
    text = _PENDING_SENDALL.pop(uid, None)
    if decision == "no" or not text:
        bot.answer_callback_query(call.id, "❌ Bekor qilindi.")
        try:
            bot.edit_message_text("❌ Ommaviy xabar bekor qilindi.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        return

    bot.answer_callback_query(call.id, "✅ Yuborilmoqda...")
    try:
        bot.edit_message_text("⏳ Xabar yuborilmoqda, biroz kuting...", call.message.chat.id, call.message.message_id)
    except Exception:
        pass

    with db_lock:
        cur.execute("SELECT user_id FROM users")
        user_ids = [r[0] for r in cur.fetchall()]
    sent, failed = 0, 0
    for target_uid in user_ids:
        if broadcast_opted_out(target_uid):
            continue   # 🔕 foydalanuvchi e'lonlarni o'chirib qo'ygan
        try:
            bot.send_message(target_uid, f"📢 <b>E'lon:</b>\n\n{text}")
            sent += 1
        except Exception:
            failed += 1
        time.sleep(0.05)  # ⏱ Telegram'ning 429 (Too Many Requests) chegarasiga tegib ketmaslik uchun
    bot.send_message(
        call.message.chat.id,
        f"📢 Xabar yuborildi: {sent} ta muvaffaqiyatli, {failed} ta yetib bormadi.\n\n"
        f"🧠 <b>{THERON_NAME}:</b> Vazifa bajarildi, xo'jayin! ✅",
    )


