COSMETIC_CURRENCY_ICON = {"stars": "⭐️", "dollar": "💵", "coin": "🪙"}


def _perform_cosmetic_buy(uid, first_name, cosmetic_id):
    with db_lock:
        cur.execute("SELECT id, kind, name, emoji, price, currency, stock, sold, active FROM cosmetics WHERE id=?", (cosmetic_id,))
        row = cur.fetchone()
    if not row:
        return {"status": "fail", "msg": "❌ Bunday kosmetika topilmadi."}
    cid, kind, name, emoji, price, currency, stock, sold, active = row
    if not active or sold >= stock:
        return {"status": "fail", "msg": "❌ Bu buyum sotuvdan tugagan yoki olib tashlangan."}
    with db_lock:
        cur.execute("SELECT 1 FROM user_cosmetics WHERE user_id=? AND cosmetic_id=?", (uid, cid))
        already = cur.fetchone()
    if already:
        return {"status": "fail", "msg": "✅ Bu buyum sizda allaqachon bor."}
    if currency == "stars":
        return {"status": "need_stars", "id": cid, "name": name, "emoji": emoji, "price": price}
    u = user_dict(uid, first_name)
    if currency == "dollar":
        if u["dollar"] < price:
            return {"status": "fail", "msg": f"❌ Yetarli Dollar yo'q. Kerak: {price} 💵"}
        add_balance(uid, dollar=-price)
    elif currency == "coin":
        if u["coin"] < price:
            return {"status": "fail", "msg": f"❌ Yetarli Hunter Coin yo'q. Kerak: {price} 🪙"}
        add_balance(uid, coin=-price)
    else:
        return {"status": "fail", "msg": "❌ Noma'lum valyuta."}
    with db_lock:
        cur.execute("UPDATE cosmetics SET sold = sold + 1 WHERE id=?", (cid,))
        cur.execute("INSERT OR IGNORE INTO user_cosmetics (user_id, cosmetic_id, purchased_at) VALUES (?,?,?)",
                    (uid, cid, time.strftime("%Y-%m-%d %H:%M")))
        conn.commit()
    return {"status": "ok", "msg": f"🎉 Tabriklaymiz! {emoji} <b>{name}</b> endi sizniki!"}


@bot.message_handler(commands=["skin_katalog"])
def cmd_skin_katalog(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    lines = ["✨ <b>Kosmetika katalogi</b> — sotuvga qo'yish uchun kodini tanlang:"]
    for label, prefix in (("\n🖼 <b>RAMKALAR</b>", "F"), ("\n🎬 <b>ANIMATSIYALAR</b>", "A"), ("\n🎨 <b>SKINLAR (fon)</b>", "S")):
        lines.append(label)
        for code, item in COSMETIC_CATALOG.items():
            if code.startswith(prefix):
                lines.append(f"<code>{code}</code> — {item['emoji']} {item['name']}")
    lines.append(
        "\n\n📌 Sotuvga qo'yish: <code>/skin_sot F3 15 stars 25</code>\n"
        "(kod | narx | valyuta: stars/dollar/coin | nechta dona — limitli tiraj)"
    )
    bot.send_message(message.chat.id, "\n".join(lines))


@bot.message_handler(commands=["skin_sot"])
def cmd_skin_sot(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    parts = message.text.split()
    if len(parts) != 5:
        bot.send_message(message.chat.id, "Foydalanish: <code>/skin_sot F3 15 stars 25</code>\n(kod narx valyuta soni)")
        return
    _, code, price_s, currency, stock_s = parts
    code = code.upper()
    currency = currency.lower()
    item = COSMETIC_CATALOG.get(code)
    if not item:
        bot.send_message(message.chat.id, f"❌ <code>{code}</code> katalogda topilmadi. /skin_katalog orqali ko'ring.")
        return
    if currency not in ("stars", "dollar", "coin"):
        bot.send_message(message.chat.id, "❌ Valyuta faqat: stars, dollar yoki coin bo'lishi kerak.")
        return
    try:
        price = int(price_s)
        stock = int(stock_s)
        assert price > 0 and stock > 0
    except Exception:
        bot.send_message(message.chat.id, "❌ Narx va soni musbat butun son bo'lishi kerak.")
        return
    with db_lock:
        cur.execute(
            "INSERT INTO cosmetics (kind, catalog_code, name, emoji, price, currency, stock, sold, active, created_at) "
            "VALUES (?,?,?,?,?,?,?,0,1,?)",
            (item["kind"], code, item["name"], item["emoji"], price, currency, stock, time.strftime("%Y-%m-%d %H:%M")),
        )
        conn.commit()
        new_id = cur.lastrowid
    cur_icon = COSMETIC_CURRENCY_ICON[currency]
    bot.send_message(
        message.chat.id,
        f"✅ Sotuvga qo'yildi! ID: <code>{new_id}</code>\n"
        f"{item['emoji']} {item['name']} — {price}{cur_icon} — {stock} dona (limitli tiraj)",
    )


@bot.message_handler(commands=["skin_royxat"])
def cmd_skin_royxat(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
        return
    with db_lock:
        cur.execute("SELECT id, name, emoji, price, currency, stock, sold, active FROM cosmetics ORDER BY id DESC")
        rows = cur.fetchall()
    if not rows:
        bot.send_message(message.chat.id, "Hozircha sotuvga qo'yilgan kosmetika yo'q. /skin_katalog dan tanlang.")
        return
    lines = ["✨ <b>Sotuvdagi kosmetika</b>:"]
    for cid, name, emoji, price, currency, stock, sold, active in rows:
        left = stock - sold
        status = "✅ FAOL" if active and left > 0 else ("⛔ TUGADI" if left <= 0 else "🚫 O'CHIRILGAN")
        cur_icon = COSMETIC_CURRENCY_ICON.get(currency, "")
        lines.append(f"<code>{cid}</code> — {emoji} {name} — {price}{cur_icon} — {left}/{stock} qoldi — {status}")
    bot.send_message(message.chat.id, "\n".join(lines))


