GIVEAWAYS = {}
GIVEAWAY_CURRENCY_ICON = {"dollar": "💵", "diamond": "💎", "coin": "🪙"}


@bot.message_handler(commands=["tarqatish"])
@bot.channel_post_handler(commands=["tarqatish"])
def cmd_tarqatish(message):
    if cmd_is_for_other_bot(getattr(message, "text", None)):
        return   # boshqa botga yo'llangan buyruq
    # Diamond/dollar/coin tarqatish huquqi FAQAT bot yaratuvchisiga tegishli —
    # guruh admini yoki vaqtinchalik admin buyumi bu buyruqqa yetarli emas.
    if is_owner_channel(message.chat):
        pass  # tasdiqlangan owner kanalidan — ruxsat berilgan
    else:
        maybe_capture_owner(message.from_user)
        safe_delete(message)
        if not is_owner(message.from_user.id):
            bot.send_message(message.chat.id, "⛔ Bu buyruqni faqat bot yaratuvchisi ishlatishi mumkin.")
            return
    parts = message.text.split()
    # 🎁 Buyum tarqatish: /tarqatish item <inventar_raqami | do'kon_kaliti> <necha_kishiga>
    if len(parts) >= 2 and parts[1].lower() in ("item", "buyum"):
        _start_item_giveaway(message, parts)
        return
    if len(parts) != 4 or parts[1] not in GIVEAWAY_CURRENCY_ICON or not parts[2].isdigit() or not parts[3].isdigit():
        bot.send_message(
            message.chat.id,
            "Foydalanish: <code>/tarqatish &lt;dollar|diamond|coin&gt; &lt;har_biriga&gt; &lt;necha_kishiga&gt;</code>\n"
            "Masalan: <code>/tarqatish diamond 5 10</code> — 10 kishiga 5 tadan olmos.\n\n"
            "🎁 Buyum tarqatish: <code>/tarqatish item &lt;inventar_raqami&gt; &lt;necha_kishiga&gt;</code>\n"
            "Inventaringizdagi buyumlar ro'yxati: <code>/tarqatish item</code>",
        )
        return
    currency, per_person, people_count = parts[1], int(parts[2]), int(parts[3])
    chat_id = message.chat.id
    icon = GIVEAWAY_CURRENCY_ICON[currency]

    gw = {
        "kind": "currency",
        "currency": currency,
        "per_person": per_person,
        "remaining": people_count,
        "total": people_count,
        "claimed": set(),
        "claimed_order": [],
        "message_id": None,
    }
    sent = bot.send_message(
        chat_id,
        f"🎉 <b>SOVG'A TARQATISH BOSHLANDI!</b>\n\n"
        f"Har bir ishtirokchiga: {icon} <b>{per_person} {currency}</b>\n"
        f"Jami: <b>{people_count}</b> kishiga yetadi.\n\n"
        f"👇 Tez bo'ling, tugmani bosing!",
        reply_markup=_giveaway_markup(chat_id, gw, icon),
    )
    gw["message_id"] = sent.message_id
    GIVEAWAYS[chat_id] = gw


def _gw_label(gw):
    """Sovg'aning qisqa nomi (valyuta yoki buyum)."""
    if gw.get("kind") == "item":
        return f"{gw['item_name']}"
    return f"{GIVEAWAY_CURRENCY_ICON[gw['currency']]} {gw['per_person']} {gw['currency']}"


def _start_item_giveaway(message, parts):
    """🎁 Owner inventaridagi (yoki do'kondagi) buyumni tarqatish."""
    chat_id = message.chat.id
    uid = message.from_user.id if message.from_user else None
    inv = []
    try:
        if uid:
            inv = json.loads(user_dict(uid)["inventory"] or "[]")
    except Exception:
        inv = []
    if len(parts) < 4:
        lines = [f"{i + 1}. {n}" for i, n in enumerate(inv)] or ["(inventar bo'sh)"]
        keys = ", ".join(f"{c}:{k}" for c, (_t, its) in SHOP_CATEGORIES.items() for k in its)
        bot.send_message(
            chat_id,
            "🎁 <b>Buyum tarqatish</b>\n\n<b>Inventaringiz:</b>\n" + "\n".join(lines[:60]) +
            "\n\nFoydalanish: <code>/tarqatish item &lt;raqam&gt; &lt;necha_kishiga&gt;</code>\n"
            "yoki do'kon kaliti bilan: <code>/tarqatish item dollar:himoya 5</code>\n"
            f"<i>Kalitlar:</i> <code>{keys[:1200]}</code>",
        )
        return
    spec, cnt_s = parts[2], parts[3]
    if not cnt_s.isdigit() or int(cnt_s) <= 0:
        bot.send_message(chat_id, "❌ Kishi soni musbat son bo'lishi kerak.")
        return
    people_count = int(cnt_s)
    cat = key = None
    item_name = None
    if spec.isdigit():
        idx = int(spec) - 1
        if idx < 0 or idx >= len(inv):
            bot.send_message(chat_id, "❌ Inventarda bunday raqamli buyum yo'q. /tarqatish item — ro'yxatni ko'rish.")
            return
        item_name = inv[idx]
        if item_name in ITEM_NAME_TO_SHOPKEY:
            cat, key = ITEM_NAME_TO_SHOPKEY[item_name]
    else:
        if ":" in spec:
            cat, key = spec.split(":", 1)
        else:
            for c, (_t, its) in SHOP_CATEGORIES.items():
                if spec in its:
                    cat, key = c, spec
                    break
        if cat in SHOP_CATEGORIES and key in SHOP_CATEGORIES[cat][1]:
            item_name = SHOP_CATEGORIES[cat][1][key]["name"]
        else:
            cat = key = None
    if not (cat and key and item_name):
        bot.send_message(chat_id, "❌ Bu buyumni tarqatib bo'lmaydi (do'kon buyumi emas).")
        return
    gw = {
        "kind": "item",
        "item_name": item_name,
        "cat": cat,
        "key": key,
        "currency": SHOP_CATEGORIES[cat][1][key]["currency"],
        "per_person": 1,
        "remaining": people_count,
        "total": people_count,
        "claimed": set(),
        "claimed_order": [],
        "message_id": None,
    }
    sent = bot.send_message(
        chat_id,
        f"🎁 <b>BUYUM TARQATISH BOSHLANDI!</b>\n\n"
        f"Sovg'a: <b>{item_name}</b>\n"
        f"Jami: <b>{people_count}</b> kishiga yetadi.\n\n"
        f"👇 Tez bo'ling, tugmani bosing!",
        reply_markup=_giveaway_markup(chat_id, gw, ""),
    )
    gw["message_id"] = sent.message_id
    GIVEAWAYS[chat_id] = gw


def _gift_shop_item(uid, name, cat, key):
    """Do'kon buyumini TEKINGA beradi: narxini vaqtincha qo'shib, xarid qildiradi."""
    item = SHOP_CATEGORIES[cat][1][key]
    cur_name, price = item["currency"], item["price"]
    user_dict(uid, name)
    add_balance_as('refund', uid, ledger=False, **{cur_name: price})
    try:
        ok, msg = _perform_shop_purchase(uid, name, cat, key)
    except Exception:
        _logger.exception("_gift_shop_item: xarid bajarilmadi (uid=%s, cat=%s, key=%s)", uid, cat, key)
        ok, msg = False, "Buyumni berib bo'lmadi. Birozdan keyin qayta urinib ko'ring."
    if not ok:
        try:
            clawed_back = try_charge(uid, cur_name, price)   # qo'shilgan narxni qaytarib olamiz
        except Exception:
            clawed_back = False
            _logger.exception("_gift_shop_item: qo'shilgan narxni qaytarib olishda xato (uid=%s)", uid)
        if not clawed_back:
            # Foydalanuvchi vaqtincha qo'shilgan pulni sarflab ulgurgan bo'lishi mumkin — yo'qotish ko'rinib tursin.
            _logger.error("_gift_shop_item: %s %s qaytarib olinmadi (uid=%s)", price, cur_name, uid)
    return ok, msg


def _giveaway_markup(chat_id, gw, icon):
    """Faqat 'olish' tugmasi. Olganlar ro'yxati xabar MATNIDA chiqadi (tugma emas)."""
    kb = types.InlineKeyboardMarkup()
    if gw["remaining"] > 0:
        if gw.get("kind") == "item":
            label = f"🎁 {gw['item_name']} olish"
        else:
            label = f"{icon} {gw['per_person']} {gw['currency']} olish"
        kb.add(types.InlineKeyboardButton(label, callback_data=f"gw|{chat_id}"))
    return kb


@bot.callback_query_handler(func=lambda c: c.data == "gw_noop")
def cb_giveaway_noop(call):
    bot.answer_callback_query(call.id, "🎁 Bu ishtirokchi allaqachon sovg'a oldi.")


@bot.callback_query_handler(func=lambda c: c.data.startswith("gw|"))
def cb_giveaway(call):
    maybe_capture_owner(call.from_user)
    _, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    gw = GIVEAWAYS.get(chat_id)
    uid = call.from_user.id

    if not gw:
        bot.answer_callback_query(call.id, "🎉 Tarqatish yakunlangan.")
        return

    # "Tekshir + da'vo qil" bitta lock ichida — aks holda ikki parallel bosish
    # ikkalasiga ham sovg'a berib, remaining'ni manfiyga tushirib yuborishi mumkin.
    with db_lock:
        if uid in gw["claimed"]:
            bot.answer_callback_query(call.id, "❌ Siz allaqachon oldingiz!", show_alert=True)
            return
        if gw["remaining"] <= 0:
            bot.answer_callback_query(call.id, "😔 Afsuski, hammasi tugadi.", show_alert=True)
            return
        name = call.from_user.first_name or "O'yinchi"
        gw["claimed"].add(uid)
        gw["claimed_order"].append((uid, name))
        gw["remaining"] -= 1

    user_dict(uid, name)
    icon = GIVEAWAY_CURRENCY_ICON[gw["currency"]]
    if gw.get("kind") == "item":
        ok, _msg = _gift_shop_item(uid, name, gw["cat"], gw["key"])
        if not ok:
            with db_lock:   # berib bo'lmadi — o'rin qaytariladi
                gw["claimed"].discard(uid)
                gw["claimed_order"] = [x for x in gw["claimed_order"] if x[0] != uid]
                gw["remaining"] += 1
            bot.answer_callback_query(call.id, "❌ Buyumni berib bo'lmadi, keyinroq urinib ko'ring.", show_alert=True)
            return
        bot.answer_callback_query(call.id, f"🎁 Siz {gw['item_name']} yutib oldingiz! Inventaringizga tushdi.", show_alert=True)
        icon = "🎁"
        per_txt = f"<b>{gw['item_name']}</b>"
    else:
        add_balance_as('owner', uid, **{gw["currency"]: gw["per_person"]})
        bot.answer_callback_query(call.id, f"🎉 Siz {icon} {gw['per_person']} {gw['currency']} yutib oldingiz!", show_alert=True)
        per_txt = f"{icon} <b>{gw['per_person']} {gw['currency']}</b>"

    # 🎁 Olganlar ro'yxati: "1) Ism 1💎" ko'rinishida (ism ortidan miqdor). Ro'yxat uzun bo'lsa
    # (Telegram 4096 belgi chegarasi) faqat birinchi 35 tasi, qolgani "va boshqa N ta kishi".
    if gw.get("kind") == "item":
        _each = f"{icon} {gw['item_name']}"
    else:
        _each = f"{gw['per_person']}{icon}"
    _GW_SHOW = 35
    claimed_lines = "\n".join(f"{i}) {mention(u, n)} {_each}"
                              for i, (u, n) in enumerate(gw["claimed_order"][:_GW_SHOW], start=1))
    if len(gw["claimed_order"]) > _GW_SHOW:
        claimed_lines += f"\nva boshqa {len(gw['claimed_order']) - _GW_SHOW} ta kishi"
    if gw["remaining"] <= 0:
        try:
            bot.edit_message_text(
                f"🎉 <b>SOVG'A TARQATISH YAKUNLANDI!</b>\n\n"
                f"Barcha sovg'alar ({per_txt}) {len(gw['claimed'])} kishiga tarqatildi. Rahmat, ishtirok etganlarga!\n\n"
                f"{claimed_lines}",
                chat_id, gw["message_id"],
                reply_markup=_giveaway_markup(chat_id, gw, icon),
            )
        except Exception:
            pass
        GIVEAWAYS.pop(chat_id, None)
    else:
        try:
            bot.edit_message_text(
                f"🎉 <b>SOVG'A TARQATISH DAVOM ETMOQDA!</b>\n\n"
                f"Har bir ishtirokchiga: {per_txt}\n"
                f"Qolgan o'rinlar: <b>{gw['remaining']}</b>\n\n"
                f"👇 Tez bo'ling, tugmani bosing!\n\n"
                f"{claimed_lines}",
                chat_id, gw["message_id"],
                reply_markup=_giveaway_markup(chat_id, gw, icon),
            )
        except Exception:
            pass


# ================================================================================
#  /top — reyting (matn buyrug'i sifatida ham, avval faqat tugma orqali ishlar edi)
# ================================================================================

# ================================================================================
#  🏆 REYTING MARKAZI — FAQAT BOT EGASI UCHUN
#  Bitta uslub, bitta mexanizm: Ball · Dollar · Olmos · Coin · G'alaba · O'yin · Guruh · Para.
#  Davr tugmalari (Bugun / Hafta / Oy / 30 kun / Hammasi), sahifalash, "Butun bot / Shu guruh".
#  Boshqa hech kim bu buyruqlarni ishlata olmaydi — ularga javob ham berilmaydi.
#  Davr bo'yicha hisob: ball — points_log, valyuta daromadi — top_ledger, guruh — group_points_log.
# ================================================================================
RK_PAGE_SIZE = 15
RK_MAX_ROWS = 150
RK_KIND_BTNS = [("ball", "🏅 Ball"), ("dollar", "💵 Dollar"), ("diamond", "💎 Olmos"), ("coin", "🪙 Coin"),
                ("wins", "🏆 G'alaba"), ("games", "🎮 O'yin"), ("guruh", "🏘 Guruh"), ("para", "💍 Para")]
_RK_CUR_PERIODS = ["bal", "kun", "hafta", "oy", "30k"]
RK_PERIODS_BY_KIND = {
    "ball": ["kun", "hafta", "oy", "30k", "mutlaq"],
    "dollar": _RK_CUR_PERIODS, "diamond": _RK_CUR_PERIODS, "coin": _RK_CUR_PERIODS,
    "wins": [], "games": [], "guruh": ["kun", "hafta", "oy", "30k", "mutlaq"], "para": [],
}
RK_DEFAULT_PERIOD = {"ball": "kun", "dollar": "bal", "diamond": "bal", "coin": "bal",
                     "wins": "-", "games": "-", "guruh": "oy", "para": "-"}
RK_PERIOD_LABELS = {"bal": "💰 Balans", "kun": "Bugun", "hafta": "Hafta", "oy": "Oy", "30k": "30 kun", "mutlaq": "Hammasi"}
_RK_CUR = {"dollar": ("💵", "DOLLAR"), "diamond": ("💎", "OLMOS"), "coin": ("🪙", "COIN")}
_RK_MEDALS = {1: "🥇", 2: "🥈", 3: "🥉"}

with db_lock:
    cur.execute("CREATE TABLE IF NOT EXISTS group_points_log (chat_id INTEGER NOT NULL, points INTEGER NOT NULL, ts REAL NOT NULL)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_gpl_ts ON group_points_log (ts)")
    conn.commit()
if not get_setting("group_points_log_since_txt"):
    set_setting("group_points_log_since_txt", time.strftime("%d.%m.%Y", time.gmtime(time.time() + TOP_TZ_OFFSET_HOURS * 3600)))


def _rk_since(per):
    now = time.time()
    if per == "30k":
        return now - 30 * 86400
    if per in ("kun", "hafta", "oy"):
        return _period_start(per, now)
    return 0


def _rk_num(v):
    return f"{int(v):,}".replace(",", " ")


def _rk_allowed(chat, user_id):
    """Faqat bot egasi (yoki egasining kanali). Boshqalar — rad, JAVOBSIZ."""
    try:
        if is_owner_channel(chat):
            return True
    except Exception:
        pass
    return bool(user_id) and is_owner(user_id)


def _rk_dur(secs):
    secs = int(secs)
    d, rem = divmod(secs, 86400)
    h, rem = divmod(rem, 3600)
    if d:
        return f"{d} kun" + (f" {h} soat" if h else "")
    return f"{h} soat {rem // 60} daqiqa" if h else f"{rem // 60} daqiqa"


def _rk_names(ids):
    out = {}
    ids = list(ids)
    for i in range(0, len(ids), 500):
        part = ids[i:i + 500]
        with db_lock:
            cur.execute(f"SELECT user_id, name FROM users WHERE user_id IN ({','.join('?' * len(part))})", part)
            for u, n in cur.fetchall():
                out[u] = n
    return out


def _rk_ball_rows(per, members):
    with db_lock:
        cur.execute("SELECT user_id, SUM(points) s FROM points_log WHERE ts>=? GROUP BY user_id HAVING s>0 ORDER BY s DESC", (_rk_since(per),))
        rows = cur.fetchall()
    ids = [u for u, _s in rows if not is_owner(u) and (members is None or u in members)][:RK_MAX_ROWS]
    sums = dict(rows)
    nm = _rk_names(ids)
    return [(u, nm.get(u) or "O'yinchi", f"{_rk_num(sums[u])} ball") for u in ids]


def _rk_currency_rows(kind, per, members):
    emoji = _RK_CUR[kind][0]
    if per == "bal":
        rows = get_top_by_field(kind, limit=RK_MAX_ROWS, member_ids=members)
        return [(u, n, f"{_rk_num(v)} {emoji}") for u, n, v in rows if (v or 0) > 0]
    rows = get_earned_top(kind, per, limit=RK_MAX_ROWS, member_ids=members)
    return [(u, n, f"+{_rk_num(v)} {emoji}") for u, n, v in rows]


def _rk_field_rows(field, suffix, members):
    rows = get_top_by_field(field, limit=RK_MAX_ROWS, member_ids=members)
    return [(u, n, f"{_rk_num(v)} {suffix}") for u, n, v in rows if (v or 0) > 0]


def _rk_group_rows(per):
    with db_lock:
        if per == "mutlaq":
            cur.execute("SELECT s.chat_id, COALESCE(k.title, ''), s.points, s.games FROM group_stats s "
                        "LEFT JOIN known_groups k ON k.chat_id = s.chat_id WHERE s.games > 0 "
                        "ORDER BY s.points DESC, s.games DESC LIMIT ?", (RK_MAX_ROWS,))
        else:
            cur.execute("SELECT g.chat_id, COALESCE(k.title, ''), SUM(g.points) sp, COUNT(*) FROM group_points_log g "
                        "LEFT JOIN known_groups k ON k.chat_id = g.chat_id WHERE g.ts>=? GROUP BY g.chat_id "
                        "ORDER BY sp DESC, COUNT(*) DESC LIMIT ?", (_rk_since(per), RK_MAX_ROWS))
        rows = cur.fetchall()
    return [(cid, title or str(cid), f"{_rk_num(pts)} ball · {int(games)} o'yin") for cid, title, pts, games in rows]


def _rk_para_rows(members):
    with db_lock:
        cur.execute("SELECT user_id, name, married_to, married_at FROM users WHERE married_to != 0 AND married_at != ''")
        rows = cur.fetchall()
    seen, pairs = set(), []
    for uid, name, pid, married_at in rows:
        key = tuple(sorted((uid, pid)))
        if key in seen:
            continue
        seen.add(key)
        if members is not None and uid not in members and pid not in members:
            continue
        secs = _married_seconds(married_at)
        if secs is None:
            continue
        pairs.append((secs, uid, name, pid))
    pairs.sort(key=lambda x: x[0], reverse=True)
    nm = _rk_names([p[3] for p in pairs[:RK_MAX_ROWS]])
    return [(uid, f"{mention(uid, name)} ❤️ {mention(pid, nm.get(pid) or 'Noma’lum')}", _rk_dur(secs))
            for secs, uid, name, pid in pairs[:RK_MAX_ROWS]]


def _rk_title(kind, per):
    if kind == "ball":
        return {"kun": "🕐 BUGUNGI ENG YAXSHI O'YINCHILAR", "hafta": "🗓 HAFTALIK ENG YAXSHI O'YINCHILAR",
                "oy": "📆 OYLIK ENG YAXSHI O'YINCHILAR", "30k": "📅 30 KUNLIK ENG YAXSHI O'YINCHILAR",
                "mutlaq": "♾ BARCHA VAQTDAGI ENG YAXSHI O'YINCHILAR"}[per]
    if kind in _RK_CUR:
        emoji, label = _RK_CUR[kind]
        if per == "bal":
            return f"{emoji} {label} BOYLAR"
        when = {"kun": "BUGUN", "hafta": "HAFTALIK", "oy": "OYLIK", "30k": "30 KUNLIK"}[per]
        return f"{emoji} {when} TOPILGAN {label}"
    if kind == "wins":
        return "🏆 ENG KO'P G'ALABA QOZONGANLAR"
    if kind == "games":
        return "🎮 ENG KO'P O'YNAGANLAR"
    if kind == "guruh":
        when = {"kun": "BUGUNGI", "hafta": "HAFTALIK", "oy": "OYLIK", "30k": "30 KUNLIK", "mutlaq": "BARCHA VAQTDAGI"}[per]
        return f"🏘 {when} ENG FAOL GURUHLAR"
    return "💍 ENG MUSTAHKAM JUFTLIKLAR"


def rk_norm(kind, per):
    if kind not in RK_PERIODS_BY_KIND:
        kind = "ball"
    periods = RK_PERIODS_BY_KIND[kind]
    if periods:
        if per not in periods:
            per = RK_DEFAULT_PERIOD[kind]
    else:
        per = "-"
    return kind, per


def rk_render(kind, per, scope_chat=None, page=0):
    """(matn, jami_sahifa, qatorlar_soni). scope_chat — guruh chat_id yoki None (butun bot)."""
    kind, per = rk_norm(kind, per)
    members = get_group_member_ids(scope_chat) if scope_chat is not None else None
    if kind == "ball":
        rows = _rk_ball_rows(per, members)
    elif kind in _RK_CUR:
        rows = _rk_currency_rows(kind, per, members)
    elif kind == "wins":
        rows = _rk_field_rows("wins", "g'alaba", members)
    elif kind == "games":
        rows = _rk_field_rows("games", "o'yin", members)
    elif kind == "guruh":
        rows = _rk_group_rows(per)
    else:
        rows = _rk_para_rows(members)
    now = time.time()
    local = time.gmtime(now + TOP_TZ_OFFSET_HOURS * 3600)
    head = f"<b>{_rk_title(kind, per)}</b>"
    sub = time.strftime("📅 %d.%m.%Y · 🕐 %H:%M", local)
    if scope_chat is not None and kind != "guruh":
        sub += " · 🏘 shu guruh"
    note = ""
    if (kind in _RK_CUR and per not in ("bal",)) or (kind == "guruh" and per != "mutlaq"):
        since = _ledger_since_text() if kind in _RK_CUR else get_setting("group_points_log_since_txt")
        if since:
            note = f"\n<i>📒 Hisob {since} dan yuritiladi — undan oldingi ma'lumot kirmaydi.</i>"
    if not rows:
        return f"{head}\n{sub}\n\nHozircha bu bo'limda reyting bo'sh.{note}", 1, 0
    total_pages = max(1, (len(rows) + RK_PAGE_SIZE - 1) // RK_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    start = page * RK_PAGE_SIZE
    show_id = kind in _RK_CUR
    lines = [head, sub, ""]
    for i, (key, name, val) in enumerate(rows[start:start + RK_PAGE_SIZE], start + 1):
        rank = _RK_MEDALS.get(i, f"{i}.")
        if kind == "guruh":
            who = f"<b>{html.escape(str(name))}</b>"
        elif kind == "para":
            who = name   # tayyor HTML
        else:
            who = mention(key, name) + (f" ({key})" if show_id else "")
        lines.append(f"{rank} {who} — {val}")
    lines.append("")
    lines.append(f"👥 Jami: {len(rows)}" + (f" · 📄 {page + 1}/{total_pages}" if total_pages > 1 else ""))
    if note:
        lines.append(note.strip())
    return "\n".join(lines), total_pages, len(rows)


def rk_kb(kind, per, scope, page, total_pages, in_group):
    kind, per = rk_norm(kind, per)
    kb = types.InlineKeyboardMarkup()

    def cb(k, p, s, pg):
        return f"rk|{k}|{p}|{s}|{pg}"
    row = []
    for k, label in RK_KIND_BTNS:
        row.append(types.InlineKeyboardButton(("• " if k == kind else "") + label, callback_data=cb(k, RK_DEFAULT_PERIOD[k] if k != kind else per, scope, 0)))
        if len(row) == 4:
            kb.row(*row)
            row = []
    periods = RK_PERIODS_BY_KIND[kind]
    if periods:
        kb.row(*[types.InlineKeyboardButton(("✅ " if p == per else "") + RK_PERIOD_LABELS[p], callback_data=cb(kind, p, scope, 0))
                 for p in periods])
    if total_pages > 1:
        nav = []
        if page > 0:
            nav.append(types.InlineKeyboardButton("◀️", callback_data=cb(kind, per, scope, page - 1)))
        nav.append(types.InlineKeyboardButton(f"{page + 1}/{total_pages}", callback_data="rk|noop|-|a|0"))
        if page < total_pages - 1:
            nav.append(types.InlineKeyboardButton("▶️", callback_data=cb(kind, per, scope, page + 1)))
        kb.row(*nav)
    if in_group and kind != "guruh":
        kb.row(types.InlineKeyboardButton(("✅ " if scope == "a" else "") + "🌍 Butun bot", callback_data=cb(kind, per, "a", 0)),
               types.InlineKeyboardButton(("✅ " if scope == "g" else "") + "🏘 Shu guruh", callback_data=cb(kind, per, "g", 0)))
    return kb


def rk_send(chat, kind, per, scope="a"):
    in_group = chat.type in ("group", "supergroup")
    scope_chat = chat.id if (scope == "g" and in_group) else None
    scope = "g" if scope_chat is not None else "a"
    kind, per = rk_norm(kind, per)
    text, tp, _n = rk_render(kind, per, scope_chat, 0)
    bot.send_message(chat.id, text, reply_markup=rk_kb(kind, per, scope, 0, tp, in_group))


@bot.callback_query_handler(func=lambda c: c.data.startswith("rk|"))
def cb_rk(call):
    try:
        maybe_capture_owner(call.from_user)
        if not _rk_allowed(call.message.chat, call.from_user.id):
            bot.answer_callback_query(call.id)   # boshqalarga — jimgina
            return
        _, kind, per, scope, page_s = call.data.split("|")
        if kind == "noop":
            bot.answer_callback_query(call.id)
            return
        in_group = call.message.chat.type in ("group", "supergroup")
        scope_chat = call.message.chat.id if (scope == "g" and in_group) else None
        scope = "g" if scope_chat is not None else "a"
        kind, per = rk_norm(kind, per)
        text, tp, _n = rk_render(kind, per, scope_chat, max(0, int(page_s)))
        page = max(0, min(int(page_s), tp - 1))
        try:
            bot.edit_message_text(text, call.message.chat.id, call.message.message_id,
                                  reply_markup=rk_kb(kind, per, scope, page, tp, in_group))
        except Exception as e:
            if "not modified" not in str(e):
                _logger.warning("cb_rk edit xatosi: %s", e)
        bot.answer_callback_query(call.id)
    except Exception as e:
        _logger.warning("cb_rk xatolik: %s", e, exc_info=True)
        try:
            bot.answer_callback_query(call.id, "⚠️ Xatolik yuz berdi.", show_alert=True)
        except Exception:
            pass


