# ================================================================================
#  🎁 GIVEAWAY (qatnashish tarqatmasi) — faqat bot egasi boshlaydi
#   /givevey 7 soat   — 7 soatdan keyin tugaydi        /givevey 100 ta — 100 ishtirokchi to'lganda tugaydi
#   Qatnashish sharti: egasining kanaliga a'zo bo'lish. Vaqt/son to'lgach, ishtirokchilar orasidan
#   tasodifiy g'olib tanlanadi va ISMI TAG QILINADI. Sovg'ani egasi qo'lda beradi.
#   Holat bazada saqlanadi — bot qayta ishga tushsa ham giveaway davom etadi.
# ================================================================================
GV_MAX_HOURS = 24 * 30
GV_MAX_COUNT = 100000
GV_EDIT_EVERY = 4.0          # soniya: ishtirokchilar soni xabarda shu oraliqdan tez yangilanmaydi
GV_LIST_SHOW = 35            # natijada nechta ismni ko'rsatish
_GV_LOCK = threading.RLock()
_GV_DIRTY = {}               # gid -> oxirgi tahrirdan keyin o'zgarish bormi
_GV_LAST_EDIT = {}           # gid -> oxirgi tahrir vaqti
_GV_THREAD = [None]

with db_lock:
    cur.execute("CREATE TABLE IF NOT EXISTS gv_giveaway (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, "
                "message_id INTEGER, mode TEXT NOT NULL, end_ts REAL, target INTEGER, created_ts REAL NOT NULL, "
                "status TEXT NOT NULL DEFAULT 'active', winner_id INTEGER)")
    cur.execute("CREATE TABLE IF NOT EXISTS gv_entry (gid INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT, ts REAL, "
                "PRIMARY KEY (gid, user_id))")
    conn.commit()


def _gv_parse(args):
    """['7','soat'] | ['100','ta'] | ['7soat'] -> ('time', soniya, None) | ('count', None, son) | None"""
    s = " ".join(args).strip().lower()
    m_ = re.fullmatch(r"(\d{1,6})\s*([a-zʻ'’`]*)", s)
    if not m_:
        return None
    n, unit = int(m_.group(1)), m_.group(2)
    if n <= 0:
        return None
    if unit in ("ta", "t", "kishi", "nafar", "odam"):
        return ("count", None, n) if 2 <= n <= GV_MAX_COUNT else None
    mult = None
    if unit in ("soat", "s", "h", "hour"):
        mult = 3600
    elif unit in ("daqiqa", "daq", "min", "m", "d"):
        mult = 60
    elif unit in ("kun", "k"):
        mult = 86400
    if mult is None:
        return None
    secs = n * mult
    return ("time", secs, None) if 60 <= secs <= GV_MAX_HOURS * 3600 else None


def _gv_fmt_left(secs):
    secs = max(0, int(secs) + 59)   # yuqoriga yaxlitlanadi
    d, rem = divmod(secs, 86400)
    h, rem = divmod(rem, 3600)
    mi = rem // 60
    parts = []
    if d:
        parts.append(f"{d} kun")
    if h:
        parts.append(f"{h} soat")
    if mi or not parts:
        parts.append(f"{mi} daqiqa")
    return " ".join(parts[:2])


def _gv_row(gid):
    with db_lock:
        cur.execute("SELECT id, chat_id, message_id, mode, end_ts, target, created_ts, status, winner_id FROM gv_giveaway WHERE id=?", (gid,))
        return cur.fetchone()


def _gv_count(gid):
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM gv_entry WHERE gid=?", (gid,))
        return int(cur.fetchone()[0])


def _gv_text(row, n):
    _id, _chat, _mid, mode, end_ts, target, _cts, _st, _w = row
    lines = ["🎁 <b>GIVEAWAY!</b>", ""]
    if mode == "time":
        lines.append(f"⏳ Tugashiga: <b>{_gv_fmt_left(end_ts - time.time())}</b>")
    else:
        lines.append(f"🎯 Maqsad: <b>{target}</b> ishtirokchi")
    lines.append(f"👥 Ishtirokchilar: <b>{n}</b>" + (f" / {target}" if mode == "count" else ""))
    lines.append("")
    if OWNER_CHANNEL_ID:
        lines.append("📌 <b>Shart:</b> kanalimizga a'zo bo'lish")
    lines.append("👇 Qatnashish uchun tugmani bosing")
    lines.append("🍀 G'olib tasodifiy tanlanadi")
    return "\n".join(lines)


def _gv_kb(gid, n):
    kb = types.InlineKeyboardMarkup()
    kb.row(types.InlineKeyboardButton(f"🎉 Qatnashish ({n})", callback_data=f"gv|{gid}"))
    url = _channel_join_url() if OWNER_CHANNEL_ID else None
    if url:
        kb.row(types.InlineKeyboardButton("📢 Kanalga a'zo bo'lish", url=url))
    return kb


def _gv_refresh(gid, force=False):
    now = time.time()
    if not force and now - _GV_LAST_EDIT.get(gid, 0) < GV_EDIT_EVERY:
        return
    row = _gv_row(gid)
    if not row or row[7] != "active":
        return
    _GV_LAST_EDIT[gid] = now
    _GV_DIRTY[gid] = False
    n = _gv_count(gid)
    try:
        bot.edit_message_text(_gv_text(row, n), row[1], row[2], reply_markup=_gv_kb(gid, n))
    except Exception as e:
        if "not modified" not in str(e):
            msg = str(e)
            m_ = re.search(r"retry after (\d+)", msg)
            if m_:
                _GV_LAST_EDIT[gid] = now + int(m_.group(1))
            else:
                _logger.warning("giveaway xabarini yangilab bo'lmadi (gid=%s): %s", gid, e)


def _gv_pick_winner(gid):
    """Tasodifiy g'olib: kanaldan chiqib ketganlar o'tkazib yuboriladi."""
    with db_lock:
        cur.execute("SELECT user_id, name FROM gv_entry WHERE gid=?", (gid,))
        rows = cur.fetchall()
    random.shuffle(rows)
    for i, (uid, name) in enumerate(rows):
        if i >= 40:
            break
        if OWNER_CHANNEL_ID and check_channel_subscription(uid) is False:
            continue
        return uid, name, len(rows)
    return None, None, len(rows)


def _gv_finish(gid, cancel=False):
    """Giveaway'ni yakunlaydi (bir marta). cancel=True — g'olibsiz bekor qilish."""
    with _GV_LOCK:
        row = _gv_row(gid)
        if not row or row[7] != "active":
            return False
        with db_lock:
            cur.execute("UPDATE gv_giveaway SET status=? WHERE id=? AND status='active'", ("cancelled" if cancel else "finishing", gid))
            conn.commit()
    _id, chat_id, mid, mode, _end, target, _cts, _st, _w = row
    _GV_DIRTY.pop(gid, None)
    _GV_LAST_EDIT.pop(gid, None)
    if cancel:
        try:
            bot.edit_message_text("🚫 <b>Giveaway bekor qilindi.</b>", chat_id, mid)
        except Exception:
            pass
        return True
    winner, wname, total = _gv_pick_winner(gid)
    with db_lock:
        cur.execute("UPDATE gv_giveaway SET status='done', winner_id=? WHERE id=?", (winner, gid))
        conn.commit()
    try:
        bot.edit_message_text(f"🎁 <b>Giveaway yakunlandi.</b>\n👥 Ishtirokchilar: <b>{total}</b>", chat_id, mid)
    except Exception:
        pass
    if winner is None:
        text = "🎁 <b>GIVEAWAY YAKUNLANDI</b>\n\n😔 Hech kim qatnashmadi (yoki shartni bajarmadi). G'olib yo'q."
    else:
        with db_lock:
            cur.execute("SELECT user_id, name FROM gv_entry WHERE gid=? ORDER BY ts ASC LIMIT ?", (gid, GV_LIST_SHOW))
            first = cur.fetchall()
        lines = [f"🎉 <b>GIVEAWAY YAKUNLANDI!</b>", "",
                 f"🏆 <b>G'olib:</b> {mention(winner, wname or 'G’olib')}",
                 f"👥 Ishtirokchilar: <b>{total}</b>", ""]
        for i, (u, n_) in enumerate(first, 1):
            lines.append(f"{i}. {mention(u, n_ or 'Ishtirokchi')}")
        if total > len(first):
            lines.append(f"va boshqa {total - len(first)} ta kishi")
        lines.append("")
        lines.append("🎊 Tabriklaymiz! Sovg'a tez orada beriladi.")
        text = "\n".join(lines)
    _send_result_robust(chat_id, text)
    return True


def _gv_loop():
    while True:
        try:
            with db_lock:
                cur.execute("SELECT id, mode, end_ts, target FROM gv_giveaway WHERE status='active'")
                active = cur.fetchall()
            now = time.time()
            for gid, mode, end_ts, target in active:
                try:
                    if mode == "time" and end_ts and now >= end_ts:
                        _gv_finish(gid)
                    elif mode == "count" and _gv_count(gid) >= (target or 0):
                        _gv_finish(gid)
                    else:
                        if _GV_DIRTY.get(gid) or (mode == "time" and now - _GV_LAST_EDIT.get(gid, 0) >= 60):
                            _gv_refresh(gid)
                except Exception as e:
                    _logger.warning("giveaway sikli xatosi (gid=%s): %s", gid, e, exc_info=True)
        except Exception as e:
            _logger.warning("giveaway sikli: %s", e)
        time.sleep(2.0)


def _gv_ensure_thread():
    with _GV_LOCK:
        t = _GV_THREAD[0]
        if t is None or not t.is_alive():
            t = threading.Thread(target=_gv_loop, name="giveaway-loop", daemon=True)
            _GV_THREAD[0] = t
            t.start()


def _gv_owner_ok(message):
    if message.chat.type == "channel":
        return is_owner_channel(message.chat)
    return bool(message.from_user) and is_owner(message.from_user.id)


@bot.message_handler(commands=["givevey", "Givevey", "giveaway"])
@bot.channel_post_handler(commands=["givevey", "Givevey", "giveaway"])
def cmd_givevey(message):
    if not _gv_owner_ok(message):
        return   # bot egasi emas — javob berilmaydi
    chat = message.chat
    if message.chat.type != "channel":
        maybe_capture_owner(message.from_user)
        safe_delete(message)
    if chat.type == "private":
        bot.send_message(chat.id, "ℹ️ /givevey guruh yoki kanalda ishlaydi.")
        return
    args = (message.text or "").split()[1:]
    spec = _gv_parse(args)
    if spec is None:
        bot.send_message(chat.id, "🎁 <b>Giveaway</b>\n\n<code>/givevey 7 soat</code> — vaqt bo'yicha\n"
                                  "<code>/givevey 30 daqiqa</code>\n<code>/givevey 2 kun</code>\n"
                                  "<code>/givevey 100 ta</code> — ishtirokchi soni bo'yicha\n\n"
                                  "To'xtatish: /stopgiveaway (g'olib tanlanadi) yoki /stopgiveaway bekor")
        return
    with db_lock:
        cur.execute("SELECT id FROM gv_giveaway WHERE chat_id=? AND status='active'", (chat.id,))
        busy = cur.fetchone()
    if busy:
        bot.send_message(chat.id, "⏳ Bu yerda giveaway allaqachon ketyapti. To'xtatish: /stopgiveaway")
        return
    mode, secs, target = spec
    now = time.time()
    with db_lock:
        cur.execute("INSERT INTO gv_giveaway (chat_id, mode, end_ts, target, created_ts) VALUES (?,?,?,?,?)",
                    (chat.id, mode, now + secs if secs else None, target, now))
        gid = cur.lastrowid
        conn.commit()
    row = _gv_row(gid)
    sent = bot.send_message(chat.id, _gv_text(row, 0), reply_markup=_gv_kb(gid, 0))
    with db_lock:
        cur.execute("UPDATE gv_giveaway SET message_id=? WHERE id=?", (sent.message_id, gid))
        conn.commit()
    _GV_LAST_EDIT[gid] = time.time()
    _gv_ensure_thread()
    if not OWNER_CHANNEL_ID and message.from_user:
        try:
            bot.send_message(message.from_user.id, "⚠️ Kanal o'rnatilmagan (/shu_kanal), shuning uchun a'zolik sharti tekshirilmaydi.")
        except Exception:
            pass


@bot.message_handler(commands=["stopgiveaway", "Stopgiveaway"])
@bot.channel_post_handler(commands=["stopgiveaway", "Stopgiveaway"])
def cmd_stopgiveaway(message):
    if not _gv_owner_ok(message):
        return
    if message.chat.type != "channel":
        safe_delete(message)
    with db_lock:
        cur.execute("SELECT id FROM gv_giveaway WHERE chat_id=? AND status='active' ORDER BY id DESC LIMIT 1", (message.chat.id,))
        row = cur.fetchone()
    if not row:
        bot.send_message(message.chat.id, "ℹ️ Bu yerda faol giveaway yo'q.")
        return
    cancel = "bekor" in (message.text or "").lower()
    _gv_finish(row[0], cancel=cancel)


@bot.callback_query_handler(func=lambda c: c.data.startswith("gv|"))
def cb_giveaway_join(call):
    try:
        gid = int(call.data.split("|")[1])
    except Exception:
        bot.answer_callback_query(call.id)
        return
    uid = call.from_user.id
    row = _gv_row(gid)
    if not row or row[7] != "active":
        bot.answer_callback_query(call.id, "🏁 Bu giveaway yakunlangan.", show_alert=True)
        return
    if is_banned(uid):
        bot.answer_callback_query(call.id)
        return
    if OWNER_CHANNEL_ID:
        ok = check_channel_subscription(uid)
        if ok is False:
            bot.answer_callback_query(call.id, "❌ Qatnashish uchun avval kanalimizga a'zo bo'ling, so'ng qayta bosing.", show_alert=True)
            return
        if ok is None:
            bot.answer_callback_query(call.id, "⚠️ A'zolikni tekshirib bo'lmadi, birozdan so'ng urinib ko'ring.", show_alert=True)
            return
    name = (call.from_user.first_name or "O'yinchi")
    with _GV_LOCK:
        row = _gv_row(gid)
        if not row or row[7] != "active":
            bot.answer_callback_query(call.id, "🏁 Bu giveaway yakunlangan.", show_alert=True)
            return
        with db_lock:
            cur.execute("INSERT OR IGNORE INTO gv_entry (gid, user_id, name, ts) VALUES (?,?,?,?)", (gid, uid, name, time.time()))
            added = cur.rowcount > 0
            conn.commit()
    if not added:
        bot.answer_callback_query(call.id, "✅ Siz allaqachon qatnashyapsiz!", show_alert=True)
        return
    try:
        user_dict(uid, name)
    except Exception:
        pass
    bot.answer_callback_query(call.id, "🎉 Siz giveaway'da ishtirok etyapsiz! Omad!", show_alert=True)
    _GV_DIRTY[gid] = True
    if row[3] == "count" and _gv_count(gid) >= (row[5] or 0):
        threading.Thread(target=_gv_finish, args=(gid,), daemon=True).start()


