@bot.message_handler(
    func=lambda m: m.chat.type in ("group", "supergroup") and not (m.text or "").startswith("/"),
    content_types=["text"],
)
def group_text_guard(message):
    chat_id = message.chat.id
    game = GAMES.get(chat_id)
    if game:
        phase = game.get("phase")
        _gid = message.from_user.id if message.from_user else None
        # 👑 v8: o'yinda QATNASHMAYOTGAN HUNTER ELITE a'zolar tunda ham, kunduzi ham
        # yoza oladi (guruh sozlamasida o'chirib qo'yilmagan bo'lsa). O'yin ICHIDAGI
        # ELITE o'yinchi esa tunda boshqalar kabi jim turadi — aks holda ittifoqchilari
        # bilan ochiq gaplashib o'yinni buzib yuborardi.
        _elite_outsider = (
            phase in ("night", "day") and _gid is not None and gsv(game, "elite_chat") == "1"
            and _gid not in game["players"] and is_elite(_gid)
        )
        if phase == "night":
            if _elite_outsider or gsv(game, "night_chat") == "open":
                return
            safe_delete(message)
            return
        if phase == "day":
            uid = message.from_user.id
            if uid not in game["players"]:
                if _elite_outsider:
                    return
                safe_delete(message)
                return
            # 💀 v8: guruh sozlamasi — o'lgan o'yinchilar kunduzi jim turishi mumkin
            if not game["players"][uid].get("alive", True) and gsv(game, "dead_chat") == "closed":
                safe_delete(message)
                return
            return

    # 🔴🔵💍 Jamoaviy va Para o'yin rejimlari ENDI alohida tizim emas — ular
    # ham xuddi shu yuqoridagi `game = GAMES.get(chat_id)` orqali boshqariladi
    # (squad_mode/couple_mode oddiy GAMES[chat_id] ichida saqlanadi), shuning
    # uchun bu yerda alohida tekshiruv shart emas.





# ================================================================================
#  👑 HUNTER ELITE — a'zolik (tarifli), shaxsiy laqab, til sozlamalari,
#     olmos sovg'a qilish tizimi.
#
#  (Almex Black Bot'da ko'rilgan "PRO obuna", "Til tanlash", "Laqab tasdiqlash
#   ovoz berishi" va "Birovga olmos sovg'a qilish" funksiyalaridan ilhomlanib,
#   Hunter Mafia botiga moslab, MAVJUD infratuzilma ustiga — charges JSON'i,
#   add_balance, Telegram Stars invoice tizimi — qurilgan. Yangi DB ustuni
#   TALAB QILINMAYDI: hammasi allaqachon mavjud "charges" ustunida saqlanadi,
#   shuning uchun eski foydalanuvchilarning hech qanday ma'lumoti yo'qolmaydi.
#
#  ESLATMA: botning asosiy interfeysi (menyular, o'yin matnlari) o'zbek tilida
#  qoladi — /til orqali tanlangan til faqat ELITE, laqab va sovg'a bo'limining
#  shaxsiy tasdiqlash xabarlarida ishlatiladi (pastda ochiq yozilgan). Bu — soxta
#  "to'liq tarjima" va'da qilmaslik uchun ataylab shunday cheklangan.)
# ================================================================================

ELITE_PLANS = [
    # {kun: (necha kunlik obuna), diamond: (Olmos narxi), stars: (Telegram Stars narxi)}
    # 🔧 YANGILANDI: 1 hafta = 100⭐/40💎 dan boshlanadi, 3 oygacha (uzoq muddat
    # olganda foizli chegirma bilan) sotib olish mumkin.
    {"days": 7,  "diamond": 40,  "stars": 100},   # 1 hafta
    {"days": 15, "diamond": 70,  "stars": 180},   # 15 kun
    {"days": 30, "diamond": 130, "stars": 320},   # 1 oy
    {"days": 60, "diamond": 230, "stars": 580},   # 2 oy
    {"days": 90, "diamond": 320, "stars": 800},   # 3 oy (eng katta chegirma)
]

_ELITE_PLANS_DEFAULT = [dict(p) for p in ELITE_PLANS]  # 🔧 QULAYLIK: "standartga qaytarish" tugmasi uchun asl nusxa


def _load_elite_plans_from_settings():
    """🔧 QULAYLIK: bot ishga tushganda, agar owner avval Admin panel orqali
    ELITE narxlarini o'zgartirgan bo'lsa (bot_settings jadvalida saqlangan),
    o'sha narxlar kod ichidagi standart narxlar o'rniga ishlatiladi. Shu
    tufayli owner narxni bir marta panel orqali o'zgartirsa, bot qayta
    ishga tushirilganda ham (masalan /tiklash yoki qayta deploy qilinganda
    ham) o'zgartirilgan narx SAQLANIB QOLADI — kodni qayta yozish shart emas."""
    global ELITE_PLANS
    try:
        raw = get_setting("elite_plans_json")
        if not raw:
            return
        data = json.loads(raw)
        if isinstance(data, list) and data and all(
            isinstance(p, dict) and {"days", "diamond", "stars"} <= set(p.keys()) for p in data
        ):
            ELITE_PLANS = data
    except Exception:
        pass  # xato bo'lsa ham standart narxlar bilan davom etadi — bot hech qachon shu sabab qotib qolmaydi


def _save_elite_plans():
    """Joriy ELITE_PLANS ro'yxatini bazaga (bot_settings) yozib qo'yadi — shundan
    keyin bot qayta ishga tushsa ham owner belgilagan narx saqlanib qoladi."""
    try:
        set_setting("elite_plans_json", json.dumps(ELITE_PLANS, ensure_ascii=False))
    except Exception:
        # Saqlanmasa narx restartdan keyin eskisiga qaytadi — owner uchun log'da ko'rinsin.
        _logger.error("ELITE narxlari bazaga saqlanmadi", exc_info=True)


_load_elite_plans_from_settings()

