def menu_welcome(uid):
    """Bosh menyu matni (True Mafia uslubida): "Salom!\nMen Mafia o'yinining rasmiy botiman." """
    t = v3t(uid, "hello")
    return t.replace("! ", "!\n", 1).replace("！", "！\n", 1) if ("! " in t) else t
for _lg, _d in V3.items():
    assert len(_V3_LANGS[_lg]) == len(_V3_KEYS), _lg


def v3t(uid_or_lang, key):
    """v3 asosiy matnlar: til → en → uz zanjiri."""
    lg = uid_or_lang if isinstance(uid_or_lang, str) else get_lang(uid_or_lang)
    return (V3.get(lg) or {}).get(key) or V3["en"].get(key) or V3["uz"].get(key, "")


# eski gate matnlarini (jins/kanal) barcha tillarga kengaytiramiz
for _lg, _d in V3.items():
    _GATE_TEXT["gender_title"][_lg] = f"👤 <b>{_d['gender']}</b>"
    _GATE_TEXT["female"][_lg] = f"👩 {_d['female']}"
    _GATE_TEXT["male"][_lg] = f"👨 {_d['male']}"
    _GATE_TEXT["sub_title"][_lg] = f"📢 <b>{_d['sub']}</b>"
    _GATE_TEXT["sub_btn"][_lg] = f"📢 {_d['subbtn']}"
    _GATE_TEXT["check_btn"][_lg] = f"✅ {_d['check']}"
    _GATE_TEXT["not_yet"][_lg] = f"❌ {_d['notyet']}"
    LANG_STRINGS.setdefault("lang_set", {})[_lg] = f"✅ {_d['langset']}"
    for _k, _ico in (("menu_addgroup", "➕ "), ("menu_cabinet", "👤 "), ("menu_roles", "🎭 "), ("menu_lang", "🌐 "),
                     ("menu_elite", "👑 "), ("menu_help", "❓ ")):
        _src = {"menu_addgroup": "addgroup", "menu_cabinet": "profile", "menu_roles": "roles",
                "menu_lang": "lang", "menu_elite": "elite", "menu_help": "help"}[_k]
        LANG_STRINGS.setdefault(_k, {})[_lg] = _ico + _d[_src]
    LANG_STRINGS.setdefault("welcome_title", {})[_lg] = "🌙 <b>Hunter Mafia</b>"
    LANG_STRINGS.setdefault("welcome_body", {})[_lg] = _d["hello"]


def localize_text(uid, text):
    """Translate recurring legacy phrases without external AI/API."""
    if not text:
        return text
    lang = get_lang(uid)
    if lang == "uz":
        return text
    if text in LANG_STRINGS.get("_skip", {}):
        return text
    if lang in globals().get("_L10N", {}):
        return text  # yangi to'liq lokalizatsiya (l10n) ishlaydi; eski qisman paket aralashtirib yubormasin
    out = text
    for src, dst in PHRASE_PACK.get(lang, {}).items():
        out = out.replace(src, dst)
    return out



def T(uid, key):
    """Foydalanuvchi tanlagan 5 tildan biridagi matnni qaytaradi."""
    lang = get_lang(uid)
    table = LANG_STRINGS.get(key, {})
    return table.get(lang) or table.get("en") or table.get("uz") or ""


def lang_direction(uid):
    return "rtl" if get_lang(uid) == "ar" else "ltr"


def get_lang(uid):
    ch = get_charges(uid)
    code = str(ch.get("lang", "uz") or "uz").lower()
    # Old releases had uk/kk/id; migrate them safely to English.
    if code not in dict(LANG_LIST):
        code = "en" if code in {"uk"} else "uz"
    return code


def set_lang(uid, code):
    if code not in dict(LANG_LIST):
        code = "uz"
    set_charge_value(uid, "lang", code)


def has_chosen_lang(uid):
    """Foydalanuvchi ilgari (birinchi /start'da yoki /til orqali) tilni
    ongli ravishda tanlaganmi — tanlamagan bo'lsa, birinchi /start'da
    tilni tanlash ekrani ko'rsatiladi (faqat BIR MARTA)."""
    ch = get_charges(uid)
    return bool(ch.get("lang_chosen"))


def mark_lang_chosen(uid):
    set_charge_value(uid, "lang_chosen", True)


def get_nickname(uid):
    ch = get_charges(uid)
    return (ch.get("nickname") or "").strip()


def set_nickname(uid, nickname):
    set_charge_value(uid, "nickname", nickname.strip()[:32])


def is_elite(uid):
    ch = get_charges(uid)
    until = ch.get("vip_until", 0)
    if bool(until) and until > time.time():
        return True
    return toifa_get(uid, ch) == "overlord"   # 🐉 OVERLORD — ELITE imkoniyatlari doimiy ochiq


def elite_days_left(uid):
    ch = get_charges(uid)
    until = ch.get("vip_until", 0)
    if not until or until <= time.time():
        return 0
    return max(0, int((until - time.time()) // 86400) + 1)


def grant_elite_days(uid, days):
    """Yangi ELITE kunlarni qo'shadi — agar hozir ham faol ELITE bo'lsa, qolgan
    muddat ustiga QO'SHILADI (ya'ni 15 kun qolganida yana 30 kun sotib olsa, 45 kun bo'ladi),
    aks holda hozirdan boshlab hisoblanadi. Yangi umumiy tugash vaqtini (unix) qaytaradi."""
    ch = get_charges(uid)
    current_until = ch.get("vip_until", 0)
    base = current_until if current_until and current_until > time.time() else time.time()
    new_until = base + days * 86400
    set_charge_value(uid, "vip_until", new_until)
    return new_until


def elite_status_line(uid):
    if toifa_get(uid) == "overlord":
        return f"{toifa_emoji_html('overlord')} <b>OVERLORD</b> — ELITE imkoniyatlari doimiy ochiq"
    if is_elite(uid):
        nick = get_nickname(uid)
        nick_part = f" | 🏷 Laqab: {esc(nick)}" if nick else ""
        return f"𝐄𝐋𝐈𝐓𝐄 💎 <b>HUNTER ELITE faol</b> — {elite_days_left(uid)} kun qoldi{nick_part}"
    return "👑 HUNTER ELITE: faol emas — /elite orqali oling"


ELITE_STYLED_WORD = "𝐄𝐋𝐈𝐓𝐄 💎"  # 🔧 Qalin shrift + olmos (avvalgi kursiv-kalligrafik "𝓔𝓵𝓲𝓽𝓮" 👑 o'rniga)


def elite_success_text(days, until):
    return (
        f"🎉 {ELITE_STYLED_WORD} <b>TABRIKLAYMIZ! HUNTER ELITE FAOLLASHTIRILDI!</b> {ELITE_STYLED_WORD} 🎉\n\n"
        f"⏳ Qo'shilgan muddat: <b>{_elite_days_label(days)}</b>\n"
        f"📅 Amal qilish muddati: <b>{time.strftime('%d.%m.%Y', time.localtime(until))}</b> gacha\n\n"
        "✨ Endi sizga ochiq:\n"
        f"• {ELITE_STYLED_WORD} Ismingiz yonida oltin ELITE nishoni\n"
        "• 🏷 Shaxsiy laqab (/taxallus)\n"
        "• 🚪 O'yin lobbysidan istalgan payt chiqish huquqi\n"
        "• 💎 Kunlik ELITE Sirli Sandiq (/elite_sandiq)\n"
        "• 👁 Kengaytirilgan profil va reytingdagi maxsus ko'rinish\n\n"
        "Rahmat! 💎"
    )


def _elite_days_label(d):
    """Kunlar sonini o'qish oson formatga o'giradi: 7->'1 hafta', 30->'1 oy' va h.k."""
    if d == 7:
        return "1 hafta"
    if d % 30 == 0:
        months = d // 30
        return f"{months} oy" if months > 1 else "1 oy"
    return f"{d} kun"


