#  🪙🎁 /coinsovga — Hunter Coin'ni boshqa foydalanuvchiga O'TKAZISH
#     (/sovga bilan bir xil mantiq, lekin Olmos o'rniga Hunter Coin — bu Hunter
#     Coin'ni haqiqiy "onlayn valyuta" kabi ishlatishga imkon beradi: endi u
#     faqat do'kondan xarid qilish uchun emas, balki odamlar orasida ham
#     o'tkazilishi mumkin.)
# --------------------------------------------------------------------------------

@bot.message_handler(commands=["coinsovga", "coingift"])
def cmd_coinsovga(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    sender_id = message.from_user.id
    parts = message.text.split()

    target_id = None
    target_name = None

    if message.reply_to_message and len(parts) == 2:
        target_id = message.reply_to_message.from_user.id
        target_name = message.reply_to_message.from_user.first_name
        amount_s = parts[1]
    elif len(parts) == 3:
        if not parts[1].lstrip("-").isdigit():
            bot.send_message(message.chat.id, "❌ Foydalanuvchi ID raqam bo'lishi kerak.")
            return
        target_id = int(parts[1])
        amount_s = parts[2]
    else:
        bot.send_message(
            message.chat.id,
            "🪙 <b>Hunter Coin sovg'a qilish</b>\n\n"
            "• Reply qilib: <code>/coinsovga &lt;miqdor&gt;</code>\n"
            "• Yoki: <code>/coinsovga &lt;ID&gt; &lt;miqdor&gt;</code>\n\n"
            "❗️ Qabul qiluvchi avval /start bosgan bo'lishi kerak.",
        )
        return

    if target_id == sender_id:
        bot.send_message(message.chat.id, "❌ O'zingizga o'tkaza olmaysiz 🙂")
        return

    try:
        amount = int(amount_s)
    except ValueError:
        bot.send_message(message.chat.id, "❌ Miqdor butun son bo'lishi kerak.")
        return
    if amount <= 0:
        bot.send_message(message.chat.id, "❌ Miqdor musbat bo'lishi kerak.")
        return

    if target_name:
        user_dict(target_id, target_name)
    elif not user_exists(target_id):
        bot.send_message(message.chat.id, "❌ Bu foydalanuvchi hali botdan foydalanmagan (avval botga /start bosishi kerak).")
        return

    sender = user_dict(sender_id, message.from_user.first_name)
    if sender_id == target_id or is_banned(sender_id):
        return
    if not try_charge(sender_id, "coin", amount):
        bot.send_message(message.chat.id, f"❌ Hunter Coin'ingiz yetarli emas! Sizda: {user_dict(sender_id)['coin']} 🪙")
        return
    add_balance_as('transfer', target_id, coin=amount, ledger=False)

    target_row = user_dict(target_id)
    bot.send_message(
        message.chat.id,
        f"🪙 <b>Hunter Coin o'tkazildi!</b>\n"
        f"{mention(sender_id, message.from_user.first_name)} ➜ "
        f"{mention(target_id, target_row['name'])}: <b>{amount} 🪙</b>",
    )
    safe_send(target_id, f"🪙 Sizga {mention(sender_id, message.from_user.first_name)} tomonidan <b>{amount} 🪙</b> Hunter Coin o'tkazildi!")


