@bot.callback_query_handler(func=lambda c: c.data.startswith("buydollar|"))
def cb_buy_dollar(call):
    maybe_capture_owner(call.from_user)
    uid = call.from_user.id
    try:
        diamond_cost = int(call.data.split("|")[1])
    except Exception:
        bot.answer_callback_query(call.id)
        return
    pkg = next((p for p in DOLLAR_PACKAGES if p["diamond"] == diamond_cost), None)
    if not pkg:
        bot.answer_callback_query(call.id, "❌ Bu paket topilmadi.", show_alert=True)
        return
    u = user_dict(uid, call.from_user.first_name)
    if not try_charge(uid, "diamond", diamond_cost):
        bot.answer_callback_query(
            call.id, f"❌ Olmos yetarli emas: {diamond_cost} 💎 kerak, sizda {u['diamond']} 💎.", show_alert=True)
        return
    add_balance(uid, dollar=pkg["dollar"], ledger=False)
    bot.answer_callback_query(call.id, f"✅ +{pkg['dollar']} 💵 (−{diamond_cost} 💎)", show_alert=True)


# --------------------------------------------------------------------------------
#  🪙📈 HUNTER COIN — JONLI (SUZIB YURUVCHI) BOZOR KURSI
#     Endi Hunter Coin oddiy "do'kon puli" emas, balki vaqt bo'yicha o'z-o'zidan
#     tebranib turadigan ONLAYN VALYUTA kabi ishlaydi (bitcoin kabi kichik random
#     tebranishlar). Har HC_MARKET_UPDATE_MINUTES daqiqada kurs ±HC_MARKET_VOLATILITY_PCT
#     foiz ichida tasodifiy o'zgaradi, lekin HC_RATE_MIN/HC_RATE_MAX chegarasidan
#     chiqmaydi. Qiymat bazada (bot_settings) saqlanadi — bot qayta ishga tushsa
#     ham oxirgi kurs yo'qolmaydi. Eski qat'iy 2:1 kurs endi faqat BOSHLANG'ICH
#     (bazaviy) qiymat sifatida ishlatiladi.
# --------------------------------------------------------------------------------

DIAMOND_TO_COIN_PRESETS = [10, 20, 50, 100, 200, 500]

HC_BASE_DIAMOND_RATE = 55      # 🔧 v8: 1 🪙 ≈ 55 💎 (atrofida tebranadi)
HC_BASE_DOLLAR_RATE = 60.0     # (eski, ishlatilmaydi — dollar↔coin ayirboshlash olib tashlangan)
HC_RATE_MIN_MULT = 0.95        # 🔒 kurs bazaning kamida 95% i (arbitrajni yopish uchun tor koridor)
HC_RATE_MAX_MULT = 1.05        # 🔒 kurs bazaning ko'pi bilan 105% i
HC_SPREAD_PCT = 5              # 🔒 sotib olish/sotish farqi: har tomonga % (kurs ± spred)
HC_TRADE_COOLDOWN_SEC = 3      # 🔒 bir foydalanuvchi uchun savdo orasidagi minimal vaqt
HC_MARKET_VOLATILITY_PCT = 2   # 🔧 v8: har tebranishda ±2% gacha (silliq o'zgarish)
HC_MARKET_UPDATE_MINUTES = 20  # har 20 daqiqada bir marta tebranadi
HC_MARKET_HISTORY_LEN = 48     # kurs tarixida saqlanadigan nuqtalar soni

# Joriy kurslar (RAM'da, tezkor o'qish uchun — bazadan bot ishga tushganda yuklanadi)
HC_DIAMOND_RATE = HC_BASE_DIAMOND_RATE
HC_DOLLAR_RATE = HC_BASE_DOLLAR_RATE
HC_PREV_DIAMOND_RATE = HC_BASE_DIAMOND_RATE
HC_PREV_DOLLAR_RATE = HC_BASE_DOLLAR_RATE


def _hc_load_market_from_db():
    """Bot ishga tushganda oxirgi saqlangan Hunter Coin kursini bazadan o'qiydi."""
    global HC_DIAMOND_RATE, HC_DOLLAR_RATE, HC_PREV_DIAMOND_RATE, HC_PREV_DOLLAR_RATE
    try:
        raw_d = get_setting("hc_diamond_rate")
        raw_dl = get_setting("hc_dollar_rate")
    except Exception:
        raw_d, raw_dl = None, None
    if raw_d:
        try:
            HC_DIAMOND_RATE = HC_PREV_DIAMOND_RATE = float(raw_d)
        except Exception:
            pass
    if raw_dl:
        try:
            HC_DOLLAR_RATE = HC_PREV_DOLLAR_RATE = float(raw_dl)
        except Exception:
            pass


def _hc_clamp_rate():
    """🔧 v8: joriy kurs bazaviy chegaradan (min–max) tashqarida bo'lsa tuzatadi: chegaraga yaqin bo'lsa —
    chegaraga qaytaradi, juda uzoq bo'lsa (masalan eski 2:1 kurs bazada qolgan) — bazaviy qiymatga qo'yadi."""
    global HC_DIAMOND_RATE, HC_PREV_DIAMOND_RATE
    lo = round(HC_BASE_DIAMOND_RATE * HC_RATE_MIN_MULT, 2)
    hi = round(HC_BASE_DIAMOND_RATE * HC_RATE_MAX_MULT, 2)
    new_val = HC_DIAMOND_RATE
    if HC_DIAMOND_RATE < lo / 1.5 or HC_DIAMOND_RATE > hi * 1.5:
        new_val = float(HC_BASE_DIAMOND_RATE)
    elif HC_DIAMOND_RATE < lo:
        new_val = lo
    elif HC_DIAMOND_RATE > hi:
        new_val = hi
    if new_val != HC_DIAMOND_RATE:
        HC_DIAMOND_RATE = HC_PREV_DIAMOND_RATE = new_val
        try:
            set_setting("hc_diamond_rate", HC_DIAMOND_RATE)
        except Exception:
            pass


_hc_load_market_from_db()
_hc_clamp_rate()


def _hc_market_tick():
    """Kursni bir martalik ±HC_MARKET_VOLATILITY_PCT% tasodifiy tebratadi va
    chegaradan chiqmasligini ta'minlaydi, so'ng bazaga saqlaydi + tarixga yozadi."""
    global HC_DIAMOND_RATE, HC_DOLLAR_RATE, HC_PREV_DIAMOND_RATE, HC_PREV_DOLLAR_RATE, HC_LAST_UPDATE_TS
    HC_PREV_DIAMOND_RATE, HC_PREV_DOLLAR_RATE = HC_DIAMOND_RATE, HC_DOLLAR_RATE
    HC_LAST_UPDATE_TS = time.time()

    def _nudge(current, base):
        pct = random.uniform(-HC_MARKET_VOLATILITY_PCT, HC_MARKET_VOLATILITY_PCT) / 100.0
        pct += ((base - current) / float(base)) * 0.10   # 🔧 v8: bazaga yumshoq tortish — kurs bir chetda "qotib" qolmaydi
        new_val = current * (1 + pct)
        lo, hi = base * HC_RATE_MIN_MULT, base * HC_RATE_MAX_MULT
        return max(lo, min(hi, new_val))

    _hc_clamp_rate()
    HC_DIAMOND_RATE = round(_nudge(HC_DIAMOND_RATE, HC_BASE_DIAMOND_RATE), 2)

    try:
        set_setting("hc_diamond_rate", HC_DIAMOND_RATE)
        set_setting("hc_dollar_rate", HC_DOLLAR_RATE)
        raw_hist = get_setting("hc_rate_history")
        hist = json.loads(raw_hist) if raw_hist else []
        hist.append({"d": HC_DIAMOND_RATE, "$": HC_DOLLAR_RATE, "t": int(time.time())})
        hist = hist[-HC_MARKET_HISTORY_LEN:]
        set_setting("hc_rate_history", json.dumps(hist))
    except Exception as e:
        _logger.warning("_hc_market_tick saqlashda xatolik: %s", e)


def _hc_market_loop():
    while True:
        time.sleep(max(60, HC_MARKET_UPDATE_MINUTES * 60))
        try:
            _hc_market_tick()
        except Exception as e:
            _logger.warning("_hc_market_loop xatolik: %s", e)
        try:
            sweep_expired_items()   # 🕒 muddati o'tgan buyumlarni tozalash
        except Exception as e:
            _logger.warning("sweep_expired_items xatolik: %s", e)


