def _achievement_stats(uid):
    u = user_dict(uid)
    hero = get_hero(uid)
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM points_log WHERE user_id=? AND reason='most_active'", (uid,))
        mvp_count = int(cur.fetchone()[0] or 0)
        cur.execute("SELECT COUNT(*) FROM referrals WHERE inviter_id=?", (uid,))
        referrals = int(cur.fetchone()[0] or 0)
    _total, streak = _points_summary(uid)
    return {
        "wins": int(u.get("wins") or 0), "games": int(u.get("games") or 0), "duel_wins": int(u.get("duel_wins") or 0),
        "has_hero": bool(hero), "hero_level": hero["level"] if hero else 0, "is_elite": is_elite(uid),
        "married": bool(u.get("married_to")), "mvp_count": mvp_count, "best_streak": streak,
        "referrals": referrals, "level": level_progress(xp_of_user(u))[0],
    }


def achievements_state(uid):
    stats = _achievement_stats(uid)
    out = [{"key": a["key"], "icon": a["icon"], "name": a["name"], "unlocked": bool(a["check"](stats))} for a in ACHIEVEMENTS]
    return {"items": out, "unlocked": sum(1 for x in out if x["unlocked"]), "total": len(out)}


@bot.message_handler(commands=["yutuqlar", "yutuqlarim"])
def cmd_yutuqlar(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    user_dict(uid, message.from_user.first_name)
    d = achievements_state(uid)
    lines = [f"🏅 <b>Yutuqlar</b> — {d['unlocked']}/{d['total']}", ""]
    for it in d["items"]:
        lines.append(f"{'✅' if it['unlocked'] else '🔒'} {it['icon']} {it['name']}")
    bot.send_message(message.chat.id, "\n".join(lines))


# ---------------------------------------------------------------- 👻 ARVOH CHATI (o'lganlar bir-biri bilan)
def _ghost_broadcast(game, from_uid, text):
    """O'lgan o'yinchilar bir-biriga xabar yuboradi (jonlilarga ko'rinmaydi)."""
    sender = game["players"].get(from_uid, {})
    name = sender.get("name", "Arvoh")
    for uid, p in game["players"].items():
        if uid != from_uid and not p.get("alive", True):
            safe_send(uid, f"👻 <b>{esc(name)}:</b> {esc(text)}")


@bot.message_handler(commands=["arvoh"])
def cmd_arvoh(message):
    """👻 O'lgan o'yinchilar o'zaro yozishishi uchun: shaxsiy chatda <code>/arvoh matn</code>."""
    maybe_capture_owner(message.from_user)
    if message.chat.type != "private":
        safe_delete(message)
        return
    uid = message.from_user.id
    text = (message.text or "").split(maxsplit=1)
    if len(text) < 2 or not text[1].strip():
        bot.send_message(message.chat.id, "👻 Foydalanish: <code>/arvoh Salom, hammaga!</code> (faqat o'lganlar ko'radi)")
        return
    found = False
    for game in GAMES.values():
        p = game["players"].get(uid)
        if p and not p.get("alive", True):
            _ghost_broadcast(game, uid, text[1])
            found = True
    if not found:
        bot.send_message(message.chat.id, "❌ Siz hozir faol o'yinda o'lgan holatda emassiz.")


# ---------------------------------------------------------------- 🤝 TAKLIF (REFERAL) TIZIMI
REFERRAL_BONUS_INVITER = 100
REFERRAL_BONUS_INVITEE = 60
REFERRAL_FIRST_PURCHASE_BONUS = 400  # 💵 (avval 💎 edi — bepul olmos yo'q) — taklif qilgan do'stingiz ilk marta REAL pul (Stars) sarflasa, SIZGA beriladi (bir marta)


def _maybe_referral_purchase_bonus(payer_uid):
    """💎 v12: taklif qilingan do'stingiz birinchi marta Stars orqali biror narsa sotib
    olsa — sizga (taklif qilganga) bir martalik kichik faollashtirish bonusi beriladi.
    Bu shunchaki ro'yxatdan o'tish uchun emas, balki HAQIQIY, pul to'layotgan
    foydalanuvchi taklif qilishga undaydi."""
    inviter_id = None
    try:
        with db_lock:
            try:
                cur.execute("SELECT inviter_id FROM referrals WHERE invitee_id=? AND COALESCE(first_purchase_paid,0)=0",
                            (payer_uid,))
                row = cur.fetchone()
                if not row:
                    return
                inviter_id = row[0]
                # "To'langan" belgisi va bonus BIR tranzaksiyada: bonus berilmasa belgi ham qolmaydi,
                # keyingi xaridda qayta uriniladi (avval belgi qo'yilib, bonus yo'qolishi mumkin edi).
                cur.execute("UPDATE referrals SET first_purchase_paid=1 WHERE invitee_id=?", (payer_uid,))
                cur.execute("UPDATE users SET dollar=MAX(0, dollar+?) WHERE user_id=?",
                            (REFERRAL_FIRST_PURCHASE_BONUS, inviter_id))
                conn.commit()
            except Exception:
                conn.rollback()
                raise
    except Exception:
        _logger.exception("Referal ilk-xarid bonusi berilmadi (payer=%s)", payer_uid)
        return
    try:
        safe_send(inviter_id, f"💎 {mention(payer_uid, user_dict(payer_uid)['name'])} (siz taklif qilgan do'stingiz) "
                              f"birinchi xaridini qildi — sizga +{REFERRAL_FIRST_PURCHASE_BONUS}$ faollashtirish bonusi berildi!")
    except Exception:
        _logger.warning("Referal bonus xabari yuborilmadi (inviter=%s)", inviter_id, exc_info=True)


# 🏆 v11: Taklif DARAJALARI — har bir bosqichda BIR MARTALIK katta mukofot beriladi
# (oddiy $150/taklif bonusdan tashqari). Bu real o'sishga (ko'proq foydalanuvchi =
# ko'proq xarid ham) undaydi va "bachkana" tuyulmaydigan haqiqiy progressiya beradi.
REFERRAL_MILESTONES = [
    (5,   {"diamond": 5},                    "🥉 Boshlang'ich taklifchi"),
    (15,  {"diamond": 10},                    "🥈 Faol taklifchi"),
    (30,  {"diamond": 15, "elite_days": 1},   "🥇 Usta taklifchi (+1 kun ELITE)"),
    (60,  {"diamond": 25, "elite_days": 3},   "💎 Zabardast taklifchi (+3 kun ELITE)"),
    (120, {"diamond": 40, "elite_days": 7},   "👑 Afsonaviy taklifchi (+7 kun ELITE)"),
]


def _referral_count(uid):
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM referrals WHERE inviter_id=?", (uid,))
        return int(cur.fetchone()[0] or 0)


def _grant_referral_milestones(inviter_id):
    """Taklif soni yangi bosqichga yetgan bo'lsa — mos mukofotni (faqat bir marta) beradi."""
    n = _referral_count(inviter_id)
    ch = get_charges(inviter_id)
    claimed = set(ch.get("ref_milestones", []))
    for threshold, reward, label in REFERRAL_MILESTONES:
        if n >= threshold and threshold not in claimed:
            claimed.add(threshold)
            if reward.get("diamond"):
                add_balance(inviter_id, dollar=reward["diamond"] * FREE_DIAMOND_DOLLAR_VALUE)
            if reward.get("elite_days"):
                grant_elite_days(inviter_id, reward["elite_days"])
            parts = []
            if reward.get("diamond"):
                parts.append(f"{reward['diamond'] * FREE_DIAMOND_DOLLAR_VALUE}$")
            if reward.get("elite_days"):
                parts.append(f"{reward['elite_days']} kun ELITE")
            safe_send(inviter_id, f"🏆 <b>Yangi taklif darajasi!</b> {label}\n"
                                   f"Siz {n} kishini taklif qildingiz — mukofot: {' + '.join(parts)}!")
    ch["ref_milestones"] = sorted(claimed)
    set_charges(inviter_id, ch)


def _referral_progress_text(uid):
    n = _referral_count(uid)
    ch = get_charges(uid)
    claimed = set(ch.get("ref_milestones", []))
    lines = []
    nxt = None
    for threshold, reward, label in REFERRAL_MILESTONES:
        mark = "✅" if threshold in claimed else ("🔸" if nxt is None else "⬜️")
        if threshold not in claimed and nxt is None:
            nxt = threshold
        lines.append(f"{mark} {threshold} ta — {label}")
    return n, "\n".join(lines)


def referral_link(uid):
    return f"https://t.me/{BOT_USERNAME}?start=ref_{uid}"


def apply_referral(invitee_id, inviter_id):
    """(ok, xabar) — birinchi marta /start ref_<id> bilan kirganda ikkalasiga ham bonus."""
    if invitee_id == inviter_id:
        return False, "O'zingizni taklif qila olmaysiz."
    if not oc_feature_on("referral"):   # 👑 Owner Center
        return False, "Taklif dasturi hozircha o'chirilgan."
    with db_lock:
        cur.execute("SELECT 1 FROM users WHERE user_id=?", (inviter_id,))
        if not cur.fetchone():
            return False, "Taklif havolasi noto'g'ri."
        cur.execute("SELECT 1 FROM referrals WHERE invitee_id=?", (invitee_id,))
        if cur.fetchone():
            return False, "Siz allaqachon kimningdir taklifi orqali ro'yxatdan o'tgansiz."
        cur.execute("INSERT INTO referrals (invitee_id, inviter_id, ts) VALUES (?,?,?)", (invitee_id, inviter_id, time.time()))
        conn.commit()
    add_balance(invitee_id, dollar=REFERRAL_BONUS_INVITEE)
    add_balance(inviter_id, dollar=REFERRAL_BONUS_INVITER)
    safe_send(inviter_id, f"🤝 {mention(invitee_id, user_dict(invitee_id)['name'])} sizning taklifingiz orqali qo'shildi! +{REFERRAL_BONUS_INVITER}$ oldingiz.")
    _grant_referral_milestones(inviter_id)
    return True, f"🎁 Xush kelibsiz! Taklif bonusi: +{REFERRAL_BONUS_INVITEE}$ Dollar."


@bot.message_handler(commands=["taklif"])
def cmd_taklif(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    user_dict(uid, message.from_user.first_name)
    n, progress = _referral_progress_text(uid)
    bot.send_message(message.chat.id,
        f"🤝✨ <b>DO'STLARINGIZNI TAKLIF QILING</b> ✨🤝\n"
        f"━━━━━━━━━━━━━━━━━━\n\n"
        f"Har bir do'stingiz shu havola orqali botga birinchi marta kirsa:\n"
        f"• Sizga +{REFERRAL_BONUS_INVITER}$ 💵\n• Unga +{REFERRAL_BONUS_INVITEE}$ 💵\n\n"
        f"💵 Do'stingiz birinchi marta ⭐️ Stars orqali xarid qilsa — sizga yana "
        f"+{REFERRAL_FIRST_PURCHASE_BONUS}$ qo'shimcha bonus!\n\n"
        f"🔗 Havolangiz:\n<code>{referral_link(uid)}</code>\n\n"
        f"👥 Hozirgacha taklif qilinganlar: <b>{n}</b>\n\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"🏆 <b>Taklif darajalari</b> (bir martalik qo'shimcha mukofot):\n{progress}")


# ---------------------------------------------------------------- 🚨 SHIKOYAT TIZIMI
@bot.message_handler(commands=["shikoyat"])
def cmd_shikoyat(message):
    """🚨 Xabarga REPLY qilib <code>/shikoyat sabab</code> — noloyiq xulq-atvor haqida bot egasiga xabar beradi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    reply = message.reply_to_message
    parts = (message.text or "").split(maxsplit=1)
    reason = parts[1].strip() if len(parts) > 1 else ""
    if not reply or not reply.from_user:
        bot.send_message(message.chat.id, "❌ Shikoyat qilmoqchi bo'lgan foydalanuvchining xabariga reply qilib <code>/shikoyat sabab</code> deb yozing.")
        return
    if not reason:
        bot.send_message(message.chat.id, "❌ Sababini ham yozing: <code>/shikoyat so'kindi</code>")
        return
    if not _rate_ok(message.from_user.id, "complaint", 5, 3600):
        bot.send_message(message.chat.id, "❌ Juda ko'p shikoyat yubordingiz — birozdan keyin urinib ko'ring.")
        return
    with db_lock:
        cur.execute("INSERT INTO complaints (reporter_id, target_id, chat_id, text, ts) VALUES (?,?,?,?,?)",
                    (message.from_user.id, reply.from_user.id, message.chat.id, reason[:500], time.time()))
        conn.commit()
    owner = _owner_uid()
    if owner:
        safe_send(owner, f"🚨 <b>Shikoyat</b>\n👤 Kim: {mention(message.from_user.id, message.from_user.first_name)}\n"
                         f"🎯 Kimga: {mention(reply.from_user.id, reply.from_user.first_name)}\n"
                         f"💬 Sabab: {esc(reason)}\n\n<code>/useri {reply.from_user.id}</code>")
    bot.send_message(message.chat.id, "✅ Shikoyatingiz qabul qilindi va ko'rib chiqiladi.")


def start_hc_market_loop():
    t = threading.Thread(target=_hc_market_loop, daemon=True)
    t.start()


def _hc_trend_arrow(current, prev):
    if current > prev:
        return "🟢▲"
    if current < prev:
        return "🔴▼"
    return "⚪️➡️"


def hc_diamond_rate_int():
    """Olmos ↔ Coin ayirboshlashda ishlatish uchun butun sonli kurs (kamida 1)."""
    return max(1, round(HC_DIAMOND_RATE))


def hc_dollar_rate_int():
    """Dollar ↔ Coin ayirboshlashda ishlatish uchun butun sonli kurs (kamida 1)."""
    return max(1, round(HC_DOLLAR_RATE))


