DOLLAR_TO_COIN_PRESETS = [300, 600, 1500, 5000, 10000]


def open_dollar_to_coin_menu(chat_id, uid):
    # 🔧 v8: Dollar → Coin ayirboshlash OLIB TASHLANGAN
    bot.send_message(chat_id, "🚫 Bu funksiya olib tashlangan: Hunter Coin endi faqat 💎 Olmosga, joriy kurs bo'yicha sotib olinadi (/olmos_coin).")
    return
    u = user_dict(uid)
    rate = hc_dollar_rate_int()
    kb = types.InlineKeyboardMarkup(row_width=2)
    buttons = []
    for d in DOLLAR_TO_COIN_PRESETS:
        c = d // rate
        if c <= 0:
            continue
        buttons.append(types.InlineKeyboardButton(f"{d}💵 → {c}🪙", callback_data=f"dl2c|{d}"))
    for i in range(0, len(buttons), 2):
        kb.add(*buttons[i:i + 2])
    arrow = _hc_trend_arrow(HC_DOLLAR_RATE, HC_PREV_DOLLAR_RATE)
    bot.send_message(
        chat_id,
        "💵➜🪙 <b>Dollar → Hunter Coin ayirboshlash</b>\n\n"
        f"💵 Sizda: {u['dollar']} Dollar\n"
        f"📈 Joriy jonli kurs: <b>{rate} 💵 = 1 🪙</b> {arrow}\n\n"
        "Qancha ayirboshlashni tanlang:",
        reply_markup=with_back_button(kb),
    )


@bot.message_handler(commands=["dollar_coin"])
def cmd_dollar_coin(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    open_dollar_to_coin_menu(message.chat.id, message.from_user.id)


@bot.callback_query_handler(func=lambda c: c.data == "open_dollar_to_coin")
def cb_open_dollar_to_coin(call):
    maybe_capture_owner(call.from_user)
    bot.answer_callback_query(call.id)
    open_dollar_to_coin_menu(call.message.chat.id, call.from_user.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("dl2c|"))
def cb_dollar_to_coin(call):
    maybe_capture_owner(call.from_user)
    bot.answer_callback_query(call.id, "🚫 Bu funksiya olib tashlangan: Hunter Coin endi faqat 💎 Olmosga, joriy kurs bo'yicha sotib olinadi (/olmos_coin).", show_alert=True)   # 🔧 v8: olib tashlangan
    return
    uid = call.from_user.id
    dollar_amount = int(call.data.split("|")[1])
    rate = hc_dollar_rate_int()
    coin_amount = dollar_amount // rate
    u = user_dict(uid, call.from_user.first_name)
    if u["dollar"] < dollar_amount:
        bot.answer_callback_query(
            call.id, f"❌ Dollaringiz yetarli emas! Kerak: {dollar_amount} 💵, sizda: {u['dollar']} 💵.",
            show_alert=True,
        )
        return
    if coin_amount <= 0:
        bot.answer_callback_query(call.id, "❌ Bu miqdor joriy kursda 1 Coin ham bermaydi.", show_alert=True)
        return
    add_balance(uid, dollar=-dollar_amount, coin=coin_amount, ledger=False)
    bot.answer_callback_query(call.id, "✅ Ayirboshlash muvaffaqiyatli!", show_alert=True)
    try:
        bot.edit_message_text(
            f"💱 <b>Ayirboshlash bajarildi!</b>\n\n"
            f"➖ {dollar_amount} 💵 Dollar sarflandi.\n"
            f"➕ Hisobingizga <b>{coin_amount}</b> 🪙 Hunter Coin qo'shildi!\n"
            f"📈 Ishlatilgan kurs: {rate} 💵 = 1 🪙",
            call.message.chat.id, call.message.message_id,
        )
    except Exception:
        pass


